pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let nx = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Dead-space avoidance (softened from parent to avoid over-penalizing small usable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: next item fits into post-residual — reward tight refills (GEN191: graded).
    if nx > 0.0 && pr >= nx {
        let after = pr - nx;
        score -= 45.0 * (1.0 - after / cap).max(0.0);
        // Exact refill chain bonus
        if after == 0.0 {
            score -= 12.0;
        } else if after <= 4.0 {
            score -= 6.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
        } else if after <= 12.0 {
            score -= 3.0 * (1.0 - (after - 4.0) / 8.0);
        }
        // Multi-chain harmonics: leave room for 2x or 3x next items
        if nx >= 2.0 && after >= 2.0 * nx && after <= 2.0 * nx + 4.0 {
            score -= 5.0 * (1.0 - (after - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress);
        }
        if nx >= 3.0 && after >= 3.0 * nx && after <= 3.0 * nx + 6.0 {
            score -= 3.5 * (1.0 - (after - 3.0 * nx) / 6.0) * (0.5 + 0.5 * progress);
        }
        // Penalize stranding a residual just below nx (unusable for lookahead)
        if after > 0.0 && after < 1.0 && fitting_bins_count >= 2 {
            score += 3.0 * (1.0 - after) * (1.0 - progress);
        }
    } else if nx > 0.0 && pr > 0.0 {
        // Next item won't fit here: penalize proportionally, stronger early.
        score += (nx - pr) * (0.6 + 0.8 * (1.0 - progress));
        // But favor the bin with the largest residual as the likely future host.
        if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
            score -= 4.0 * (1.0 - br / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
        }
    }

    // Fitting pressure.
    if fitting_bins_count > 1 {
        score -= 10.0;
    } else if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Open bins pressure.
    score += (open_bins_count as f64) * 1.5;

    // Tighter bins relative to mean residual.
    score += (mean_residual - pr) * 0.3;

    // Dead-ratio analysis for open bins (borrowed idea: fraction of remaining space wasted).
    if bin_residual != bin_capacity && br > 0.0 {
        let dead = pr / br.max(1.0);
        if dead > 0.75 && pr > 15.0 {
            score += 2.0 * (dead - 0.75);
        }
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 3.0 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
        }
        if dead > 0.5 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 1.5 * (1.0 - (pr - nx) / 2.0);
        }
    }

    // NEW-BIN CANDIDATE evaluation (GEN191: lookahead-driven, replaces flat penalty).
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        // If placing item here leaves room for nx with a tight chain, favor the new bin.
        let after_new = cap - item_size as f64 - nx;
        if nx > 0.0 && after_new >= 0.0 {
            if after_new == 0.0 {
                score -= 6.0;
            } else if after_new < nx {
                score -= 2.0 * (1.0 - after_new / nx.max(1.0)) * (0.5 + 0.5 * progress);
            } else {
                // Wide leftover: penalize, especially mid/late stream.
                score += 1.5 * ((after_new - nx) / cap) * (0.5 + progress);
            }
        } else if nx > 0.0 {
            // New bin can't host nx after this item: penalize when open bins could.
            if open_bins_count > 0 && mean_residual >= nx {
                score += 2.5 * (1.0 - progress);
            }
        }
        // Large waste in a fresh bin: discourage, more so when many bins are open.
        if waste > 0.5 {
            score += 2.0 * (waste - 0.5) * (1.0 + 0.5 * progress);
        }
        // Late stream: strongly discourage new bins when open space suffices.
        if open_bins_count > 0 && progress > 0.7 && mean_residual >= item_size as f64 {
            score += 3.0 * (progress - 0.7) / 0.3;
        }
        // Early stream with tight mean residual: opening is more acceptable.
        if progress < 0.25 && mean_residual < cap * 0.2 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Late-stream tightening toward exact fits.
    score -= progress * 20.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // fit a meaningful item (below the minimum plausible item footprint)
    // are heavily penalized dead space.
    let dead_threshold = 20.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0;
    }
    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2) when possible.
    if next_item_size > 0 {
        if post_residual == next_item_size as u64 as u32 || post_residual as f64 == next_item_size as f64 {
            score -= 15.0;
        } else if (post_residual as f64) >= next_item_size as f64 {
            score -= 4.0;
        } else if next_item_size as f64 > pr && pr > 0.0 {
            // this placement creates a gap that cannot host the next item
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, filling tightly is fine. Coupled with mean residual: prefer
    // bins whose residual is close to the mean (balanced packing), penalize
    // placing into already-tight bins when alternatives exist.
    let fit_quality = item_size as f64 / bin_residual as f64;
    score += fit_quality * 8.0; // prefer bins where item fills a large fraction

    let residual_dev = (bin_residual as f64 - mean_residual).abs();
    score += residual_dev * 0.3;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when no existing bin fits well
    // (i.e., the item is large relative to available residuals and many bins
    // are already open with small residuals).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let new_bin_bonus = 30.0
            - item_size as f64 * 0.2
            - pressure * 4.0
            - progress * 5.0;
        score += new_bin_bonus;
        // A large item into a fresh bin wastes capacity; slight penalty.
        if item_size > 60 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Dead-space class: residuals that can never absorb the smallest item.
        if post_residual < 10 {
            score += 400.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 120.0; // marginal class
        } else if post_residual <= 40 {
            score += 30.0;
        } else if post_residual <= 70 {
            score -= 40.0; // reusable class
        } else {
            score -= 80.0; // half-bin or better remains
        }

        // Modulo-10 harmonic band: residuals near multiples of 10 align with item grid.
        let m = post_residual % 10;
        if m == 0 {
            score -= 25.0;
        } else if m >= 7 {
            score += 10.0; // awkward sliver above a grid point
        }

        // Lookahead coupling: can next item fill the post_residual?
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0; // chain exact fit
            } else if next_item_size <= post_residual {
                let waste = post_residual - next_item_size;
                score -= 60.0 * (1.0 - waste as f64 / cap);
                // integer-division threshold: how many more items could still fit after next
                let depth = post_residual / next_item_size.max(1);
                score -= 15.0 * depth as f64;
            } else {
                // next item can't use this residual: penalize by overshoot class
                score += 20.0 + 0.5 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current fit is poor and many open bins.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / cap;
        score = 90.0 - 40.0 * fit_quality;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 60.0; // all open bins are tight anyway
        }
        // late in stream, avoid bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference to fill fuller bins (smaller residual) first.
    score -= 0.3 * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit residual (best-fit flavor)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Aggressive 2-step lookahead: reward if next item fits perfectly into post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let slack = post - next;
            // Perfect chain fit gets a big bonus; small slack still rewarded
            if slack == 0.0 {
                score -= 60.0;
            } else {
                score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow into this bin: penalize dead space proportionally
            score += 10.0 + (next - post).min(50.0) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins whose post state tracks the pack average
    let post_f = post_residual as f64;
    let dev = (post_f - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 5.0 * crowd - 20.0 * progress;
        // If next item is large, opening a new bin may be wise
        if next_item_size as f64 >= mean_residual {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins tighter near the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // tiny gap => heavy penalty
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: bonus if the post residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot fit here; penalize leaving gap smaller than next item
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64)).max(0.0);
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline; discourage unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score = 55.0 - 20.0 * fill_ratio;
        if fitting_bins_count == 1 {
            score += 50.0; // don't open new bin if this is the only fitting one
        }
    }

    // Late-stream tightening: become more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue determines dead-space quality
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    score += residue * 0.8; // residues not divisible by 10 are less reusable

    // Perfect fits and clean classes
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr % 10 == 0 {
        score -= 12.0; // clean class residual is highly reusable
    } else if pr < 10 {
        score += 25.0; // tiny dead space below min item size
    }

    // Integer-division threshold: how many mid-size items (>=20) fit in post_residual
    let fits_mid = pr / 20;
    score -= fits_mid as f64 * 6.0;

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni <= pr {
            // prefer leaving space exactly matching next item or a clean class
            if ni == pr {
                score -= 40.0;
            } else if (pr - ni) % 10 == 0 {
                score -= 18.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize leaving large unusable gap
            score += (ni - pr) as f64 * 0.15;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if all open bins are tight/fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_frag = (cap - mean_residual) / cap;
        // open new bin when existing bins are heavily fragmented and many bins open
        score = 55.0 + mean_frag * 40.0 - open_bins_count as f64 * 1.5 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Slight preference for tighter bins overall (small residual before placement)
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Gap usable by the smallest items; mild penalty.
        score += 8.0;
    }

    // Reward residual large enough to fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (post_residual as f64 - next_item_size as f64) * 0.2;
        } else {
            score += 6.0; // this bin becomes dead after placement
        }
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; only preferred over very poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 1.0;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when a last-chance bin exists
        }
    }

    // Mild mean-residual coupling: prefer bins with residual near the mean (balanced packing).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Slight progression pressure: tighten packing as the stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.1 + 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let nx = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if pr > 0.0 && pr < 10.0 {
        score += 60.0 - pr * 4.0;
    }
    // Perfect fit reward.
    if pr == 0.0 {
        score -= 40.0;
    }

    // Lookahead: reward leaving space the next item can use; penalize stranded gaps.
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            score -= 15.0 * (1.0 - after / cap).max(0.0);
            // Reward tight refills: leftover after hosting nx is small or matches nx chains.
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0);
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 && nx >= 2.0 {
                score -= 3.0 * (1.0 - (after - 2.0 * nx) / 8.0);
            }
        } else if pr > 0.0 {
            // Gap too small for lookahead item: dead space, penalize harder when late.
            score += 20.0 + 10.0 * progress;
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 8.0 * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 20.0);
    score += pressure * 2.0;

    // Dead-space ratio: penalize bins whose remaining space is mostly wasted.
    let dead = pr / br.max(1.0);
    if pr > 0.0 && dead > 0.6 && pr > 10.0 && nx > 0.0 && nx > pr {
        score += 4.0 * (dead - 0.6);
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins fit poorly.
        let waste = (cap - item_size as f64) / cap;
        let bad_open = if fitting_bins_count == 0 { 0.0 } else { (mean_residual - item_size as f64).max(0.0) };
        score += 30.0 + bad_open * 0.5 - (open_bins_count as f64) * 0.5;
        score += progress * 5.0;
        // Large waste in a new bin is bad unless nothing fits.
        if waste > 0.5 {
            score += 4.0 * (waste - 0.5) * (0.5 + 0.5 * progress);
        }
        // If any open bin can host the next item tightly, discourage a new bin.
        if open_bins_count > 0 && fitting_bins_count >= 1 && mean_residual >= nx * 0.8 && progress > 0.3 {
            score += 6.0 * (progress - 0.3) / 0.7;
        }
        // New bin whose leftover can host nx is more acceptable early.
        if nx > 0.0 && (cap - item_size as f64) >= nx && progress < 0.4 {
            score -= 4.0 * (1.0 - progress);
        }
        // Late stream: never open bins with tiny expected leftovers.
        if progress > 0.8 && mean_residual >= item_size as f64 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
    } else {
        // Favor tight fits: residual closest above the item.
        score += (bin_residual - item_size) as f64 * 0.1;
        // Prefer bins whose post-residual can exactly host the next item again.
        if pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
        // When several bins fit, prefer the one with residual near mean (balanced consolidation).
        if fitting_bins_count >= 3 && (pr - mean_residual).abs() < 3.0 {
            score -= 2.0 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
    }
    // Penalize if next item would leave a dead gap in this bin.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Open bins pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count > 1 {
        score -= 10.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 70.0;
    }

    // Mild pressure from number of open bins: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Slight preference for tighter bins relative to mean residual.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize moderately so it's chosen only when all open bins are bad.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // Late-stream tightening: as stream progresses, be greedier about exact fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-item capacity lookahead (fine-grained: reward leftover that can host small future items)
    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.0;
    let fits_small = post_residual / 6;
    if fits_small > fits_mid {
        score -= (fits_small - fits_mid) as f64 * 1.2 * (0.4 + 0.6 * progress);
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
                if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress); }
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // GEN178: reward tight after-spaces in the 1..=12 band more aggressively
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0);
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress);
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress);
            }
            if after >= 6.0 && after <= 14.0 && fitting_bins_count >= 3 {
                score -= 0.7 * (1.0 - (after - 6.0) / 8.0);
            }
            // chaining: leave room for next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // chainable after-space: can host next item AND leave a small residual
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            // awkward leftover: barely larger than next item
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress);
            }
            // tiny after-space is excellent
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            // GEN178: reward exact 2-chain and 3-chain refills with tight margins
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 && nx > 0.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
            if nx >= 3.0 && after >= 3.0 * nx && after <= 3.0 * nx + 6.0 {
                score -= 0.8 * (1.0 - (after - 3.0 * nx) / 6.0) * (0.5 + 0.5 * progress);
            }
            // GEN178: penalize wide leftover bands late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5);
            }
            // penalize leftover that is too big relative to need when bins are plentiful
            if after > 30.0 && after < 60.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.4 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        } else {
            // next item won't fit here
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 0.6 * (1.0 - progress);
            }
            // GEN178: late stream, no bin fits nx — favor the largest-residual bin as future host
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br.max(1.0) / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
            }
            if fitting_bins_count == 0 && br < mean_residual * 0.85 && br > 0.0 {
                score -= 0.3 * (1.0 - br / mean_residual.max(1.0)) * (1.0 - progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // dead-space below min item size is wasted when next item can't use it
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // last-chance bin
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio (fragmentation of this bin) analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    // mid-range dead space with large residual: penalize
    if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
        score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress);
    }
    // GEN178: reward low dead-space bins that still leave usable space for nx
    if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
        score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
    }
    // GEN178: penalize high dead-space bins with stranded residuals harder when many bins compete
    if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
        score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25;
    }
    // pool-balance bonus
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    // near-exact next-item fit into residual
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    // GEN178: penalize bins that strand a residual just below nx when other bins could host nx
    if dead > 0.35 && nx > 0.0 && pr >= nx && pr - nx < 1.0 && pr - nx > 0.0 && fitting_bins_count >= 2 {
        score += 0.3 * (1.0 - (pr - nx)) * (1.0 - progress);
    }
    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
            // double-lookahead: reward opening when leftover after next item is tiny
            if after_new > 0.0 && after_new < 6.0 {
                score -= 1.2 * (1.0 - after_new / 6.0) * (0.4 + 0.6 * progress);
            }
            // GEN178: reward multi-chain capacity in the new bin (after hosting nx, room for nx again)
            if after_new >= nx && nx >= 3.0 && after_new < 2.0 * nx {
                score -= 0.5 * (1.0 - (after_new - nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // penalize opening when a fitting open bin's residual is almost exactly the item
        if open_bins_count > 0 && fitting_bins_count >= 1 && mean_residual >= item_size as f64
            && (mean_residual - item_size as f64) < 0.05 * cap {
            score += 1.5 * (1.0 - (mean_residual - item_size as f64) / (0.05 * cap));
        }
        // GEN178: discourage opening a new bin mid/late stream when any open bin can host nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65;
        }
        // GEN178: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= item_size as f64 {
            score += 1.0 * (progress - 0.8) / 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // Density reward: keep residual below mean.
    score -= 0.35 * (mean_residual - br).abs();

    // Small post residuals are prime targets (near-perfect fills).
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // Lookahead: how well does the next item use the post residual?
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            score -= 14.0 * (1.0 - after / cap).max(0.0);
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if after == 0.0 {
                score -= 3.0 + 1.5 * (1.0 - progress);
            }
            // Chainable small windows keep bins productive.
            if after >= 2.0 && after <= 7.0 && open_bins_count >= 2 {
                score -= 0.7 * (1.0 - (after - 2.0) / 5.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            // Mid-band: after-space comfortably exceeds next item in a lean pool.
            if after > 10.0 && after <= 18.0 && fitting_bins_count <= 3 && nx >= 4.0 {
                score -= 0.55 * (1.0 - (after - 10.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            // Double-lookahead: residual can host next item twice.
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
            // Awkward 1..3 overhang above next item fragments the future.
            if after > 6.0 && after < nx + 4.0 && after > nx + 1.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress);
            }
            // Very large leftover with a much smaller next item: mild penalty early.
            if after > 30.0 && after < 60.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
        } else {
            // Next item cannot fit here: penalize the gap, stronger early.
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    }

    // Tiny dead residual that next item cannot use.
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    // Moderately small residual far below a quarter of capacity: slight penalty.
    if pr > 9.0 && pr < 0.25 * cap {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0 * (0.5 + 0.5 * progress);
    }
    if fitting_bins_count <= 2 && pr > 0.0 && pr >= nx && nx > 0.0 {
        score -= 4.0 * (1.0 - progress);
    }

    // Dead-space ratio relative to what was already used.
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 {
        score += 1.2 * (dead - 0.75);
    }
    if dead > 0.6 && pr > 10.0 {
        score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
    }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
        score += 1.5 * (dead - 0.9) * (0.5 + progress);
    }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.5 && nx > 0.0 && pr > nx + 1.0 && pr < nx + 3.0 && br > 0.55 * cap {
        score += 0.65 * (nx + 3.0 - pr) * (0.5 + 0.5 * progress);
    }
    if dead <= 0.3 && pr >= 2.0 * nx && nx >= 3.0 && fitting_bins_count >= 2 {
        score -= 0.5 * (1.0 - dead / 0.3) * (0.4 + 0.6 * (1.0 - progress));
    }
    // Tight lookahead match within 2% of capacity.
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }

    // ---- New-bin candidate logic ----
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        // Reward new bins whose post-residual can host the next item.
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        // Discourage new bins when the existing pool has generous room.
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste * cap >= nx {
            let after2 = waste * cap - nx;
            if after2 < 6.0 {
                score -= 1.2 * (1.0 - after2 / 6.0) * (0.4 + 0.6 * progress);
            }
            if after2 >= 2.0 && after2 <= 7.0 && open_bins_count >= 2 {
                score -= 0.7 * (1.0 - (after2 - 2.0) / 5.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
        // Late-stream: strongly discourage opening new bins when the pool still has room.
        if open_bins_count > 0 && progress > 0.7 && mean_residual > cap * 0.4 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (progress - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact-ish fits (small post_residual).
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how tightly next item nests.
            let nest = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * nest;
        } else {
            // Dead space for the next item: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Prefer bins with residuals below mean (tight packing) mildly.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: penalize spreading; encourage filling existing bins.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so it loses against decent existing fits.
        score = bin_capacity as f64 * 1.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If this bin is the only fitting option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
