        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.6 * (waste - 0.55) * (progress - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late in the stream, demand tight packing.
    let tightness_weight = 0.5 + 2.5 * progress * progress;
    score += tightness_weight * norm_pr * norm_pr * cap * 0.1;

    // Dead-space penalty: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 3.0 * waste * (1.0 + progress);
    }

    // Reward bins whose residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: this is the only fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below-average residual (tight bins).
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Partial match: reward proportional to how much of post_residual the next item consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 400.0 * fill;
            // Penalize leftover after the lookahead placement (dead space over two steps).
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use this bin's post residual: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Reward bins whose residual is below mean (denser bins) to keep consolidation.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize very small post residuals that likely become dead space
    // unless they are an exact lookahead match (already heavily rewarded).
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 150.0;
    }

    // Early in the stream, prefer keeping flexibility: penalize tight fits slightly less
    // as the stream progresses (fewer future opportunities).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        score -= 20.0 * progress;
    }

    // New-bin candidate: baseline competitive score; only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 120.0 - 100.0 * progress;
    }

    score
}

