    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but keep the new-bin candidate (residual == capacity) neutral-ish
    // so it wins only when fits into open bins are genuinely bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 6.0;
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward chain fit: if the next item exactly fills the post-residual,
    // this is a perfect two-item closure -> strong bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }

    // Reward when the next item still fits into the post-residual,
    // scaled by how snugly (smaller leftover after the pair is better).
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - pair_leftover / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize dead space,
        // more so when post_residual is small and unusable.
        let cap = bin_capacity as f64;
        score += 10.0 * (1.0 - post_residual as f64 / cap);
    }

    // Prefer bins whose residual deviates from the mean residual in a useful way:
    // filling a bin far below the mean residual tightens the pool.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in the stream, mildly prefer spreading items (keep flexibility);
    // late in the stream, strongly prefer closing bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: neutral residual (full capacity) is penalized unless
    // no open bin offers a decent fit; the lookahead chain-fit bonus above
    // can still justify opening a fresh bin for a large upcoming item.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Opening a new bin lets both current and next item pair cleanly.
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linear.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 40.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // partial compatibility reward, scaled by how well it fits
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize wasted space
            score += (post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64;
        // open new bin if mean residual of open bins is low (they are nearly full)
        if mean_residual < 15.0 {
            score -= 30.0;
        } else {
            score += 25.0 + mean_residual * 0.4;
        }
        let _ = spread;
    } else {
        // Penalize bins far from mean residual (outliers) to keep residual distribution tight
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;

        // Late in the stream, consolidate: prefer bins with smaller residual
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += post_residual as f64 * progress * 0.3;
    }

    // Many open bins: encourage filling existing ones rather than scattering
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, dead space matters more
    let prog_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 8.0 * progress * pr;
    score -= 4.0 * prog_coupling * (cap - pr);

    // Penalize residuals that are too small to be useful for typical items
    let useless = if pr > 0.0 {
        let r = (pr / 80.0).min(1.0);
        (1.0 - r) * (1.0 - r)
    } else {
        0.0
    };
    score += 6.0 * useless * (0.5 + progress);

    // Reward filling bins nearly completely
    score -= 5.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: mildly discourage opening bins when good fits exist,
    // but encourage it when mean residual across open bins is fragmented
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score += 4.0 + 6.0 * (1.0 - frag.abs() - 0.5).abs();
        score -= 3.0 * progress;
    }

    // Mean residual interaction: prefer bins near the mean (keeps residuals uniform)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but avoid tiny useless residuals.
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit is gold
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect fit, dead space negligible
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class of post_residual: residual mod 10 bands.
    // Residuals in [1..9] are only fillable by small items (rare in 10..80 range),
    // so treat them as near-dead; multiples of 10 are highly reusable.
    let rem = post_residual % 10;
    if post_residual > 0 && rem != 0 {
        // penalize non-aligned residuals proportionally to how small the largest
        // usable chunk would be
        let largest_usable = (post_residual / 10) * 10;
        score += (10 - rem) as f64 * 0.8 + (10 - largest_usable.min(10)) as f64 * 0.3;
    } else if rem == 0 && post_residual >= 10 {
        score -= 8.0; // aligned residual, very reusable
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0; // chain of perfect fits
        }
        // harmonic coupling: next item also leaves an aligned residual
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot go here regardless; slight penalty if this bin
        // would become the "trap" bin with awkward residual
        if post_residual > 0 && post_residual < 10 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation elsewhere.
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 1.5;
    }

    // New-bin candidate logic: empty bin gets a neutral baseline that must be
    // beaten only when existing fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost. Prefer new bin when item is large
        // and stream is early (room to build future tight fits).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 - 20.0 * (1.0 - progress) - (item_size as f64 - 10.0) * 0.25;
        if open_bins_count == 0 {
            score -= 100.0; // must place somewhere
        }
    }

    // Mild preference to keep mean residual spread balanced.
    score += ((post - mean_residual) / 50.0).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for tiny unusable dead space (gaps that likely can't host future items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 30 {
        score += 3.0;
    }

    // Reward very tight fits (item fills bin almost exactly)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already small (dense bins)
    score += (bin_residual as f64) * 0.15;

    // Pressure from number of open bins: discourage spreading when many bins open,
    // encourage using existing bins; but allow opening new bins when few are open.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize slightly so it only wins when fits are bad,
    // but relax the penalty as the stream progresses (bins accumulate anyway).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress;
    }

    // Lookahead: if next item fits in the post-residual, reward leaving that space
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0;
    }

    // Deviation from mean residual: prefer bins far below the mean (denser than average)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post-residual is exponentially better.
    if post_residual > 0 {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);
    } else {
        score -= 25.0; // perfect fill
    }

    // Penalize dead space that is too small to hold typical items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item cannot use this residual: mild penalty proportional to slack
            score += 3.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * post_residual as f64;
    }

    // New-bin candidate: base its attractiveness on global state.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when few bins are open or mean residual is high
        // (existing bins are fragmented); expensive when bins are well-filled.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = post_residual as f64
            + 6.0                                  // inherent cost of a new bin
            - 4.0 * fragmentation                  // cheap if open bins are fragmented
            - 3.0 * (1.0 - progress)               // cheaper to open early in the stream
            - (open_bins_count as f64).min(6.0);   // slight scaling with open bins
        // But if a perfect fit exists elsewhere, the perfect-fit bonus above will win.
    } else {
        // Mild penalty for spreading across many bins when mean residual is already high.
        if mean_residual > 0.5 * bin_capacity as f64 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual (bigger leftover = better fit), polynomially coupled with progress
    let mut score = pr;

    // Smooth non-linear coupling: residual value decays as stream progresses
    // (late in the stream, tight fits matter less than bin count)
    let decay = 1.0 - 0.35 * progress * progress;
    score *= decay;

    // Dead-space penalty: quadratic in normalized residual, stronger early
    score += 18.0 * x * x * (1.0 - progress);

    // Tight-fit reward: cubic term rewarding small post_residual
    score -= 12.0 * (1.0 - x).powi(3);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Penalty for bins much emptier than the mean (keeps residuals balanced)
    let dev = pr - mean_residual;
    score += 0.08 * dev * dev / (1.0 + open_bins_count as f64);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mild penalty for opening new bins when others fit
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into modulo-10 residue classes.
    let r = post_residual % 10;
    // Residues that pair well with common item sizes (multiples of 10) are "harmonic".
    let harmonic = matches!(r, 0 | 10);
    if harmonic {
        score -= 12.0;
    } else {
        score += 6.0 + 1.5 * (r as f64);
    }

    // Integer-division thresholds on post_residual: dead-space bands.
    let band = post_residual / 20; // 0..5
    score -= band as f64 * 4.0;

    // Fraction of capacity left: prefer filling bins that are already mostly full.
    let fill_frac = (bin_residual as f64) / cap;
    score += (1.0 - fill_frac) * 10.0;

    // Coupling with next item: harmonic pairing if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect second placement
        } else if next_item_size <= post_residual {
            let nres = post_residual - next_item_size;
            let nclass = (nres % 10 == 0) as i32;
            score += nres as f64 * 0.6 - nclass as f64 * 8.0;
        } else {
            // next item won't fit here; penalize small post_residuals less (dead space)
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score += 45.0 - pressure.min(40.0);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0; // big next item: fresh bin useful
        }
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.5;

    // Mean-residual coupling: if this bin's residual is below mean, prefer it.
    let resid_frac = (post_residual as f64) / cap;
    if resid_frac < mean_residual / cap {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the minimum
    // item (<= 10) are unusable "dead space" -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 3.0;
    }

    // Reward near-perfect fits strongly (non-linear coupling).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, using it
    // avoids opening a new bin -> reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize spreading across many open bins; prefer filling existing ones
    // when open bin count is high.
    score += (open_bins_count as f64) * 0.35;

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (i.e., best existing fit would leave a bad gap) or bin pressure is low.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        // Opening a new bin is cheap early, expensive late.
        score += (open_bins_count as f64) * 0.8;
        if post_residual as f64 > mean_residual {
            score -= 2.0;
        }
        // Discourage new bin if a small next item could use leftover space.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 15 {
            score += 25.0;
        }
        return score;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (creates a perfect slot for the next item).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Mild preference for bins below mean residual (keep large gaps available).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    if next_item_size > 0 {
        // Two-step lookahead: reward residuals that exactly match the next item.
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 120.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 250.0; // exact 2-item pairing
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual across open bins: tighter-than-average fits are good.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin unless the item is large (small residual waste otherwise).
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * post_residual as f64;
        if item_size >= 70 {
            score -= 60.0; // large items fine in fresh bins
        }
    }

    // Slight preference for keeping residual small relative to capacity overall.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 1.0 {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (post_residual as f64 - nxt) / cap;
        } else {
            // Next item won't fit here; slight penalty for wasting space now.
            score += 5.0 * (nxt - post_residual as f64) / cap;
        }
    }

