    }

    // Smooth non-linear coupling: bins far below mean residual are less attractive later on.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * (4.0 + 8.0 * progress) * 10.0 - dev * (2.0 + 4.0 * progress);

