    // Deviation from mean residual
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // New-bin candidate: open only when open bins are under pressure
    if br == cap {
        let avg_pressure = mean_residual / cap;
        score += 20.0 + 20.0 * avg_pressure + 10.0 * (1.0 - progress);
