pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: maximal reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals in [1, 12] are nearly unusable
    // (min item size is 10 in typical streams; small gaps are waste).
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    }

    // Residuals in (12, 20) are marginal: mild penalty.
    if post_residual > 12 && post_residual <= 20 {
        score += 0.5 * (post_residual as f64 - 12.0);
    }

    // Reward bins whose residual matches the next item well (lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * (next_item_size as f64);
    }
    // Penalize leaving a gap that just barely fails to fit the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless it would create dead space).
    if fitting_bins_count == 1 && !(post_residual >= 1 && post_residual <= 12) {
        score -= 40.0;
    }

    // Open-bins pressure: many open bins -> favor tightening existing bins,
    // few open bins -> opening a new bin is relatively cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when open bins are crowded or the
    // item is large and fits would leave bad gaps.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64 / 8.0).min(1.0);
        let bad_fit = if post_residual >= 1 && post_residual <= 12 { 1.0 } else { 0.0 };
        score += 25.0 - 30.0 * crowd - 20.0 * bad_fit
            + 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, only attractive when open bins are hopeless.
    if bin_residual == bin_capacity {
