    if pr == 0.0 {
        score -= 28.0 ;
    } else if pr <= 2.0 {
        score -= 14.0 ;
    } else if pr <= 5.0 {
        score -= 8.5 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 1.0 ;
    }

    // lookahead: can next item reuse the leftover space?
