        // if the item placed in a fresh bin leaves a hole the next item fits exactly,
        // opening is actually attractive
        if nx > 0.0 && pr >= nx && (pr - nx) < 2.0 {
            score -= 9.0 ;
        }
    }

    // global consolidation: prefer reusing bins with larger residual when many bins are open
    if open_bins_count > 6 && pr > 0.0 {
        score -= 0.6 * (pr / cap) ;
    }

    score
}

