pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (modulo capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fit: reward strongly.
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead-space class: residual too small for the smallest plausible item (1..100 range).
    // Class A: post_residual in 1..=10 -> likely dead space, penalize.
    if pr >= 1 && pr <= 10 {
        score += 40.0;
    }
    // Class B: post_residual in 11..=25 -> marginal; penalize unless it matches next item.
    else if pr <= 25 {
        if next_item_size > 0 && next_item_size <= pr {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Harmonic quarter classes of residual: 0, 25, 50, 75 mod 100 style thresholds.
    let quarter = pr / 25; // 0..4
    match quarter {
        0 => { score += 30.0; }          // near-full bin: excellent packing, reward
        1 => { score += 10.0; }          // 25..49 residual: decent
        2 => { score += 0.0; }           // 50..74 residual: neutral
        _ => { score -= 5.0; }           // nearly empty bin: prefer filling it
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            // Harmonic class of the double-residual
            score -= 30.0 * (1.0 - leftover as f64 / cap);
            if leftover <= 5 {
                score -= 25.0;
            } else if leftover <= 15 {
                score += 10.0;
            }
        } else {
            // next item cannot use this residual -> dead space penalty grows
            score += 12.0 + 0.3 * (next_item_size as f64 - prf).min(50.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if pr <= 10 {
            score -= 20.0; // even a near-perfect squeeze is worth it
        }
    }

    // New-bin candidate handling: brand-new empty bin gets residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin only when existing bins would leave large ugly residuals
        // or when there are no open bins at all.
        if open_bins_count == 0 {
            score -= 500.0;
        } else {
            // Base cost of opening a bin; reduced late in the stream or when
            // mean residual across open bins is already fragmented.
            let progress = step_index as f64 / total_items.max(1) as f64;
            let mut new_bin_score = 60.0 - 20.0 * progress;
            if mean_residual < 30.0 {
                new_bin_score -= 25.0; // existing bins are tight; new bin helps
            }
            if mean_residual > 70.0 {
                new_bin_score += 30.0; // existing bins are roomy; use them
            }
            score = score.min(1e9) + new_bin_score;
