            if pr == bin_capacity {
                score += 0.0;
            }
        }
    }

    // Integer-division threshold on post_residual / next_item_size ratio classes.
    if next_item_size > 0 {
        let ratio_class = pr / next_item_size.max(1); // 0 = fits, >=1 = doesn't
