            score += 6.0 * ratio_class.min(4) as f64;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Small tie-breaker toward fuller bins (lower post residual already does this,
    // but sharpen non-linearity for near-perfect fits).
    if pr <= 3 {
        score -= 60.0;
    }

    score
}

