        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 1.0 ;
    }

    // lookahead: can next item reuse the leftover space?
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 15.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
