    }

    // mutation: penalize leaving a residual that is just barely too small for the
    // next item (wasted slot), scaled by how much space is stranded
    if nx > 0.0 && pr > 0.0 && pr < nx && (nx - pr) <= 2.0 {
        score += 4.0 * (1.0 - progress) ;
    }

    // mutation: when many bins can fit the item, prefer the tightest fit more strongly
    if fitting_bins_count >= 4 && pr <= 5.0 && pr > 0.0 {
        score -= 1.5 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    let next = next_item_size as f64;
    let pr = post_residual as f64;
    if next > 0.0 && pr > 0.0 && pr < next {
        // Residual too small for the next item: pure dead space unless it can
        // still absorb a future item; penalize heavily, scaled by gap smallness.
        let gap_ratio = 1.0 - pr / next.max(1.0);
        score += 40.0 * gap_ratio;
