    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones and
    // encourage filling existing ones; few open bins -> new bins are cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (pr / bin_capacity as f64) * 6.0;
    if bin_residual == bin_capacity {
        score += 5.0 + pressure * 8.0;
    }

    // Prefer bins whose residual deviates from the mean in a "fillable" way:
    // bins with residual near item_size are ideal completions.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * diff;

    // Early stream: keep residuals flexible (moderate penalty for very tight
    // fills that leave nothing); late stream: squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && pr > 0.0 && pr < 10.0 {
        score += 6.0 * (1.0 - progress / 0.3);
    }

    // Reward leaving room exactly for the next item (perfect lookahead fit).
    if next > 0.0 && pr == next {
        score -= 12.0;
    }

    score
}

