    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.0;
    }

    // Smooth fill bonus
    let fill_ratio = 1.0 - pr / cap;
    score -= 20.0 * fill_ratio * fill_ratio * fill_ratio;

