    // Penalize residuals that cannot fit the lookahead item (smooth logistic-ish falloff).
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 20.0 * (1.0 - fits_next) * (1.0 - (-gap * 8.0).exp());
        // Reward if post residual still fits next item well
        score -= 15.0 * fits_next * (pr / cap);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Slight preference to fill bins when many are open (consolidation).
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 3.0;

    // Pull toward mean residual to balance bin loads smoothly.
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: make empty bins moderately attractive only when they beat bad fits.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    // deviation from mean residual: prefer bins near the pack norm
    score += 0.011 * (mean_residual - br) . abs () ;

    // reward tight fits (post_residual near 0)
    if pr == 0.0 {
        score -= 28.0 ;
    } else if pr <= 2.0 {
        score -= 14.0 ;
    } else if pr <= 5.0 {
        score -= 8.5 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 1.0 ;
    }

    // lookahead: can next item reuse the leftover space?
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 15.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after >= 1.0 && after <= 12.0 {
                score -= 6.5 ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            // two-item lookahead proxy: leftover after next item still fits a small third
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - progress) ;
            }
        } else {
            // placing here strands space that next item cannot use
            score += (nx - pr) * (0.9 + 0.9 * (1.0 - progress)) ;
            // but if the stranded space is tiny, the cost is low
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalty: small residual that next item cannot use
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    // scarcity: with very few fitting bins, favor bins that can also host the next item
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }

    // waste-avoidance: penalize bins whose residual is just above a likely-small next item
    if nx > 0.0 && pr > nx && pr - nx < 3.0 && pr > 12.0 {
        score += 1.2 ;
    }

    // new-bin candidate: empty bin has br == cap, pr == cap - it
    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        // discourage opening a new bin unless open-bin fits are poor
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.5 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            // scale new-bin aversion with how good the best open fit already is
            let open_pressure = if fitting_bins_count >= 3 { 7.5 } else { 4.5 } ;
            score += open_pressure + 4.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "clean" is the leftover space?
    // Residuals divisible by common item sizes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let mut harmony: f64 = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmony += 2.0; }
        if pr % 20 == 0 { harmony += 1.5; }
        if pr % 25 == 0 { harmony += 1.0; }
        if pr % 50 == 0 { harmony += 2.0; }
        // integer-division class: residual bucket by fifths of capacity
        let fifth = (pr * 5) / bin_capacity;
        harmony += match fifth {
            0 => 3.0,   // tiny leftover: nearly perfect fit
            1 => 0.5,
            2 => 1.0,
            3 => -0.5,  // awkward ~60% leftover
            _ => 1.5,   // large leftover: still flexible
        };
    } else {
        harmony += 6.0; // perfect closure is excellent
    }
    score -= harmony;

    // Next-item lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0;
        } else if next_item_size < pr {
            // fractional fit quality of next item into post_residual
            let fit_q = next_item_size as f64 / pr as f64;
            if fit_q > 0.7 { score -= 4.0 * fit_q; }
            else { score -= 1.0 * fit_q; }
        } else {
            // next item won't fit here; penalize large wasted residuals mildly
            score += 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: only attractive when current fit is terrible
    // (large post_residual relative to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_frac = post_residual as f64 / cap;
        // fresh bin baseline; penalize so it's chosen only when fits are bad
        score = cap * 0.9 + waste_frac * 10.0 - (1.0 - progress) * 5.0;
        if post_residual == 0 { score = cap * 0.5; }
    }

    // Mild penalty for leaving residual far from mean (fragmentation control)
    score += 0.3 * ((post_residual as f64 - mean_residual) / cap).abs();

    // Prefer filling bins when many are open (reduce open-bin sprawl)
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

