pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (1..=9) are nearly unusable
    // for items >= 10, so penalize them heavily; larger residuals are fine.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (1.0 + (10.0 - post_residual as f64) / 10.0);
    } else if post_residual > 9 && post_residual < 20 {
        // Moderately risky gap: could fit small items only.
        score += 12.0 * (20.0 - post_residual as f64) / 11.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Large residual = flexible space; mild reward scaled to size.
        score -= (post_residual as f64 - 20.0).min(40.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (which wastes the residual entirely).
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits: nudge score.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 70.0; // chain of perfect fits
            } else if slack <= 9 {
                score += 25.0; // next item leaves dead space here, discourage
            } else {
                score -= 10.0;
            }
        } else if post_residual > 0 {
            // Next item cannot use this gap: gap is likely dead.
            score += (post_residual as f64).min(30.0) * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, opening new is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= pressure * 3.0;
    }

    // Mean residual coupling: if this bin's residual is far below average,
    // it is a "nearly full" outlier — reward closing it out.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev.min(50.0) * 0.4;
    } else {
        score += (-dev).min(50.0) * 0.1;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when current bins are badly fragmented or none fit well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream is not
        // meaningful, but early pressure keeps bin count low.
        let mut new_bin_score = 55.0;
        // If many bins fit the item, opening a new bin is wasteful.
        new_bin_score += 30.0 * (fitting_bins_count as f64).min(4.0);
        // If the item is huge relative to capacity, new bin is safer
        // (avoid tiny leftovers in existing bins).
        if item_size >= bin_capacity * 7 / 10 {
            new_bin_score -= 35.0;
        }
        // If few bins fit and mean residual is small (bins nearly full),
        // opening a new bin is reasonable.
        if fitting_bins_count <= 1 {
            new_bin_score -= 40.0;
        }
        if mean_residual < 15.0 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    score
}

