pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: perfect match is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            // Exact fit for the next item: strongly favor this bin.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement; reward closeness.
            score -= 25.0 - diff * 0.5;
        } else {
            // Next item would NOT fit: penalize proportionally to leftover waste.
            score += diff * 0.4;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average waste is good, more than average is bad.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid opening extra bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 8.0;
    }

    // Small penalty for very large dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // nearly perfect fill
    }

