}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize large dead space that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // perfectly sealed bin
    } else if post_residual < 20 {
        score -= 6.0;
    } else if post_residual < 40 {
        score += 4.0;
    } else {
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps future options open
            // extra reward if residual matches next item closely
            let gap = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 3.0; // kills future usability of this bin
        }
    } else {
        // last item: seal bins as tightly as possible
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
