    // Many open bins: encourage consolidation into existing bins
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score -= 0.8 * pressure * (item_size as f64 / bin_capacity as f64);

    // Time horizon: early stream -> be conservative (favor new bins when fit is bad);
    // late stream -> squeeze everything into open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (keeps a balanced portfolio of partial bins)
    let dev = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();
    score += 6.0 * dev;

    // Empty new-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0; // item is small; a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
