    if br == cap {
        let avg_pressure = mean_residual / cap;
        let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 26.0 + 18.0 * avg_pressure + 14.0 * (1.0 - progress) + 3.0 * open_pressure.min(4.0);
        if nx > 0.0 && pr >= nx {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
        // If several open bins already fit this item, definitely avoid a new bin
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let nx = next_item_size as f64;

    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: penalize leftover space, more strongly later in the stream
    let mut score = pr * (1.0 + 0.9 * prog2 + 0.7 * prog3);

    // Discrete near-perfect-fit bonuses (borrowed from best heuristic)
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.0;
    }

    // Reward high fill ratio with a smooth cubic bonus
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: dead space that cannot host the next item is wasted
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0); // reward leaving near-exact room
            let after = pr - nx;
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0; // leftover still usable by typical items
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after == 0.0 {
                score -= 3.0;
            }
        } else if pr > 0.0 {
            // penalize unusable sliver proportional to what's stranded
            score += (nx - pr) * (1.1 + 0.9 * (1.0 - progress));
            if pr < 10.0 {
                score += 2.5 + 1.5 * (1.0 - progress);
            }
        }
    } else {
        // Last item: pure tightness packing
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // Mean-residual alignment bonus (small absolute deviation)
    score += 0.011 * (mean_residual - br).abs();

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if br == cap {
        let avg_pressure = mean_residual / cap;
        score += 22.0 + 18.0 * avg_pressure + 12.0 * (1.0 - progress);
        if nx > 0.0 && pr >= nx {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: dead space squared, amplified late in the stream
    let waste = pr / cap;
    score += 12.0 * waste * waste * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size)
    score -= 8.0 * (it / cap) * (1.0 - waste) * (1.0 - waste);

    // Smooth coupling: prefer bins whose residual is close to the item
    let gap = (bin_residual as f64 - it) / cap;
    score += 5.0 * gap * gap;

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (nx / cap) * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * (nx / cap) * waste;
        }
    }

    // Mild pressure toward consolidating many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * waste;

    // Prefer bins with residual near mean residual (smooth kernel)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

