pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0), tiny dead space, mid, large
    let pr = post_residual as i64;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 3 {
        score += 25.0; // near-perfect but wasted sliver
    } else if pr <= 10 {
        score -= 10.0; // small residual may host tiny future items
    }

    // Modulo arithmetic on capacity fractions: residual divisible by small classes is more reusable
    if pr > 0 {
        let pri = post_residual;
        let div_bonus = if pri % 10 == 0 { 12.0 }
            else if pri % 5 == 0 { 8.0 }
            else if pri % 2 == 0 { 4.0 }
            else { 0.0 };
        score -= div_bonus;

        // Prime-ish / odd residuals are dead space prone
        if pri % 2 == 1 && pri < 20 { score += 9.0; }
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 && (next_item_size as f64) <= (post_residual as f64) {
        score -= 18.0 + 0.25 * (next_item_size as f64);
        // harmonic match: next item exactly consumes residual class
        if post_residual % next_item_size.max(1) == 0 {
            score -= 14.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to how close it is
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 10.0 { score += 6.0 + gap; }
    }

    // Integer-division thresholds on bin_residual fullness
    let fullness_class = bin_residual / (bin_capacity / 4).max(1); // 0..4 quartile class
    match fullness_class {
        0 => score += 4.0,          // nearly empty open bin: mild penalty vs new bin
        1 => score -= 3.0,
        2 => score -= 6.0,
        3 => score -= 9.0,
        _ => score -= 12.0,         // nearly full: strong preference
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        score += 20.0 - crowded.min(20.0);
        // early stream: opening fresh bins is fine
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - t);
    }

    // Pull toward mean residual: avoid fragmenting distribution
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    // deviation from mean residual: prefer bins near the pack norm
    score += 0.011 * (mean_residual - br) . abs () ;

    // reward tight fits (post_residual near 0)
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 1.0 ;
    }

    // lookahead: can next item reuse the leftover space?
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 3.5 ;
            } else if after >= 1.0 && after <= 12.0 {
                score -= 6.0 ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.0 ;
            }
            // two-item lookahead proxy: leftover after next item still fits a small third
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - progress) ;
            }
        } else {
            // placing here strands space that next item cannot use
            score += (nx - pr) * (0.9 + 0.9 * (1.0 - progress)) ;
            // but if the stranded space is tiny, the cost is low
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalty: small residual that next item cannot use
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    // scarcity: with very few fitting bins, favor bins that can also host the next item
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }

    // new-bin candidate: empty bin has br == cap, pr == cap - it
    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        // discourage opening a new bin unless open-bin fits are poor
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.5 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items are wasted.
    // Penalize post_residual that falls into an "unusable" band (small but nonzero),
    // since nothing in [1,100] range of practical item sizes will fill it well.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 - pr * 2.0; // worst near post_residual ~ 10
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 60.0;
    } else if post_residual <= 25 {
        // Moderately awkward gap: mild penalty, scaled by tightness
        score += (25.0 - pr) * 0.6;
    } else {
        // Large residual is reusable: reward proportionally
        score -= pr * 0.15;
    }

    // Reward filling the bin tightly relative to current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Open-bin pressure: when many bins are open, discourage spreading items
    // across bins; prefer consolidating into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 1.5 * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin fits well (i.e., post_residual here is
    // large and existing bins are poor). Otherwise keep it slightly unattractive
    // to encourage filling existing bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // But if the item would leave a small dead space in every other bin,
        // a fresh bin becomes preferable: discount when mean residual is small.
        score -= (100.0 - mean_residual.min(100.0)) * 0.25;
        // Lookahead: if next item is large, having a fresh bin helps.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item exactly fits the post_residual of this bin,
    // big bonus for this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (next_item_size as f64) / (post_residual as f64);
        if next_tight > 0.85 {
            score -= 25.0;
        }
    }
    // If next item would NOT fit in post_residual, mild penalty for wasting potential.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 12 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: perfect chain fit (post_residual == next_item_size) is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 25.0; // exact 2-chain
        } else if pr > nxt {
            // next item fits after this one; reward closeness of the leftover gap
            let gap = pr - nxt;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit after this placement -> dead space risk
            score += 8.0 + 0.3 * nxt * (pr / bin_capacity as f64);
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, tighten discrimination on fit quality
        score += 2.0 * (fitting_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with residuals below mean (consolidate small gaps), avoid large-residual bins when fit is loose.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // New-bin candidate handling: only allow opening a new bin when no open bin offers
    // a decent fit (post_residual would be very small) or lookahead says we need fresh space.
    if bin_residual == bin_capacity {
        let pr = post_residual as f64;
        if next_item_size > 0 && (next_item_size as f64) >= pr {
            // fresh bin can also host the next item -> attractive
            score -= 10.0;
        } else {
            // default: discourage opening new bins
            score += 20.0;
        }
    }

    // Late in the stream, close out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot use the leftover, penalize large leftovers slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins would waste a lot of space
    // or when the current bin is a poor fit.
    if bin_residual == bin_capacity {
        let best_open_waste = if fitting_bins_count > 0 {
            // unknown per-bin waste; approximate with mean residual minus item
            (mean_residual - item_size as f64).max(0.0)
        } else {
            100.0
        };
        // Prefer new bin if existing bins have large residual (bad fits).
        let pressure = best_open_waste / bin_capacity as f64;
        score = 60.0 + 80.0 * (1.0 - pressure);
        // Early in the stream, opening bins is cheap; later, be conservative.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins with small mean residual -> avoid new bins.
        score += mean_residual * 0.3;
    } else {
        // Slight preference for bins with smaller residuals among open bins (best-fit flavor).
        score += (bin_residual as f64) * 0.05;
    }

    // Prefer bins whose residual deviates favorably from the mean (more filled bins).
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Mild penalty for spreading across too many bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: waste from post residual, non-linearly shaped by stream progress.
    // Early: mild quadratic waste; late: strong cubic waste (dead space hurts more).
    let base = pr * (1.0 + 0.9 * progress) + 0.0035 * pr * pr * (0.5 + progress);

    // Cubic coupling: large residuals late in the stream are heavily penalized.
    let norm_pr = pr / cap;
    let cubic = 12.0 * norm_pr * norm_pr * norm_pr * (0.4 + 0.6 * progress);

    // Fit quality: reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    let fit_bonus = -8.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -14.0 } else { 0.0 };

    // Lookahead: reward if next item fits into post residual (chain packing).
    let lookahead = if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            -6.0 * (1.0 - (next_item_size as f64) / cap)
        } else {
            // Penalize residuals that are too small for the next item (dead space).
            3.0 * (1.0 - pr / (next_item_size as f64))
        }
    } else {
        0.0
    };

    // Mean residual context: prefer bins close to the mean (balanced packing),
    // stronger early when many bins remain to be filled.
    let dev = (pr - mean_residual).abs();
    let balance = -0.6 * dev * (1.0 - progress);

    // New empty bin candidate: penalize unless residuals are large / stream is late.
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_penalty = is_new * (10.0 + 0.05 * (open_bins_count as f64) - 8.0 * progress
        + 0.15 * mean_residual * (1.0 - progress));

    // Slight preference for filling fewer bins overall.
    let count_pull = 0.02 * (open_bins_count as f64) * is_new;

    base + cubic + fit_bonus + last_chance + lookahead + balance + new_penalty + count_pull
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    // deviation from mean residual: prefer bins near the pack norm
    score += 0.011 * (mean_residual - br) . abs () ;

    // reward tight fits (post_residual near 0)
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 1.0 ;
    }

    // lookahead: can next item reuse the leftover space?
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after >= 1.0 && after <= 12.0 {
                score -= 6.0 ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.0 ;
            }
            // two-item lookahead proxy: leftover after next item still fits a small third
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - progress) ;
            }
        } else {
            // placing here strands space that next item cannot use
            score += (nx - pr) * (0.9 + 0.9 * (1.0 - progress)) ;
            // but if the stranded space is tiny, the cost is low
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalty: small residual that next item cannot use
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    // scarcity: with very few fitting bins, favor bins that can also host the next item
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }

    // new-bin candidate: empty bin has br == cap, pr == cap - it
    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        // discourage opening a new bin unless open-bin fits are poor
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.5 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.0 * (1.0 - progress) ;
        }
    }

    // late-stream consolidation: when few items remain, prefer near-perfect fills harder
    if progress > 0.75 && pr <= 4.0 {
        score -= 2.0 * (progress - 0.75) * 4.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let nx = next_item_size as f64;
    let prog2 = progress * progress;

    // Base: penalize leftover space, ramping up through the stream
    let mut score = pr * (1.0 + 0.9 * prog2);

    // Reward high fill ratio with a smooth cubic bonus
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Tiered exact/near-fit bonus
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.0;
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0); // reward leaving near-exact room
            let after = pr - nx;
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0; // nicely reusable remainder
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after == 0.0 {
                score -= 3.0;
            }
        } else if pr > 0.0 {
            // stranded sliver: penalize relative to its size and lateness
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
        // small sliver that cannot host next item, extra late penalty
        if pr > 0.0 && pr < 10.0 && nx > pr {
            score += 2.5 + 1.5 * (1.0 - progress);
        }
    } else {
        // Last item: pure tightness packing
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if br == cap {
        let avg_pressure = mean_residual / cap;
        let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 26.0 + 18.0 * avg_pressure + 14.0 * (1.0 - progress) + 3.0 * open_pressure.min(4.0);
        if nx > 0.0 && pr >= nx {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
        // If several open bins already fit this item, definitely avoid a new bin
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into capacity fractions.
    // Classes: [0..=5] perfect-ish, (5..=15] tight, (15..=40] medium, (40..=70] loose, >70 bad.
    let post_class: u32 = if post_residual <= 5 { 0 }
        else if post_residual <= 15 { 1 }
        else if post_residual <= 40 { 2 }
        else if post_residual <= 70 { 3 }
        else { 4 };

    // Reward tight fits strongly (dead-space minimization).
    match post_class {
        0 => score -= 40.0,
        1 => score -= 22.0,
        2 => score -= 5.0,
        3 => score += 6.0,
        _ => score += 12.0,
    }

    // Harmonic compatibility: does next item fit harmonically into post_residual?
    // Reward if next_item_size <= post_residual (chained fit), penalize near-miss waste.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // How much of the post residual the next item consumes: modulo-style coupling.
            let next_fit_ratio = next_item_size as f64 / post_residual as f64;
            if next_fit_ratio > 0.8 {
                score -= 18.0; // next item nearly fills leftover: excellent chain
            } else if next_fit_ratio > 0.5 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item won't fit: leftover becomes dead space unless another bin takes next.
            let waste = (next_item_size - post_residual) as f64;
            score += (waste * 0.15).min(15.0);
        }
    }

    // Integer-division thresholds on bin_residual: how "deep" into the bin we are.
    let depth = bin_residual / (bin_capacity / 4); // 0..=4 quarters
    score -= depth as f64 * 3.0; // prefer filling fuller (lower residual) bins

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive if all open bins are crowded
    // and the current fit is poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 15.0 && open_bins_count > 0;
        let poor_fit = post_class >= 3;
        if crowded && poor_fit {
            score -= 30.0; // prefer fresh bin
        } else {
            score += 35.0; // prefer existing bins otherwise
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;

    // Small tie-break toward bins already below mean residual (balance residual mass).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
