    score -= 0.3 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Relative to mean residual: bins below mean residual are more "loaded",
    // finishing them off is good; bins above mean are wasteful targets
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Early in stream: be more willing to open fresh bins for large items
    if bin_residual == bin_capacity {
        let new_bin_bonus = 15.0 * (1.0 - progress) + 5.0;
        score -= new_bin_bonus;
        // opening a new bin is bad if many bins are open and nearly empty
        score += 0.2 * open_bins_count as f64;
    }

    // Late stream: consolidate, discourage new bins
    if bin_residual == bin_capacity && progress > 0.7 {
        score += 10.0 * progress;
    }

    score
}

