    // Lookahead coupling: if next item fits the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= mean_residual {
        // Next item won't fit here but could elsewhere; mild penalty.
        score += 5.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
