    score += 0.013 * (mean_residual - br) . abs () ;

    // reward near-perfect compaction
    if pr == 0.0 { score -= 26.0 ; }
    else if pr <= 2.0 { score -= 13.5 ; }
    else if pr <= 5.0 { score -= 8.5 ; }
    else if pr <= 9.0 { score -= 3.5 ; }

    // lookahead: prefer bins whose post-residual can host the next item
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after >= 1.0 && after <= 12.0 { score -= 6.5 ; }
            if (pr - nx) . abs () < 0.5 { score -= 5.5 ; }
            if after == 0.0 { score -= 3.5 ; }
            // if the leftover after next item matches item_size again, chain bonus
            if after >= it && after - it <= 10.0 { score -= 2.5 * (1.0 - progress) ; }
        } else if pr > 0.0 {
            // wasted-space penalty scaled by remaining stream and item tightness
            let waste = (nx - pr) / cap ;
            score += (nx - pr) * (0.9 + 0.9 * (1.0 - progress)) + 4.0 * waste * (1.0 - progress) ;
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // awkward small residual that next item cannot use
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }

    // low-utility large residual in a mostly empty bin
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    // scarce alternatives: commit to the only fitting bin when it hosts next item
    if fitting_bins_count <= 1 && pr > 0.0 && pr >= nx && nx > 0.0 {
        score -= 4.5 * (1.0 - progress) ;
    }
    // many alternatives: discourage leaving tiny unusable slivers
    if fitting_bins_count > 4 && pr > 0.0 && pr < 4.0 && nx > pr {
        score += 1.0 ;
    }

    // new-bin candidate: discourage unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 { (mean_residual / cap) . clamp (0.0 , 1.0) } else { 0.0 } ;
        score += 6.0 + 8.0 * frag ;
        if nx > 0.0 && bin_capacity >= nx { score -= 2.0 * (1.0 - progress) ; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

