    // the post-residual (perfect chaining), penalize when next item cannot
    // use the leftover space (dead space for one step).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            let gap = post - nxt;
            score -= 120.0 * (1.0 - gap / post.max(1.0)); // partial reuse
        } else {
            // next item won't fit in leftover: dead space for one step
            score += 40.0 * (nxt - post) / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: keep residual distribution
    // balanced, but tolerate tighter-than-average bins (good packing).
    let mean = mean_residual.max(1.0);
    if (post_residual as f64) < mean {
        score -= 30.0 * (mean - post_residual as f64) / mean;
    } else {
        score += 20.0 * ((post_residual as f64) - mean) / mean;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large (would leave
    // big unusable residue in existing bins) or no good fit exists.
    if bin_residual == bin_capacity {
