    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 / next_item_size as f64).ln().max(0.0);
        } else {
            score += 6.0;
        }
