            let after = pr - nx;
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0; // residual still usable by typical items
            }
            if after == 0.0 {
                score -= 3.0; // perfect two-item fill
            }
        } else if pr > 0.0 {
            // penalize unusable sliver proportional to what's stranded
            score += (nx - pr) * (1.1 + 0.9 * (1.0 - progress));
        }
    } else {
