    // Smooth polynomial coupling of post-residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + p2) * cap;
    score -= 8.0 * norm_item * (1.0 - norm_pr) * (1.0 + p3) * cap;

    // Dead-space penalty: small post-residual relative to minimum plausible item
    let dead = norm_pr * (1.0 - norm_pr * 4.0).max(0.0);
    score += 6.0 * dead * cap * (1.0 - p3);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post-residual well
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        score -= 10.0 * (1.0 - fit_gap / cap).max(0.0);
    } else {
        score += 2.0 * norm_pr * cap;
    }

    // Mean residual coupling: prefer bins close to mean residual state
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * (1.0 + p2);

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly late unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
        score -= 6.0 * norm_item * progress;
    }

    // Encourage tight fills as stream progresses
    score -= 5.0 * (1.0 - norm_pr) * p3 * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;

    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: penalize leftover space, more strongly later in the stream
    let mut score = pr * (1.0 + 0.9 * prog2 + 0.7 * prog3);

    // Discrete near-zero residual bonuses (borrowed idea): exact fills matter most
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.0;
    }

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 12.0 * fit * fit;

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: dead space that cannot host the next item is wasted
    let nx = next_item_size as f64;
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            // reward leaving room that is itself a small sliver (future-tight)
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after == 0.0 {
                score -= 3.0;
            }
        } else if pr > 0.0 {
            // stranded sliver below next item size
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    } else {
        // Last item: pure tightness packing
        score -= 10.0 * fill_ratio;
    }

    // Mid-size dead space penalty: residual small but too big for next item
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 9.0 && pr < 0.25 * cap {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if br == cap {
        let avg_pressure = mean_residual / cap;
        score += 22.0 + 18.0 * avg_pressure + 12.0 * (1.0 - progress);
        if nx > 0.0 && pr >= nx {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity divided into 5 classes
    let item_class = item_size / 20; // 0..4
    let next_class = if next_item_size > 0 { next_item_size / 20 } else { 0 };

    // Reward tight fits: post_residual modulo classes create dead-space bands.
    // Residuals < 10 are near-perfect; residuals in [10, 20) are the worst
    // because they cannot host any item of the minimum size.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score += 15.0; // dead space band: penalize
    } else {
        // Smooth reward for larger usable residuals, with harmonic modulation
        let mod_term = (post_residual % 10) as f64;
        score -= (post_residual as f64) * 0.15 + mod_term * 0.3;
    }

    // Complementarity: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Harmonic pairing: classes summing to capacity/20*5 (i.e. complement classes)
            if (item_class as u32).wrapping_add(next_class) == 3 {
                score -= 5.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer filling it rather than opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Open new bin only when mean residual across open bins is low (crowded)
        score += 30.0 - pressure * 40.0 + progress * 5.0;
        // Large items justify fresh bins more
        if item_class >= 3 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (spreading load evenly)
    score += ((mean_residual - bin_residual as f64) * 0.05).clamp(-3.0, 3.0);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
