    score += 0.011 * (mean_residual - br) . abs () ;

    // reward tight fits (post_residual near 0)
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 14.0 ;
    } else if pr <= 5.0 {
        score -= 8.5 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 1.0 ;
    }

    // lookahead: can next item reuse the leftover space?
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 15.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after >= 1.0 && after <= 12.0 {
                score -= 6.5 ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
