    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    // scarcity: with very few fitting bins, favor bins that can also host the next item
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }

    // new-bin candidate: empty bin has br == cap, pr == cap - it
    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        // discourage opening a new bin unless open-bin fits are poor
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.5 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            // when the item nearly fills a fresh bin, opening is genuinely good
            if pr <= 4.0 {
                score -= 20.0 ;
            } else {
                score -= 12.0 ;
            }
        } else {
            // scale reluctance with how much space would be stranded in open bins
            score += 6.0 + 4.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 {
        score += 60.0; // tiny dead space is worthless
    } else if post_residual < 20 {
        score += 25.0 * (20 - post_residual) as f64 / 10.0;
    } else if post_residual <= 30 {
        // gap in [20,30] still risky for items >=10
        score += 8.0;
    }

    // Reward very tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        score -= 15.0;
