    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this gap -> gap becomes dead space
        score += post_residual as f64 * 0.5;
    }

    // New-bin candidate: penalize opening new bins, more so when many open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
    }

    // Open-bin pressure: mild penalty scaled by number of open bins
    // (consolidate into fewer bins when feasible).
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins below mean residual (keep spread even).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.1;
    }

    score
}

