pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly placement: reward proportionally to how snugly
            // the next item fills the leftover space.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 + 80.0 * snug;
        } else {
            // Next item won't chain here: penalize dead space creation,
            // scaled by how much unusable gap we leave behind.
            let dead = (post_residual as f64).min(next_item_size as f64 - 1.0);
            score += 0.5 * dead;
        }
    }

    // Compare against mean residual: placing into a bin with residual far
    // above the mean wastes the "large holes"; prefer bins below the mean.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin is attractive only if the item
    // is large and no good chaining is available; make the empty-bin call
    // mildly expensive so we only open when open bins are truly bad fits.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 30.0 * tightness;
        // Late in the stream, discourage opening new bins even more.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
    }

    // Small bonus for filling bins tightly relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized fit quality: how well the item fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio;

    // Penalize dead space quadratically when the leftover is unusable
    // (smaller than the smallest plausible item ~ item_size or < 10).
    let dead = post_residual as f64;
    if dead > 0.0 {
        let usable = dead >= 10.0;
        if !usable {
            score += 25.0 + dead * 0.5;
        } else {
            score += 0.02 * dead * dead * (1.0 - fit_ratio);
        }
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
