        // Last item in stream: strongly prefer tightest fit.
        score -= 30.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (favor tight fits less aggressively); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // Global state coupling: if mean residual across open bins is high,
    // encourage using bins with residual far from the mean (balance workload);
    // if mean residual is low, prefer the emptiest usable bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if mean_residual > 40.0 {
        score -= 0.10 * dev;
    } else {
        score += 0.05 * dev;
    }

