    // and this bin is fresh (encourages consolidation).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to capacity, opening a new bin
        // is often fine — soften the penalty.
        score -= 0.06 * item_size as f64;
