        1 => score += 2.0,
        2 => score -= 1.0,
        _ => score -= 2.0,                           // roomy leftover
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 7.0;                            // chains nicely
            let gap = pr - next_item_size;
            if gap % 10 == 0 { score -= 2.0; }       // harmonic chain alignment
        } else {
            score += 5.0;                            // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are congested with small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        score = 20.0 + 30.0 * (1.0 - congestion) + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 { score -= 25.0; }
    } else {
        // Mild pressure toward consolidating into existing bins when many are open.
        score += 0.15 * open_bins_count as f64;
        score += 0.3 * (bin_residual as f64 - mean_residual); // prefer above-average residual bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead" residuals: small gaps that few future items can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 2.5 } else if post_residual < 25 { 1.5 } else { 0.0 };
        score += dead * post_residual as f64;
    } else {
        // Perfect fit reward
        score -= 15.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading too thin,
    // but allow opening a new bin when the only fitting bin would waste space.
    if bin_residual == bin_capacity {
        // New-bin candidate: mildly attractive unless it creates dead space
        score += 5.0 + 0.3 * open_bins_count as f64;
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid opening a bin
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty for trapping it
        score += 3.0;
    }

    // Mean residual coupling: prefer bins close to mean when residuals are large
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * diff;

    // Early stream: be more selective about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * (1.0 - progress) * fill_ratio;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    // deviation from mean residual: prefer bins near the pack norm
    score += 0.011 * (mean_residual - br) . abs () ;

    // reward tight fits (post_residual near 0)
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    // lookahead: can next item reuse the leftover space?
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.5 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            // two-item lookahead proxy: leftover after next item still fits a small third
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
        } else {
            // placing here strands space that next item cannot use
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            // but if the stranded space is tiny, the cost is low
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalty: small residual that next item cannot use
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    // dead-space ratio penalty on non-empty bins: residual mostly unusable
    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
    }

    // scarcity: with very few fitting bins, favor bins that can also host the next item
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    // abundance: with many fitting bins, mild bonus for leaving room for next item
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    // new-bin candidate: empty bin has br == cap, pr == cap - it
    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        // open a new bin only when open-bin fits are poor or strand too much space
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
