            score -= 4.0 ;
        }
        // combined: fresh bin that hosts next item with a tight after-fit is attractive
        if nx > 0.0 && pr >= nx && (pr - nx) <= 6.0 {
            score -= 2.5 * (1.0 - progress) ;
        }
