        if pr > 0.0 && pr < 6.0 && nx > pr {
            score += 1.2 * (1.0 - progress) ;
        }
        // combined: open bins whose residual exactly absorbs the next item
        // with zero leftover are strong compaction candidates
        if nx > 0.0 && pr == nx {
            score -= 3.0 ;
        }
    }

    score
}

