    // Relative to mean residual: prefer bins tighter (less residual) than average
    score -= (mean_residual - post_residual as f64) * 3.0;

    // Penalize large dead space creation
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small residual is still potentially usable
    }
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 20.0; // dead space smaller than any plausible next item
    }

    // New bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 250.0;
        // but if no other bin fits, opening is necessary
        if fitting_bins_count == 0 {
            score -= 1000.0;
