    // Classify post_residual into "usable bands" via integer division thresholds.
    // Bands: [1..=10] tiny dead space, [11..=25] small, [26..=50] medium, [51..=100] large.
    let band = post_residual / 26; // 0..3 harmonic class
    score -= (band as f64) * 30.0;

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularities (10, 20, 25) are more likely to be filled by future items.
    let pr = post_residual as i64;
    let mut harmony: f64 = 0.0;
    if pr % 10 == 0 && pr > 0 { harmony += 12.0; }
    if pr % 20 == 0 && pr > 0 { harmony += 8.0; }
    if pr % 25 == 0 && pr > 0 { harmony += 10.0; }
    if pr % 50 == 0 && pr > 0 { harmony += 10.0; }
    score -= harmony;

    // Lookahead coupling: does next_item_size fit exactly or harmonically?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // next item fills this bin perfectly
        } else if next_item_size < post_residual {
            let nxt = next_item_size as i64;
            // harmonic match: next item leaves a harmonic residual again
            let nxt_post = pr - nxt;
            if nxt_post % 10 == 0 || nxt_post % 25 == 0 {
                score -= 40.0;
            }
            // penalize if next item would leave tiny dead space
            if nxt_post > 0 && nxt_post < 10 {
                score += 25.0;
            }
        } else {
            // next item does NOT fit here: this residual is a trap for the lookahead
            score += 15.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin is a valuable resource; only
    // prefer it when the fit here would be poor (large disharmonic residual).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 40 && post_residual % 10 != 0 && post_residual % 25 != 0;
        if poor_fit {
            score -= 60.0; // open fresh bin rather than shatter residual
        } else {
            score += 150.0; // keep existing bin, it fits acceptably
        }
    }

    // Late in the stream, tighten up: waste matters more, prefer tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual.min(100)) as f64 * progress * 0.5;

    // Prefer bins already below mean residual (consolidate emptier bins' use).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
