pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (post_residual 1..=10) are the worst outcome.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 25 {
        // Medium gaps are moderately wasteful.
        score += 0.5 * (post_residual as f64 - 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate handling: opening a new bin wastes the residual of this bin;
    // only attractive when residual is tiny (bin nearly full) or item leaves good space.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: grows with number of open bins and remaining stream.
        score += 25.0 + 0.5 * open_bins_count as f64 + 15.0 * (1.0 - progress);
        // But if current bin would leave a dead gap, new bin becomes attractive.
        if post_residual > 0 && post_residual <= 10 {
            score -= 55.0;
        }
        // New bin is fine if the item is large (little alternative use of residual anyway).
        if item_size >= 70 {
            score -= 10.0;
        }
    } else if bin_residual <= 15 {
        // Nearly-full bin: using it is cheap and frees bin count.
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: next item fills post_residual perfectly
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves a third residual: penalize growing dead space
        let third = post_residual - next_item_size;
        score += third as f64 * 1.5;
        // Bonus if next item fills most of the remaining space
        let fill_frac = next_item_size as f64 / post_residual as f64;
        score -= fill_frac * 40.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally
        score += 25.0;
    }

    // Reward tight fits relative to mean residual
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Penalize bins whose residual deviates far above mean (fragmentation risk)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.4;
    } else {
        score += dev * 0.2;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer it only when residual after placement is small
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Late in stream: prefer tighter packing, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;
    if open_bins_count > 8 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize small dead space that no future item (>=1) can use efficiently.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits in the post residual, reward; if it would
    // be wasted, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // wasted capacity relative to next item
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
        // If next item exactly fills post residual, big bonus (perfect chain).
        if next_item_size == post_residual && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Global state: prefer using bins with below-average residual when many
    // bins are open (balance), but keep large-residual bins for big future items.
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Time horizon: early in stream, be conservative (favor new bins less);
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate: only attractive when current bin residual is small
    // relative to item size (poor fit) or many bins already jammed.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = waste + 40.0 - 25.0 * progress;
        if fitting_bins_count <= 1 {
            // no real alternative: opening new bin is fine
            score -= 35.0;
        }
        if item_size >= 50 {
            score -= 10.0; // big items deserve fresh bins
        }
    }

    score
}

