pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // base: wasted space, weighted quadratically by progress
    let mut score = pr * (1.0 + 2.0 * progress * prn);

    // smooth polynomial coupling of post_residual with progress
    let t = prn;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like, no piecewise constants
    score += 30.0 * poly * (0.5 + progress);

    // reward tight fits: subtract more when post_residual is small
    score -= 25.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + 0.5 * progress);

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // lookahead: penalize if post_residual can't fit next item but is small-ish waste
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 10.0 * (nx - pr) / cap;
        } else {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // penalize many open bins slightly to encourage consolidation
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // mean residual coupling: prefer bins deviating below mean (tighter)
    score += 0.3 * (mean_residual - pr);

    score
}

