            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.0 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin: leftover hosts next item then nears zero
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        // combined feature: open bin whose residual after this item still
        // tightly hosts the next item is doubly valuable when bins are scarce
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        // dead-space ratio guard: penalize bins whose remaining fraction
        // after placement is tiny but nonzero (unusable slivers)
        if pr > 0.0 && pr < 3.0 && nx > pr {
            score += 1.0 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: strongly reward when next item exactly fills the leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next item fits, but leave some slack; reward proportionally to how much is consumed
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fill;
            // penalize tiny dead space left after the lookahead placement
            let after = post_residual - next_item_size;
            if after <= 10 {
                score -= 60.0;
            }
        } else {
            // next item cannot use this residual: dead-space penalty grows with slack
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Small residuals are valuable targets; penalize creating awkward leftovers.
    if post_residual < 10 {
        score -= 80.0;
    } else if post_residual < 20 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New empty bin candidate: make it unattractive unless it would be a near-perfect
    // single-item fill or no decent alternative exists.
    if bin_residual == bin_capacity {
        if item_size >= 90 {
            score -= 500.0; // opening a bin for a huge item is fine
        } else {
            score += 70.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Mild preference for tighter bins relative to the fleet mean.
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize residuals that neither fit the next item nor are near zero.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // usable for next item: mild reward proportional to leftover after next item
            let after_next = post_residual - next_item_size;
            score -= 6.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize more if gap is small (almost-fit)
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 8.0 * (1.0 - gap / 100.0);
        }
    } else {
        // last item: just minimize waste
        score += post_residual as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        // baseline preference for new bins early or when mean residual is low
        score = 30.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64) - 0.5 * crowding;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 40.0; // impossible next item shouldn't matter for empty bin
        }
        // if many bins can fit, discourage new bin
        score += fitting_bins_count as f64 * 3.0;
    }

    // Slight preference for bins with residual close to item (best-fit flavor).
    score += 0.1 * (bin_residual - item_size) as f64;

    // Mild global balance: prefer bins below mean residual (filling emptier bins first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr + 0.6 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, waste is more acceptable (favor tight packing later).
    let progress_weight = 0.5 + 1.5 * t * t;
    score *= progress_weight;

    // Interaction: post_residual vs mean residual — avoid bins far from the fleet average.
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev * cap;

    // Reward near-perfect fits smoothly.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_frac * fit_frac * fit_frac;

    // Lookahead: penalize leaving residual that barely fails next item, reward exact match.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score += 0.4 * gap;
        if pr >= n {
            score -= 0.6 * n / cap * 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding: many open bins encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    // deviation from mean residual: prefer bins near the pack norm
    score += 0.011 * (mean_residual - br) . abs () ;

    // reward tight fits (post_residual near 0)
    if pr == 0.0 {
        score -= 28.0 ;
    } else if pr <= 2.0 {
        score -= 14.0 ;
    } else if pr <= 5.0 {
        score -= 8.5 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 1.0 ;
    }

    // lookahead: can next item reuse the leftover space?
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 15.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after >= 1.0 && after <= 12.0 {
                score -= 6.5 ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            // two-item lookahead proxy: leftover after next item still fits a small third
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - progress) ;
            }
            if after > 12.0 && after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
        } else {
            // placing here strands space that next item cannot use
            score += (nx - pr) * (0.9 + 0.9 * (1.0 - progress)) ;
            // but if the stranded space is tiny, the cost is low
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalty: small residual that next item cannot use
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    // scarcity: with very few fitting bins, favor bins that can also host the next item
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }

    // dead-space ratio check for open bins
    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.0 * (dead - 0.8) ;
        }
        if fitting_bins_count >= 4 && pr > nx && nx > 0.0 {
            score -= 0.5 ;
        }
    }

    // new-bin candidate: empty bin has br == cap, pr == cap - it
    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        // encourage new bin when it would host next item too (perfect pair)
        if nx > 0.0 && nx <= pr {
            let after = pr - nx ;
            if after <= 12.0 {
                score -= 6.0 * (1.0 - progress) ;
            }
        }
        // discourage opening a new bin unless open-bin fits are poor
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.5 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            // calibrate: large waste in a fresh bin is bad
            if waste < 0.35 {
                score -= 2.0 * (1.0 - waste / 0.35) ;
            } else {
                score += 4.0 + 4.0 * (1.0 - progress) + 2.0 * ((waste - 0.35) / 0.65) ;
            }
            if open_bins_count > 0 && mean_residual > cap * 0.5 {
                score += 2.0 ;
            }
        }
        // combined: fresh bin + next item leaves a dead sliver -> extra penalty late
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.0 && (pr - nx) < 6.0 && progress > 0.5 {
            score += 1.5 ;
        }
    }

    // new: penalize bins whose residual after placement is just under a "reusable zone"
    // (stranded sliver that no typical small item can fill)
    if pr > 0.0 && pr < 3.0 && nx > pr {
        score += 1.0 * (1.0 - progress) ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space into 5 classes
    let class = post_residual / (bin_capacity / 5).max(1);
    let class_penalty = match class {
        0 => -40.0,           // near-perfect fit
        1 => -15.0,           // small gap, still useful
        2 => 5.0,             // awkward medium gap
        3 => 12.0,            // poor gap
        _ => 25.0,            // large waste
    };
    score += class_penalty;

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 30.0 - 0.2 * mean_residual;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 15.0; // keep room for pairing in a fresh bin
        }
    }

    // Prefer filling bins when many are open (consolidation pressure)
    score -= 0.4 * (bin_capacity - bin_residual) as f64;

    // Early stream: be slightly greedy to build tight bins
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / cap);

    score
}

