pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gaps too small for the smallest plausible item (size ~10) are dead space.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 60.0; // near-zero gap is wasted capacity
    } else if (post_residual as f64) < 2.0 * min_item {
        score += 15.0; // small gap, hard to fill later
    }

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (tight coupling with next item).
    if next_item_size > 0 {
        if post_residual == next_item_size as u32 {
            score -= 30.0;
        } else if (post_residual as f64) < next_item_size as f64 {
            // residual cannot fit next item: mildly penalize if gap is dead
            if (post_residual as f64) < min_item {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate more, and reward tight fits in open bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bins and stream progress.
        score += 20.0 + 5.0 * bin_pressure + 10.0 * progress;
        // But if no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Reward using large residual bins (good capacity utilization).
        score -= 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
        // Slight bonus for placing into bins when many are open (consolidation).
        score -= 2.0 * bin_pressure;
    }

    // Penalize wasteful placements: item much smaller than residual leaves
    // a large awkward gap relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.5 && bin_residual != bin_capacity {
        score += 10.0 * waste_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space penalty (nonlinear)
        if post_residual < 10 {
            score += 20.0;
        }
        // Lookahead: reward if next item fits into post_residual exactly
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 30.0 - slack_after_next as f64 * 0.5;
            if slack_after_next == 0 {
                score -= 100.0;
            }
        } else if next_item_size > post_residual {
            // next item won't fit here; penalize leaving awkward gaps
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 40.0 + (bin_capacity - item_size) as f64 * 0.1;
    }

    // Late stream: prefer tightening packing as we approach the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 15.0;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot follow here; penalize proportionally to wasted gap
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make new bins attractive only when current fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a bin
        score += 8.0;
        // If many open bins with plenty of slack, discourage new bins
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 20.0;
        }
        // Early in stream, allow new bins more freely to diversify residuals
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If lookahead item is large and no bin will have room after, new bin helps
        if next_item_size > 50 && post_residual >= 0 {
            score -= 5.0;
        }
    } else {
        // Slight preference to keep existing bins consolidated when few open
        if open_bins_count <= 2 {
            score -= 6.0;
        }
        // Penalize leaving residual far from mean (fragmentation of slack distribution)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Global pressure: when many bins open, prioritize filling them tightly
    score -= (open_bins_count as f64).ln().max(0.0) * (20.0 - tightness * 20.0);

    // Mild time-dependent greed: later in stream, be more conservative (favor exact fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // bumps near mid residuals
    score -= poly * cap * (0.5 + 2.0 * progress);

    // Penalize large dead space more aggressively as stream progresses
    let dead = prn * prn * prn;
    score += dead * cap * (0.3 + 1.5 * progress);

    // Reward tight fits: small post_residual
    score -= (1.0 - prn).powi(4) * (2.0 + 4.0 * progress);

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fit_next = if pr >= ni { 1.0 } else { 0.0 };
        score -= fit_next * (1.0 + ni / cap) * (1.0 + progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Slight preference for filling bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - prn);

    // Mean residual coupling: prefer bins below mean residual (fill emptier space evenly)
    let mr = mean_residual / cap;
    score += (prn - mr) * (1.0 + progress);

    // New-bin candidate handling: make empty bin moderately attractive
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        score = cap * (0.6 + 0.4 * progress) - (1.0 - prn) * (1.0 + progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual via integer division thresholds
    let cls = post_residual / 10;
    match cls {
        0 => score -= 40.0,                 // near-perfect fit
        1 => score -= 25.0,                 // small leftover
        2 => score -= 10.0,
        3 => score += 5.0,
        4 => score += 15.0,                 // awkward ~50 zone
        5 => score += 10.0,
        6 => score -= 8.0,                  // ~70 leaves room for typical items
        7 => score -= 12.0,
        8 => score -= 6.0,
        _ => score -= 2.0,
    }

    // Modulo arithmetic: residuals divisible by common item sizes are valuable
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // bonus if next item fits snugly
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        score += 3.0;
    }

    // Prefer filling bins with low mean residual (tight packing across fleet)
    score += 0.15 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin unless existing fit is terrible
    if bin_residual == bin_capacity {
        let tightness = if post_residual == 0 { 0.0 } else { post_residual as f64 / cap };
        score += 30.0 - 25.0 * tightness;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for bins that are already mostly full
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    // deviation from mean residual: prefer bins near the pack norm
    score += 0.011 * (mean_residual - br) . abs () ;

    // reward tight fits (post_residual near 0)
    if pr == 0.0 {
        score -= 28.0 ;
    } else if pr <= 2.0 {
        score -= 14.0 ;
    } else if pr <= 5.0 {
        score -= 8.5 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 1.0 ;
    }

    // lookahead: can next item reuse the leftover space?
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 15.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.5 ;
            } else if after >= 1.0 && after <= 12.0 {
                score -= 6.5 ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            // two-item lookahead proxy: leftover after next item still fits a small third
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - progress) ;
            }
            if after > 12.0 && after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            // combined feature: exact double-fill (item + next == residual) is ideal
            if after == 0.0 && fitting_bins_count <= 3 {
                score -= 2.0 ;
            }
        } else {
            // placing here strands space that next item cannot use
            score += (nx - pr) * (0.9 + 0.9 * (1.0 - progress)) ;
            // but if the stranded space is tiny, the cost is low
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalty: small residual that next item cannot use
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    // scarcity: with very few fitting bins, favor bins that can also host the next item
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }

    // dead-space ratio check for open bins
    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.0 * (dead - 0.8) ;
        }
        if fitting_bins_count >= 4 && pr > nx && nx > 0.0 {
            score -= 0.5 ;
        }
    }

    // new-bin candidate: empty bin has br == cap, pr == cap - it
    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        // encourage new bin when it would host next item too (perfect pair)
        if nx > 0.0 && nx <= pr {
            let after = pr - nx ;
            if after <= 12.0 {
                score -= 6.0 * (1.0 - progress) ;
            }
        }
        // discourage opening a new bin unless open-bin fits are poor
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.5 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            // calibrate: large waste in a fresh bin is bad
            if waste < 0.35 {
                score -= 2.0 * (1.0 - waste / 0.35) ;
            } else {
                score += 4.0 + 4.0 * (1.0 - progress) + 2.0 * ((waste - 0.35) / 0.65) ;
            }
            if open_bins_count > 0 && mean_residual > cap * 0.5 {
                score += 2.0 ;
            }
        }
        // combined: fresh bin + next item leaves a dead sliver -> extra penalty late
        if nx > 0.0 && pr >= nx && (pr - nx) > 0.0 && (pr - nx) < 6.0 && progress > 0.5 {
            score += 1.5 ;
        }
        // new: fresh bin is only attractive if the item nearly fills it outright
        if waste > 0.6 && fitting_bins_count > 0 && mean_residual < cap * 0.35 {
            score += 3.0 * (1.0 - progress) ;
        }
    }

    // penalize bins whose residual after placement is just under a "reusable zone"
    if pr > 0.0 && pr < 3.0 && nx > pr {
        score += 1.0 * (1.0 - progress) ;
    }

    // combined feature: prefer the open bin whose post-residual best matches next item
    // among moderately-sized leftovers, rewarding near-exact two-item pairing
    if nx > 0.0 && pr >= nx && pr - nx <= 2.0 && pr > 0.0 && br < cap {
        score -= 1.5 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let nx = next_item_size as f64;

    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: penalize leftover space, more strongly later in the stream
    let mut score = pr * (1.0 + 0.9 * prog2 + 0.7 * prog3);

    // Reward high fill ratio with a smooth cubic bonus
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: dead space that cannot host the next item is wasted
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0); // reward leaving near-exact room
            let after = pr - nx;
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0; // leaves a useful small slot
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0; // near-exact fit for next item
            }
            if after == 0.0 {
                score -= 3.0; // perfect chain
            }
            if after > 12.0 && after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0;
            }
        } else if pr > 0.0 {
            // stranded sliver that cannot host the next item
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if pr < 10.0 {
                score += 2.5 + 1.5 * (1.0 - progress);
            }
        }
    } else {
        // Last item: pure tightness packing
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if br == cap {
        let avg_pressure = mean_residual / cap;
        score += 22.0 + 18.0 * avg_pressure + 12.0 * (1.0 - progress);
        let waste = (cap - it) / cap;
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
    } else {
        let dead = pr / br.max(1.0);
        if dead > 0.8 && pr > 15.0 {
            score += 1.0 * (dead - 0.8);
        }
        if fitting_bins_count >= 4 && pr > nx && nx > 0.0 {
            score -= 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..=12) are pure waste.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - 3.0 * post_residual as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving gaps that cannot fit the lookahead item (k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward gaps that exactly or comfortably host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it attractive only when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.2;
    }

    // Prefer tighter fits overall.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Mild progression scaling: later in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Remainder after a hypothetical next placement: penalize leftover dead space.
        let two_step_waste = post_residual - next_item_size;
        score += two_step_waste as f64 * 0.6;
        // Mild bonus if the next item still fits comfortably.
        score -= 8.0;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the shortfall.
        let shortfall = next_item_size - post_residual;
        score += shortfall as f64 * 0.35;
    }

    // Reward tight fits relative to current item (low post residual).
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Penalize deviating from mean residual balance (avoid stranding bins).
    let dev = post_residual as f64 - mean_residual;
    score += (dev * dev).sqrt() * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let scarcity = if fitting_bins_count == 0 { 45.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty + scarcity - progress * 10.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= item_size {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Penalize large post_residual (dead space) superlinearly.
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / 10.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item then fits snugly.
        let next_fill = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 5.0 * next_fill;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item would need a new bin if we fill this poorly.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early on, be more willing to open new bins (explore);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's used only when fits are bad.
        score += 30.0;
        score -= 20.0 * progress;
        // Open new bin if best alternative would leave very fragmented space.
        if pr > 40.0 { score -= 10.0; }
        // If many open bins with slack, discourage another bin.
        if mean_residual > 30.0 { score += 10.0; }
        if open_bins_count > 8 { score += 12.0; }
    } else {
        // Slight preference for fuller bins among open ones.
        score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
        // If bin residual is small and item fits almost perfectly, big bonus.
        if post_residual <= 5 {
            score -= 12.0;
        }
    }

