pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Tightness of fit: normalized post residual
    let pr = post_residual as f64 / cap;
    let fit_quality = 1.0 - pr; // 1 = perfect fill

    // Non-linear polynomial coupling of fit quality with stream progress
    let coupling = fit_quality * fit_quality * (1.0 + progress) * (1.0 + fit_quality * progress);
    score -= 40.0 * coupling;

    // Penalize post residual that matches no plausible future item (dead space)
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt / cap).abs();
        score += 10.0 * gap * gap;
        // Reward if next item fits snugly into post residual
        if nxt <= post_residual as f64 {
            score -= 8.0 * (1.0 - ((post_residual as f64 - nxt) / cap).abs());
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation pressure)
    let frag = (mean_residual / cap - pr).abs();
    score += 5.0 * frag * frag * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Prefer using existing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        // integer division thresholds on post_residual
        let cls = post_residual / 10; // 10-wide harmonic classes
        score += (cls as f64) * 2.0;
        // penalize residuals that no plausible item (1..100) can fill well
        if post_residual < 10 {
            score += 25.0; // tiny dead space
        } else if post_residual <= 50 {
            // residual matching a common item class is fine
            let common = [10, 20, 25, 30, 40, 50];
            let mut best = 999u32;
            for &c in &common {
                if c <= post_residual {
                    let d = post_residual - c;
                    if d < best { best = d; }
                }
            }
            score += best as f64 * 0.8;
        }
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0; // chain two items in this bin
        // harmonic match of next item to post residual class
        let ncls = (next_item_size + post_residual) / 20;
        score -= (ncls % 3) as f64 * 2.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // next item won't chain here
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly unless current fit is bad
    if bin_residual == bin_capacity {
        // opening fresh: score = full residual; adjust by stream phase and fit quality
        let phase = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual == 0 || (item_size as f64) < 0.35 * cap && mean_residual < 15.0;
        if !poor_fit {
            score += 30.0 + 20.0 * phase;
        } else {
            score -= 10.0;
        }
    }

    // mean residual coupling: prefer bins below mean residual (tighter packing)
    score += (mean_residual - pr) * 0.3;

    // modulo arithmetic flavor on item class vs residual class
    let imod = (item_size % 10) as f64;
    let rmod = (bin_residual % 10) as f64;
    if imod == rmod && bin_residual != bin_capacity {
        score -= 3.0; // same harmonic class -> clean alignment
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

