    let mr = mean_residual;
    if (bin_residual as f64) < mr {
        score -= 8.0;
    } else {
        score += (bin_residual as f64 - mr) * 0.15;
    }

    // Last chance: this is the only bin that fits -> strong reward
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Early in the stream, be more willing to open new bins / spread items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized when many bins open
        score = 25.0 + progress * 20.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't chain: penalize wasted residual slightly.
        score += 6.0;
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative (prefer existing bins);
    // late in the stream, allow more exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer filling
    // bins above the mean residual (reduce fragmentation).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score += 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate: make it costly unless residual situation is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if no existing bin fits well (large dead space would result elsewhere),
        // a fresh bin is attractive when the item is large.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 22.0;
        }
        // Late stream with many open bins: opening new bins spreads load.
        if progress > 0.7 && open_bins_count > 4 {
            score -= 5.0;
        }
    }

    // Mild penalty for using bins with large residuals when item is small
    // (save big-space bins for big items).
    if item_size < 30 && bin_residual > 70 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: post residual, with smooth non-linear shaping.
    let mut score = pr;

    // Non-linear penalty for dead space: small residuals are valuable but risky,
    // large residuals waste capacity. Use cubic coupling with stream progress.
    let dead = x * x * (1.0 - x);
    score += 60.0 * dead * (0.5 + progress);

    // Reward tight fits: quadratic bonus shrinking as post_residual -> 0.
    let tight = (1.0 - x) * (1.0 - x);
    score -= 25.0 * tight * (1.0 - progress);

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // from the fleet mean (smooth interaction, no piecewise constants).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.5 + 0.5 * progress);
    score -= 8.0 * dev * (1.0 - progress);

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let fit_q = 1.0 - (gap / cap) * (gap / cap);
            score -= 20.0 * fit_q;
        } else {
            score += 10.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Pressure from many open bins: discourage spreading when fleet is large.
    score += 2.0 * (open_bins_count as f64).ln() * x;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
