        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
        }
        // prefer fresh bin only if it can chain two future items
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 >= nx && nx > 0.0 {
                score -= 2.0 * (1.0 - progress) ;
            }
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
