        // tightly hosts the next item is doubly valuable when bins are scarce
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it divides into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as capacity fraction

    // Reward near-perfect fits (small post residual) super-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 150.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 40.0;
    }

    // Harmonic classes: quantize residual into capacity/8 buckets.
    let bucket = post_residual / (bin_capacity / 8).max(1);
    score -= (bucket as f64) * 2.0;

    // Dead-space penalty: residual that no plausible item (1..=80) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10,20,25,50) are more reusable.
    if post_residual > 0 {
        let r = post_residual;
        if r % 50 == 0 { score -= 12.0; }
        else if r % 25 == 0 { score -= 8.0; }
        else if r % 20 == 0 { score -= 6.0; }
        else if r % 10 == 0 { score -= 4.0; }
        if r % 7 == 0 { score -= 1.5; }
    }

    // Next-item lookahead: reward residuals that can exactly/loosely fit next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (pr - n).abs() < 1.0 {
            score -= 90.0; // next item fills this bin exactly
        } else if n <= pr {
            score -= 15.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 10.0; // next item cannot use this bin
        }
        // Harmonic pairing: item + next divides capacity evenly
        let s = item_size as f64 + n;
        if cap % s == 0.0 && s <= cap {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.9;
        // Early in stream, opening fresh bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 25.0;
        }
        // Many open bins with high mean residual: prefer consolidation.
        if open_bins_count > 3 && mean_residual > 25.0 {
            score += 40.0;
        }
    } else {
        // Prefer bins whose residual is below mean (consolidate fullness).
        if (pr as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Crowding: with many fitting bins, demand tighter fits.
        if fitting_bins_count > 2 {
            score += (fitting_bins_count as f64) * 1.5;
        }
    }

    // Fractional penalty on wasted fraction of capacity, quadratic.
    score += 25.0 * frac * frac;

    score
}

