    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin: leftover hosts next item then nears zero
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        // combined feature: open bin whose residual after this item still
        // tightly hosts the next item is doubly valuable when bins are scarce
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        // prefer open bins whose current residual closely matches the item
        // (low fragmentation of the matched band) when several bins fit
        if fitting_bins_count >= 3 && pr > 0.0 {
            let band = (br - it) / cap ;
            if band < 0.06 {
                score -= 0.8 * (1.0 - band / 0.06) ;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score *= 1.0;

    // Aggressive 2-step lookahead: perfect chain match gets a big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // item + next item will exactly fill this bin
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item also fits: reward proportionally to how well it matches
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item won't fit: dead space penalty scaled by wasted amount
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Relative-to-mean coupling: bins with residual far from mean are
    // less attractive unless the fit is very tight
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the current item is
    // large and no good fit exists elsewhere; otherwise penalize opening bins
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size >= 60 && (bin_capacity as f64 - mean_residual) < item_size as f64 {
            score -= 10.0; // allow opening a fresh bin for large items when open bins are tight
        } else {
            score += 25.0; // discourage opening a new bin by default
        }
    }

    // Slight stream-progression pressure: later in the stream, consolidate more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    // Mild preference to spread load when many bins are open
    score += 0.01 * open_bins_count as f64;

    score
}

