pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual, scaled smoothly by stream progress (late stream -> tighter packing preferred)
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling of post_residual with progress:
    // penalize small residuals (dead space) more strongly as stream advances
    let x = pr / cap; // normalized residual in [0,1]
    score += cap * (1.0 - progress) * (x * x - 2.0 * x * x * x + x * x * x * x) * 2.0;

    // Reward good fit: residual close to zero relative to capacity
    score -= (1.0 - x) * (1.0 - x) * 8.0 * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits the post-residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty proportional to number of open bins to encourage consolidation
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: neutral-ish baseline, only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 partition dead-space
    // into "friendly" classes (multiples of common item sizes) vs awkward ones.
    let r = post_residual % 10;
    let residue_penalty = match r {
        0 => -18.0, // perfectly harmonic: divisible by most item sizes
        5 => -8.0,  // half-harmonic
        2 | 4 | 6 | 8 => 4.0,
        _ => 9.0,   // odd awkward residues (1,3,7,9)
    };
    score += residue_penalty;

    // Integer-division thresholds: how many "average items" still fit.
    let slots = post_residual / 10;
    score -= slots as f64 * 2.5;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic coupling with lookahead item: does post_residual admit next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: class match bonus, stronger when remainder is harmonic
            let rem = post_residual - next_item_size;
            score -= 12.0 + (rem % 10 == 0) as f64 * 10.0;
        } else {
            // bin becomes dead after this placement
            score += 20.0 + (post_residual as f64 / bin_capacity as f64) * 25.0;
        }
    }

    // Tight-fit fraction: reward high fill ratio non-linearly.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= fill * fill * 30.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // bias toward opening fresh bins early or when mean residual is small
        score += 30.0 - 22.0 * progress - (mean_residual / bin_capacity as f64) * 15.0 - crowd * 0.5;
        // a fresh bin is good if item is large relative to capacity
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    } else {
        // prefer bins whose residual is closest above the item (min wasted gap)
        let gap = (bin_residual - item_size) as f64;
        score += gap * gap * 0.02;
    }

    // Mean-residual coupling: when average residual is large, prefer consolidating
    // into fuller bins (penalize choosing a roomy bin).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
