    let nx = next_item_size as f64;

    // Base: penalize leftover space, more strongly later in the stream
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Discrete near-perfect fill bonuses (borrowed from best heuristic)
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.0;
    }

    // Tight-fit reward: how well item matches residual
    let fit = it / br.max(1.0);
    score -= 12.0 * fit * fit;

    // Last-chance bin: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: anticipate the next item's placement
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            let gap = after / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if after == 0.0 {
                score -= 3.0;
            }
            if after > 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
