            // stranded sliver that can't host the next item
            score += (nx - pr) * (1.1 + 0.9 * (1.0 - progress));
            if pr < 10.0 {
                score += 2.5 + 1.5 * (1.0 - progress);
            }
        }
    } else {
        score -= 10.0 * (1.0 - pr / cap);
    }

