pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let nx = next_item_size as f64;

    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: penalize leftover space, more strongly later in the stream
    let mut score = pr * (1.0 + 0.9 * prog2 + 0.7 * prog3);

    // Reward high fill ratio with a smooth cubic bonus
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Tiered near-perfect-fit bonuses (borrowed idea: exact/tiny residuals are gold)
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.0;
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: dead space that cannot host the next item is wasted
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0); // reward leaving near-exact room
            let after = pr - nx;
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after == 0.0 {
                score -= 3.0;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
        } else if pr > 0.0 {
            // penalize unusable sliver proportional to what's stranded
            score += (nx - pr) * (1.1 + 0.9 * (1.0 - progress));
        }
        if pr > 0.0 && pr < 10.0 && nx > pr {
            score += 2.5 + 1.5 * (1.0 - progress);
        }
    } else {
        // Last item: pure tightness packing
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // Dead-space ratio diagnostics for open bins
    let is_new = bin_residual == bin_capacity;
    if !is_new {
        let dead = pr / br.max(1.0);
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
        }
        if dead > 0.85 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.85) * (0.5 + progress);
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
    }

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if is_new {
        let waste = (cap - it) / cap;
        let avg_pressure = mean_residual / cap;
        score += 22.0 + 18.0 * avg_pressure + 12.0 * (1.0 - progress);
        if nx > 0.0 && pr >= nx {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
        // fresh-bin waste shaping (borrowed idea)
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (<= 10) are effectively unusable -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space for the known next item -> penalty proportional to gap.
        score += 10.0;
    }

    // Open bins pressure: discourage spreading when many bins are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it only wins when
    // all open bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 45.0 + 1.5 * open_bins_count as f64;
        // If the current item is large relative to mean residual, new bin
        // becomes relatively more attractive.
        score -= (item_size as f64 - mean_residual).max(0.0) * 0.3;
    }

    // Progress pressure: late in the stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-perfect lookahead fit (small gap still usable by next item)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in leftover: penalize dead space proportionally
        score += 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Favor bins tighter than the mean residual (good fillers)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is hopeless
    if bin_residual == bin_capacity {
        score += 300.0;
        // Allow new bin if leftover would be tiny dead space anyway
        if post_residual == bin_capacity && (bin_residual as f64) < mean_residual {
            score -= 350.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
