pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - post / cap;
        score -= 25.0 * tightness * tightness;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack_after_next = post - next_item_size as f64;
        score -= 12.0 * (1.0 - slack_after_next / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty scaled by gap.
        let gap = next_item_size as f64 - post;
        score += 6.0 * (gap / cap).min(1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large or few bins fit.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 30.0 + 40.0 * (1.0 - item_frac) * (1.0 - scarcity) * (0.5 + 0.5 * (1.0 - progress));
        score += penalty;
    }

    // Discard bins whose residual is small and unusable relative to typical item sizes.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.3 && post_residual < 10 {
        score += 8.0;
    }

    // Mild preference to consolidate when many bins are open.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post / cap);

    score
}

