pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let mut score = pr;

    // Base: penalize leftover space, stronger late in the stream
    score += pr * (0.25 * progress);

    // Reward high fill ratio smoothly
    score -= 22.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward
    let fit = it / br.max(1.0);
    score -= 12.0 * fit * fit;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 16.0 + 10.0 * progress;
    }

    // Lookahead: prefer placements that leave an exact/near-exact slot for the next item
    if nx > 0.0 {
        if pr == 0.0 {
            score -= 24.0; // perfect fill
        } else if pr >= nx {
            let after = pr - nx;
            let gap = after / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            if after == 0.0 {
                score -= 3.0;
            } else if after >= 1.0 && after <= 6.0 {
                score -= 5.0 * (1.0 - after / 6.0) * (0.5 + 0.5 * progress);
            } else if after <= 12.0 {
                score -= 3.0;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 1.5;
            }
        } else {
            // stranded sliver that cannot host the next item
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if pr < 10.0 {
                score += 2.0 * (1.0 - pr / 10.0);
            }
        }
    } else {
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty: bin far from mean residual less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (25.0 + 45.0 * progress) - dev * (2.0 + 3.0 * progress);

    // New-bin candidate: penalize opening fresh bins unless clearly beneficial
    if br == cap {
        let waste = (cap - it) / cap;
        let avg_pressure = mean_residual / cap;
        score += 20.0 + 16.0 * avg_pressure + 10.0 * (1.0 - progress);
        if nx > 0.0 && (cap - it) >= nx {
            score -= 6.0; // fresh bin can host the lookahead item too
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else if open_bins_count >= 3 {
            score += 1.5 * ((waste - 0.35) / 0.65) * (1.0 + progress);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
    } else {
        // dead-space ratio: fraction of remaining residual unusable for next item
        let dead = pr / br.max(1.0);
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) * (0.5 + progress);
        }
        if dead > 0.6 && pr > 10.0 && nx > pr {
            score += 0.8 * (dead - 0.6);
        }
        if pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
        if fitting_bins_count >= 4 && pr > nx && nx > 0.0 {
            score -= 0.5;
        }
    }

    score
}

