pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let is_new = bin_residual == bin_capacity;

    // Base: penalize leftover space, more strongly later in the stream
    let prog2 = progress * progress;
    let mut score = pr * (1.0 + 0.9 * prog2 + 0.7 * prog2 * progress);

    // Tiered near-perfect fit bonuses (borrowed from best heuristic)
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.0;
    }

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: dead space that cannot host the next item is wasted
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 12.0 * (1.0 - gap).max(0.0); // reward leaving near-exact room
            let after = pr - nx;
