pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * p2 + 2.0 * p3);
    score += 40.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bin bonus (smooth, weighted by progress)
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post-residual leaves room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = pr - nx;
        if room >= 0.0 {
            score -= 15.0 * (room / cap) * (0.5 + p2);
        } else {
            score += 8.0 * (-room / cap);
        }
    }

    // Mild pressure to consolidate into fewer bins early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a bin unless residuals are tight
    score += is_new_bin * (10.0 + 25.0 * (1.0 - progress) * norm_pr);

    score
}

