    let mut score = post_residual as f64;

    // Harmonic class: reward small post-residuals via integer-division buckets
    let div = (post_residual / 10) as f64;
    score += div * 6.0;

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Residual classes: 0, 10, 20, ... are "harmonic" slots reusable by 10-multiples
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual > 0 && post_residual < 10 {
        score += 30.0; // dead space below 10 is nearly unusable
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
            // perfect chain: next item leaves another harmonic residual
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 {
                score -= 20.0;
            }
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: only open when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 250.0 - pressure * 200.0
            + (post_residual as f64) * 0.5
            - (open_bins_count as f64).sqrt() * 2.0;
        // open new bin if current item is large and mean residual is tight
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 80.0;
        }
        if fitting_bins_count == 1 {
            score += 300.0; // never open when a unique bin fits
        }
    }

    // Progress modulation: tighten packing as stream advances
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Penalize bins far from mean residual (fragmentation)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty: unusable dead space (gap smaller than the minimum item size)
    if post_residual < 10 {
        score += 200.0 - 10.0 * post_residual as f64; // smaller dead gap -> slightly less bad
    }

    // Reward near-perfect fits
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Tightness ratio: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // Penalize bins whose residual deviates below the mean (fragmented bins)
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no good fit exists
    if bin_residual == bin_capacity {
        score = 150.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // Normalize wasted space relative to bin capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Aggressive 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this placement enables a perfect follow-up.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits; reward proportionally to how well it fills remainder.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * chain_fill;
        } else {
            // Next item will NOT fit here after this placement; penalize leaving
            // a gap that is too small to be useful (dead space).
            let gap_useless = (next_item_size - post_residual) as f64;
            score += 0.5 * gap_useless.min(40.0);
        }

        // 3-step chain: if next item fills post_residual exactly, and the item
        // after that could fit the then-empty-ish bin, extra bonus.
        if next_item_size == post_residual && post_residual > 0 {
            score -= 15.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "almost full",
    // prefer filling them up (closing bins out) rather than spreading across bins.
    let rel = (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly so tight fits win, but keep
    // it competitive against very poor fits (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        score = 45.0 + 0.25 * next_item_size as f64;
        // Early in the stream, opening bins is cheap; later, discourage sprawl.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If many bins already open, discourage opening yet another.
        score += 2.0 * open_bins_count as f64;
    }

    // Small tie-breaker favoring earlier bins to consolidate placements.
    score += 0.001 * step_index as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize wasted space relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 60.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins fit, to encourage spreading via tight fit logic.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize leaving a residual that's too small for the next item (dead space).
            let dead = (post_residual as i64 - 1).max(0) as f64;
            score += dead * 0.35;
        }
    }

    // Global state: penalize adding to bins when many open bins already exist
    // with low mean residual (fragmentation pressure).
    let frag = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += frag * 8.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0;
    score -= progress * 4.0;

    // New-bin candidate: neutral-ish baseline; open a new bin only when
    // the item fits poorly everywhere (score stays near capacity scale).
    if bin_residual == bin_capacity {
        // New bin baseline: post_residual = capacity - item_size dominates,
        // but discourage opening when a decent fit exists.
        score += 10.0;
        if fitting_bins_count > 0 && item_size >= bin_capacity / 2 {
            score += 5.0; // large items into open bins is fine, avoid hoarding
        }
    }

    // Mild preference for bins whose residual is close to item size (best-fit core).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.1;

    // Small open-bins count pressure: fewer bins -> consolidate.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear waste term: squared normalized post-residual penalizes dead space
    let waste = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 40.0 * waste;

    // Reward tight fits more aggressively: cubic bonus for small post_residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness.powi(3);

    // Penalize using a nearly-full bin when the item barely fits (fragile placement)
    let fragility = if bin_residual > 0 {
        (item_size as f64 / bin_residual as f64).powi(2)
    } else {
        1.0
    };
    score += 10.0 * fragility;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a residual that is too small for the next item (dead space)
            score += 12.0 * ((post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Stream-progress coupling: later in the stream, prefer consolidating into fewer bins
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when item is large
    // or no open bin offers a good fit; make the empty-bin baseline moderately high
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2);
        score += 35.0 - 30.0 * large_item_bonus;
        // Late in stream, opening new bins is less attractive if many bins are open
        score += 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - progress);
    }

    // Mild penalty when many bins can fit the item: prefer the tightest via post_residual already,
    // but add slight pressure toward bins with residuals close to the item
    let slack = (bin_residual - item_size) as f64;
    score += 0.05 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: harmonic classes of residual usage
    let usage_frac = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 20.0;
    } else if post_residual < 30 {
        score -= 8.0;
    }

    // Modulo-arithmetic classes: post_residual divisible by common small sizes
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
    }

    // Lookahead pairing: does next item fit the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * (next_item_size as f64);
        // harmonic class: post_residual - next_item_size small
        let r2 = post_residual - next_item_size;
        if r2 < 10 { score -= 10.0; }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space that next item cannot use
        score += 0.15 * post_residual as f64;
    }

    // Penalize wasteful large post_residual relative to mean residual
    if post_residual as f64 > mean_residual * 1.5 {
        score += 5.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 + 20.0 * progress + pressure;
        // allow new bin if item is large and would leave awkward residual elsewhere
        if usage_frac > 0.7 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Mild tie-break toward fuller bins
    score -= 0.05 * usage_frac * bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; residuals below next_item_size can't serve the lookahead.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: highly desirable
    } else if post_residual < 10 {
        score += 60.0; // tiny unusable gap -> strong penalty
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // gap can't host the next item
    } else {
        // reward tight-but-usable fits
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness * tightness;
    }

    // Bonus when this placement allows the next item to fit exactly here-after
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when all open bins would leave bad gaps
    if bin_residual == bin_capacity {
        // neutral baseline; slight penalty so decent fits in open bins win
        score += 12.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing large-then-large in fresh bin is fine
        }
    }

    // Mild stream-progression adaptation: later in stream, be more conservative
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits in the post residual
    else if next_item_size > 0 && post_residual >= next_item_size {
        // Tighter leftover after the next item is better
        let after_next = post_residual - next_item_size;
        score -= 25.0 - (after_next as f64) * 0.5;
    }
    // Next item does NOT fit in the post residual: penalize proportionally
    else if next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.3;
    }

    // Reward tight fits now (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 15.0;

    // Compare post_residual against mean residual across open bins:
    // leaving less than average is good (consolidating space)
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is more acceptable if few bins fit the item
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if fitting_bins_count == 1 {
            score += 10.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot be used by the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // bin stays useful for lookahead item
        } else {
            score += (post_residual as f64) * 0.9; // wasted remainder
        }
    } else {
        // last item: prefer fullest packing
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly when many bins are already open with slack
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let avg_open_slack = mean_residual / (open_bins_count.max(1) as f64);
        score += 14.0 + 20.0 * (1.0 - progress) - 0.35 * avg_open_slack;
        // opening a new bin is fine if the item is huge (poor fit anywhere)
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Penalize bins whose residual deviates far above mean (fragmentation)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.12 * dev.abs();

    // Slight preference for bins with residual close to item_size multiples
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect closure
    }

    // Time-horizon modulation: early on, be conservative with tight fits;
    // later, pack aggressively
    let progress = step_index as f64 / (total_items.max(2) as f64);
    score -= 6.0 * progress * tightness;

    // Coupling: many open bins -> prefer consolidating into existing ones
    score += 0.8 * (open_bins_count as f64).sqrt() * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
