pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Quadratic/cubic waste penalty: dead space hurts more as it grows
    score += 1.8 * fit_norm * fit_norm * cap;
    score -= 0.9 * fit_norm * fit_norm * fit_norm * cap;

    // Smooth stream-progress coupling: tighter packing valued later
    let progress_gain = (t * t) * (1.0 - fit_norm) * 30.0;
    score -= progress_gain;

    // Exact fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize near-empty bins left with tiny unusable residuals
    let tiny = (1.0 - (fit_norm * 10.0).min(1.0)).min(1.0);
    score += 12.0 * tiny * (1.0 - t);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * (1.0 - fit_norm);
    }

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - ((pr - nx) / cap)) * (0.5 + t);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mean residual alignment: prefer bins close to average state
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Mild preference to fill already-open bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * (1.0 - fit_norm);
        score += 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
