    let fill_ratio = 1.0 - pr / cap;
    let nx = next_item_size as f64;

    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: penalize leftover space, more strongly later in the stream
    let mut score = pr * (1.0 + 0.9 * prog2 + 0.7 * prog3);

    // Reward high fill ratio with a smooth cubic bonus
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: dead space that cannot host the next item is wasted
    if nx > 0.0 {
        if pr < nx && pr > 0.0 {
            score += (nx - pr) * 1.1;
        } else {
            let after = pr - nx;
            let gap = after / cap;
            score -= 12.0 * (1.0 - gap).max(0.0); // reward leaving near-exact room
            // NEW: reward post-fit residual landing in a "reusable" band
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0 * (1.0 - (after - 1.0) / 11.0);
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress);
            }
        }
    } else {
        // Last item: pure tightness packing
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // Dead-space ratio penalty (fraction of residual stranded after placement)
    if pr > 0.0 && nx > 0.0 && nx > pr {
        let dead = pr / br.max(1.0);
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
        }
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75);
        }
    }

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if br == cap {
        let avg_pressure = mean_residual / cap;
        let waste = 1.0 - it / cap;
        score += 22.0 + 18.0 * avg_pressure + 12.0 * (1.0 - progress);
        if nx > 0.0 && pr >= nx {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
        // NEW: waste-aware modulation of new-bin penalty
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else if open_bins_count > 0 {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let pr = post_residual;
    let pr_mod = (pr % 10) as f64;
    // Penalize residuals that fall in "dead" classes (small non-zero slivers)
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver for items >= 10, but small items may exist
    } else {
        score += pr_mod * 0.8; // slight penalty for off-class residuals
    }

    // Integer division thresholds: reward residual classes that fit common item sizes
    let pr_quarter = pr / 25;
    match pr_quarter {
        0 => score -= 6.0,          // residual < 25: nearly perfect fit
        1 => score -= 2.0,          // residual 25..49
        2 => score += 1.0,          // residual 50..74: half-full
        _ => score += 4.0,          // residual 75..99: mostly empty bin used
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 20.0; // perfect chain
        } else if diff < 10 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this residual: residual likely wasted
        score += (pr as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = score * 0.5 + 30.0 + open_bins_count as f64 * 0.5 - progress * 10.0;
    }

    // Mild preference to fill bins below mean residual (balance)
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
