pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9)
    // are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual,
    // reward the placement (chaining two items in one bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * (next_item_size as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // residuals are still large; encourage consolidation.
    score += open_bins_count as f64 * 0.6;

    // Favor bins whose residual is below the mean (compact bins),
    // penalize dumping into already-loose bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: empty bin has residual == capacity.
    // Make it attractive only when the item is large and no good fit
    // exists (post_residual of a fresh bin = capacity - item_size).
    if bin_residual == bin_capacity {
        let fresh_waste = post_residual as f64;
        score += 6.0;                       // mild default penalty
        if item_size >= 60 {
            score -= 12.0;                  // big items start fresh bins
        }
        if fresh_waste < 10.0 {
            score -= 20.0;                  // near-perfect fresh fit
        }
    }

    // Slight stream-progression tightening: later in the stream,
    // waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

