pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Partial match: reward proportional to how much of post_residual the next item consumes.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 400.0 * fill;
            // Penalize leftover after the lookahead placement (dead space over two steps).
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use this bin's post residual: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Reward bins whose residual is below mean (denser bins) to keep consolidation.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize very small post residuals that likely become dead space
    // unless they are an exact lookahead match (already heavily rewarded).
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 150.0;
    }

    // Early in the stream, prefer keeping flexibility: penalize tight fits slightly less
    // as the stream progresses (fewer future opportunities).
    let progress = step_index as f64 / total_items.max(1) as f64;
