    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving just enough room for the lookahead item
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-slack / 25.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, push toward best fit
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Penalize bins whose residual deviates badly from the mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Reward filling bins that are already mostly full (encourage closing bins)
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill.powi(3);

    // Time horizon: early on, prefer spreading (open bins); later, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 4.0 * fill;

    // Many open bins: prefer consolidation into existing bins
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large or no decent fit exists
    if bin_residual == bin_capacity {
