        let no_good_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 1);
        if no_good_fit && big_item > 0.5 {
            score -= 10.0;
        } else {
            score += 20.0 + 10.0 * (1.0 - big_item);
        }
    }

    score
}

