pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // Reward tight post residuals (small leftover = dense packing).
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            // Perfect 2-step match
            if after == 0.0 {
                score -= 8.0;
            }
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0);
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            // Penalize leaving a mid-sized hole the next item cannot fully use
            if after > 30.0 && after < 60.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
        } else {
            // Next item cannot use this residual: penalize proportionally
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    }

    // Consolidation: reward bins denser than the mean.
    score -= 0.4 * (mean_residual - br).abs().min(0.0).abs() * 0.0;
    if br < mean_residual {
        score -= 0.4 * (mean_residual - br);
    }

    // Tiny dead-space residual that next item cannot consume.
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0 * (1.0 - 0.5 * progress);
    }
    if fitting_bins_count <= 1 && pr > 0.0 && pr >= nx && nx > 0.0 {
        score -= 4.0 * (1.0 - progress);
    }

    // New-bin candidate logic.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        // If next item fits in the new bin's leftover, it's more attractive.
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if open_bins_count >= 2 && fitting_bins_count >= 2 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (0.5 + 0.5 * progress);
        }
        if nx > 0.0 && (cap - item_size as f64) < nx && (cap - item_size as f64) > 0.0 {
            score += 1.0 * (1.0 - (cap - item_size as f64) / nx) * (0.6 + 0.4 * (1.0 - progress));
        }
    } else {
        // Dead-space ratio penalty for existing bins.
        let dead = pr / br.max(1.0);
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75);
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress);
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress);
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
        }
        if dead > 0.5 && pr > 10.0 && nx > 0.0 && nx < pr - 3.0 && nx > 0.5 * pr {
            score += 0.4 * (dead - 0.5) * ((pr - nx) / (pr + 1.0)) * (1.0 - progress);
        }
        // Reward bins whose post-fit residual stays reusable by the next item.
        if dead > 0.4 && pr >= nx && nx > 0.0 && (pr - nx) >= 1.0 && (pr - nx) <= 10.0 && mean_residual < cap * 0.4 {
            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 4 && pr > nx && nx > 0.0 {
            score -= 0.5;
        }
    }

    // Early-stream flexibility: slight progress-scaled reward for keeping residual.
    if pr > 0.0 {
        score -= 20.0 * progress * 0.05;
    }

