        // extra penalty when new-bin leftover cannot host the next item
        if nx > 0.0 && pr < nx && pr > 0.0 {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count == 1 && waste > 0.7 {
            score += 0.8 * (waste - 0.7) * (1.0 + 0.5 * progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) >= 3.0 && (pr - nx) <= 8.0 && fitting_bins_count >= 2 {
            score += 0.6 * (1.0 - (pr - nx - 3.0) / 5.0) ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr + 12.0 * prn * prn * cap;

    // Smooth coupling of post_residual with stream progress:
    // late in stream, tight fits (small post_residual) are rewarded more,
    // large wasted residuals penalized more.
    let tightness = 1.0 - prn;
    score -= 25.0 * progress * tightness * tightness;
    score += 18.0 * progress * prn * prn * prn;

    // Perfect fit bonus (smooth, polynomial)
    if pr == 0 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = ((pr as f64) - (next_item_size as f64)).abs() / cap;
        score -= 20.0 * fits_next * (1.0 - gap * gap);
        score += 8.0 * (1.0 - fits_next) * (1.0 - progress) * prn;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 + 0.5 * progress);
    }

    // Penalize spreading across many open bins mildly; encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * prn;

    // New-bin candidate: make it attractive only when existing bins fit poorly
    let is_new = (bin_residual == bin_capacity) && (item_size as f64) < bin_residual as f64;
    if is_new {
        score = cap - item_size as f64 + 40.0 * prn + 10.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    score
}

