pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // --- Harmonic class logic on post_residual (mod 25) ---
    // Perfect closure (pr == 0) is ideal; residues divisible by 25 leave
    // "harmonic" slots reusable by mid-size items; tiny residues (1..5)
    // are dead space and get penalized.
    if pr == 0 {
        score -= 1000.0;
    } else {
        let class = pr % 25;
        match class {
            0 => score -= 20.0,
            1..=5 => score += 6.0 + (5 - class) as f64,
            10 | 20 => score -= 5.0,
            _ => {}
        }
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item chains perfectly into this bin: strong reward
            score -= 15.0 + next_item_size as f64 * 0.1;
            // extra harmonic bonus if chained residual stays on a class boundary
            if (pr - next_item_size) % 25 == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, avoid opening new ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate penalty ---
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    // --- Capacity-fraction waste term ---
    score += (pr as f64 / bin_capacity as f64) * 20.0;

    // --- Global pressure coupling ---
    score -= mean_residual * 0.05;
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

