    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += (10.0 - gap) * 12.0;
    } else if gap >= 10.0 && gap < 20.0 {
        score += (20.0 - gap) * 4.0;
    } else if gap >= 20.0 && gap < 40.0 {
        score += (40.0 - gap) * 1.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        score += open_pressure + 15.0;
    } else {
        score -= open_pressure * 0.5;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (avoid fragmenting outliers).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Late in the stream: tighten packing, avoid waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += gap * progress * 0.3;

    score
}

