pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight match, penalize mismatch relative to lookahead.
        score -= 40.0 * (-diff / 15.0).exp();
        // Penalize leaving residual that neither fits next item nor is near zero.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: any placement fine, prefer tightest fit.
        score += 0.0;
    }

    // Prefer bins whose residual is already below average (consolidation).
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Penalize large post_residual waste unless it's a new empty bin.
    if bin_residual < bin_capacity {
        if post_residual > 0 {
            score += 4.0 * (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;
        }
    } else {
        // New empty bin candidate: penalty so we only open when open bins are bad fits.
        score += 35.0;
        // If many bins already fit, discourage opening a new one further.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in stream, opening new bins is cheaper than wasting capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for using bins with small current residual (best-fit core).
    score += 0.5 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let is_new = bin_residual == bin_capacity;

    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Reward near-perfect fills
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    score -= 20.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward
    let fit = it / br.max(1.0);
    score -= 12.0 * fit * fit;

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 && !is_new {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: dead space unusable by next item is wasted
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            let gap = after / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            // reward leaving a small reusable remainder
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            }
            if after > 30.0 && after < 60.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
            // penalize stranded mid-holes the next item cannot reuse
            if after > 12.0 && nx < after - 5.0 {
                score += 0.9 * ((after - 12.0) / 20.0).min(1.0);
            }
        } else if pr > 0.0 {
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
        // small residual the next item cannot use: penalize
        if pr > 0.0 && pr < 10.0 && nx > pr {
            score += 2.5 + 1.5 * (1.0 - progress);
        }
    } else {
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty from mean residual
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);
    score += 0.011 * (mean_residual - br).abs();

    // New-bin candidate logic
    if is_new {
        let waste = (cap - it) / cap;
        // fresh bin can host next item too
        if nx > 0.0 && (cap - it) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count >= 2 && fitting_bins_count >= 2 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (0.5 + 0.5 * progress);
        }
        // leftover cannot host next item
        if nx > 0.0 && (cap - it) < nx {
            score += 1.0 * (1.0 - (cap - it) / nx) * (0.6 + 0.4 * (1.0 - progress));
        }
    } else {
        // dead-space ratio analysis for existing bins
        let dead = pr / br.max(1.0);
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75);
        }
        if dead > 0.5 && pr > 8.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
        }
        if pr > 0.0 && pr >= nx && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
        if dead > 0.4 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 10.0 && mean_residual < cap * 0.4 {
            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress);
        }
        if dead > 0.5 && pr > 10.0 && nx > 0.0 && nx < pr - 3.0 && nx > 0.5 * pr {
            score += 0.4 * (dead - 0.5) * ((pr - nx) / (pr + 1.0)) * (1.0 - progress);
        }
        if fitting_bins_count >= 4 && pr > nx && nx > 0.0 {
            score -= 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (nonlinear).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.05;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax the penalty
    // late in the stream or when open bins have large residuals (poor fits likely).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 55.0;
        // If the best existing fit is bad (post_residual large) relative to next item, allow new bin.
        let next_fits_here = next_item_size > 0 && next_item_size <= post_residual;
        if next_fits_here {
            new_bin_penalty -= 20.0; // new bin leaves room for the lookahead item
        }
        if mean_residual > 30.0 {
            new_bin_penalty -= 10.0 * ((mean_residual - 30.0) / 70.0).min(1.0);
        }
        score += new_bin_penalty - 10.0 * progress;
    }

    // Lookahead synergy: reward bins whose post-residual accommodates the next item snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 100.0);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Penalize stranding residual that the next item cannot use.
        score += 8.0;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.4 * open_bins_count as f64;

    // Slight preference for bins with residuals near the mean (keeps fleet balanced).
    score += 0.15 * ((bin_residual as f64 - mean_residual) / 10.0).abs();

    score
}

