            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress) ;
            }
            // penalize leaving a mid-sized hole the next item cannot use
            if after > 30.0 && after < 60.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        // stranded leftover between usable sizes
        if dead > 0.5 && pr > 10.0 && nx > 0.0 && nx < pr - 3.0 && nx > 0.5 * pr {
            score += 0.4 * (dead - 0.5) * ((pr - nx) / (pr + 1.0)) * (1.0 - progress) ;
        }
        // residual stays reusable by the next item
        if dead > 0.4 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 10.0 && mean_residual < cap * 0.4 {
            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        // discourage new bin when several open bins fit well
        if open_bins_count >= 2 && fitting_bins_count >= 2 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (0.5 + 0.5 * progress) ;
        }
        // leftover cannot host next item
        if nx > 0.0 && pr < nx && pr > 0.0 {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
        if pr >= nx && nx > 0.0 && (pr - nx) >= 3.0 && (pr - nx) <= 8.0 && fitting_bins_count >= 2 {
            score += 0.6 * (1.0 - (pr - nx - 3.0) / 5.0) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 2.0 * t * t - 2.0 * t + 1.0; // smooth U-shaped weight in [0.5, 1.0]
    score += 12.0 * poly * (pr / cap) * (pr / cap);

    // Penalize residuals too small for typical future items, smoothly.
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let slack = (pr - ns) / cap;
        if slack < 0.0 {
            score += 8.0 * slack * slack;
        } else {
            score -= 4.0 * slack;
        }
    }

    // Reward tight fits (low post residual) with a cubic bonus.
    let tight = 1.0 - pr / cap;
    score -= 10.0 * tight * tight * tight;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty proportional to crowdedness, scaled by progress.
    score += 0.5 * poly * (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by coarse buckets (e.g. 10, 25) are "usable" future slots.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize residuals in awkward harmonic classes (prime-ish / odd remainders).
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;
    if mod10 != 0 { score += (10 - mod10) as f64 * 0.3; }
    if mod25 != 0 { score += (25 - mod25) as f64 * 0.15; }

    // Perfect-fit harmonic classes: residual exactly 0, 25, 50, 75 are ideal slots.
    if post_residual == 0 { score -= 40.0; }
    else if post_residual % 25 == 0 { score -= 12.0; }

    // Integer-division threshold: residual in (0,10] is dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 { score += 25.0; }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Reward when next item divides residual cleanly (harmonic match).
            let ratio = post / nxt;
            if (ratio - ratio.round()).abs() < 0.01 {
                score -= 18.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual; penalize large wasted residuals.
            score += 0.2 * (post - (nxt - post).max(0.0)).min(30.0);
        }
    } else {
        // Last item: prefer exact fill.
        score += 0.5 * post;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / ((total_items.max(1)) as f64).sqrt();
        let mean_fill = 1.0 - (mean_residual / cap);
        if mean_fill > 0.75 {
            score -= 10.0 + 20.0 * (mean_fill - 0.75);
        } else {
            score += 12.0 + 10.0 * (0.75 - mean_fill);
        }
        score += pressure * 5.0;
    }

    // Mild tightness reward: filling bins deeper than mean residual is good.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

