pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are pure waste; residuals just above typical small-item thresholds are
    // "dead zones" that can never be filled efficiently.
    let dead_zone = post_residual > 0 && post_residual < 10;
    if dead_zone {
        score += 40.0; // unusable sliver
    }
    // Penalize mid-size dead gaps (10..=25) that only tiny items can use.
    if post_residual >= 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward tight fits (perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless the
    // fit is good; encourage using existing bins when bins are plentiful.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * (open_bins_count as f64 - mean_residual / 10.0).max(0.0);

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (chaining); if next item would be stranded, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // New-bin candidate: prefer opening a fresh bin when the item is large
    // and no open bin offers a tight fit; make the empty bin attractive when
    // open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0;
        let poor_fit = post_residual as f64 > 30.0;
        if crowded && poor_fit {
            score -= 20.0;
        } else {
            score += 15.0 + 10.0 * progress; // default: prefer existing bins
        }
    }

    score
}

