        // NEW: extra penalty when new-bin leftover cannot host nx
        if nx > 0.0 && pr > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // NEW: reward near-exact chaining of nx inside residual
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: compare post_residual against next_item_size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: bin becomes exactly full after next item
            score -= 35.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mildly reward keeping space usable
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit: penalize creating a near-dead residual
            let waste = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.25 * waste;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Mildly penalize bins with many alternatives to preserve flexibility
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Deviation from mean residual: prefer bins tighter than average (good fills)
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Penalize small unusable leftovers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // New-bin candidate: only chosen when no decent fit exists among open bins
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 22.0 + 8.0 * progress;
    }

    score
}

