    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If the next item could pair with this item in a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0;
        }
        // Late in the stream, avoid opening new bins aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        return score;
    }

    // Reward tight fits (small dead space) super-linearly.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward residual.
            score += 5.0;
        }
    } else {
        // Last item: pure tightness matters.
        score -= 15.0;
    }

    // Last-chance bin: avoid wasting a bin that only this bin can take the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
