    // Prefer bins below mean residual (relatively full bins) to consolidate space.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Penalize leaving residuals that are hard to fill (very small or awkward mid-range).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

