        if dead > 0.4 && pr >= nx && nx > 0.0 && (pr - nx) >= 1.0 && (pr - nx) <= 10.0 && mean_residual < cap * 0.4 {
            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: tight fit reward, non-linear in post_residual (quartic decay).
    let mut score = post_norm * post_norm * post_norm * post_norm * cap;

    // Smooth polynomial coupling with stream progress: waste matters more later.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Dead-space penalty: post_residual too small for typical future items.
    let dead_threshold = 0.12 * cap;
    if post < dead_threshold {
        score += (dead_threshold - post) * (1.5 + progress);
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 0.35 * cap * (1.0 + 0.5 * progress);
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 0.20 * cap * (post - nxt) / cap * (1.0 + progress);
        } else {
            // Penalize leaving residual that blocks the next item slightly.
            score += 0.10 * (nxt - post).min(cap) * progress;
        }
    }

    // New-bin candidate (empty bin): penalize opening unless open bins are crowded.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let crowd = mean_residual / cap; // average slack across open bins
        let pressure = (open_f / (open_f + 3.0)) * (1.0 - crowd);
        score = 0.55 * cap + 0.45 * cap * (1.0 - pressure) * (1.0 + progress)
            - 0.15 * cap * pressure;
    }

    // Mild dispersion penalty: prefer bins deviating from mean residual (balance).
    score += 0.05 * (post - mean_residual).abs();

    score
}

