pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded,
    // tiny dead space (1..=5) heavily penalized, mid-range mildly penalized.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score += 60.0 * (6.0 - post_residual as f64);
    } else if post_residual <= 10 {
        score += 12.0;
    }

    // Dead space that no future item (min size 1, but typically >=10) can use:
    // post_residual in a "dead harmonic class" if < 10.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Next-item lookahead: if next item fits exactly into post_residual,
    // strongly reward (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            score -= 20.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
        } else {
            // next item won't fit here; mild penalty scaled by how much it overflows
            score += 5.0;
        }

        // Harmonic pairing: post_residual and next_item_size share a divisor class
        // (e.g. both multiples of 10 or 5) -> likely compatible family of sizes.
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 10.0;
        }
        if next_item_size % 5 == post_residual % 5 && next_item_size <= post_residual {
            score -= 3.0;
        }
    } else {
        // Last item: prefer zero residual absolutely.
        score -= 50.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the residual waste is huge.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins with low mean residual: prefer bins tighter than the mean.
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // New-bin candidate (empty bin): penalize so it's chosen only when open bins
    // would leave large waste; allow it when residual of this bin is already large.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If item is large (harmonic half/full class), a fresh bin is attractive.
        if item_size as f64 > 0.6 * cap {
            score -= 55.0;
        }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= cap {
            score -= 20.0;
        }
    }

    // Prefer filling bins that are already relatively full (small bin_residual).
    score += 0.3 * (bin_residual as f64 - post_residual as f64) * -1.0;

    // Progress-based mild adjustment: early in stream, tolerate more open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A post_residual that is too small to hold even the smallest plausible item
    // (or the lookahead item) is "dead space" -> large penalty.
    let min_useful = if next_item_size > 0 { next_item_size.min(20) } else { 20 };
    if post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 8.0;
    }

    // Nonlinear dead-space curve: residuals just above 0 and just below 30 are worst.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 30.0 {
        score += (30.0 - pr) * (30.0 - pr) * 0.05;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward leaving a gap that exactly fits the next item (lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // mild reward for still being able to host next item
        score -= 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless it's a great fit.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current bins fit badly
    // (large post_residual waste everywhere) or no bins fit.
    if bin_residual == bin_capacity {
        let badness = if fitting_bins_count == 0 { 0.0 } else { (post_residual as f64) };
        // neutral base; add penalty so we only open new bins when truly needed
        score += 20.0 + badness * 0.3 - pressure * 1.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
    } else {
        // Tight-fit reward: waste relative to mean residual.
        let waste = (post_residual as f64 - mean_residual).max(0.0);
        score += waste * 0.4;
        // Reward filling bins more completely as the stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (item_size as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large post_residual
    score += (post_residual as f64).powf(1.3) * 0.05;

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: reward chaining
            let chain_waste = post_residual - next_item_size;
            score -= 12.0;
            score += (chain_waste as f64) * 0.15;
        } else {
            // next item won't fit: penalize dead space proportionally
            let dead = next_item_size - post_residual;
            score += (dead as f64) * 0.35;
        }
