pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Penalize small dead space that is hard to reuse (below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score += (30 - post_residual) as f64 * 0.3; // mild penalty for awkward leftovers
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // next item won't fit here; this bin becomes dead-ish
        }
    }

    // Last chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        if fitting_bins_count == 0 || (poor_fit && fit_ratio < 0.5) {
            score -= 15.0; // allow new bin when nothing fits well
        } else {
            score += 45.0 + 20.0 * progress; // prefer reusing open bins
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += consolidation * 0.15;
        score -= open_bins_count as f64 * 0.5;
    }

    // Time horizon: late in stream, be more aggressive at closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * fit_ratio * 10.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

