    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let nx = next_item_size as f64;

    // Base: penalize leftover space, stronger later in the stream
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Reward high fill ratio smoothly
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Exact-fill bonuses (borrowed from best heuristic)
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: reward leaving near-exact room for next item
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            let gap = after / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            if after < 0.5 {
                score -= 5.0;
            }
            if after >= 1.0 && after <= 6.0 {
                score -= 1.2 * (1.0 - after / 6.0) * (0.5 + 0.5 * progress);
            }
            if after >= 2.0 && after <= 12.0 {
                score -= 6.0 * (1.0 - (after - 2.0) / 10.0);
            }
            // second-lookahead: residual can host next item twice
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
        } else if pr > 0.0 {
            // stranded sliver just below next item: near-miss hole penalty
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if nx - pr <= 4.0 && pr > 2.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
    } else {
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // Dead-space pressure: residual that is a large fraction of original residual is wasted
    if bin_residual != bin_capacity {
        let dead = pr / br.max(1.0);
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) * (1.0 + 0.5 * progress);
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress);
        }
    }

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if br == cap {
        let waste = (cap - it) / cap;
        let avg_pressure = mean_residual / cap;
        score += 22.0 + 18.0 * avg_pressure + 12.0 * (1.0 - progress);
        if nx > 0.0 && pr >= nx {
            score -= 8.0;
        }
        // large item nearly filling a fresh bin is acceptable
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        // fresh bin can't host lookahead: extra penalty
        if nx > 0.0 && waste * cap < nx {
            score += 1.4 * (1.0 - progress);
        }
        // many open bins with roomy residuals: discourage new bin less
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
