                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= nx && nx > 0.0 && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 1.0 && after <= 10.0 && mean_residual < cap * 0.4 {
                score -= 0.5 * (1.0 - after / 10.0) * (0.5 + 0.5 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if nx > 0.0 && pr > 2.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.5 && pr > 6.0 && pr <= 15.0 && nx > 0.0 && nx > pr && br > 0.4 * cap {
            score += 0.6 * (dead - 0.5) * ((nx - pr) / (nx + 1.0)) * (1.0 - progress) ;
        }
        if dead > 0.4 && pr >= nx && nx > 0.0 && (pr - nx) >= 1.0 && (pr - nx) <= 10.0 && mean_residual < cap * 0.4 {
            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        // discourage opening a new bin whose leftover would strand a near-miss for next item
        if open_bins_count > 0 && nx > 0.0 && pr >= nx {
            let after_new = pr - nx ;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let nx = next_item_size as f64;

    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: penalize leftover space, more strongly later in the stream
    let mut score = pr * (1.0 + 0.9 * prog2 + 0.7 * prog3);

    // Reward high fill ratio with a smooth cubic bonus
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Discrete near-exact-fill bonuses (borrowed from best heuristic)
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: dead space that cannot host the next item is wasted
    if nx > 0.0 {
        if pr < nx && pr > 0.0 {
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
        let after = pr - nx;
        if after >= 0.0 {
            let gap = after / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            // exact-fit-after bonus
            if after == 0.0 {
                score -= 3.0;
                if fitting_bins_count <= 2 {
                    score -= 1.5 * (1.0 - progress);
                }
            }
            // small leftover after hosting next item is good
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress);
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0);
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // near-miss: leftover just above next item is a wasted near-fit
            if after > 0.0 && after <= 2.0 && pr > 8.0 {
                score += 0.9 * (1.0 - after / 2.0) * (0.4 + 0.6 * (1.0 - progress));
            }
            if after > 30.0 && after < 60.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
        } else {
            score += 8.0 * (-gap_unused()) * 0.0; // no-op guard (kept structure)
        }
    } else {
        // Last item: pure tightness packing
        score -= 10.0 * fill_ratio;
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if br == cap {
        let avg_pressure = mean_residual / cap;
        score += 22.0 + 18.0 * avg_pressure + 12.0 * (1.0 - progress);
        if nx > 0.0 && pr >= nx {
            score -= 8.0;
        }
        // discourage opening a bin whose leftover strands a near-miss for next item
        if open_bins_count > 0 && nx > 0.0 && pr >= nx {
            let after_new = pr - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

#[inline(always)]
fn gap_unused() -> f64 { 0.0 }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // Denser-bin consolidation reward.
    score += 0.011 * (mean_residual - br).abs();

    // Small-residual tiered bonuses (low post residual = tight fit is good).
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // Lookahead: reward bins whose post residual hosts the next item well.
    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 3.0;
                if fitting_bins_count <= 2 {
                    score -= 1.5 * (1.0 - progress);
                }
            }
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress);
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress);
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress);
            }
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            if after > 0.0 && after <= 2.0 && nx <= item_size as f64 {
                score -= 0.9 * (2.0 - after) * (0.3 + 0.7 * progress);
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
        } else {
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    }

    // Near-miss: residual just above next item (wasted exact fit by 1-2 units).
    if pr > 0.0 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
        score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress));
    }

    // Small residuals that next item cannot use: likely dead space.
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    // Moderately small residuals relative to capacity.
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // Last-chance bin with usable residual.
    if fitting_bins_count <= 1 && pr > 0.0 && pr >= nx && nx > 0.0 {
        score -= 4.0 * (1.0 - progress);
    }

    // Dead-space ratio (post residual relative to current residual).
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 {
        score += 1.2 * (dead - 0.75);
    }
    if dead > 0.6 && pr > 10.0 {
        score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0);
    }
    if pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
        score += 1.5 * (dead - 0.9) * (0.5 + progress);
    }
    if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
        score += 1.0 * (dead - 0.85) * (1.0 - progress);
    }
    if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
        score += 1.2 * (pr / br) * (1.0 - progress);
    }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
        score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress);
    }
    if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
        score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate logic.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if nx > 0.0 && (cap - item_size as f64) < nx && (cap - item_size as f64) > 0.0 {
            score += 1.0 * (1.0 - (cap - item_size as f64) / nx) * (0.6 + 0.4 * (1.0 - progress));
        }
        // Discourage new bin whose leftover strands a near-miss for next item.
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let is_new = bin_residual == bin_capacity;

    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Base: penalize leftover space, more strongly later in the stream
    let mut score = pr * (1.0 + 0.9 * prog2 + 0.7 * prog3);

    // Reward high fill ratio with a smooth cubic bonus
    score -= 30.0 * fill_ratio * fill_ratio * fill_ratio;

    // Tight-fit reward: smooth quadratic term on how well item matches residual
    let fit = it / br.max(1.0);
    score -= 15.0 * fit * fit;

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: exact/near-exact fit for the next item is highly valuable
    if nx > 0.0 {
        if pr == 0.0 {
            score -= 22.0; // perfect fill: no dead space at all
        } else if pr >= nx {
            let after = pr - nx;
            let gap = after / cap;
            score -= 12.0 * (1.0 - gap).max(0.0); // reward leaving near-exact room
            if after == 0.0 {
                score -= 6.0; // exact two-item chain fill
            } else if after <= 3.0 {
                score -= 2.5 * (1.0 - after / 3.0) * (0.5 + 0.5 * progress);
            } else if after <= 12.0 {
                score -= 1.5 * (1.0 - (after - 3.0) / 9.0);
            } else if after > 30.0 && nx < after - 5.0 {
                score += 0.8 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
            // two-lookahead: residual after next item should host a mid-size item too
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.2 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
        } else {
            // stranded sliver that cannot host the next item
            score += (nx - pr) * 1.1;
            if pr < 10.0 {
                score += 2.0 * (1.0 - pr / 10.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    } else {
        // Last item: pure tightness packing
        score -= 10.0 * fill_ratio;
    }

    // Dead-space ratio penalty: residual that is mostly unusable
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 {
        score += 1.5 * (dead - 0.75) * (0.6 + 0.4 * progress);
    }

    // Spread penalty: bin far from mean residual is less attractive, stronger late
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (30.0 + 50.0 * progress) - dev * (2.0 + 4.0 * progress);

    // New-bin candidate: penalize opening fresh bins unless residuals are tight
    if is_new {
        let avg_pressure = mean_residual / cap;
        score += 22.0 + 18.0 * avg_pressure + 12.0 * (1.0 - progress);
        if nx > 0.0 && pr >= nx {
            score -= 8.0; // fresh bin can host the lookahead item too
        }
        // discourage opening a bin whose leftover strands a near-miss for next item
        let waste = (cap - it) / cap;
        if open_bins_count > 0 && waste > 0.55 && nx > waste * cap {
            score += 1.5 * (1.0 - progress);
        }
        if open_bins_count > 0 && avg_pressure > 0.5 {
            score += 2.0;
        }
    }

