        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) >= 3.0 && (pr - nx) <= 8.0 && fitting_bins_count >= 2 {
            score += 0.6 * (1.0 - (pr - nx - 3.0) / 5.0) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;
    let nx = next_item_size as f64;
    let prog2 = progress * progress;

    let mut score = pr * (1.0 + 0.8 * prog2);

    // Tight small-residual bonuses (borrowed from best)
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // Fit quality
    let fit = it / br.max(1.0);
    score -= 12.0 * fit * fit;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 16.0 + 12.0 * progress;
    }

    // Lookahead: exact room for next item is golden
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            let gap = after / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            if after == 0.0 {
                score -= 3.0;
            } else if after <= 6.0 {
                score -= 1.5 * (1.0 - after / 6.0) * (0.5 + 0.5 * progress);
            } else if after <= 12.0 {
                score -= 4.0;
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // room for two more next-sized items
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0);
            }
        } else {
            // stranded sliver: unusable for next item
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if pr > 0.0 && pr < 10.0 {
                score += 2.5 + 1.5 * (1.0 - progress);
            }
        }
