        score -= 10.0 * fill_ratio;
    }

    // Deviation from mean residual
    let dev = (br - mean_residual) / cap;
    score += dev * dev * (28.0 + 45.0 * progress) - dev * (2.0 + 4.0 * progress);

    // Dead-space ratio penalty for large residuals
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 {
        score += 1.2 * (dead - 0.75);
    }
    if dead > 0.6 && pr > 10.0 {
        score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
    }

    // New-bin candidate: penalize unless item is big or residuals are tight
    if br == cap {
        let waste = (cap - it) / cap;
        score += 22.0 + 16.0 * (mean_residual / cap) + 10.0 * (1.0 - progress);
        if nx > 0.0 && nx <= cap && (cap - it) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        // new bin whose leftover would barely miss the next item
        if open_bins_count > 0 && nx > 0.0 && (cap - it) >= nx {
            let after_new = cap - it - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0);
            }
        }
    } else {
        // residual just above next item: near-miss penalty
        if dead > 0.4 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress));
        }
        if pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
    }

    score
}

