            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        // discourage new bin when an open bin can host both current and next item
        if open_bins_count > 0 && nx > 0.0 && mean_residual >= nx + it {
            score += 2.0 * (1.0 - progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual dominates, but nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Next item won't fit here; penalize large dead space proportionally.
            score += 0.15 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).min(post_residual as f64));
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when many bins are already open with slack.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean_residual + fixed opening cost.
        score = mean_residual + 30.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
            score -= 10.0; // fresh bin is fine for future packing
        }
        if fitting_bins_count == 1 {
            score += 200.0; // never open a new bin when only one bin fits
        }
    } else {
        // Prefer bins whose residual is close to the mean (keep residuals balanced).
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    // Time horizon: early in the stream, be more conservative (keep bins open);
    // late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - tightness);
    score += 10.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let post_norm = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling: reward tight fits more strongly late in the stream
    score -= (1.0 - post_norm).powi(3) * (1.0 + 2.0 * progress) * 30.0;
    // penalize residuals that no typical item can use (dead space), smoothly
    score += (post_norm * (1.0 - post_norm)).powi(2) * 20.0;
    // lookahead: reward leaving room for the next item, penalize near-misses
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        score -= (1.0 / (1.0 + (diff / cap).abs() * 4.0)) * 15.0 * (1.0 - progress);
        if diff < 0.0 && diff > -10.0 {
            score += 12.0 * (1.0 - progress);
        }
    }
    // last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }
    // mild penalty for spreading across many bins when mean residual is high
    score += (open_bins_count as f64 / (1.0 + mean_residual / cap)) * 2.0;
    // smooth pressure toward consolidation as stream progresses
    score += post_norm * progress * 10.0;
    score
}

