        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item classes is reusable
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // Modulo harmony: residuals that are multiples of common size classes (10,20,25,50) are valuable
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 10.0; }

        // Dead-space penalty: tiny unusable slivers relative to typical item sizes
        if pr < 10 {
            score += 60.0; // cannot fit anything (items >= 1..100 unknown, but small slivers risky)
        } else if pr < 20 {
            score += 25.0;
        }

        // Coupling with lookahead item: reward if next item fits harmonically
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 80.0; // next item exactly fills this bin
            } else if next_item_size <= pr {
                let npr = pr - next_item_size;
                score -= 10.0;
                if npr % 10 == 0 { score -= 8.0; }
                if npr == 0 { score -= 30.0; }
            } else {
                // next item won't fit here: mild penalty scaled by leftover gap
                score += (next_item_size - pr) as f64 * 0.15;
            }
        }
    }

    // Capacity-fraction thresholds: bins filled past 3/4 or 9/10 are excellent targets
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill >= 0.9 { score -= 15.0; }
    else if fill >= 0.75 { score -= 8.0; }
    else if fill < 0.25 { score += 10.0; } // avoid dumping into barely-used bins when better options exist

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean_residual; penalize unless
    // no open bin fits well (this call has bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        score += 35.0 + waste * 0.05;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: new bin is correct
        }
        if post_residual < 15 {
            score += 20.0; // opening a bin for an item that nearly fills it is wasteful
        }
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs().min(30.0) * 0.3;

    // Mild preference for bins below mean residual (balance load)
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible future item (<= ~15) are "dead". Penalize hard.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    }
    // Medium-small gaps are risky too, scaled penalty.
    if post_residual >= 15 && post_residual < 30 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64 / 10.0);
    }
    // If next item almost fits (gap of <= 10), mild reward.
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
        && next_item_size - post_residual <= 10 {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size > 60 {
            score -= 25.0; // big items are fine starting a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open
        }
    }

    // Open-bins pressure: with many open bins, avoid spreading residual
    // capacity; prefer consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Slight preference to fill bins below mean residual (drier bins first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: perfect 2-step match (item + next item exactly fill the bin)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward: next item also fits in the residual left behind
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Penalize: post_residual is nonzero but too small for the next item (dead space)
    else if next_item_size > 0 && post_residual > 0 {
        score += 20.0 + 0.3 * post_residual as f64;
    }

    // Relative-to-mean adjustment: prefer bins with residual close to mean (balanced use)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins exist and fit reasonably
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            // new bin is fine for a perfect next match
            score -= 0.0;
        }
        score += 60.0;
        // late in the stream, avoid opening bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Slight preference for tighter fits overall
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

