pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize when post_residual is large relative to capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 25.0 * progress;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mildly discourage spreading across bins
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement; penalize more if the leftover is tiny (dead space)
            if post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let mean_resid_frac = mean_residual / bin_capacity as f64;
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * (2.0 + 6.0 * mean_resid_frac);
    }

    // Early stream: be slightly greedy about filling; late stream: consolidate harder
    score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin is only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases as the stream progresses
        let new_bin_cost = 55.0 - 20.0 * progress;
        // If many open bins can already fit the item, opening a new bin is wasteful
        let penalty = if fitting_bins_count > 0 { 30.0 + 10.0 * fitting_bins_count as f64 } else { 0.0 };
        // If open bins have low mean residual, prefer them over a fresh bin
        let resid_penalty = 25.0 * (1.0 - mean_resid_frac);
        score += new_bin_cost + penalty + resid_penalty;
    }

