pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mildly favor tight fills; late stream: strongly penalize wasted space.
    let w = 0.5 + 2.5 * progress * progress;
    score += w * (post / cap) * (post / cap) * cap * 0.1;

    // Reward near-perfect fits smoothly (quadratic valley around post_residual == 0).
    score -= 12.0 * (-post * post / (cap * cap)).exp();

    // Penalize dead space that no typical item can use: smooth sigmoid on post_residual.
    let dead = 1.0 / (1.0 + (-(post - 15.0) / 8.0).exp());
    score += 20.0 * dead;

    // Lookahead coupling: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - (gap / cap).min(1.0)).powi(3);
    }

    // Last-chance bin: penalize opening new bins when only one fits, more so late in stream.
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * progress;
    }

    // Smooth preference toward bins with residual below the mean (consolidate space).
    score += 2.0 * ((post - mean_residual) / cap);

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.3 * open_bins_count as f64 * (post / cap);

    score
}

