                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= nx && after2 - nx <= 4.0 {
                score -= 0.8 * (1.0 - (after2 - nx) / 4.0) * (1.0 - progress) ;
            }
        }
