    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Dead space is worse if it cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
