        // REFINE: near-miss for next item in mid-dead bins — small extra penalty to avoid stranding
        if dead > 0.4 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
