pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let min_next = 1u32;
        // Dead space = residual too small to ever be useful again.
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += 200.0;
        }
        // Penalize gaps that cannot fit the lookahead item if it would otherwise fit nowhere.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 15.0;
        }
        // Reward gaps that can host the next item (chain packing).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Perfect fit bonus.
        if post_residual == min_next - 1 {
            score -= 50.0;
        }
    } else {
        // Exact fill: ideal.
        score -= 100.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 40.0 + 8.0 * open_bins_count as f64;
        // Late in stream, strongly prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
    } else {
        // Reward using bins when many are open (reduce bin count).
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (compact placement).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

