    let mut score = pr;

    // Small residuals are nearly dead space; reward bins that leave none or almost none.
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after == 0.0 {
                score -= 3.0;
                if fitting_bins_count <= 2 {
                    score -= 1.5 * (1.0 - progress);
                }
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress);
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress);
            }
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
        } else {
            // Next item cannot fit: penalize the gap, stronger early in the stream.
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // Tiny residual that the next item cannot use: likely dead space.
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    // Moderately small residual below a quarter of capacity: penalize mildly.
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }
    // Last-chance bin with a usable fit: strong consolidation bonus.
    if fitting_bins_count <= 1 && pr > 0.0 && pr >= nx && nx > 0.0 {
        score -= 4.0 * (1.0 - progress);
    }

    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        // New bin is attractive if the next item can also fit in its leftover.
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        // Don't open new bins while open bins still have lots of room.
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        // Discourage opening a new bin whose leftover would strand a near-miss for next item.
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
    } else {
        // Dead-space ratio of the residual relative to what this bin still holds.
        let dead = pr / br.max(1.0);
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75);
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
        }
        if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
            score += 1.0 * (nx - pr) / (nx + 1.0);
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress);
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress);
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress);
        }
        // Near-miss: residual just above next item wastes an almost-perfect fit.
        if dead > 0.4 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress));
        }
        // Reward bins whose residual the next item fits with a small remainder.
        if dead > 0.4 && pr >= nx && nx > 0.0 && (pr - nx) >= 1.0 && (pr - nx) <= 10.0 && mean_residual < cap * 0.4 {
            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress);
        }
        if fitting_bins_count >= 4 && pr > nx && nx > 0.0 {
            score -= 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the resulting residual (perfect 2-step match)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 50.0; // exact two-item fill: ideal
        }
        // Penalize residuals too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit as usual
        score += 0.0;
    }

    // Reward closeness to mean residual structure (keeps bin population balanced)
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Penalize very small post residuals that can't fit typical items (dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // opening a bin for a perfect pair is fine
        }
    }

    // Slight preference for tighter fits overall
    score += 0.2 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            // discourage stranding a near-miss for the next item in a fresh bin
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible next item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly-ish,
    // strongly reward this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else and global residuals are large.
    if bin_residual == bin_capacity {
        let global_pressure = mean_residual / bin_capacity as f64;
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // Penalize new bins by default, discounted when open bins are fragmented
        // and the item is large.
        score += 55.0 - 30.0 * global_pressure - 20.0 * poor_fit;
        // Late in the stream, be more conservative: reuse existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Mildly reward using bins with below-average residual (balance load),
        // penalize dumping into the emptiest bin when item is small.
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 6.0 * dev;
        if item_size <= 20 && bin_residual > 60 {
            score += 10.0; // don't waste big residual space on tiny items
        }
    }

    // Mild penalty for proliferating bins.
    score += 0.4 * open_bins_count as f64;

    // Early-stream exploration: slightly favor new bins early to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep parent's mod-10 dead-space quality signal, softened
    let residue = (post_residual % 10) as f64;
    score += residue * 0.35;

    if pr == 0.0 {
        score -= 26.0;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-size item capacity of leftover
    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.0;

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 { score -= 3.0; }
            if after >= 1.0 && after <= 12.0 { score -= 6.0; }
            if after >= 12.0 && after <= 30.0 { score -= 1.5 * (1.0 - (after - 12.0) / 18.0); }
            if after >= 20.0 && mean_residual < cap * 0.35 { score -= 1.0 * (1.0 - progress); }
            if after >= 1.0 && after <= 4.0 { score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress); }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 { score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress); }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 { score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress); }
            // near-miss: leaving space just under next item strands it
        } else {
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // small stranded leftover that next item can't use
    if pr > 0.0 && pr < 10.0 && nx > pr { score += 2.5 + 1.5 * (1.0 - progress); }
    if pr > 9.0 && pr < 0.25 * cap { score += 1.5 * (1.0 - pr / (0.25 * cap)); }

    // last-chance: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size { score -= 30.0; }
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx { score -= 4.0 * (1.0 - progress); }

    // fragmentation-aware dead fraction
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.5 && pr > 8.0 && nx > pr && fitting_bins_count <= 3 { score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)); }

    // NEW-BIN CANDIDATE: only open when leftovers of open bins are large & unusable
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 { score += 2.5 * ((waste - 0.5) / 0.5); }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap { score += 1.4 * (1.0 - progress); }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 { score += 1.1 * (waste - 0.5) * (1.0 - progress); }
        if open_bins_count > 0 && waste > 0.3 && waste < 0.45 && nx > 0.0 && nx > waste * cap { score += 0.7 * (0.45 - waste) * (1.0 + 0.5 * progress); }
        // discourage new bin whose leftover just misses next item
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    // tighter-bin tiebreak
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: waste^2 grows superlinearly
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Tight fit reward (small post_residual relative to item size)
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize if post_residual can't fit next item but could have been better used
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt && (bin_residual as f64) >= nxt {
            score += 8.0 * (1.0 - progress);
        }
        // Reward leaving room exactly for the next item
        let gap = ((post_residual as f64) - nxt).abs();
        score -= 6.0 * (-gap / 25.0) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild competition bonus for better-than-average fit
        let fit_adv = mean_residual - bin_residual as f64;
        score += 0.05 * fit_adv;
    }

    // Stream progress: late in stream, prefer filling existing bins (avoid many tiny leftovers)
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no good option exists
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fits = if fitting_bins_count == 1 && post_residual as f64 > 0.0 { 0.5 } else { 0.0 };
        score = bin_capacity as f64 * (0.9 + 0.1 * progress)
            - 25.0 * desperation
            - 10.0 * poor_fits * (1.0 - progress);
    }

    // Small regularization against many open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: perfect fit is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic-class penalty on the dead space left behind.
        // Classify post_residual into coarse classes via integer division.
        let cls = post_residual / 10; // 0..=9 harmonic class
        score += cls as f64 * 2.0;

        // Bonus if the leftover residual can still host the next item (lookahead coupling).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 {
            // Penalize residuals that are too small for the next item (unusable dead space).
            score += (next_item_size - post_residual) as f64 * 0.5;
        }

        // Penalize residuals in "awkward" small classes (e.g. 1..9) that rarely get filled.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins with reasonable fit exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaled by number of open bins.
        score += 30.0 + open_bins_count as f64 * 1.5;
        // If nothing else fits well, opening a new bin becomes attractive:
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild tie-breaker: prefer bins whose residual is close to the mean residual
    // (keeps bin states balanced, avoids many near-empty bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer filling bins that are already mostly full (small residual).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // combined: two-step lookahead — residual after next item should also host the one after
            if after >= nx && nx > 0.0 && after - nx <= 3.0 {
                score -= 0.9 * (1.0 - (after - nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            // discourage stranding a near-miss for the next item in a fresh bin
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // combined: fresh bin whose leftover can host next item twice is more attractive
            if after2 >= nx && after2 - nx <= 2.0 {
                score -= 0.8 * (1.0 - progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        // combined: avoid opening a bin when the leftover is far above any plausible next item
        if open_bins_count > 0 && nx > 0.0 && pr > nx && pr - nx > 0.3 * cap && mean_residual < cap * 0.4 {
            score += 1.2 * (1.0 - progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for the minimum item size
    // (interface allows items down to 1) are wasted capacity.
    let dead_threshold = 3.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 500.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Small-but-usable residuals: mildly penalize, unless the lookahead item
    // can exactly fill them.
    if post_residual > 0 && (post_residual as f64) < 20.0 {
        let usable_for_next = next_item_size > 0 && next_item_size <= post_residual;
        if !usable_for_next {
            score += 30.0 * (20.0 - post_residual as f64) / 20.0;
        } else if next_item_size == post_residual {
            score -= 200.0; // chain of perfect fits
        } else {
            score -= 50.0; // lookahead fits comfortably
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    // (mean residual low) or many bins are already open.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).sqrt() * 8.0
            + (mean_residual / bin_capacity as f64) * 40.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 + pressure + 20.0 * progress;
    }

    // Open-bin pressure: prefer spreading into bins with larger residuals
    // when many bins are open (keeps bin count stable).
    score += (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Tight fit reward: the fuller the bin gets, the better.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    score
}

