pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: pair completes the bin
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64); // near-perfect chain
        } else {
            // Next item cannot use the leftover: penalize dead space more when it is
            // small-but-unusable (worst case for future packing).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 10.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    } else {
        // Last item: simply minimize leftover.
        score -= 5.0 * tightness;
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving this bin with residual far below the mean wastes capacity elsewhere.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let dev = (post_residual as f64 - mr) / bin_capacity as f64;
    score += 8.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins with decent residual exist,
    // unless the item is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // New bin is attractive only if existing bins are mostly full (low mean residual)
        // and this item is big.
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 * (1.0 - fragmentation) - 20.0 * big_item;
        if fitting_bins_count > 0 && fragmentation > 0.3 && next_item_size > 0 && (next_item_size as f64) <= mr {
            score += 20.0; // existing bins can still chain; avoid needless new bin
        }
    }

    // Mild penalty for accumulating too many open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 {
        score += 2.0 * progress * (open_bins_count as f64).ln();
    }

    score
}

