    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that becomes unusable for typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin when decent fits exist,
    // but encourage it when the item is large and no tight fit is available.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 0.5 * bin_capacity as f64;
        if large_item {
            score -= 20.0 * (1.0 - progress);
        } else {
            score += 15.0 + 20.0 * (1.0 - progress);
        }
        // If many bins are open and fragmented, a fresh bin can be attractive.
        score -= 3.0 * (open_bins_count as f64).sqrt();
    }

    // Global fragmentation pressure: if mean residual is low, be greedy with tight fits.
    let frag = mean_residual / bin_capacity as f64;
    score -= 10.0 * (1.0 - frag) * tightness;

    // Late in the stream, prefer consolidating into fewer bins.
    if step_index + 1 >= total_items.saturating_sub(5) {
        score += 5.0 * post_residual as f64 / bin_capacity as f64;
    }

    score
}

