        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.3 && waste < 0.45 && nx > 0.0 && nx > waste * cap {
            score += 0.7 * (0.45 - waste) * (1.0 + 0.5 * progress) ;
        }
        if open_bins_count >= 2 && fitting_bins_count >= 2 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (0.5 + 0.5 * progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count == 1 && waste > 0.7 {
            score += 0.8 * (waste - 0.7) * (1.0 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear decay of residual value with stream progress:
    // late in the stream, residual space is worth more, so penalize large post_residuals harder.
    let decay = 1.0 + 2.0 * progress * progress + 0.5 * progress;
    score *= decay;

    // Cubic coupling: strongly punish mid-range dead space (unusable gaps),
    // mildly reward near-full and near-empty outcomes via smooth polynomial.
    let x = pr / cap;
    let dead_zone = (4.0 * x * (1.0 - x)).powi(2); // peaks at half-full residual
    score += 25.0 * dead_zone;

    // Tight fit reward (small post_residual) — subtract smoothly.
    score -= 15.0 * (-pr / 20.0).exp();

    // Last-chance bin: strong reward if this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Crowding penalty: many fitting bins means we can afford to be picky.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving residual close to next item size (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-gap / 25.0).exp();
        // Penalize blocking: post_residual smaller than next item but not tiny.
        if pr < next_item_size as f64 && pr > 5.0 {
            score += 8.0 * (1.0 - pr / next_item_size as f64);
        }
    }

    // Mean-residual coupling: prefer bins whose post_residual keeps them near the mean
    // (preserves diversity of residual sizes for future items).
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (large mean residual spread) or late in stream with tight existing bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        let new_bin_bonus = 20.0 * fragmentation + 30.0 * progress * (1.0 - fragmentation);
        score = 60.0 - new_bin_bonus;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
