pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "clean"
    // fractions of capacity (0, 25, 50) and divisible small slabs.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr % 25 == 0 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 10.0;
    } else {
        // penalize awkward dead space, worse when small and unusable
        let awkward = (pr % 10) as f64;
        score += awkward * 1.5;
    }

    // Class of post_residual relative to next item: if next item fits
    // exactly or near-exactly, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack <= 5 {
            score -= 20.0;
        }
    } else if next_item_size > pr {
        // next item can't use this residual: mild penalty scaled by waste
        score += (next_item_size - pr).min(40) as f64 * 0.3;
    }

    // Integer-division thresholds on post_residual: tiny residuals are dead.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // allow opening early when many bins open and mean residual is low
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 15.0 && progress > 0.2 {
            score -= 40.0;
        }
    }

    // Prefer tighter existing bins: closeness of fit reward.
    let tightness = (bin_residual - item_size) as f64;
    score -= (bin_capacity as f64 - tightness) * 0.05;

    // Mild preference to keep number of open bins from exploding.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving space that the next item can still use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 20.0; // gap too small for lookahead item: likely dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 20.0);
    score += pressure * 2.0;

    // New-bin candidate: only attractive when no open bin fits well
    // (large open count with small mean residual makes new bins relatively better).
    if bin_residual == bin_capacity {
        let bad_open = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - item_size as f64).max(0.0)
        };
        score += 30.0 + bad_open * 0.5 - (open_bins_count as f64) * 0.5;
        // Late in the stream, avoid opening bins with tiny expected leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    } else {
        // Favor bins whose residual is closest above the item (tight fit).
        score += (bin_residual - item_size) as f64 * 0.1;
    }

    score
}

