pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early stream: prefer tight fills (low post residual) strongly;
    // late stream: dead space matters less, slightly relax.
    let phase = progress * std::f64::consts::PI;
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;

    score += w_early * 40.0 * x * x * (1.0 - x);
    score -= w_late * 12.0 * x * (1.0 - x);

    // Reward good fit: item filling a large fraction of the bin.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 - x);

    // Penalize leaving post-residual just below next item size (unusable wedge),
    // with smooth quadratic proximity term.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            let gap = (nx - pr) / cap;
            score += 25.0 * gap * (1.0 - gap) * (1.0 - w_late);
        } else {
            let slack = (pr - nx) / cap;
            score -= 8.0 * slack * slack;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - x * x);
    }

    // Mild pressure toward consolidating into few bins as stream progresses.
    score += w_late * (open_bins_count as f64).ln_1p() * 2.0 * x;

    // Prefer bins whose residual is above average (use big space now).
    score += 5.0 * (pr as f64 - mean_residual) / cap;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
