            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        // lookahead: penalize new bin whose leftover can't host next item while mean residual can
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space classification.
    // Class 0: perfect fit (post_residual == 0) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small dead-space classes (1..=10) are nearly useless: penalize mildly less.
    if post_residual > 0 && post_residual <= 10 {
        score += 5.0;
    }

    // Harmonic residue class via integer division: post_residual / 10.
    // Larger classes (wider leftover) are more reusable -> subtract proportional reward.
    let residue_class = post_residual / 10;
    score -= (residue_class as f64) * 3.0;

    // Modulo-5 fine structure: post_residual divisible by 5 is a "harmonic" slot
    // that many item sizes can land on exactly.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain continuation. Reward scaled by tightness.
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 15.0 * tightness;
            // Exact harmonic match of next item into post_residual.
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize if leftover is small.
            let waste = post_residual as f64;
            score += 0.05 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has maximum residual.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins generally: add a base cost to opening new bins.
        score += 12.0;
        // But if current bin would leave a large awkward leftover and next item
        // is big, opening fresh may be better.
        if post_residual > 0 && post_residual < 20 && next_item_size > post_residual {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheap (many items to come).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Crowding: many open bins with high mean residual -> prefer consolidating
    // into tighter bins (penalize bins far from mean residual usage).
    let usage_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * usage_gap;

    // Prefer bins with larger current residual usage (less residual = tighter fit).
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    // Mild penalty for opening many bins when stream is late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

