pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are heavily penalized (they become permanent waste).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }
    // Gaps that cannot fit even the smallest plausible item are dead space.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residual that can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize residual that just barely blocks the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage consolidation; but relax pressure as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.5 - progress) * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.6;
        if crowded || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 25.0 + (open_bins_count as f64).min(10.0);
        }
    }

    score
}

