        }
        if dead > 0.5 && pr > 10.0 && nx > 0.0 && nx < pr - 3.0 && nx > 0.5 * pr {
            score += 0.4 * (dead - 0.5) * ((pr - nx) / (pr + 1.0)) * (1.0 - progress);
        }
        if dead > 0.4 && pr >= nx && nx > 0.0 && (pr - nx) >= 1.0 && (pr - nx) <= 10.0 && mean_residual < cap * 0.4 {
            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress);
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress);
        }
        if dead > 0.4 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress));
        }
        // Dead-space coupling: high dead ratio with roomier alternatives elsewhere
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress);
        }
        // Balance bonus: post residual near mean keeps pool balanced
        if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            // Perfect two-item chain: this bin takes current + next item exactly.
            score -= 40.0;
        } else if gap <= 10.0 {
            score -= 25.0 * (1.0 - gap / 10.0);
        } else {
            // Leftover after the pair: penalize proportionally to dead space.
            score += gap * 0.6;
        }
    }

    // If next item cannot fit here at all, mild penalty (it must go elsewhere or new bin).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item leaves a useful residual
    // for the lookahead item, otherwise strongly discourage opening a new bin.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score = 100.0 + gap as f64; // new bin only wins on near-perfect chains
        } else {
            score = 1000.0;
        }
    }

    // Progress scaling: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.4 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
