            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0; // near-perfect: kills tiny dead space
    }

    // Dead-space penalty for large leftovers that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // sliver unusable for min-size items
    }

    // Lookahead coupling: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0 + 0.3 * (next_item_size as f64);
        } else {
            // Penalize leaving a residual that just barely misses the next item.
            let miss = (next_item_size as f64 - post_residual as f64).abs();
            if miss < 12.0 {
                score += 25.0 * (1.0 - miss / 12.0);
            }
        }
    }

    // Last-chance bin: this is the only open bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest; slight crowding penalty elsewhere.
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: as the stream progresses, avoid opening new bins and consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, increasingly penalized later.
        score += 30.0 + 250.0 * progress;
        // But if no open bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Opening a bin is good if the item is large and would leave a big hole elsewhere.
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    } else {
        // Favor bins with below-mean residual (more congested bins get emptied first).
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 30.0 * dev;
        // Slight preference to fill bins with many open bins (reduce bin count).
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Late-stage consolidation: reward using existing bins heavily near the end.
    score -= 40.0 * progress * (1.0 - fit_ratio);

    score
}

