    // stream, small residuals are less likely to be filled.
    score += 30.0 * progress2 * pr3 * (1.0 - pr_norm);

    // Tight fits (small post_residual) are rewarded more strongly as the
    // stream advances; smooth cubic interaction instead of a threshold.
    score -= 20.0 * (1.0 - pr2) * (0.5 + 0.5 * progress);

    // Last-chance bonus: smooth reward scaled by inverse fitting bins.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 15.0 * scarcity * (1.0 - pr_norm * pr_norm);
    }

    // Penalize bins whose residual deviates strongly from the mean residual,
    // with a non-linear (quadratic) coupling weighted by open bins count.
    let dev = pr - mean_residual;
    score += 0.05 * (open_bins_count as f64).sqrt() * dev * dev / (bin_capacity as f64);

    // Lookahead: reward leaving room for the next item via smooth kernel.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / bin_capacity as f64;
        score -= 12.0 * (-20.0 * diff * diff).exp();
    }

    // Mild penalty for opening a new bin when progress is high (waste aversion).
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress2;
    }

    score
}

