pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in [1..10] is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Modulo classes on post_residual relative to small item sizes (harmonic classes)
    let class = post_residual % 20;
    score += match class {
        0 => -12.0,
        1..=5 => 10.0,
        6..=9 => 6.0,
        10..=15 => 0.0,
        _ => 4.0,
    } as f64;

    // Lookahead: reward if next item fits exactly-ish into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 15.0 - (slack as f64).min(15.0);
        if slack == 0 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // dead space likely for next item
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize mildly unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Integer-division threshold: bins whose residual can still hold a mid item
    if post_residual / 20 >= 2 {
        score -= 5.0;
    }

    // Stream progression: later in stream, tighten bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post-residuals that can never
    // accept typical items are heavily penalized dead space.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize waste relative to item size: putting a small item into a
    // huge bin wastes packing potential.
    score += (item_size as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: prefer spreading load across fewer bins when
    // many bins are open; prefer existing bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.5;

    // Prefer bins whose residual is below the mean (consolidating fills).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin to
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement; if next item is large and would not fit,
    // slightly penalize hoarding space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 5.0;
        }
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (large dead space) or no bin is tight. Base cost for new bins.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual == bin_residual {
            0.0
        } else {
            (dead_threshold - (bin_residual - item_size).min(20) as f64).max(0.0)
        };
        score += 15.0 + open_bins_count as f64 * 2.0 - bad_fit * 3.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
