pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward leaving exactly enough space for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit
        } else if post_residual >= next_item_size {
            // reward tighter-than-needed leftover above next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // leftover too small for next item: dead space penalty, worse if tiny
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 60.0; // near-useless sliver
            } else {
                score += 20.0 * (1.0 - waste / 100.0);
            }
        }
    }

    // Reward bins tighter than the mean residual (good packing density).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize opening a new bin, unless current
    // residuals are all poor fits (post_residual very small dead space).
    if bin_residual == bin_capacity {
        score += 300.0;
        if post_residual < 10 {
            score += 50.0; // don't open a bin that will end up with sliver waste
        }
        // late in the stream, avoid opening bins for marginal gains
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    score
}

