pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits get strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Reward tightness relative to capacity.
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize leaving dead space that cannot fit small future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual is large enough for the next item, mild reward.
