        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 10.0 * (ni / 100.0);
        }
        if (post_residual as f64) == ni {
            score -= 60.0;
        }
    }

    // Time horizon: early in stream, be pickier about waste; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    // Prefer filling bins with below-average residual (reduce fragmentation),
    // but penalize spreading across too many open bins.
