    if res_f < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((res_f - mean_residual) / (bin_capacity as f64));
    }

    // Mild pressure to reuse existing bins rather than open new ones.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    score
}

