pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items that leave residuals divisible
    // by common item sizes are more likely to be completed later.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that are "harmonically compatible" with typical sizes.
    // Perfect fit is best.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Divisibility bonuses: residual divisible by small common sizes
        for d in [5u32, 10, 20, 25, 50] {
            if pr % d == 0 && pr >= d {
                score -= 2.0 + (d as f64) * 0.05;
            }
        }
        // Penalize residuals in "dead zone": too small for most items (1..10 range
        // is rare, but residual < 10 is nearly dead space)
        if pr < 10 {
            score += 15.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // Prefer leaving slack that is itself harmonically small
            score -= 20.0 * (1.0 - slack / cap).max(0.0);
            if pr % next_item_size == 0 {
                score -= 10.0; // next item divides residual: future fits align
            }
        } else {
            // next item cannot fit here; mildly penalize large leftovers
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create bad fits (large awkward post_residual) and mean residual
    // across open bins is low (bins are nearly full anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are cheap early, expensive late
        score += 10.0 + 40.0 * progress;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 25.0; // open bins have room; don't open a new one
        }
        if pr == 0 { score -= 0.0; }
    }

    // Prefer bins whose residual fraction is harmonically aligned with capacity
    let frac = (bin_residual as f64) / cap;
    let eighth = (frac * 8.0).round() / 8.0;
    score -= 5.0 * (1.0 - (frac - eighth).abs() * 8.0);

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill;

    // Slight penalty for proliferating bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // REFINE: chaining — leftover can host next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: penalize leaving a near-miss gap the next item barely misses reusing
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: dead-space lookahead — if after-space is large relative to mean residual, mild penalty
            if after > 0.0 && after > mean_residual * 1.6 && mean_residual > 1.0 && fitting_bins_count >= 2 {
                score += 0.5 * (1.0 - progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: near-miss with roomier alternatives — extra penalty to steer away
            if pr > 0.0 && nx - pr <= 3.0 && open_bins_count >= 3 && mean_residual > pr + nx {
                score += 0.8 * (1.0 - (nx - pr) / 3.0) * (1.0 - progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        // REFINE: high dead ratio with roomier alternatives elsewhere — steer away
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        // REFINE: keep pool balanced — bonus when post-residual matches mean residual
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        // REFINE: dead-space compression — reward bins whose leftover shrinks a lot vs original residual
        if pr > 0.0 && br > pr && (br - pr) / br > 0.55 && fitting_bins_count >= 1 {
            score -= 0.8 * ((br - pr) / br - 0.55) * (0.5 + 0.5 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        // REFINE: leftover can't host next item but some open bin can — avoid new bin
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        // REFINE: open a fresh bin when open bins are nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        // REFINE: avoid opening a new bin that strands a leftover the next item nearly fits
        if open_bins_count > 0 && nx > 0.0 && pr > 0.0 && pr < nx && nx - pr <= 6.0 {
            score += 1.6 * (1.0 - (nx - pr) / 6.0) * (1.0 - progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward tight fits generally: closeness of post_residual to 0.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Lookahead coupling: if next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size.min(10) {
        score += 15.0; // post residual likely dead for the next item
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, discourage spreading to a
    // fresh/low-fill bin; encourage filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when few bins are open
    // or the fit elsewhere is hopeless.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Prefer bins whose residual is already near the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Late in the stream, tighten up: dead space matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += score * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 / (post_residual as f64).powf(0.5);
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill_ratio;
        } else {
            // next item cannot use leftover: penalize dead space creation
            score += 40.0;
        }
    }

    // Relative to mean residual: prefer bins whose post residual stays near/below mean
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / mean_residual;
        score += 25.0 * dev;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin candidate unless nothing fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline penalty; softened if few bins open or stream is young.
        score += 300.0;
        if open_bins_count == 0 {
            score -= 1000.0; // must open first bin
        }
        // If current item is large, a fresh bin is more attractive.
        score -= 0.5 * item_size as f64;
        // If the only alternative would leave big dead space, allow new bin.
        if pr > 0.0 && (bin_residual as f64 - item_size as f64) < 15.0 {
            score -= 350.0;
        }
    }

    // Slight preference for tighter bins (smaller residual before placement).
    score += 0.1 * bin_residual as f64;

    // Late in the stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 200.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
