pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: reward tight fits with a polynomial in
    // normalized fill ratio, amplified as the stream progresses.
    let fill_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (post_residual as f64 / cap);
    let poly_coupling = fill_ratio * tightness * (1.0 + 2.0 * progress * tightness);
    score -= 30.0 * poly_coupling;

    // Quadratic penalty on wasted residual, modulated by progress so early
    // stream placements tolerate slack, late ones do not.
    let wasted = post_residual as f64 / cap;
    score += 12.0 * wasted * wasted * (0.5 + progress);

    // Lookahead interaction: reward bins whose post-residual can smoothly
    // accommodate the next item (polynomial in the match ratio).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let match_ratio = nxt / post_residual as f64;
            score -= 10.0 * match_ratio * (2.0 - match_ratio) * (1.0 + progress);
        } else {
            // Post-residual too small for the lookahead: penalize dead space
            let dead = (nxt - post_residual as f64) / cap;
            score += 15.0 * dead * dead;
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins whose residual is close to the
    // fleet mean (smooth quadratic deviation) to keep options balanced.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Bin-count pressure: with many open bins, slightly discourage opening
    // new ones; the empty-bin candidate gets a smooth polynomial surcharge.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 8.0 + 25.0 * pressure * pressure * (1.0 - progress * 0.5);
        // But allow new bins early when the item is large and fits poorly nowhere.
        if item_size as f64 > 0.8 * cap {
            score -= 10.0 * fill_ratio;
        }
    }

    score
}

