pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item are "dead" and heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }

    // Reward tight fits (small but usable residuals less than raw residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * item_size as f64 * 0.8;

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use the leftover: leftover likely becomes dead space
            score += (post_residual as f64).min(next_item_size as f64) * 0.5;
        }
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.4;

    // Prefer bins whose residual is below mean residual (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward strongly unless it creates dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive early in the stream or when the
    // item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let poor_options = fitting_bins_count == 0
            || (post_residual < 10 && open_bins_count > 0);
        if large_item || poor_options || progress < 0.15 {
            score -= 25.0;
        } else {
            score += 20.0 + open_bins_count as f64 * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward post_residual that exactly matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // exact match gets a big reward; near matches get graded reward
        if diff == 0.0 {
            score -= 60.0;
        } else {
            score -= 20.0 * (-diff / 15.0).exp();
        }
        // penalize leaving residual that can't fit the next item at all
        if (post_residual as u32) < next_item_size {
            score += 8.0;
        }
    }

    // penalize tiny unusable dead space relative to the item-size domain
    if post_residual < 10 {
        score += 12.0;
    }

    // compare against mean residual of open bins: prefer bins that tighten waste
    score -= 0.5 * (mean_residual - post_residual as f64);

    // last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // early in the stream, allow opening new bins more freely to build a good pool
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // mild penalty for too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
