        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 6.0 + 0.5 * nxt;
        } else {
            // reward leaving room exactly usable by next item
            let waste = (post_residual as f64) - nxt;
            score -= 4.0 * (1.0 - waste / cap).max(0.0);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when fits are poor or many bins open
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let bad_fit = tightness < 0.25;
        if bad_fit || open_bins_count == 0 {
            score -= 20.0 + 5.0 * progress;
        } else {
            score += 12.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Mild preference for bins below mean residual (balance load)
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Slight time-decay on open-bin usage to encourage consolidation early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - progress) * tightness;

    score
}

