pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact-ish fits (small post_residual).
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how tightly next item nests.
            let nest = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * nest;
        } else {
            // Dead space for the next item: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Prefer bins with residuals below mean (tight packing) mildly.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: penalize spreading; encourage filling existing bins.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so it loses against decent existing fits.
        score = bin_capacity as f64 * 1.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If this bin is the only fitting option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

