            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        // open bin whose post-residual tightly hosts the next item when bins scarce
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        // near-perfect fit missed by 1-2 units: mildly penalize (stranded sliver)
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        // prefer bins whose post-residual becomes near-zero dead space
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        // mid-range dead space that cannot host nx — push toward tighter bins
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        // residual that is a multiple of common small-item sizes keeps future fits cheap
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // dead-space ratio penalties from best variant, adapted
        let dead = pr / br . max (1.0) ;
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // REFINE: balance bonus — post-residual near pool mean keeps the pool usable
        if pr > 4.0 && norm_gap < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - norm_gap / 3.0) * (0.5 + 0.5 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the post-residual: reward proportionally to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * tight;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space scaled by wasted amount.
        let dead = next_item_size as f64 - post_residual as f64;
        score += 0.5 * dead.min(60.0);
    }

    // Penalize post-residual that is far below mean residual (creating unusable slivers)
    // while rewarding leaving room above the mean.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score += 0.3 * diff;
    } else {
        score += 0.1 * diff; // negative diff -> small reward
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize very small unusable post-residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor or absent.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            -100.0
        } else if fitting_bins_count == 1 {
            20.0
        } else {
            40.0 + 5.0 * open_bins_count as f64
        };
        score += desperation;
        // Late in stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild preference to fill already-open bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by fraction of bin consumed by this item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 55.0 * fit_ratio * fit_ratio;

    // Perfect or near-perfect closure is highly desirable.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Penalize creating dead space below the minimum plausible future item (1..100 unknown,
    // but small residual that no typical item can use is waste). Use non-linear dead-space term.
    let dead = if post_residual < 25 { (25 - post_residual) as f64 } else { 0.0 };
    score += 1.8 * dead;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let nh = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 * nh;
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += 0.3 * ((next_item_size - post_residual) as f64).min(50.0);
        }
    }

    // Global state: when many bins are open with high mean residual, prefer consolidating
    // into existing bins rather than spreading; when mean residual is low, opening a new
    // bin for a poor fit is less costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation_pressure = mean_residual / bin_capacity as f64;
    score += 25.0 * consolidation_pressure * (1.0 - progress);

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how badly the item fits
        // existing bins (few fitting bins => new bin more acceptable) and stream progress.
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.6 / fitting_bins_count as f64 };
        let open_cost = 120.0 - 70.0 * scarcity - 30.0 * progress;
        // If item is large relative to capacity, opening fresh is more attractive.
        let size_bonus = 0.4 * item_size as f64;
        score += open_cost - size_bonus;
        // Slight penalty if many bins already open (limit bin proliferation).
        score += 1.5 * open_bins_count as f64;
    } else {
        // Existing bins get a mild preference baseline.
        score -= 10.0;
        // Favor bins whose residual is close to item size relative to the fleet mean.
        let rel = bin_residual as f64 - mean_residual;
        score += 0.15 * rel;
    }

    score
}

