pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Tight fits (small post_residual) are rewarded increasingly as stream progresses.
    let x = post / cap; // normalized post residual in [0,1]
    let tightness = (1.0 - x) * (1.0 - x); // quadratic tightness term
    score -= 30.0 * tightness * (0.4 + 0.6 * t);

    // Cubic penalty for large dead space that becomes harder to fill later.
    score += 12.0 * x * x * x * (0.5 + 0.5 * t);

    // Reward bins whose residual closely matches the next item (lookahead coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let match_next = 1.0 - (x - nx).abs();
        score -= 15.0 * match_next * match_next;
    }

    // Penalize the brand-new empty bin candidate smoothly, but relax late in stream
    // or when this is the only fitting bin.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let open_f = open_bins_count as f64;
        let pressure = 1.0 / (1.0 + open_f * open_f / 16.0);
        let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += (25.0 + 40.0 * t) * pressure * (1.0 - 0.6 * last_chance);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 * (1.0 - x);
    }

    // Mild coupling to mean residual: prefer bins deviating from mean (consolidation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 6.0 * dev.abs() * (1.0 - t);

    score
}

