pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod 10 decile) ---
    // Residuals that are "nice" multiples of 10 are more likely reusable
    // by future items drawn from typical integer distributions.
    let cls = post_residual % 10;
    score += cls as f64 * 0.35;

    // Integer-division threshold: residuals in [1,10) are near-dead space
    // (only tiny items can use them); penalize strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Residuals in [10,25) are half-dead: usable but risky.
    if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect harmonic match: reserve this space.
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Partial match reward, scaled by fill fraction of the residual.
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * frac;
        } else {
            // Next item cannot use this residual: residual likely wasted.
            score += 6.0;
        }
    }

    // --- Tightness reward: how well the item fills the current residual ---
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill;

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin should only win when existing fits are poor.
        // Base penalty plus mild pressure from mean residual of open bins.
        score += 18.0 + 0.08 * mean_residual;
        // Early in the stream, having spare open capacity is fine; later,
        // prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // --- Mild bin-count coupling: with many open bins, prefer fuller bins ---
    let pr = post_residual as f64 / bin_capacity as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 1.2 * pr;

    score
}

