    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items >= 1, but small gaps below 10 are pure waste) are heavily penalized.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this placement (sets up a perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use this residual: residual likely dead space.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading items; also dampens new-bin attractiveness.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when few bins are open, or when the item
        // is huge (a big item alone in a fresh bin leaves a large useful residual
        // for other streams... but with unknown distribution, keep moderate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
