pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        // Exact 2-step match: big reward.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Reward closeness of post_residual to next_item_size.
            score -= 25.0 * (-diff / 20.0).exp();
            // Penalize post_residual that is unusable for the next item (dead space).
            if pr < nx {
                score += 15.0 * (1.0 - pr / nx.max(1.0));
            }
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins),
    // unless the fit is exact.
    let pr = post_residual as f64;
    score += 0.35 * (pr - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would create large dead space and the next item fits the fresh bin.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 0.5 {
            // Fresh bin perfectly fits next item: mild discount.
            score -= 30.0;
        }
        let waste = pr;
        if next_item_size > 0 && (waste as f64) < next_item_size as f64 {
            // Current bins would strand space; new bin more attractive.
            score -= 45.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (waste minimization) with a nonlinear coupling.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.1 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item (perfect chaining).
        let chain = post_residual as f64 - next_item_size as f64;
        score -= 3.0 * (1.0 - chain / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when the item barely fits open bins
    // (i.e., poor fit everywhere) or early in the stream with few open bins.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64; // = post_residual of a fresh bin
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins generally, less so when open bins are crowded.
        let crowd = mean_residual / bin_capacity as f64;
        score += 10.0 + 15.0 * progress - 8.0 * crowd - 0.05 * open_bins_count as f64;
        // If item is large relative to capacity, a fresh bin is more forgiving.
        score -= 0.05 * item_size as f64;
        let _ = poor_fit;
    }

    // Mild bonus for bins whose residual is close to the global mean residual
    // (keeps the bin pool balanced for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Slight preference for mature bins (opened earlier) to close them out.
    score += 0.001 * (bin_capacity as f64 - bin_residual as f64);

    score
}

