    score += 8.0 * norm_post * norm_post * (0.5 + progress);

    // Reward if the lookahead item fits in the post residual (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_margin = post - nxt;
        if fit_margin >= 0.0 {
