    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Prefer bins with residual below the mean residual (consolidate emptier space).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev;

    // Slight preference to keep fewer open bins when many are open.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0;
        if poor_fit_everywhere {
            score -= 5.0;
        } else {
            score += 20.0 + 10.0 * (1.0 - progress);
        }
    }

    score
}

