pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals that are multiples of common item sizes (or near-capacity fractions)
    // are more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows super-linearly for small unusable leftovers.
    if post_residual > 0 {
        let dead = (cap / pr.max(1.0)).ln(); // larger when pr is small
        score += dead * 12.0;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Harmonic class: post_residual mod small integers — residuals divisible
    // by 10/20/25 align with typical item granularity and are easier to fill.
    let m10 = (post_residual % 10) as f64;
    let m20 = (post_residual % 20) as f64;
    score += m10 * 0.8 + m20 * 0.4;

    // Lookahead coupling: reward when next item fits exactly or harmonically
    // into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 35.0; // exact two-item closure
        }
        let diff = (post_residual - next_item_size) as f64;
        if diff > 0.0 {
            score += (cap / diff.max(1.0)).ln() * 5.0; // penalize awkward leftovers
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this bin's leftover: mild penalty scaled by tightness.
        score += 8.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
