pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Gap usable by the smallest items; mild penalty.
        score += 8.0;
    }

    // Reward residual large enough to fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (post_residual as f64 - next_item_size as f64) * 0.2;
        } else {
            score += 6.0; // this bin becomes dead after placement
        }
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; only preferred over very poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 1.0;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when a last-chance bin exists
        }
    }

    // Mild mean-residual coupling: prefer bins with residual near the mean (balanced packing).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Slight progression pressure: tighten packing as the stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.1 + 0.25 * progress);

    score
}

