pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: square the post residual to punish wasteful fits.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Exact fit is heavily favored.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small dead space (< smallest plausible item) is nearly unusable: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Leftover too small for next item: mild penalty proportional to waste.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is cheaper than fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
        // If next item is huge and this bin is fresh, a new bin is attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer filling bins below the mean residual (balancing global state).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Fragmentation guard: penalize leaving residual far from mean in many-bin regimes.
    if open_bins_count > 4 {
        score += 0.1 * ((post_residual as f64 - mean_residual).abs());
    }

    score
}

