    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // Small post residuals are near-perfect compaction: reward them.
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // Lookahead: reward when next item fits the post residual well.
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            let gap = after / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            if after == 0.0 {
                score -= 3.0;
                if fitting_bins_count <= 2 {
                    score -= 1.5 * (1.0 - progress);
                }
                if fitting_bins_count >= 3 {
                    score -= 0.8 * (1.0 - progress);
                }
            }
            if after >= 1.0 && after <= 6.0 {
                score -= 1.2 * (1.0 - after / 6.0) * (0.5 + 0.5 * progress);
            }
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
