            }
        } else {
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    }

    // Dead-space ratio: penalize bins whose post residual dominates the current residual.
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 {
