pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo small divisors of capacity.
    let pr = post_residual;
    let mod_class = (pr % 10) as f64;
    score += mod_class * 0.35; // residue not aligned with common item sizes -> dead space

    // Perfect closure reward: residual exactly matches next item or near-zero.
    if next_item_size > 0 && pr == next_item_size {
