        0 => score -= 30.0,           // nearly full: excellent
        1 => score -= 10.0,           // residual 10-19: still usable by small items
        2 => score += 5.0,            // residual 20-29
        3 => score += 12.0,           // residual 30-39: awkward
        4 => score += 3.0,            // residual 40-49: often fillable
        _ => {}
    }

    // Capacity-fraction coupling: penalize leaving > half-empty bins early.
    let frac = post_residual as f64 / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if frac > 0.5 {
        score += (frac - 0.5) * 40.0 * (1.0 - progress);
    }

