pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Medium dead space (10..=20) is also risky but less severe.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect-fit lookahead: if the next item fits the post residual exactly, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 && post_residual - next_item_size > 0 {
        // Next item would leave a tiny dead gap here — mild penalty.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit here is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by pressure.
        score += 30.0;
        // If many open bins exist with slack, opening a new bin is wasteful.
        score += (open_bins_count as f64) * 1.5;
        // If mean residual is large (lots of slack overall), penalize new bins more.
        score += mean_residual * 0.4;
        // Early in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
        // But if this bin is the only fitting bin, opening a new bin is legitimate.
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
