pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post-residuals non-linearly
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 50.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strong bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after hypothetical next placement
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
        } else {
            // next item cannot fit here: penalize leaving a gap smaller than next item
            score += 120.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it unattractive unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 400.0;
        // late in stream, opening new bins is relatively cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 150.0;
    }

    // Penalize tiny unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    score
}

