pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize large dead space: post_residual that few future items can use.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powi(3);
        score += 60.0 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (pairing bonus).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; small penalty for wasting space.
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item fits poorly everywhere (large relative to residuals) or the
    // stream is early (plenty of future items to fill it).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let tightness = bin_residual as f64 - item_size as f64; // post_residual of fresh bin
        // Penalize new bins more as the stream progresses (less time to fill them).
        score += 30.0 + 70.0 * progress;
        // But if the new bin's post-residual matches the next item, soften.
        if next_item_size > 0 && (next_item_size as f64 - tightness).abs() < 1.0 {
            score -= 60.0;
        }
        // If existing bins are very full on average, a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Global pressure: many open bins with small mean residual -> consolidate.
    let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
    score -= 8.0 * pressure;

    // Mild time-horizon shaping: later in the stream, prefer tighter packing.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

