    score += (pr * pr) / (cap * cap) * (30.0 + 60.0 * t);

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (1.0 + 0.5 * t);

    // Last-chance bin: smooth bonus scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * t;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: prefer bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 8.0 * (post_residual - next_item_size) as f64 / cap;
    } else if next_item_size > 0 {
        score += 6.0 * t;
    }

    // Mild penalty for spreading across many open bins when residuals are small
    score += 0.4 * open_bins_count as f64 * (1.0 - (mean_residual / cap).min(1.0));

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 10.0 * t - 20.0 * (1.0 - norm_pr.min(1.0));
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
