    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                // MUTATE: exact-fill bonus scaled by scarcity of hosts for next item
                if fitting_bins_count <= 3 {
