                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        // MUTATE: avoid opening a new bin late in the stream unless waste is small
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        // MUTATE: stronger late-stream gating — open new bins only if leftover can host next item
        if progress > 0.5 && nx > 0.0 && pr < nx && open_bins_count >= 3 {
            score += 0.8 * progress ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is the residual?
    // Residuals divisible by common item sizes (or landing in friendly bands)
    // are more valuable than awkward dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity band penalty: dead space in (0,10) is nearly unusable
    // since items are >= 1 but typical streams have larger items; strongly
    // penalize tiny unusable slivers, reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: dominant reward
    } else {
        // modulo classes of post_residual against common item sizes
        let mut harmony_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                harmony_bonus += 8.0;
            }
        }
        // awkward sliver: residual too small for any plausible next item
        if post_residual < 10 {
            harmony_bonus -= 25.0;
        } else if post_residual <= 20 {
            harmony_bonus -= 5.0;
        }
        score -= harmony_bonus;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if next item is a near-miss (just above post_residual).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins. Only attractive when this bin's fit is bad.
    if bin_residual == bin_capacity {
        // new empty bin: score = capacity baseline; penalize by open-bin waste
        score += open_bins_count as f64 * mean_residual * 0.5;
        // but if the item is huge relative to capacity, new bin is fine
        score -= (item_size as f64 / cap) * 20.0;
    } else {
        // prefer tighter fits among open bins: scale by fullness
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= fullness * 15.0;
    }

    // Late in the stream, consolidation matters more; early on, keep options open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - pr / cap);

    // Mild tie-break toward bins below mean residual (keep big holes for big items).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

