                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if open_bins_count >= 2 && fitting_bins_count >= 2 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (0.5 + 0.5 * progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Dead-space classes: residuals that few item sizes can fill are bad.
    // Items are 1..=100, so any residual is fillable, but small residuals
    // waste less absolute space — keep base score = post_residual.

    // Modulo-class penalty: residuals in "awkward" classes (not divisible
    // by common item sizes 5/10/20/25) are harder to pack.
    let awkward = (post_residual % 5 != 0) as f64 * 8.0
        + (post_residual % 10 != 0) as f64 * 6.0
        + (post_residual % 20 != 0 && post_residual % 25 != 0) as f64 * 4.0;
    score += awkward;

    // Lookahead harmony: does next_item_size fit exactly or well in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let chain_left = post_residual - next_item_size;
            score -= 30.0 + (chain_left as f64).min(50.0) * 0.5;
            // harmonic bonus if chain leaves a "round" residual
            if chain_left % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize mildly, more if this was
            // the only fitting bin (forcing a new bin later anyway).
            score += 10.0 + if fitting_bins_count == 1 { 20.0 } else { 0.0 };
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): open a fresh bin only when the current
    // item is large relative to capacity or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer new bin when item is big (would leave tiny post_residual
        // elsewhere) and stream is early (long horizon to use the bin).
        let big_item = (item_size as f64 / bin_capacity as f64) * 250.0;
        score += 120.0 - big_item * (1.0 - progress * 0.5) - fragmentation * 0.3;
        // Late in stream, prefer reusing open bins.
        score += progress * 80.0;
        // Many open bins: discourage spreading.
        score += open_bins_count as f64 * 2.0;
    }

    // Slight preference for bins with residuals near the mean (balanced packing).
    score -= 5.0 / (1.0 + ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
