        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.3 && waste < 0.45 && nx > 0.0 && nx > pr {
            score += 0.7 * (0.45 - waste) * (1.0 + 0.5 * progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count == 1 && waste > 0.7 {
            score += 0.8 * (waste - 0.7) * (1.0 + 0.5 * progress) ;
        }
        if open_bins_count >= 2 && fitting_bins_count >= 2 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (0.5 + 0.5 * progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // new-bin leftover can't host next item but some open bin can
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        // reward fresh bin when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        // two-step lookahead on fresh bin
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 4.0 && norm_gap < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - norm_gap / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        let dead = pr / br . max (1.0) ;
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.4 && pr >= nx && nx > 0.0 && (pr - nx) >= 1.0 && (pr - nx) <= 10.0 && mean_residual < cap * 0.4 {
            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward if the NEXT item exactly fills the leftover space.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 55.0; // perfect chain: this bin will be exactly closed by next item
        } else if diff <= 5 {
            score -= 25.0;
        } else if diff <= 10 {
            score -= 10.0;
        } else {
            // next item cannot use the leftover well: mild penalty proportional to gap
            score += (diff as f64 - 10.0).min(30.0) * 0.3;
        }
    }

    // Penalize dead space relative to mean residual: bins with residual far above mean
    // that stay large after placement waste capacity.
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += dead * 0.15;
    } else {
        score += dead * 0.05; // slight reward for bringing residual toward/below mean
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (post_residual <= 10) as i32 as f64 * 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity and no good fit exists. Penalize mildly by default,
    // but scale penalty down as the stream progresses and open-bin count is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (open_bins_count as f64 / 10.0).min(2.0);
        let mut new_bin_penalty = 12.0 + crowding * 5.0;
        // Large items (little room elsewhere) make new bins more acceptable.
        if item_size >= 60 { new_bin_penalty -= 10.0; }
        if item_size >= 80 { new_bin_penalty -= 8.0; }
        // Late in the stream, prefer closing out existing bins.
        new_bin_penalty += progress * 10.0;
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
