            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // chaining: leftover hosts next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // tiny leftover slivers keep bins near-closed
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && pr >= nx * 0.9 && pr < nx {
                score += 0.7 * (1.0 - (nx - pr) / 4.0 . max (nx * 0.1 + 1.0)) . max (0.0) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        // dead-space coupling: high dead ratio while other bins are roomier
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.3 && waste < 0.45 && nx > 0.0 && nx > pr {
            score += 0.7 * (0.45 - waste) * (1.0 + 0.5 * progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        // leftover can't host nx but some open bin can — penalize opening
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        // reward opening a fresh bin when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        // penalize fresh bin whose leftover is a bad host for anything
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // keep bin pool balanced: bonus when post-residual matches mean residual
        if pr > 4.0 && norm_gap < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - norm_gap / 3.0) * (0.5 + 0.5 * progress) ;
        }
        let dead = pr / br . max (1.0) ;
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (wasted space is quadratic dead weight).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste_frac * waste_frac;

    // Lookahead: bonus if the next item exactly fits the post-residual (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but a large leftover after that is still bad.
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the leftover: penalize proportionally to leftover size.
            score += 0.35 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Fragmentation guard: penalize leaving residuals that are hard to fill
    // (small odd leftovers below the typical minimum item chunk).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Global balance: prefer bins whose residual is close to the mean residual
    // (keeps open bins uniformly filled, easier to close them out).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in the stream: keep bins comparable so future items have options;
    // late in the stream: prioritize tight packing since fewer items remain.
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * progress * (1.0 - waste_frac);

    // Many open bins: discourage opening yet another bin unless fit is excellent.
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline slightly above a perfect fit,
        // cheaper when few bins are open or the item is small relative to capacity.
        let load_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 55.0 + 30.0 * (1.0 - load_frac);
        new_bin_score -= 10.0 * (open_bins_count as f64).ln().max(0.0);
        new_bin_score += 15.0 * waste_frac;
        // Late in stream, reusing existing bins matters more.
        new_bin_score += 25.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
