        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        // REFINE: late-stream — forbid new bins unless waste is small or no open bin fits
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let x = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    let coupling = x * x * (1.0 - p) - x * p * (1.0 - x);
    score += 12.0 * coupling;

    // Reward tight fits smoothly
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit * fit * (1.0 - p);

    // Penalize dead space that next item cannot use (smooth)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 6.0 * gap * gap;
        let next_fits = next_item_size as f64 <= pr;
        if next_fits { score -= 4.0 * (1.0 - p); }
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 10.0 * (1.0 - x) * (1.0 - p);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * x;

    // Prefer bins below mean residual (consolidation), smooth
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev.abs().sqrt();

    // New-bin candidate: penalize mildly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - p) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" sizes
    // (small, or multiples of common item sizes 10..80).
    let pr = post_residual as i64;
    let mut harmonic_bonus: f64 = 0.0;

    if pr == 0 {
        harmonic_bonus -= 60.0; // perfect fill
    } else if pr < 10 {
        harmonic_bonus -= 40.0; // dead space below minimum item size
    } else {
        // modulo classes on post_residual over base 10..20 harmonics
        if pr % 10 == 0 { harmonic_bonus -= 25.0; }
        else if pr % 20 == 0 { harmonic_bonus -= 30.0; }
        else if pr % 25 == 0 { harmonic_bonus -= 20.0; }
        else {
            // penalize residuals in awkward bands
            let band = (pr % 50) as f64;
            harmonic_bonus += band * 0.15;
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            harmonic_bonus -= 20.0 + slack * 0.1;
            // exact chain fit is ideal
            if post_residual == next_item_size { harmonic_bonus -= 35.0; }
        } else {
            harmonic_bonus += 15.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        harmonic_bonus -= 45.0;
    }

    // Avoid wasting a nearly-empty bin when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        harmonic_bonus += (open_bins_count as f64 - 4.0) * 1.5 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual
    score += harmonic_bonus;
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-ish; only open new bin if placement
    // would leave bad dead space
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual > 0 && post_residual < 10)
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        if !bad_fit {
            score += 12.0; // slight bias toward existing bins
        } else {
            score -= 30.0; // opening fresh bin avoids dead space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // Small post residuals are near-dead space: reward closing them out (borrowed from best).
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after >= 1.0 && after <= 12.0 { score -= 6.0; }
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            if after == 0.0 { score -= 3.0; }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            if after == 0.0 && fitting_bins_count <= 2 {
                score -= 1.5 * (1.0 - progress);
            }
        } else {
            // Next item cannot use this bin's post residual: penalize the gap.
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // Dead-space ratio coupling (borrowed from best heuristic).
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if fitting_bins_count <= 1 && pr > 0.0 && pr >= nx && nx > 0.0 {
        score -= 4.0 * (1.0 - progress);
    }
    // Keep bin pool balanced.
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // Penalize opening a new bin whose leftover can't host next item while open bins can.
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
