        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.3 && mean_residual < cap * 0.2 && nx > 0.0 && pr >= nx {
            score -= 0.8 * (1.0 - waste / 0.3) . abs () * (0.5 + 0.5 * progress) ;
