pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to ever hold a plausible item (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual > 0 {
        // Usable leftover space is mildly good; reward proportionally.
        score -= 0.05 * (post_residual.min(60) as f64);
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit in post residual, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size <= bin_residual {
            // Next item would fit better in another bin; mild penalty.
            score += 3.0;
        }
        // Chain bonus: next item exactly fills post residual.
        if next_item_size == post_residual && post_residual > 0 {
            score -= 15.0;
        }
    }

    // Global state: when many bins are open, discourage spreading into new bins
    // and encourage consolidating into bins with above-average residual.
    if bin_residual as f64 > mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // Base cost of a new bin, modulated by progress and open bin count.
        score += 55.0 - 25.0 * progress + 0.5 * open_bins_count as f64;
