        if item_size >= 50 {
            score -= 10.0;
        }
        // If no open bin can fit (fitting_bins_count==0 handled elsewhere),
        // the new-bin candidate should win; give it a strong discount.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    // Discourage placing small items into large residuals early (waste of space),
    // encourage it late (consolidation).
    let small_item = item_size <= 30;
    if small_item {
        score += (1.0 - progress) * 6.0 - progress * 4.0;
    }

    // Mild penalty proportional to how much of the bin's residual is consumed
    // wastefully (item much smaller than residual).
    let waste = (bin_residual - item_size) as f64;
    if waste > 40.0 {
        score += 0.08 * (waste - 40.0);
    }

    score
}

