    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear emphasis on tight fits.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: later in the stream,
    // dead space becomes costlier, so tighten preference quadratically/cubically.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * progress * progress;
    score *= progress_coupling;

    // Reward last-chance bins (avoid opening a new bin) with a smooth term.
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (place into bins that are relatively full), smooth quadratic penalty.
    let mean_norm = mean_residual / cap;
    score += 4.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm) * (1.0 - norm_pr);

    // Lookahead: if the next item can use the post_residual, reward leaving it;
    // smooth interaction with post_residual size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let usable = (pr - ni).abs() / cap;
        score += 3.0 * usable * usable * (1.0 - progress);
    }

    // Slight penalty for proliferating open bins, smooth in count.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

