pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 60.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item is large and would not fit here, mildly discourage wasting residual.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins when many bins are open (reduce bin count pressure).
    let fill_ratio = 1.0 - tightness;
    score -= fill_ratio * (open_bins_count as f64).ln().max(0.0) * 8.0;

    // Compare residual against mean residual: prefer bins below-mean residual (fuller than average).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: neutral-to-slightly-high baseline so new bins are
    // opened only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper; late, avoid fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If next item is huge, a fresh bin preserves flexibility.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild time-horizon term: late in the stream, favor aggressive packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * fill_ratio;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 26.5 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
                // exact-fill with several alternatives: slightly less urgent
                if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
