            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            // REFINE: after-space too large relative to nx wastes room — mild penalty late
            if after > 3.0 * nx && after > 20.0 && progress > 0.5 {
                score += 0.4 * (1.0 - progress) ;
