        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // REFINE: late-stream — new bins only when the leftover can chain the next item
        if progress > 0.75 && nx > 0.0 && pr >= nx && (pr - nx) > 0.5 * nx {
            score -= 0.6 * progress ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (chain packing), penalize near-misses that
    // strand small dead space.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let gap = post - next;
            if gap == 0.0 {
                score -= 800.0; // perfect chain: next item fills this bin exactly
            } else if gap <= 10.0 {
                score -= 400.0; // near-perfect chain
            } else {
                score -= (next / post) * 150.0; // proportional fit reward
            }
        } else {
            // Next item cannot fit here; post residual becomes dead space.
            score += (next - post) * 2.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (post_f - mean_residual) * 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize wasting a nearly-empty bin on a small item (bad dead-space trade).
    if item_size < bin_residual / 3 {
        score += 60.0;
    }

    // Late-stream pressure: as the stream progresses, prefer tighter packing
    // and be more reluctant to open new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 80.0;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 3.0;

    // New-bin candidate: only attractive when nothing decent fits.
    if bin_residual == bin_capacity {
        score += 350.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative: opening a new bin is correct
        } else if next_item_size > 0 && post_residual == bin_capacity - item_size {
            // Opening fresh for a large item that leaves room for the next one.
            let room = (bin_capacity - item_size) as f64;
            if room >= next_item_size as f64 {
                score -= 120.0;
            }
        }
    }

    score
}

