pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space only if it's likely unusable (dead zone).
    // Residuals in (0, 10) are effectively dead; residuals that exactly fit are perfect.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score += 20.0; // small unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global pressure: when many bins are open, prefer consolidating into existing bins
    // rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 5.0 * open_pressure;
    } else {
        // New-bin candidate: penalize opening new bins when open bins have slack.
        score += 15.0 + 10.0 * open_pressure;
        // But if mean residual is small (bins nearly full), a new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 25.0;
    }

    // Time horizon: early in the stream, be conservative with new bins (long future);
    // late in the stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress); // new bins cost more early on
    } else {
        score -= 10.0 * progress; // existing bins favored more later
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (balanced packing), avoiding extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    score
}

