            score -= 2.0 * (1.0 - progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        // near-perfect fit missed by 1-2 units: mildly penalize (stranded sliver)
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        // prefer bins whose post-residual becomes near-zero dead space
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        // mid-range dead space that cannot host nx — push toward tighter bins
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        // residual that is a multiple of common small-item sizes keeps future fits cheap
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        let dead = pr / br . max (1.0) ;
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // REFINE: near-exact next-item fit bonus
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        // REFINE: keep bin pool balanced around mean residual
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);

    let mut score = pr + 40.0 * poly;

    // Penalize dead space more strongly as the stream progresses
    score += 30.0 * norm_pr * norm_pr * progress;

    // Reward tight fits
    score -= 25.0 * norm_item * (1.0 - norm_pr);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty when many bins are open relative to progress (encourage consolidation)
    score += 2.0 * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()) * (1.0 - progress);

    // New-bin candidate: slightly penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 10.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fraction classes) ---
    // Residuals are classified by integer division into "harmonic" bands:
    // class 0: post_residual == 0 (perfect closure)
    // class 1: tiny dead space (1..=9) -> nearly unusable, penalize hard
    // class 2: small (10..=19) -> only fits smallest items
    // class 3: medium (20..=49) -> reusable
    // class 4: large (>=50) -> highly reusable
    let post_class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 9 {
        1
    } else if post_residual <= 19 {
        2
    } else if post_residual <= 49 {
        3
    } else {
        4
    };

    match post_class {
        0 => { score -= 60.0; }                       // perfect fit: strong reward
        1 => { score += 25.0; }                       // dead space: hard penalty
        2 => { score += 8.0; }                        // marginal space
        3 => { score -= 5.0; }                        // decent leftover
        _ => { score -= 12.0; }                       // big leftover: very reusable
    }

    // --- Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are "harmonic" and more reusable ---
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
        // Odd, non-round residuals are awkward
        if post_residual % 5 != 0 { score += 3.0; }
    }

    // --- Lookahead: does the next item fit into the post residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact harmonic match with the next item is gold.
        if post_residual == next_item_size {
            score -= 45.0;
        } else {
            let next_leftover = post_residual - next_item_size;
            if next_leftover <= 9 {
                score += 10.0; // chains into dead space: bad
            } else {
                score -= 15.0; // next item also fits: chain reward
            }
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: leftover likely wasted
        let gap = next_item_size - post_residual;
        if gap <= 9 {
            score += 12.0; // near-miss: painful dead space
        } else {
            score += 4.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual is large, so the class
        // reward already applies. Add a mild preference so we only open a new
        // bin when existing fits are clearly poor (their penalties push them up).
        score += 10.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins are open, discourage adding more unless needed.
        score += 2.0 * open_bins_count as f64;
    }

    // --- Last-chance bin: if this is the ONLY bin that fits, use it rather
    // than opening a new bin (avoid bin proliferation) ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // --- Congestion: when many bins compete, prefer tighter fits even more ---
    if fitting_bins_count > 2 {
        score -= 0.5 * (post_residual as f64).ln().max(0.0);
    }

    // --- Mean residual coupling: if the average leftover across bins is low,
    // conserve remaining space more aggressively ---
    if mean_residual < 15.0 && post_residual > 0 && post_residual <= 19 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty grows if the leftover gap cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward bins whose post-residual can still host the next item.
