            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // Base tight-fit term.
    score += 0.012 * (mean_residual - br).abs();

    // Tiered leftover rewards: perfect / near-perfect fits are strongly preferred.
    if pr == 0.0 {
        score -= 28.0;
    } else if pr <= 2.0 {
        score -= 14.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    } else if pr < 0.25 * cap {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // Lookahead: reward leaving space the next item can use, especially tightly.
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            let gap = after / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            if after == 0.0 {
                score -= 4.0;
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // Chainable: after-space that could host next item twice.
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
            // Awkward leftover: barely bigger than next item.
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress);
            }
        } else if pr > 0.0 {
            // Dead space for the lookahead item: penalize, worse early.
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // Small unusable gaps that next item cannot fill.
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 * (1.0 - progress);
        if nx > 0.0 && pr >= nx {
            score -= 3.0;
        }
    }

    // Consolidation pressure when many bins are open.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 20.0);
    score += pressure * 1.2;

    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        // New-bin candidate: penalize by default; only attractive when open bins fit poorly.
        score += 30.0;
        if open_bins_count > 0 && fitting_bins_count >= 1 {
            score += 3.0 + waste * 4.0;
            if mean_residual > cap * 0.5 {
                score += 2.0;
            }
        }
        // Reward opening when leftover after next item would also be small.
        if nx > 0.0 && waste * cap >= nx {
            let after2 = waste * cap - nx;
            if after2 < 6.0 {
                score -= 1.2 * (1.0 - after2 / 6.0) * (0.4 + 0.6 * progress);
            }
        }
        // Late in stream: avoid wasteful new bins.
        score += progress * 4.0;
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else if open_bins_count >= 3 {
            score += 1.0 * (waste - 0.35) * (1.0 + progress);
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
    } else {
        // Dead-space ratio analysis for open bins.
        let dead = pr / br.max(1.0);
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75);
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress);
        }
        // Pool balancing: keep residuals near mean when dead space is low.
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35)
                * (1.0 - (mean_residual - br) / mean_residual.max(1.0))
                * (0.5 + 0.5 * progress);
        }
        // Near-exact next-item fit in residual.
        if pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress);
        }
    }

    score
}

