            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // REFINE: late-stream — forbid new bins when a mean-residual open bin can host next item too
        if progress > 0.8 && open_bins_count >= 2 && mean_residual >= nx && waste > 0.25 {
