        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // MUTATION: forbid new bins late when mean residual is still healthy
        if progress > 0.8 && open_bins_count > 0 && mean_residual >= it {
            score += 1.2 * progress * (mean_residual / cap) ;
