        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit strongly rewarded
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class: prefer post_residual that lies in "usable" small-residue classes
    // Residues <= 10 are near-dead space (min item is 1 here); residues divisible by
    // common item sizes (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    let dead = (pr > 0 && pr < 10) as f64 * 25.0;
    score += dead;

    let reusable = ((pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0)) as f64;
    score -= reusable * 12.0;

    // Integer-division threshold on post_residual: half-full or better bins are attractive
    if pr >= bin_capacity / 2 {
        score -= 8.0;
    } else if pr >= bin_capacity / 4 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: penalize proportionally to wasted fraction after next
            let after = pr - next_item_size;
            score -= 10.0 - (after as f64 / bin_capacity as f64) * 10.0;
        } else {
            // next item won't fit here: mild penalty scaled by gap class
            let gap = next_item_size - pr;
            score += (gap / 10).min(5) as f64 * 2.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin is fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        score += 20.0 + 15.0 * (1.0 - progress) - fragmentation.min(30.0);
        // modulo class on item size: large items (mod classes 60..100) justify new bins
        if item_size > bin_capacity / 2 {
            score -= 18.0;
        }
    }

    // Mild pressure against accumulating many open bins with high mean residual
    score += (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
