            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        // open bin whose post-residual tightly hosts the next item when bins scarce
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        // near-perfect fit missed by 1-2 units: mildly penalize (stranded sliver)
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        // prefer bins whose post-residual becomes near-zero dead space
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        // mid-range dead space that cannot host nx — push toward tighter bins
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        // residual that is a multiple of common small-item sizes keeps future fits cheap
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // dead-space ratio penalties from best variant, adapted
        let dead = pr / br . max (1.0) ;
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // COMBINED: residual-pool balancing — prefer fat bins when many bins are open
        if open_bins_count >= 4 && br > mean_residual * 1.2 && pr > 3.0 && nx > 0.0 && nx <= pr {
            score -= 0.35 * (1.0 - mean_residual . max (1.0) / br) * (0.6 + 0.4 * progress) ;
        }
        // COMBINED: exact nx fit in open bin with low dead ratio — extra reward
        if dead <= 0.4 && nx > 0.0 && pr >= nx && (pr - nx) < 0.02 * cap {
            score -= 1.2 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it partitions the capacity
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Dead-space penalty by harmonic class
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible
    } else if post_residual < tenth {
        score -= 25.0; // near-perfect, nearly unusable sliver anyway
    } else if post_residual <= fifth {
        score += 10.0; // small but usable pocket
    } else if post_residual <= quarter {
        score += 18.0;
    } else {
        score += 25.0 - (post_residual as f64) * 0.1; // large residual keeps flexibility
    }

    // Modulo harmony: residual divisible by small classes is more reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        }
        if post_residual % 3 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post residual exactly/well
    if next_item_size > 0 && post_residual >= next_item_size {
        let nxt_left = post_residual - next_item_size;
        score -= 14.0;
        if nxt_left <= fifth {
            score -= 10.0; // chains into another near-closure
        }
        if nxt_left % 10 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize by wasted fraction
        let waste = next_item_size as f64 - post_residual as f64;
        if waste > fifth as f64 {
            score += 6.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // the fit here is terrible (large item in fresh bin is fine)
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big item pairs well with fresh bin
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_frac;

    // Stream phase: early on, keep bins balanced; late, close aggressively
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += phase * (post_residual as f64 - mean_residual) * 0.05;

    score
