pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (small post_residual is good).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 300.0 * tightness * tightness;
    }

    // Aggressive 2-step lookahead: if the next item fits into the post-residual,
    // this placement chains perfectly — reward it heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        score -= 200.0;
        score -= (bin_capacity as f64 - chain_slack as f64) * 0.5;
        // Perfect chain (next item exactly fills the remainder)
        if chain_slack == 0 {
            score -= 500.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, especially
        // if that dead space is too small for typical future items.
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += 150.0 * (1.0 - dead / (next_item_size as f64));
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Compare against mean residual: prefer using bins with residual close to
    // the mean (balanced usage) but favor bins tighter than the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 + 100.0 * progress;
        // New bin is acceptable if no open bin can fit (fitting_bins_count == 0
        // for open bins) or item is huge and would leave near-zero waste elsewhere.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 60.0;
        }
    }

    // Slight preference for bins with larger residual when item is small
    // (keeps tight bins for tight items).
    if item_size <= 30 {
        score += (bin_capacity as f64 - bin_residual as f64) * 0.1;
    }

    score
}

