pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Quarters of capacity: leftover in [0,25) is nearly dead space -> heavy penalty.
    if post_residual < bin_capacity / 4 {
        score += 60.0 * (1.0 - post_f / (cap / 4.0));
    } else if post_residual < bin_capacity / 2 {
        // [25,50): awkward class, mild penalty
        score += 12.0;
    } else if post_residual < (3 * bin_capacity) / 4 {
        // [50,75): decent class, small reward
        score -= 8.0;
    } else {
        // [75,100): excellent leftover, strong reward
        score -= 20.0;
    }

    // Integer-division harmonic class: post_residual mod 10 (items are 1..100 ints).
    // Leftovers that are tiny modulo slivers (1..=5) are hard to reuse.
    let m = post_residual % 10;
    if m >= 1 && m <= 5 {
        score += 6.0;
    }

    // Perfect-harmonic leftovers: post_residual divisible by 10 or 25 are attractive targets.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Exact fit: perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that placement drives a harmonic penalty
            let post2 = post_residual - next_item_size;
            let m2 = post2 % 10;
            if m2 >= 1 && m2 <= 5 {
                score += 5.0;
            }
            if post2 < bin_capacity / 4 {
                score += 8.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers less if
            // other bins exist that could absorb next item; penalize small leftovers more.
            if post_residual < next_item_size && post_residual < bin_capacity / 4 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has high residual; only prefer it when
    // no open bin offers a good harmonic fit (large item relative to capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset when the item is large and would
        // otherwise leave a bad fractional class in an existing bin.
        score = 0.55 * cap;
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 0.35 * cap * (frac - 0.5);
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        score += 8.0 * fitting_bins_count as f64;
        // If mean residual is large, existing bins have room: discourage new bin.
        score += 0.2 * mean_residual;
    }

    score
}

