            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // MUT: never open a new bin late when an open bin can host the next item too
        if progress > 0.9 && waste > 0.25 && fitting_bins_count >= 1 && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.8 * (waste - 0.25) * (1.0 + progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the minimum item size (1..10 range)
    // are effectively unusable; penalize heavily in the small-gap zone.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    } else if post_residual < 20 {
        // Small gaps that only tiny items can fill: moderate penalty.
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open,
    // to avoid fragmentation; scale with stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin gets a base offset so it
    // is chosen only when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Opening a new bin is more attractive late in the stream when
        // mean residuals across open bins are small (little reusable space).
        if mean_residual < item_size as f64 + 10.0 {
            score -= 35.0;
        }
        // Prefer opening a fresh bin if the next item would not fit the
        // post-residual anyway (lookahead awareness).
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    } else {
        // Lookahead: penalize placements in open bins whose post-residual
        // cannot fit the next item but is too large to be dead space.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 5.0;
        }
    }

    // Mild alignment with mean residual: prefer bins close to the mean
    // to keep residual distribution balanced.
    score -= ((post_residual as f64 - mean_residual).abs()) * -0.5;

    score
}

