pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in low classes (tiny slivers)
    // are dead space -> penalize; perfect/zero leftovers -> reward.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let residue_class = post_residual / eighth; // 0..=8 harmonic class
    match residue_class {
        0 => score -= 12.0,                       // near-perfect fit
        1 => score -= 6.0,                        // excellent fit
        2 => score -= 2.0,                        // good fit
        3 => score += 0.0,                        // neutral
        4 => score += 3.0,                        // quarter empty
        5 => score += 6.0,
        6 => score += 9.0,
        7 => score += 12.0,                       // mostly empty: wasteful placement
        _ => {}                                   // class 8 = brand-new bin
    }

    // Modulo arithmetic: leftover congruent to common small sizes (10..=30)
    // is reusable by typical small arrivals -> reward reusability.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual >= 10 && post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (guaranteed two-item packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residue: judge that residue
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score -= 8.0; // next item nearly fills bin
            } else {
                score -= 2.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty
            // scaled by how much dead space we would strand.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0 + (post_residual as f64) * 0.03;
    }

    // New-bin candidate handling: an empty bin has neutral base but should
    // only win when open bins offer poor fits. Penalize opening a new bin
    // more when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    }

    // Tie-break toward bins with residuals close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.02;

    // Slight preference for bins below mean residual (consolidating space)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

