pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest
    // future item are pure waste; penalize them super-linearly.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }
    // General dead-space curve: small nonzero residuals are the worst.
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 200.0 / (pr + 1.0);
    }

    // Reward tight fits (small waste relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation,
    // penalize spreading across bins.
    score += 3.0 * open_bins_count as f64;

    // Prefer bins with residual below the mean (filling the emptiest-ish
    // bins first keeps a set of large residual bins alive).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 / (gap + 1.0);
    }

    // New-bin candidate logic: an empty bin has a high base score so it is
    // only chosen when existing bins are truly poor fits; ease this when
    // few bins are open or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 180.0 - 60.0 * progress - 8.0 * open_bins_count as f64;
        // If no open bin can fit at all, new bin is mandatory anyway.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    score
}

