    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, just close bins out.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * (post_residual as f64) * 0.15;
    score -= t * 2.0;

    // Global residual balance: avoid bins far from the mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03 * (1.0 - t);

    // Discourage opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
        if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

