        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin: leftover hosts next item then nears zero
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - after2 / 6.0) * (0.4 + 0.6 * progress) ;
            }
            // near-miss for nx: opening a new bin that just barely misses nx strands space
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // triple lookahead: after2 can host a second copy of nx
            if after2 >= nx && after2 <= 2.0 * nx + 4.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after2 - nx) / (nx + 4.0)) * (0.5 + 0.5 * progress) ;
            }
        }
        // penalize fresh bin whose leftover is a bad host for anything
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        // penalize opening a new bin when an existing fit leaves near-zero waste
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.7 && mean_residual >= it {
            score += 0.9 * (waste - 0.7) * (0.6 + 0.4 * progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        // open bin whose post-residual tightly hosts the next item when bins scarce
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        // near-perfect fit missed by 1-2 units: mildly penalize (stranded sliver)
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        // prefer bins whose post-residual becomes near-zero dead space
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        // mid-range dead space that cannot host nx — push toward tighter bins
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        // residual that is a multiple of common small-item sizes keeps future fits cheap
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // dead-space ratio penalties from best variant, adapted
        let dead = pr / br . max (1.0) ;
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // residual-pool balancing — drain fat bins first when many are open
        if open_bins_count >= 4 && br > mean_residual * 1.2 && pr > 3.0 && nx > 0.0 && nx <= pr {
            score -= 0.35 * (1.0 - mean_residual . max (1.0) / br) * (0.6 + 0.4 * progress) ;
        }
        // reward low-dead bins whose residual stays near the pool mean
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact match leaves zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the
    // next item size (chain packing), penalize near-misses that strand space.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0;
        } else if (post_residual as f64 - next).abs() <= 5.0 {
            score -= 200.0;
        } else if (next_item_size as u32) > post_residual {
            // next item cannot use the leftover anyway: mild penalty scaled by gap
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
        // reward leaving residual usable by the next item at all
        if post_residual >= next_item_size {
            score -= 0.5 * (post_residual as f64 - next);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    // (best-fit flavor), penalize bins much looser than average.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize large dead space quadratically (unusable fragments).
    score += 0.02 * (post_residual as f64).powi(2);

    // Slight preference for consolidating into fewer bins as stream progresses.
    if open_bins_count > 1 {
        score -= 0.1 * open_bins_count as f64;
    }

    // New-bin candidate: opening a fresh bin should only win when the fit is
    // poor; make the empty bin moderately unattractive by default.
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual is good).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Penalize small unusable dead space: residual below smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 0.8;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Waste: post residual can't fit next item; penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // Prefer bins with residual above the mean (balance across bins),
    // so we drain the "fattest" bins first and keep small residuals for small items.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early on, be conservative about filling bins unevenly;
    // later, exploit tight fits more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= tightness * progress * 15.0;

    // When many bins are open, encourage consolidating into them rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // New-bin candidate: make it moderately unattractive unless the item fits
    // nothing well elsewhere; empty-bin score baseline.
    if bin_residual == bin_capacity {
        score += 10.0 + (item_size as f64) * 0.1;
        // Late in stream with many open bins, opening a new bin is rarely good.
        score += progress * 10.0;
    }

    score
}

