pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: favor tight fits strongly (post residual dominates).
    // Late in the stream: penalize wasted residual more aggressively.
    let p = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += p * post * post / cap; // quadratic waste penalty growing with progress

    // Reward filling the bin well: subtract a smooth function of item size relative to capacity.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * (1.0 - 0.5 * p);

    // Penalize bins that are much tighter than the mean residual (poor spread usage),
    // with a smooth cubic coupling to progress.
    let mean_term = (post - mean_residual) / cap;
    score += mean_term * (0.5 + 2.0 * progress * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // (smoothly scaled by how little space would remain).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post / cap);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild penalty for spreading across many open bins, smoothed by progress.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + p) * 0.5;

    // New-bin candidate: make it moderately attractive only when residuals across
    // open bins are small relative to the item (smooth condition).
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap - item_size as f64 / cap).max(0.0);
        score = 5.0 + 30.0 * (1.0 - (tight * 2.0).min(1.0));
    }

    score
}

