pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: classify dead space into residue classes mod 10.
    // Small residuals (1..10) are near-perfect fits; large residuals are wasted space.
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 && pr <= 10 {
        score -= 60.0; // near-tight fit, excellent
    } else if pr <= 20 {
        score -= 15.0; // decent
    } else if pr <= 50 {
        score += 10.0 + (class as f64) * 0.5; // moderate waste
    } else {
        score += 25.0 + (class as f64); // large dead space penalty
    }

    // Harmonic penalty scaled by fraction of capacity wasted
    let waste_frac = pr as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size < pr && (pr - next_item_size) <= 10 {
            score -= 50.0;
        } else if next_item_size > pr {
            // next item won't fit here; slight penalty for blocking sequence
            score += 8.0;
        }
        // harmonic class match: next item shares residue class with post residual
        if next_item_size > 0 && pr >= next_item_size && (pr % 10) == (next_item_size % 10) {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when item is huge
    // relative to residuals or when open bins are already crowded.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 60 {
            score -= 45.0; // big items deserve fresh bins
        }
        if open_bins_count > 0 && (mean_residual < item_size as f64) {
            score -= 60.0; // no open bin really fits well
        }
        if next_item_size > 0 && next_item_size >= 50 && item_size >= 50 {
            score -= 20.0 * progress; // pair big items in fresh bins late in stream
        }
    } else {
        // existing bin mild bonus when mean residual is high (bins are loose)
        if (bin_residual as f64) > mean_residual {
            score -= 6.0;
        }
        // prefer fuller bins (smaller residual) among open bins
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // Slight preference for fewer open bins early on
    score += open_bins_count as f64 * 0.3 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

