            score -= 4.0;
        } else if next_item_size as f64 > pr && pr > 0.0 {
            // this placement creates a gap that cannot host the next item
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, filling tightly is fine. Coupled with mean residual: prefer
    // bins whose residual is close to the mean (balanced packing), penalize
    // placing into already-tight bins when alternatives exist.
    let fit_quality = item_size as f64 / bin_residual as f64;
    score += fit_quality * 8.0; // prefer bins where item fills a large fraction

    let residual_dev = (bin_residual as f64 - mean_residual).abs();
    score += residual_dev * 0.3;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when no existing bin fits well
    // (i.e., the item is large relative to available residuals and many bins
    // are already open with small residuals).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let new_bin_bonus = 30.0
            - item_size as f64 * 0.2
            - pressure * 4.0
            - progress * 5.0;
        score += new_bin_bonus;
        // A large item into a fresh bin wastes capacity; slight penalty.
        if item_size > 60 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but with slack — mild reward proportional to fit tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * tightness;
        } else {
            // Next item cannot use the post residual: dead space penalty,
            // stronger when the leftover is small (highly fragmented).
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 40.0 * (1.0 - waste) * (1.0 - waste);
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Penalize the brand-new empty bin candidate, but less so when the item
    // is large relative to capacity or when few bins fit the item.
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        let scarcity_bonus = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - 25.0 * large_item_bonus - 60.0 * scarcity_bonus;
    }

    // Early in the stream, allow slightly more freedom to open bins;
    // late in the stream, be stricter about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 26.5 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // REFINE: chainable after-space — leftover after nx can host nx again (double-lookahead)
            if after >= nx && after <= 2.0 * nx + 4.0 && nx >= 2.0 {
                score -= 0.9 * (1.0 - (after - nx) / (nx + 4.0)) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: awkward leftover just above nx — strands a sliver
            if after > nx && after < nx + 3.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: after-space that can still host a mid-size item (>= 20) keeps pool flexible
            if after >= 20.0 && after <= 40.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - (after - 20.0) / 20.0) * (1.0 - progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            // REFINE: near-miss — residual only 1-3 units short of nx; this bin is nearly usable
            if nx - pr <= 3.0 {
                score += 1.2 * (1.0 - (nx - pr) / 3.0) * (0.6 + 0.4 * (1.0 - progress)) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        // REFINE: extreme dead-space with large residual — bin is being hollowed badly
        if dead > 0.9 && pr > 22.0 && fitting_bins_count >= 3 {
            score += 1.0 * (dead - 0.9) * (0.5 + progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }
    // REFINE: pool balancing — drain fat bins first when many are open
    if open_bins_count >= 4 && br > mean_residual * 1.2 && pr > 3.0 && nx > 0.0 && nx <= pr {
        score -= 0.35 * (1.0 - mean_residual . max (1.0) / br) * (0.6 + 0.4 * progress) ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
