            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5) . max (1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin: leftover hosts next item then nears zero
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: triple lookahead — after2 can host nx again, opening is attractive
            if after2 >= nx && after2 <= 2.0 * nx + 4.0 && fitting_bins_count >= 2 {
                score -= 0.7 * (1.0 - (after2 - nx) / (nx + 4.0)) * (0.5 + 0.5 * progress) ;
            }
        }
        // penalize fresh bin whose leftover is a bad host for anything
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        // REFINE: never open a new bin when an open bin already fits and mean residual can host nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && mean_residual >= nx && waste > 0.6 {
            score += 1.2 * (waste - 0.6) * (0.6 + 0.4 * progress) ;
        }
        // REFINE: opening is cheap when mean residual pool is nearly exhausted
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        let dead = pr / br . max (1.0) ;
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // REFINE: reward low-dead bins whose residual is near the pool mean (keeps future fits easy)
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // REFINE: exact-fit lookahead for nx when bins are scarce
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && (pr - nx) < 0.02 * cap && pr > nx {
            score -= 1.5 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small for any plausible future item
    // (items range 1..100, so residual < 10 is nearly unusable).
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 18.0 * (1.0 - leftover as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; slight penalty for stranding this bin.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (plenty of future items to fill them); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late consolidation pressure.
        score += 15.0 * (1.0 - progress);
        score -= 10.0 * progress;
        // Don't open a new bin if the item fits reasonably well somewhere else.
        if fitting_bins_count > 0 && item_size as f64 <= mean_residual {
            score += 20.0;
        }
    } else {
        // Existing bin: mild reward that grows with progress (consolidation).
        score -= 6.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than proliferating.
    if open_bins_count > 3 {
        score += 0.15 * open_bins_count as f64;
        if bin_residual as f64 > mean_residual {
            score -= 3.0; // prefer bins with above-average residual to balance load
        } else {
            score += 2.0;
        }
    }

    // Prefer bins whose residual is close to the item size (minimize waste).
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * waste_ratio * waste_ratio;

    score
}

