pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions.
    // Dead space classes: residuals that few item sizes can use are penalized.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let cls = post_residual / quarter; // 0..4 harmonic class
    match cls {
        0 => {
            // Very small leftover: likely dead space unless exact fit (handled above).
            score += 40.0;
        }
        1 => {
            // Leftover in (25,50]: usable by mid-size items.
            score -= 15.0;
        }
        2 => {
            // (50,75]: highly reusable.
            score -= 25.0;
        }
        _ => {
            // (75,100]: big space remains, fine but keeps bin open.
            score -= 5.0;
        }
    }

    // Lookahead: reward if next_item_size fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Partial credit scaled by how much would remain after next item.
            let next_post = post_residual - next_item_size;
            score -= 60.0 * (1.0 - (next_post as f64) / (bin_capacity as f64));
        } else {
            // Next item cannot use this residual; penalize small unusable leftovers more.
            if post_residual < 10 {
                score += 60.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, reward tighter fits relatively.
        score -= 10.0 * (1.0 - (post_residual as f64) / (bin_residual.max(1) as f64));
    }

    // Prefer filling bins that are already relatively full (reduce bin count pressure).
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * fullness;

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or when
        // open bins are mostly full.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_fullness = 1.0 - mean_residual / (bin_capacity as f64);
        score += 120.0 - 60.0 * avg_fullness - 30.0 * progress;
        // If the current item is large, a fresh bin is naturally good.
        if item_size >= bin_capacity / 2 {
            score -= 50.0;
        }
    }

    // Mild stream-progress modulation: later in stream, be more aggressive
    // about closing bins tightly (favor small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    score
}

