pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot fit the smallest plausible item (1)
    // but more importantly if it is small enough that nothing typical fits.
    let dead_threshold = 10.0f64; // items are >= 1, but typical min in stream unknown; use graded penalty
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Non-linear penalty on post_residual relative to bin capacity:
    // waste grows superlinearly as fraction of capacity left unused.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Reward tight fits (post_residual near 0) strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins,
    // i.e., favor existing bins; the new-bin candidate gets penalized implicitly
    // because its post_residual is large, but add explicit coupling.
    let bin_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportional to open bins count and progress
        score += bin_pressure * 8.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // existing bin: slight reward scaled by open bin pressure
        score -= bin_pressure * 1.5;
    }

    // Mean residual coupling: if mean residual across bins is low, conserve
    // capacity by avoiding bins whose post_residual leaves big gaps.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual * 1.5) * 2.0;
    }

    // Lookahead: if the next item would fit into this bin's post_residual,
    // reward the placement (chaining two items in one bin).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 {
        // next item cannot use the leftover: leftover likely dead space
        score += (post_residual as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-item capacity lookahead
    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.0;

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
