        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.7 && mean_residual >= item_size as f64 {
            score += 0.9 * (waste - 0.7) * (0.6 + 0.4 * progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack * 1.5;
        } else {
            // Next item won't fit here: penalize large dead space that likely becomes waste.
            let dead = (post_residual as f64 - mean_residual).max(0.0);
            score += dead * 0.8;
        }
    }

    // Penalize small unusable residuals (dead space) more than linear.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize leaving residual far below the mean residual (creating outlier waste).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Mild preference for filling bins tighter as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // New-bin candidate: only attractive when it enables a good 2-step chain
    // (empty bin residual = capacity; next item exactly fills after current item).
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            -60.0
        } else {
            0.0
        };
        score += 40.0 + chain_bonus;
    }

    score
}

