        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // Dead space for the known next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to typical residuals or fits are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        // Baseline cost of a fresh bin, discounted by scarcity and item size.
        score = bin_capacity as f64 - (item_size as f64 / 10.0) * (2.0 + 4.0 * scarcity)
            - 30.0 * progress * (mean_residual / bin_capacity as f64);
        // Never open a new bin if a perfect fit exists elsewhere is handled
        // by the -1000 above; keep new-bin score bounded below.
        if score < 0.0 {
            score = 0.0;
        }
    }

    // Mild preference to fill bins with below-average residual (balance load).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Slight time pressure: later in the stream, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

