pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Reward tight fits: small post_residual relative to capacity.
    let post_norm = post / cap;
    score -= (1.0 - post_norm) * (1.0 - post_norm) * 18.0;

    // Penalize dead space that likely cannot be used later: mid-range residuals
    // are the least useful; smooth bump centered at cap/2.
    let dead = post_norm * (1.0 - post_norm) * 4.0; // peaks at 0.5
    score += dead * 10.0;

    // Perfect fit bonus (smooth, near-zero post_residual).
    score -= (1.0 - post_norm).powi(8) * 25.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else {
        // Mild congestion penalty grows with number of open bins.
        score += (open_bins_count as f64).ln() * 2.0;
    }

    // Lookahead coupling: reward leaving space the next item can use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let waste = post - nxt;
            let waste_norm = waste / cap;
            score -= (1.0 - waste_norm * waste_norm) * 14.0;
        } else {
            // Next item won't fit in the leftover: penalize proportionally.
            score += ((nxt - post) / cap) * 12.0;
        }
    }

    // Stream-progress coupling: early on, keep bins flexible (penalize very
    // small leftovers); late, prefer filling bins as tightly as possible.
    let tight = (1.0 - post_norm).powi(3);
    score -= tight * 10.0 * progress;
    score += post_norm * 8.0 * (1.0 - progress);

