pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals in "dead zones" (small but unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes: residuals near multiples of common item sizes are reusable.
    let harmonics: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut harmonic_bonus = 0.0;
    for h in harmonics.iter() {
        if post_residual >= *h && post_residual % h == 0 {
            harmonic_bonus += 8.0;
        } else {
            let r = post_residual % h;
            if r <= 2 {
                harmonic_bonus += 3.0;
            }
        }
    }
    score -= harmonic_bonus;

    // Perfect fit reward (exact fill).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
