    // Fractional-threshold penalty: residual in (0.4C, 0.6C) is versatile, keep it;
    // residual just above small-item sizes is awkward.
    if frac > 0.35 && frac < 0.55 {
        score -= 6.0;
    }

    // Many open bins: discourage spreading, favor tight fills.
    if open_bins_count > 4 {
        score += post_residual as f64 * 0.05 * ((open_bins_count as f64).ln());
    }

    score
}

