    }

    // Reward bins whose residual was already tight (efficient consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // penalize spreading items across too many bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if the item is huge
    // (would leave tiny dead space anyway) or no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0; // default: prefer existing bins
        if item_size >= 90 {
            score -= 45.0; // huge item: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Lookahead: if the next item would fit the post-residual exactly,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 18.0;
        } else if slack < 10 {
            score -= 6.0;
        }
    }
    // If next item cannot fit here, and post-residual is small, slight bonus
    // (bin is "closed" cleanly).
    if next_item_size > post_residual && post_residual < 10 {
        score -= 4.0;
    }

    // Stream progression: late in the stream, be more conservative with
    // new bins (less future to amortize).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // what is being consumed (keeps residuals homogeneous and packable).
    score += 0.15 * (bin_residual as f64 - item_size as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when next item exactly matches post_residual (perfect 2-step chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize leaving residual too small for the next item (dead space).
            if next_item_size > post_residual {
                score += 25.0;
            }
        } else {
            // Next item won't fit here: penalize proportional to wasted residual.
            score += 10.0 + post_residual as f64 * 0.15;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    let cap = bin_capacity as f64;
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    // Mild penalty for very tight leftovers that are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 26.5 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // chainable after-space: can host next item and still leave a small residual
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            // awkward leftover just above next item size
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
            // after-space divisible by small items keeps future fits cheap
            if after >= 4.0 && after <= 20.0 && fitting_bins_count >= 2 && mean_residual > cap * 0.2 {
                score -= 0.4 * (1.0 - (after as u32 % 2) as f64) * (1.0 - progress) ;
            }
            // after-space that could host two more copies of next item
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // triple lookahead: after2 can host a second copy of nx
            if after2 >= nx && after2 <= 2.0 * nx + 4.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after2 - nx) / (nx + 4.0)) * (0.5 + 0.5 * progress) ;
            }
        }
        // penalize fresh bin whose leftover is a bad host for anything
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        // penalize opening new bin when a decent existing fit exists
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.7 && mean_residual >= it {
            score += 0.9 * (waste - 0.7) * (0.6 + 0.4 * progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        let dead = pr / br . max (1.0) ;
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // dead-space fine-tuning: penalize mid-range dead space with large residual
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        // reward low-dead-space bins near mean residual (pool balancing)
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // drain fat bins first when many open
        if open_bins_count >= 4 && br > mean_residual * 1.2 && pr > 3.0 && nx > 0.0 && nx <= pr {
            score -= 0.35 * (1.0 - mean_residual . max (1.0) / br) * (0.6 + 0.4 * progress) ;
        }
        // near-miss within small threshold of nx: mildly reward tighter bins
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize unusable dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use this bin's leftover; leftover likely wasted
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in stream, be pickier (penalize mediocre fits);
    // late in stream, prefer packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.35;
    score -= progress * 6.0;

    // Global state: many open bins -> favor consolidation (existing bins).
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: prefer bins with residual above mean (more usable).
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= (res - mean_residual) * 0.08;
    } else {
        score += (mean_residual - res) * 0.08;
    }

    // New-bin candidate handling: only attractive for large items or when
    // no good existing fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let large = (item_size as f64) / (bin_capacity as f64);
        score += 55.0 - 45.0 * large * large;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big items coming, fresh bin useful
        }
    }

    score
}

