        score -= 26.5 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
