            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        // GEN139: low-dead chain bonus — residual hosts nx twice
        if dead <= 0.3 && pr >= 2.0 * nx && nx >= 3.0 && fitting_bins_count >= 2 {
            score -= 0.5 * (1.0 - dead / 0.3) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        // GEN139: awkward 1..3 overshoot above nx fragments future fits
        if dead > 0.5 && nx > 0.0 && pr > nx + 1.0 && pr < nx + 3.0 && br > 0.55 * cap {
            score += 0.65 * (nx + 3.0 - pr) * (0.5 + 0.5 * progress) ;
