        if dead <= 0.35 && pr >= 2.0 * nx && nx >= 3.0 && fitting_bins_count >= 2 {
            score -= 0.5 * (1.0 - dead / 0.35) * (0.4 + 0.6 * (1.0 - progress)) ;
