pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit), with non-linear shaping.
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space (future items will use it);
    // late, penalize dead space more strongly.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += 0.9 * progress_weight * (post / cap) * (post / cap) * cap;

    // Reward tight fits: post_residual small relative to item size.
    let tightness = 1.0 - (post / residual.max(1.0));
    score -= 6.0 * tightness * tightness * (item / cap);

    // Penalize leaving a sliver that nothing small can use: quadratic valley around tiny post.
    let sliver = (post / cap) * (1.0 - post / cap);
    score += 4.0 * sliver * (post / cap);

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Slight reward for spreading load when many bins can fit.
        score -= 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins below mean residual (fills laggard bins first), smooth cubic coupling.
    let dev = (residual - mean_residual) / cap;
    score += 3.0 * dev * dev * dev.signum().mul_add(1.0, 0.0) + 3.0 * dev;

