        // when open bins are nearly full (mean residual small).
        let crowding = (open_bins_count as f64).ln().max(0.5);
        let fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 + 4.0 * crowding * (1.0 - progress) + 12.0 * (1.0 - fullness);
    }

    score
