    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "useful" classes
    // (multiples of common item granularity) and penalize dead space classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin: reward high fill (low post_residual relative to capacity)
