    // prefer compacting into existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when enough bins are open.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But a new bin is attractive if the next item is large and no open
        // bin would have room for both.
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 > mean_residual {
            score -= 12.0;
        }
    } else {
        // Existing bin: slight reward proportional to open bins count.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use leftover space -> dead space likely.
        score += 8.0;
    }

    // Stream progression: later in the stream, be more conservative with
    // dead space (less time to recover it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below average
    // (compaction) when mean residual is high.
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= nx && nx > 0.0 && (after - nx) >= 1.0 && (after - nx) <= 6.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after - nx) / 6.0) * (0.4 + 0.6 * progress) ;
            }
            if after == 0.0 && fitting_bins_count <= 3 {
                score -= 1.2 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && nx >= 2.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - progress) ;
            }
            if after > nx && after - nx <= 3.0 && fitting_bins_count <= 2 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) ;
            }
            if after > 0.0 && after <= 0.5 * cap && (after / 2.0 - nx) . abs () <= 1.0 && nx >= 2.0 {
                score -= 0.6 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
            // GEN144: deepen mid-band chain reward — after-space 10..18 hosting nx twice with few fitting bins
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && fitting_bins_count <= 3 && nx >= 4.0 {
                score -= 0.45 * (1.0 - (after - 2.0 * nx) / 4.0) * (0.6 + 0.4 * (1.0 - progress)) ;
            }
            // GEN144: tiny sliver after-space is nearly perfect packing
            if after > 0.0 && after < 3.0 {
                score -= 1.4 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if pr > 0.0 && open_bins_count >= 2 && mean_residual >= nx && mean_residual > pr + 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / (nx + 1.0)) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.6 && nx > 0.0 && pr < nx && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.0 * (dead - 0.6) * (1.0 - progress) ;
        }
        if dead > 0.65 && pr > 10.0 && mean_residual < cap * 0.2 {
            score += 0.6 * (dead - 0.65) * (0.5 + 0.5 * progress) ;
        }
        if pr > 6.0 && (pr - mean_residual) . abs () < 5.0 && fitting_bins_count >= 3 {
            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // GEN144: reward low-dead bins whose residual hosts nx twice
        if dead <= 0.45 && pr >= 2.0 * nx && nx >= 4.0 && fitting_bins_count >= 2 && mean_residual < cap * 0.35 {
            score -= 0.4 * (1.0 - dead / 0.45) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        // GEN144: penalize high-dead bins fragmenting into an awkward 1..2 sliver above nx
        if dead > 0.6 && nx > 0.0 && pr > nx && pr - nx <= 2.0 {
            score += 0.5 * (2.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // GEN144: reward bins whose residual is close to a multiple of nx (chainable)
        if dead <= 0.4 && nx >= 3.0 && pr >= nx && (pr % nx) < 2.0 && fitting_bins_count >= 2 {
            score -= 0.45 * (1.0 - dead / 0.4) * (0.5 + 0.5 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
