pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space classification via harmonic classes on post_residual.
    let pr = post_residual;
    // Post-residual classes: small leftovers are hard to reuse.
    if pr < 10 {
        score += 25.0; // tiny sliver, nearly dead space
    } else if pr < 20 {
        score += 10.0;
    } else if pr <= 50 {
        score -= 5.0; // medium residual is reusable by typical items
    } else {
        score -= 2.0; // large residual still useful
    }

    // Lookahead coupling: does next_item_size fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain placement possible: reward proportional to tightness of the chain.
            let chain_tightness = (pr - next_item_size) as f64;
            score -= 15.0 - 0.15 * chain_tightness;
        } else {
            // Next item won't chain here; penalize more if leftover is awkward.
            score += 8.0;
        }
        // Harmonic class match: next item divides residual nicely (integer division).
        if pr >= next_item_size && (pr / next_item_size.max(1)) >= 2 {
            score -= 6.0; // residual can host next item multiple times
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is fresh.
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline, penalize so it's only chosen when
        // existing bins have bad fits (their scores already carry penalties).
        score += 20.0;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins that are already relatively full (small residual before placement).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Mean residual coupling: placing into a bin below mean residual consolidates space.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Many open bins: encourage consolidation.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Modulo harmonic bonus: post_residual in friendly multiples of common item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    }

    score
}

