    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline; discourage unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score = 55.0 - 20.0 * fill_ratio;
        if fitting_bins_count == 1 {
            score += 50.0; // don't open new bin if this is the only fitting one
        }
    }

    // Late-stream tightening: become more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
