            score -= 0.5 * (1.0 - (pr - nx) / 10.0) * (0.5 + 0.5 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already favored by base term).

    // Lookahead: penalize if the next item would NOT fit in the leftover space,
    // slightly reward if it would fit exactly or snugly.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            let snug = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 4.0 * (1.0 - snug.min(1.0));
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing options exist,
    // but allow it when residuals are fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fitting_bins_count > 0 && fragmentation > (item_size as f64 / bin_capacity as f64) {
            score += 12.0;
        } else if fitting_bins_count == 0 {
            score -= 5.0; // no alternative, new bin is fine
        }
        // Mild preference to consolidate early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 2.0 * (1.0 - progress);
    } else {
        // Favor filling bins that are already relatively full (small residual fraction).
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 3.0 * fill;
        // Slight penalty when bin residual diverges from mean (avoid over-fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
        score += 1.5 * dev;
    }

    // Late-stream urgency: prefer closing out bins tightly as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 0.05 * post_residual as f64 * progress;
    }

    // Small penalty for having many open bins (encourage consolidation).
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear penalty on large dead space
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins (small post_residual); later, tolerate slack
    let progress_coupling = 1.0 - 0.5 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);
    score *= progress_coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 12.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 8.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 4.0 * progress * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near/below mean residual (tighter bins)
    score += 0.1 * (mean_residual - pr).abs();

    // New-bin candidate: penalize slightly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-item capacity lookahead
    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.0;

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
                else { score -= 0.8 * (1.0 - progress); }
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0);
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            // chaining: leave room for next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // GEN147: deepen mid-band chain reward — after-spaces that can host nx twice
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && fitting_bins_count <= 3 {
                score -= 0.45 * (1.0 - (after - 2.0 * nx) / 4.0) * (0.6 + 0.4 * (1.0 - progress));
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // awkward sliver just above next item
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress);
            }
            if after > 30.0 && after < 60.0 && nx > 0.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress);
            }
        } else {
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // dead-space below next item size is wasted
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
        if pr < 6.0 { score += 1.0 * (nx - pr) / (nx + 1.0); }
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // last-chance bin
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio (fragmentation) analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 { score += 1.0 * (dead - 0.85) * (1.0 - progress); }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
        score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress);
    }
    if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
        score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0);
    }
    // GEN147: penalize high-dead bins fragmenting into a 1..2 sliver above the next item
    if dead > 0.6 && nx > 0.0 && pr > nx && pr - nx <= 2.0 {
        score += 0.5 * (2.0 - (pr - nx)) * (0.6 + 0.4 * progress);
    }
    // GEN147: reward low-dead bins that can host nx twice even at moderate dead ratio
    if dead <= 0.45 && pr >= 2.0 * nx && nx >= 4.0 && fitting_bins_count >= 2 && mean_residual < cap * 0.35 {
        score -= 0.4 * (1.0 - dead / 0.45) * (0.5 + 0.5 * (1.0 - progress));
    }
    // pool-balance bonus
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    // near-exact next-item fit into residual
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
            if after_new >= nx && nx >= 3.0 && after_new < 2.0 * nx {
                score -= 0.5 * (1.0 - (after_new - nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste * cap >= nx {
            let after2 = waste * cap - nx;
            if after2 < 6.0 {
                score -= 1.2 * (1.0 - after2 / 6.0) * (0.4 + 0.6 * progress);
            }
            if after2 >= 2.0 && after2 <= 7.0 && open_bins_count >= 2 {
                score -= 0.7 * (1.0 - (after2 - 2.0) / 5.0) * (0.5 + 0.5 * (1.0 - progress));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class_penalty: f64 = if post_residual == 0 {
        -60.0 // perfect fit: strongly reward
    } else if post_residual < eighth {
        -20.0 // tiny dead space: nearly perfect
    } else if post_residual <= quarter {
        10.0 // awkward quarter-ish gap
    } else if post_residual <= 2 * quarter {
        0.0 // half-ish gap: reusable
    } else {
        5.0 // large gap: bin barely used
    };
    score += class_penalty;

    // Modulo-arithmetic coupling: reward residuals that are harmonically
    // compatible with common item sizes (multiples of 10 and 20).
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 8.0; }
        if r % 20 == 0 { score -= 6.0; }
        if r % 25 == 0 { score -= 4.0; }
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot use this residual: penalize small leftovers more
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += 5.0 * (1.0 - waste / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
        // but if it creates a very small dead space, reward extra
        if post_residual < eighth && post_residual > 0 {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline that makes it
    // attractive only when the item is large or fits are poor.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // large items: prefer a fresh bin; small items: prefer existing bins
        score = 40.0 - 55.0 * frac;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // stream of large items: fresh bin useful
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer tightening
    // existing bins over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.15;

    // Penalize bins whose residual deviates wildly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

