    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that no item (min size 1..10 typical) can use
    // are pure waste; penalize heavily when post_residual is a small unusable gap.
    let dead_zone = 10u32;
    if post_residual > 0 && post_residual < dead_zone {
        score += 40.0 * (dead_zone - post_residual) as f64;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins when a new bin
    // is competitive; penalize slightly per open bin.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits into the post-residual, reward this bin;
    // if next item would leave a dead gap, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            let next_post = post_residual - next_item_size;
            if next_post > 0 && next_post < dead_zone {
                score += 10.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is near the mean (keep residuals balanced).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Mild progression term: early in the stream, tolerate new bins more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    // New-bin candidate: make it unattractive unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.3;
    }

    score
}

