}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Tight fit reward
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize dead space that nothing small (>=10) can use
    if post_residual < 10 {
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins already below average residual (denser bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin before opening a new bin: strong bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting alternatives exist
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0; // new bin still fine if next item fits
        }
    }

    score
}

