pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with quadratic sharpening
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling with stream progress: later in stream,
    // penalize residual more strongly (waste becomes costlier)
    score *= 1.0 + 1.5 * progress * norm_pr;

    // Reward filling a bin more completely as it shrinks (cubic term)
    let fill = 1.0 - norm_pr;
    score -= 25.0 * fill * fill * fill * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post residual,
    // reward; if post residual is awkwardly close to next item size, penalize
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            score += 10.0 * (-gap / cap).min(1.0);
        }
    }

    // Slight preference to keep mean residual spread balanced
    score += 0.05 * (pr - mean_residual);

    // Mild penalty for proliferating open bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "large dead space" classes are penalized super-linearly.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr / 10; // integer-division class (0..10)
        score += 0.35 * (cls as f64).powi(2);
    }

    // Perfect fit: zero waste is ideal.
    if pr == 0 {
        score -= 25.0;
    } else {
        // Reward small leftovers, especially those matching common item sizes.
        if pr <= 10 {
            score -= 8.0;
        }
        // Harmonic compatibility: leftover that exactly fits the lookahead item
        // (or a small multiple/divisor class of it) is valuable.
        if next_item_size > 0 && pr == next_item_size {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size <= pr {
            score -= 3.0;
        }
        // Dead space: leftover too small for typical items (pr < 10 and
        // smaller than next item) is nearly unusable.
        if next_item_size > 0 && pr < next_item_size && pr < 10 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full
    // (mean residual low) or this bin is a poor fit. Penalize fresh bins
    // mildly so existing capacity is used first.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in the stream, fewer open bins -> be more willing to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Coupling with mean residual: prefer bins below the mean residual
    // (fill the emptiest bins first, keeping tight bins tight).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Prefer placing large items into bins with proportionally small residual.
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += 4.0 * frac * (item_size as f64 / bin_capacity as f64);

    score
}

