pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (< 10, min item size)
    // are worthless; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // gaps of 10..19 are only usable by the smallest items; moderate penalty
        score += 18.0;
    }

    // Reward near-perfect fits (post_residual very small or zero)
    if post_residual == 0 {
        score -= 100.0;
    } else if (post_residual as i64 - 10) <= 0 {
        score -= 25.0;
    }

    // Reward residual closeness to item size (tight fit relative measure)
    let tightness = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent (chains two items).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let next_gap = post_residual - next_item_size;
            if next_gap < 10 {
                score += 15.0; // creates dead space for the following item
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's remainder; slightly penalize
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure
        score += 30.0 + 12.0 * pressure;
        // But if no open bin fits decently, new bin becomes attractive:
        // (fitting_bins_count includes open bins only; new bin always fits)
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            // last-chance existing bin competes; only open new bin if
            // this placement would be very wasteful
            if post_residual > 40 {
                score -= 60.0;
            }
        }
    } else {
        // Existing bin: mild bonus for having low mean residual (well-packed set)
        score -= 3.0 * (mean_residual / 10.0);
    }

    score
}

