            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN152: low-dead double-chain — prefer bins chaining nx twice when fragmentation is low
        if dead <= 0.25 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 5.0 {
            score -= 0.6 * (1.0 - (pr - 2.0 * nx) / 5.0) * (0.6 + 0.4 * progress) ;
        }
        // GEN152: late-stream consolidation — penalize medium slivers that strand space
        if progress > 0.8 && nx > 0.0 && pr > nx && pr - nx > 6.0 && pr - nx < 20.0 {
            score += 0.7 * ((pr - nx - 6.0) / 14.0) * (progress - 0.8) / 0.2 ;
        }
        // GEN152: near-exact fit within 2% of cap — strong reward
        if pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
