                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
            // GEN156: triple-chain lookahead — after-space hosting nx three times is prime
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 9.0 && fitting_bins_count <= 4 {
                score -= 0.55 * (1.0 - (after - 3.0 * nx) / 9.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN156: tiny sliver after nx is near-waste unless another bin can host nx
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
