pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still hold the next item: mild reward proportional to closeness
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize creating small dead space
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 15.0 * (10.0 - dead);
        }
    }

    // Compare post_residual against mean residual across open bins
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless item is small relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 100.0 - 30.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
    }

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score toward zero for near-full bins.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 20.0;

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how much slack remains after next item
            let after_next = post_residual - next_item_size;
            score -= 12.0 * (after_next as f64) / (bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize large dead space
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * (1.0 - progress);
        if mean_residual >= item_size as f64 {
            score += 20.0; // an open bin could have taken it
        }
    } else {
        // Favor bins whose residual is below the mean (consolidate space).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild pressure to keep open-bin count low.
    score += 0.3 * open_bins_count as f64;

    // Prefer placing into bins that would otherwise waste space relative to item size.
    if post_residual < item_size {
        score -= 8.0; // residual too small for future typical items: good, we filled it
    }

    score
}

