pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use leftover space: penalize relative to leftover size
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(60.0);
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Relative to mean residual: bins with unusually small residual are precious,
    // avoid stuffing big items into them unless it's a near-perfect fit.
    if post_residual > 0 {
        let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score += 40.0 * tightness.max(0.0);
        score -= 20.0 * (-tightness).max(0.0);
    }

    // Penalize leaving dead space that no plausible item (min size ~1) can use well:
    // small nonzero residuals are awkward.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: prefer it only when open bins would leave very awkward
    // residuals (large post_residual relative to capacity) or when few bins open.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = bin_capacity as f64 * 0.9;
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 200.0;
        }
        // late in stream, be more willing to open new bins to keep residuals clean
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
    }

    score
}

