pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let progress_sq = progress * progress;
    let progress_cb = progress_sq * progress;

    // Tight fits are increasingly valuable as the stream progresses.
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm); // quadratic tightness
    score -= 24.0 * (0.5 + 0.5 * progress) * tightness * (item_size as f64 / cap);

    // Penalize residual that cannot fit the lookahead item (smoothly weighted).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        let usable = (pr / nx).min(1.0).max(0.0);
        score += 14.0 * gap * gap - 10.0 * usable * usable * (1.0 - progress);
    }

    // Dead-space penalty: cubic in wasted fraction, stronger late in stream.
    let waste = pr_norm * pr_norm * pr_norm;
    score += 18.0 * (0.4 + 0.6 * progress) * waste;

    // Last-chance bonus: strongly favor the only fitting bin, smoothly scaled.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (0.6 + 0.4 * (1.0 - progress));
    }

    // Crowd penalty: many open bins with low mean residual -> prefer consolidation.
    let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * (1.0 - mean_residual / cap).max(0.0);
    score += 6.0 * crowd * (1.0 - progress_cb);

    // Mild preference for new bins early, discourage late.
    if bin_residual == bin_capacity {
        score += 8.0 * progress - 4.0 * (1.0 - progress);
    }

    score
}

