        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN161: reward new-bin leftovers that can chain the next item twice
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN161: exact 2x fill chain in new bins
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        // GEN161: late-stream — forbid new bins unless waste is small or no open bin fits
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // GEN161: discourage opening a new bin mid-late when some open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.6 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: residual modulo capacity quarters
    let q = post_residual % (bin_capacity / 4);
    score -= q as f64 * 0.4; // reward residuals near a quarter-class boundary

    // Dead-space penalty: tiny unusable post_residual
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize leaving awkward residue
            let class = post_residual / (bin_capacity / 4);
            if class == 1 || class == 3 {
                score += 6.0;
            }
        }
    }

    // Prefer filling bins with low mean residual (tight bins)
    score += (mean_residual - post_residual as f64) * 0.15;

    // Early in stream: mildly prefer reusing bins over opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when few bins open / early
        score += 30.0 + 40.0 * (1.0 - progress) + (open_bins_count as f64) * 2.0;
        // but allow new bin if all existing fits are terrible
        if post_residual == bin_capacity && (bin_residual - item_size) < 20 {
            score -= 20.0;
        }
    }

    // Integer division threshold on post_residual: half-capacity sweet spot
    if post_residual >= bin_capacity / 2 {
        score -= 10.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 4.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // GEN161: strengthen triple-chain lookahead — residual that can host nx twice more
            if after >= 2.0 * nx && after <= 3.0 * nx + 6.0 && nx >= 3.0 {
                score -= 1.1 * (1.0 - ((after - 2.0 * nx) / (nx + 6.0)) . min (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN161: reward after exactly matching nx again (perfect chain)
            if after >= 1.0 && (after - nx) . abs () < 0.5 {
                score -= 2.4 * (0.5 + 0.5 * progress) ;
            }
            // GEN161: penalize sliver just under nx when other bins could host nx
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.5 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
            // GEN161: reward after that can still host nx once more with a small margin
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            // GEN161: soften mismatch penalty when many bins compete and mean residual is large
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN161: prefer fresh bins whose leftover after nx can chain nx once more (exact 2x fill)
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 1.0 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        // GEN161: discourage opening a new bin late when an open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.7 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
        // GEN161: discourage new bins whose leftover cannot host nx at all while open bins are plentiful
        if open_bins_count >= 3 && nx > 0.0 && pr > 0.0 && pr < nx {
            score += 1.2 * (1.0 - pr / nx) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // GEN161: reward low-dead bins whose post-space exactly matches nx plus tiny margin
        let dead = pr / br . max (1.0) ;
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // GEN161: penalize mid-dead bins leaving a wide unusable band just above nx
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN161: reward bins whose post-space can host nx exactly twice (double-chain)
        if dead <= 0.25 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 5.0 {
            score -= 0.6 * (1.0 - (pr - 2.0 * nx) / 5.0) * (0.6 + 0.4 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically small gaps) are wasted.
    if post_residual > 0 {
        // Dead space: post_residual too small to fit the lookahead item
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Very tiny unusable gap -> heavy penalty
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Tight-fit reward: fraction of bin consumed by this item
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new bins); with few open bins, opening is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins fit or bin pressure low
        score += 30.0 + 4.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below the
    // mean (i.e., this bin is already tighter than average)
    score += 0.5 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Late in the stream, consolidate harder
    score += progress * 5.0 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-item capacity lookahead (GEN161: scaled by residual share so large
    // residuals get stronger pressure to host mid-size future items)
    let fits_mid = post_residual / 20;
    let mid_scale = 1.0 + 0.5 * (br / cap);
    score -= fits_mid as f64 * 4.0 * mid_scale;

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // GEN161: small usable sliver bonus (best-heuristic idea)
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            // GEN161: chain bonus when leftover fits nx again
            if after >= nx && nx > 0.0 && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
            // chaining: leave room for next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // GEN161: triple-chain bonus
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 9.0 && fitting_bins_count <= 4 {
                score -= 0.35 * (1.0 - (after - 3.0 * nx) / 9.0) * (0.5 + 0.5 * progress);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // GEN161: penalize awkward mid-sliver just above nx when pool can absorb nx
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress);
            }
            // penalize leftover that is too big relative to need when bins are plentiful
            if after > 30.0 && after < 60.0 && nx > 0.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
        } else {
            // next item won't fit here
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            // GEN161: soften mismatch when competition is strong and pool is roomy
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // dead-space below min item size is wasted when next item can't use it
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // last-chance bin
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio (fragmentation of this bin) analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    // GEN161: reward low-dead bins whose post-space nearly exactly matches nx
    if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
        score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress);
    }
    // GEN161: penalize mid-dead bins leaving a wide unusable band above nx
    if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
        score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress));
    }
    // pool-balance bonus
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    // near-exact next-item fit into residual
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
            // GEN161: reward new-bin leftover that chains nx exactly twice
            if after_new >= 2.0 * nx && after_new < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after_new - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress);
            }
            // GEN161: tiny leftover after nx in a fresh bin is excellent
            if after_new > 0.0 && after_new <= 2.0 {
                score -= 1.0 * (2.0 - after_new) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // GEN161: discourage opening a new bin late when some open bin already fits nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.6 * (waste - 0.55) * (progress - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward when next item fits exactly into the new post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally to wasted space
            score += 0.35 * post_residual as f64;
        }
    }

    // Relative to mean residual: bins with residual far below mean are "tighter" — prefer filling them.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge relative to capacity
    // or the stream is early and consolidation still possible.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if progress < 0.25 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for larger items into tighter bins as stream progresses.
    score += 0.1 * (item_size as f64 / bin_capacity as f64) * (1.0 - progress);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // GEN161: strengthen triple-chain lookahead — residual that can host nx twice more
            if after >= 2.0 * nx && after <= 3.0 * nx + 6.0 && nx >= 3.0 {
                score -= 0.9 * (1.0 - ((after - 2.0 * nx) / (nx + 6.0)) . min (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN161: reward after exactly matching nx again (perfect chain)
            if after >= 1.0 && (after - nx) . abs () < 0.5 {
                score -= 2.2 * (0.5 + 0.5 * progress) ;
            }
            // GEN161: penalize sliver just under nx when other bins could host nx
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.5 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
            // GEN161: reward mid-size leftovers that still fit nx plus a small margin
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            // GEN161: soften mismatch penalty when many bins compete and mean residual is large
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
            // GEN161: soften mismatch further when mean residual can still host nx
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 0.6 * (1.0 - progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN161: prefer fresh bins whose leftover after nx can chain nx once more (exact 2x fill)
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.8 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        // GEN161: discourage opening a new bin late when an open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.7 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
        // GEN161: discourage new bins late when mean residual still comfortably hosts nx
        if open_bins_count > 0 && progress > 0.7 && mean_residual > cap * 0.4 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (progress - 0.7) / 0.3 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // GEN161: reward low-dead bins whose post-space exactly matches nx plus tiny margin
        let dead = pr / br . max (1.0) ;
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // GEN161: penalize mid-dead bins leaving a wide unusable band just above nx
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN161: reward bins whose residual is nearly consumed with an exact nx fit
        if pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        // GEN161: penalize high-dead bins that cannot host nx while mean residual could
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
    }

    score
}

