            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // GEN162: reward low-dead bins whose post-space nearly matches nx exactly
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // GEN162: penalize wide unusable band just above nx in low-mean pools
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        // GEN162: reward low-dead bins that can chain nx twice
        if dead <= 0.25 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 5.0 {
            score -= 0.6 * (1.0 - (pr - 2.0 * nx) / 5.0) * (0.6 + 0.4 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN162: exact 2x fill chain on new bin leftover
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // GEN162: discourage opening a new bin late when an open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.6 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += pr * (0.5 * t * t + 0.3 * t + 0.2) * (1.0 - pr_norm);

    // Penalize large dead space quadratically, dampened late in stream
    score += 0.8 * pr_norm * pr_norm * cap * (0.5 + 0.5 * (1.0 - t));

    // Reward tight fits (small post_residual) especially when many bins fit the item
    if fitting_bins_count > 1 {
        score -= 6.0 * (1.0 - pr_norm) * (pr_norm * (1.0 - pr_norm) * 4.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = (pr - n) / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * ((n - pr) / cap);
        }
    }

    // Prefer filling bins with low mean residual (near-full bins)
    score += 0.15 * (mean_residual - pr).abs();

    // Slight penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1
    let class = (frac * 8.0).floor() as i32; // 8 harmonic classes of residual

    // Reward small residuals (tight fit), with harmonic-class jumps.
    match class {
        0 => score -= 30.0,                    // residual < 12.5% : near-perfect
        1 => score -= 18.0,                    // < 25%
        2 => score -= 10.0,                    // < 37.5%
        3 => score -= 4.0,                     // < 50%
        4 => score += 2.0,                     // half-empty: weak
        5 => score += 6.0,
        6 => score += 10.0,
        _ => score += 14.0,                    // > 87.5% left: wasted placement
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_frac = next_item_size as f64 / pr.max(1.0);
        if (next_frac - 1.0).abs() < 0.01 {
            score -= 25.0; // perfect follow-up fill
        } else {
            score -= 12.0 * next_frac; // good follow-up potential
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that next item cannot use: penalize by harmonic class of leftover.
        score += 8.0 + 0.15 * pr;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap);
        if avg_fill > 0.75 {
            score -= 10.0 * (avg_fill - 0.75) * 4.0; // justified opening
        } else {
            score += 15.0 + 20.0 * (0.75 - avg_fill); // discourage premature bin
        }
        // Late in stream, prefer closing out bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Modulo harmonic bonus: residual that is a multiple of common item sizes is reusable.
    let pr_u = post_residual;
    if pr_u > 0 && (pr_u % 10 == 0 || pr_u % 20 == 0 || pr_u % 25 == 0 || pr_u % 50 == 0) {
        score -= 6.0;
    }

    // Prefer bins with below-mean residual (consolidate emptiness).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Many open bins: pressure to fill existing ones rather than spread.
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (1) are pure waste; the worst zone is tiny unusable gaps.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0; // heavy penalty for near-full waste
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Reward placements that leave a residual usable by the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64) * 0.15;
        } else if post_residual > 0 {
            score += 6.0; // creates dead space relative to next item
        }
    }

    // Tight fit bonus: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage proliferation of bins; make existing bins
    // more attractive as open_bins_count grows.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * (2.0 + 3.0 * progress);
    } else {
        // New-bin candidate: penalize opening a bin, more strongly when good
        // alternatives exist or the stream is late.
        score += 30.0 + fitting_bins_count as f64 * 10.0 + progress * 20.0;
        // But allow a new bin if all existing fits would create tiny dead space.
        if fitting_bins_count == 0 || (post_residual as f64) < mean_residual * 0.5 {
            score -= 45.0;
        }
    }

    // Prefer bins whose residual is already below average (consolidate scraps).
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step fit bonus (strongly subtract)
        if gap == 0.0 {
            score -= 60.0 + 0.5 * item_size as f64;
        } else {
            // Penalize residuals that cannot host the next item
            if (post_residual as u32) < next_item_size {
                score += gap * 0.8;
            } else {
                // Next item fits: mild reward proportional to tightness
                score -= 10.0 * (1.0 - gap / bin_capacity as f64);
            }
        }
    } else {
        // Last item: just minimize post residual (already base), extra reward for near-full
        score -= (bin_capacity as f64 - post_residual as f64) * 0.1;
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leaving residual far above mean wastes capacity; leaving far below mean creates dead space.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        if rel < -0.5 {
            // creating unusually small residual: dead space penalty scaled by size
            score += (-rel) * mean_residual * 0.35;
        } else if rel > 0.5 {
            // leaving much more than mean: mild penalty
            score += rel * mean_residual * 0.15;
        } else {
            // harmonizing with mean: small reward
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        if tightness > 0.4 {
            score -= 25.0 + 20.0 * tightness;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin when open bins exist
    // and stream is early/mid; allow late in stream or when bins are saturated.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let saturation = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 30.0 * (1.0 - progress) * (1.0 + saturation);
        // but if next item is huge and no bin will fit it well, opening is safer
        if next_item_size > 60 && fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Non-linear coupling: quadratic waste term for large dead space
    let waste = post_f / bin_capacity as f64;
    score += 12.0 * waste * waste;

    // Slight preference for filling fuller bins (best-fit flavor)
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: bins whose residual closely matches the item are precious.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Perfect pairing: item now + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mildly favor bins that would be most filled.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty makes open bins preferred; shrinks late in stream or
        // when mean residual across open bins is small (open bins nearly full).
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let penalty = 35.0 - 15.0 * progress - 25.0 * mean_tight;
        // If the item would leave a large useful residual, new bin is fine.
        let roomy = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += penalty - 10.0 * roomy;
    }

    // Global state: many open bins -> prefer consolidating into existing ones.
    score += 0.4 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Prefer bins below mean residual (less-full bins get slightly favored,
    // balancing load and avoiding stranding near-full bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0 as usize) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= nx && nx > 0.0 && (after - nx) >= 1.0 && (after - nx) <= 6.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after - nx) / 6.0) * (0.4 + 0.6 * progress) ;
            }
            if after == 0.0 && fitting_bins_count <= 3 {
                score -= 1.2 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && nx >= 2.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - progress) ;
            }
            if after > nx && after - nx <= 3.0 && fitting_bins_count <= 2 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) ;
            }
            if after > 0.0 && after <= 0.5 * cap && (after / 2.0 - nx) . abs () <= 1.0 && nx >= 2.0 {
                score -= 0.6 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
