pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: tight fits preferred (quadratic in post_residual).
    let mut score = pr * pr / cap;

    // Smooth progress coupling: later in stream, demand tighter fits more strongly.
    let tightness = 1.0 + progress * progress * 1.5;
    score *= tightness;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= (pr - n) * (0.5 + progress);
        } else {
            // next item can't follow here; mild penalty scaled by overshoot
            score += (n - pr) * 0.25;
        }
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize bins whose residual is far below mean (avoid fragmenting good bins)
    // and reward bins with residual above mean only if fit is tight.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= dev * 2.0;

    // Smooth penalty on relative waste of the bin.
    let waste = pr / cap;
    score += waste * waste * 10.0;

    // New-bin candidate: penalize opening a new bin, more so when other bins fit
    // and early/late in the stream.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

