fn dead_ratio (pr : f64 , br : f64) -> f64 { pr / br . max (1.0) }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild reward proportional to slack left after both.
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit: penalize small dead space heavily.
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Penalize small-but-nonzero dead space (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Prefer bins with residuals below the mean (tighter bins get filled first).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0; // new bin can chain large items
        }
    }

    // Late in the stream: consolidate to reduce total bin count.
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize post-residuals that are small but unusable (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward leaving residual that fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += 4.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 12.0; // still avoid near-dead placements even as last chance
        }
    }

    // New-bin candidate handling: make opening a new bin attractive only
    // when all open bins would leave bad residuals, or when many bins are open.
    if bin_residual == bin_capacity {
        let opening_penalty = 20.0 + 2.0 * open_bins_count as f64;
        score += opening_penalty;
        // Late in the stream, discourage new bins more (want to close out).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // But if next item is large and this item is small, new bin may be better.
        if next_item_size > 60 && item_size < 30 {
            score -= 18.0;
        }
    }

    // Global state: when mean residual is high, prefer consolidating into
    // bins with residuals near the mean (balance-aware placement).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer bins whose residual is close to item size (minimize slack).
    let slack = (bin_residual - item_size) as f64;
    score += 0.02 * slack;

    score
}

