fn dead_proxy (after : f64 , br : f64) -> f64 {
    if br > 0.0 { (after / br . max (1.0)) . clamp (0.0 , 1.0) } else { 0.5 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual can't host next item: penalize proportionally to how much we "waste".
            score += 0.1 * (post_residual as f64);
            // But if post residual is near zero, it's fine to close this bin.
            if post_residual <= next_item_size / 3 {
                score -= 8.0;
            }
        }
    }

    // Last chance: this is the only bin that fits; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current fit is poor and many bins are open (fragmentation high).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 0.35 * bin_capacity as f64;
        if poor_fit && open_bins_count > 2 {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 35.0 + 10.0 * (1.0 - progress);
        }
        // Early in stream, prefer consolidating into few bins.
        if open_bins_count <= 2 {
            score += 50.0;
        }
    }

    // Global state: high mean residual means open bins are roomy; prefer
    // filling them rather than spreading.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Prefer bins with less residual overall (best-fit flavor) modulated by load.
    score += 0.03 * (bin_residual as f64 - item_size as f64);

    // Late in the stream, be more conservative: favor tight existing fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    score
}

