pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly compressed non-linearly
    let mut score = pr.powf(0.85);

    // Non-linear coupling of residual with stream progress:
    // late in stream, larger residuals are penalized super-linearly (dead space matters more)
    let late_penalty = norm_pr.powi(3) * (1.0 + 3.0 * progress) * cap;
    score += late_penalty;

    // Early stream: reward tight fits slightly to build good bins
    let early_bonus = (1.0 - progress) * (cap - pr) * 0.3;
    score -= early_bonus;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // next item fits but not perfectly: mild reward scaled by fill ratio
        score -= 6.0 * (next_item_size as f64 / pr.max(1.0));
    } else if next_item_size > 0 {
        // next item would not fit here: penalize leaving awkward residual
        score += 4.0 * norm_pr;
    }

    // Many open bins with high mean residual: discourage spreading, prefer tight bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize unless residuals elsewhere are terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

