    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
            // GEN167: new-bin leftover small and usable after nx
            if after_new > 0.0 && after_new <= 2.0 {
                score -= 1.0 * (2.0 - after_new) * (0.5 + 0.5 * progress);
            }
            // GEN167: prefer new bins whose leftover after nx can chain nx once more
            if after_new >= 2.0 * nx && after_new < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after_new - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // GEN167: discourage opening a new bin late when some open bin already fits nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.6 * (waste - 0.55) * (progress - 0.6) / 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Dead space relative to capacity.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Open-bin pressure: discourage spreading across many bins when fit is loose.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && next_item_size - post_residual < 10 {
            score += 6.0; // creates a gap that barely fails the next item
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Early stream: slightly prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * fit_ratio;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 10.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly (small post residual is exponentially better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: perfect chain match (next item exactly fills remainder).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chain fits that leave small follow-up slack; penalize large leftovers.
            score -= 120.0 * (-slack / 20.0).exp();
            score += 0.5 * slack;
        } else {
            // Next item cannot use this residual at all: residual likely becomes dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    }

    // Compare residual against mean residual of open bins: avoid creating outliers.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev.abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins: prefer consolidating into fuller bins (small residual).
    if open_bins_count > 2 {
        score += 0.1 * (open_bins_count as f64);
    }

    // New-bin candidate: only attractive when current residuals are badly fragmented
    // (high mean residual spread vs item) or this is a large item early in the stream.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty keeps new bins rare; discount when open bins are very full.
        let mut new_score = 90.0
            - 80.0 * fragmentation
            + 30.0 * (1.0 - progress);
        if item_size > 60 && fragmentation > 0.6 {
            new_score -= 60.0; // big item with fragmented bins: fresh bin is fine
        }
        score = score.min(new_score) + new_score - score.min(new_score); // keep as candidate
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = if item_size > 0 { post_residual as f64 / item_size as f64 } else { 1.0 };
    score += tightness * 10.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize leaving residual that is hard to reuse later:
    // small leftovers (1..10) are dead space if no tiny items exist
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward for a "chained" near-perfect sequence
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }
    // If next item would leave this bin's remainder stranded, mild penalty
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: early in the stream, be pickier (penalize mediocre fits),
    // late in the stream, accept decent fits more readily to avoid new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pickiness = 1.0 - progress;
    score += tightness * pickiness * 8.0;

    // Many open bins: discourage spreading; few open bins: consolidation is fine
    if open_bins_count > 5 {
        score += post_residual as f64 * 0.1;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // gives a reasonably tight fit, or when open bins are all badly fragmented
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        let mut new_bin_score = 55.0;
        // If this is the last item or no bins fit, a new bin is natural
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // Late in the stream with a good lookahead chain, allow opening
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size && progress > 0.7 {
            new_bin_score -= 20.0;
        }
        // Very large item: new bin often fine
        if item_size > bin_capacity / 2 {
            new_bin_score -= 15.0;
        }
        score = score.min(new_bin_score) * 0.0 + new_bin_score;
        return score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
