            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
            let after2 = after_new;
            if after2 >= 2.0 && after2 <= 7.0 && open_bins_count >= 2 {
                score -= 0.7 * (1.0 - (after2 - 2.0) / 5.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress);
            }
            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // GEN168: discourage opening a new bin late when some open bin already fits nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.6 * (waste - 0.55) * (progress - 0.6) / 0.4;
        }
        // GEN168: discourage late new bins with large waste while mean residual is high
        if open_bins_count > 0 && progress > 0.7 && mean_residual > cap * 0.4 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (progress - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual (quartic-ish growth for large dead space)
    let norm_pr = pr / cap;
    score += 6.0 * norm_pr * norm_pr * cap;

    // Reward tight fits: coupling post_residual with stream progress
    let tightness = 1.0 - norm_pr;
    score -= (1.5 + 4.0 * progress) * tightness * tightness * cap * 0.1;

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let gap = (pr - ns) / cap;
            score -= 8.0 * (1.0 - gap * gap);
        } else {
            score += 4.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many bins fit
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 5.0 + 6.0 / fit_pressure + 4.0 * (1.0 - progress);
        // Favor new bin if existing residuals are small and item is large
        if mean_residual < item_size as f64 * 0.5 {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is close to mean (harmonic consolidation)
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for proliferation of open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by large classes (multiples of 10, 20, 25) are more
    // "reusable" under typical item-size lattices, so reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
            if pr % 20 == 0 {
                score -= 3.0;
                if pr % 25 == 0 || pr % 50 == 0 {
                    score -= 3.0;
                }
            }
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            // Odd/awkward residual: penalize via integer-division dead-space class.
            score += (pr % 10) as f64 * 0.6;
        }
        // Tiny unusable slivers are dead space.
        if pr < 10 {
            score += 8.0;
        }
    } else {
        // Perfect closure is ideal.
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly favor this bin (harmonic match between classes).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score += slack as f64 * 0.15;
            if slack % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this residual at all: mild penalty scaled
            // by how much of the next item's need is stranded.
            let deficit = next_item_size - pr;
            score += (deficit % 20) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins with decent
    // harmonic fit, but keep it competitive when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 4.0;
    }

    // Prefer filling bins far below the mean residual (tightening loose bins).
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Mild pressure against bin proliferation.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0 as usize) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
