            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= nx && nx > 0.0 && (after - nx) >= 1.0 && (after - nx) <= 6.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after - nx) / 6.0) * (0.4 + 0.6 * progress) ;
            }
            if after == 0.0 && fitting_bins_count <= 3 {
                score -= 1.2 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && nx >= 2.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - progress) ;
            }
            if after > nx && after - nx <= 3.0 && fitting_bins_count <= 2 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) ;
            }
            if after > 0.0 && after <= 0.5 * cap && (after / 2.0 - nx) . abs () <= 1.0 && nx >= 2.0 {
                score -= 0.6 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
            // GEN169: extend triple-chain bonus (borrowed from best lineage)
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 9.0 && fitting_bins_count <= 4 {
                score -= 0.35 * (1.0 - (after - 3.0 * nx) / 9.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN169: penalize tiny sliver after-space when mean residual elsewhere can host nx
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.4 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if pr > 0.0 && open_bins_count >= 2 && mean_residual >= nx && mean_residual > pr + 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / (nx + 1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN169: soften mismatch when many bins compete and mean residual is large
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.6 && nx > 0.0 && pr < nx && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.0 * (dead - 0.6) * (1.0 - progress) ;
        }
        if dead > 0.65 && pr > 10.0 && mean_residual < cap * 0.2 {
            score += 0.6 * (dead - 0.65) * (0.5 + 0.5 * progress) ;
        }
        if pr > 6.0 && (pr - mean_residual) . abs () < 5.0 && fitting_bins_count >= 3 {
            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // GEN169: reward low-dead bins whose post-space matches nx with tiny margin
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // GEN169: penalize mid-dead bins leaving a wide unusable band above nx
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN169: exact 2x chain fill in new bin is ideal
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // GEN169: discourage opening a new bin late when some open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.6 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step fill
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetical next placement
            score += leftover * 0.4;
            if leftover <= 9.0 {
                score -= 25.0; // near-perfect two-item fill
            }
        } else {
            // next item cannot follow in this bin; penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize large dead space that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // small leftover is fine (near-full bin)
    } else if post_residual >= 10 && post_residual < 30 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // late in the stream, or when few bins fit, opening a new bin is more attractive
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // if next item is large, a fresh bin gives flexibility
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild preference for consolidating into fewer bins when many are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative slack squared.
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += 6.0 * tightness * tightness * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize large dead space a bit.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the fleet average residual.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in stream: consolidate harder into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.15 * post_residual as f64;

    // Many open bins: discourage opening new bins / spreading.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by open bins.
        score += 55.0 + 2.0 * open_bins_count as f64;
        // New bin is acceptable if item is large and nothing tight exists.
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If lookahead is large, a fresh bin can host a pair.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Penalize creating residuals that are awkward (small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0 as usize) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 3 { score -= 1.2 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN170: extend triple-chain reward reach
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 9.0 && fitting_bins_count <= 4 {
                score -= 0.55 * (1.0 - (after - 3.0 * nx) / 9.0) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= nx && nx > 0.0 && (after - nx) >= 1.0 && (after - nx) <= 6.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after - nx) / 6.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && nx >= 2.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - progress) ;
            }
            if after > nx && after - nx <= 3.0 && fitting_bins_count <= 2 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) ;
            }
            // GEN170: penalize sliver just under nx when other bins can host nx instead
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.5 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
            // GEN170: mid-band after-space with nx>=4 and few competing bins is still useful
            if after > 10.0 && after <= 18.0 && fitting_bins_count <= 3 && nx >= 4.0 {
                score -= 0.55 * (1.0 - (after - 10.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN170: reward exact 2x-chain with tight window
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && fitting_bins_count <= 3 {
                score -= 0.5 * (1.0 - (after - 2.0 * nx) / 4.0) * (0.6 + 0.4 * (1.0 - progress)) ;
            }
            if after > 0.0 && after <= 0.5 * cap && (after / 2.0 - nx) . abs () <= 1.0 && nx >= 2.0 {
                score -= 0.6 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if pr > 0.0 && open_bins_count >= 2 && mean_residual >= nx && mean_residual > pr + 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / (nx + 1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN170: soften mismatch penalty when many bins compete and mean residual is large
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.6 && nx > 0.0 && pr < nx && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.0 * (dead - 0.6) * (1.0 - progress) ;
        }
        if dead > 0.65 && pr > 10.0 && mean_residual < cap * 0.2 {
            score += 0.6 * (dead - 0.65) * (0.5 + 0.5 * progress) ;
        }
        if pr > 6.0 && (pr - mean_residual) . abs () < 5.0 && fitting_bins_count >= 3 {
            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // GEN170: reward low-dead bins whose post-space nearly exactly fits nx
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // GEN170: penalize mid-dead bins leaving a wide unusable band just above nx
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        // GEN170: reward low-dead bins that can chain nx twice with tight margin
        if dead <= 0.25 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 5.0 {
            score -= 0.6 * (1.0 - (pr - 2.0 * nx) / 5.0) * (0.6 + 0.4 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN170: exact 2x-chain in a new bin is very valuable
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.9 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Base: prefer tight fits (low post_residual), with a mild non-linear
    // emphasis on small residuals via quadratic coupling.
    let mut score = post + 0.9 * (post * post) / cap;

    // Dead-space penalty: residuals too small for typical items (below ~10)
    // are wasted; penalize smoothly as post approaches 0.
    score += 6.0 * ((cap / 10.0 - post) / cap).max(0.0).powi(3) * cap;

    // Stream-progress coupling: later in the stream, tighter packing matters
    // more (fewer chances to amortize slack); weight the quadratic term up.
    score *= 1.0 + 0.35 * progress * (post / cap);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 25.0;
    }

    // Lookahead: reward leaving a residual that can still host the next item,
    // scaled by how much slack would remain after that hypothetical placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 8.0 * (1.0 - slack / cap) * (1.0 + progress);
        } else {
            // Residual too small for next item: mild penalty, worse when large.
            score += 3.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins; penalize proportionally to mean residual and bin count, but
    // relax the penalty when few bins fit (poor alternatives) or when the item
    // nearly fills a fresh bin.
    if is_new > 0.5 {
        let waste = mean_residual * (open_bins_count as f64);
        let fit_pressure = 1.0 / (fitting_bins_count.max(1) as f64);
        let fill_quality = item_size as f64 / cap;
        score += 4.0 + 0.35 * waste
            - 20.0 * fit_pressure * (0.5 + 0.5 * progress)
            - 15.0 * fill_quality * fill_quality;
        // If next item is huge and current bin would be nearly empty after,
        // opening fresh is more attractive.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-item capacity lookahead (scaled by residual share)
    let fits_mid = post_residual / 20;
    let mid_scale = 1.0 + 0.5 * (br / cap);
    score -= fits_mid as f64 * 4.0 * mid_scale;

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
                if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress); }
            } else if after >= 1.0 && after <= 12.0 {
                // GEN170: sharpen small-after bonus (best-heuristic idea)
                score -= 6.0 * (1.0 - after / 12.0);
                if after >= 1.0 && after <= 4.0 {
                    score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
                }
                if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                    score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress);
                }
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
                if after >= 12.0 && after <= 20.0 && fitting_bins_count <= 2 { score -= 2.0; }
            }
            // small usable sliver bonus
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
                // GEN170: penalize sliver under nx when pool can absorb nx
                if fitting_bins_count >= 2 && mean_residual >= nx {
                    score += 0.4 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress));
                }
            }
            // chain bonus when leftover fits nx again
            if after >= 2.0 * nx && nx > 0.0 && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // triple-chain bonus
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 9.0 && fitting_bins_count <= 4 {
                score -= 0.35 * (1.0 - (after - 3.0 * nx) / 9.0) * (0.5 + 0.5 * progress);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // GEN170: reward near-exact fit with small margin (best-heuristic idea)
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            // penalize awkward mid-sliver just above nx
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress);
            }
            // penalize leftover too big relative to need when bins are plentiful
            if after > 30.0 && after < 60.0 && nx > 0.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
        } else {
            // next item won't fit here
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 0.6 * (1.0 - progress);
            }
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // dead-space below min item size is wasted when next item can't use it
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // last-chance bin
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio (fragmentation of this bin) analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    // reward low-dead bins whose post-space nearly exactly matches nx
    if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
        score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress);
    }
    // penalize mid-dead bins leaving a wide unusable band above nx
    if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
        score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress));
    }
    // pool-balance bonus
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    // near-exact next-item fit into residual
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
