        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 10.0;
            } else if slack > 40 {
                score += 3.0;
            }
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 5 {
                score += 6.0; // next item just misses: dead space risk
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin for a large item is fine,
    // but wasteful for small items when other bins fit.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / c;
        if frac > 0.6 {
            score -= 5.0;
        } else if fitting_bins_count > 0 {
            score += 30.0; // prefer existing bins for small items
        }
        // Late in stream, fewer open bins is better
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Tight fits are good regardless of class.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness * tightness;

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (pr / c);

    // Keep score aligned with mean residual scale.
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0 as usize) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN171: triple-chain lookahead borrowed from best lineage
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 9.0 && fitting_bins_count <= 4 {
                score -= 0.35 * (1.0 - (after - 3.0 * nx) / 9.0) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= nx && nx > 0.0 && (after - nx) >= 1.0 && (after - nx) <= 6.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after - nx) / 6.0) * (0.4 + 0.6 * progress) ;
            }
            if after == 0.0 && fitting_bins_count <= 3 {
                score -= 1.2 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && nx >= 2.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - progress) ;
            }
            if after > nx && after - nx <= 3.0 && fitting_bins_count <= 2 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) ;
            }
            // REFINE: reward after-space that exactly matches a plausible future pair sum
            if after > 0.0 && after <= 0.5 * cap && (after / 2.0 - nx) . abs () <= 1.0 && nx >= 2.0 {
                score -= 0.6 * (1.0 - progress) ;
            }
            // REFINE: chaining — after-space that still hosts next item twice is valuable late
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            // REFINE: chainable after-space — reward when after-space can host next item AND still leave a small residual
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: penalize awkward leftover just above next item
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
            // GEN171: penalize sliver after-space (1..3) when another open bin can host nx instead
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.4 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: near-miss residual that another roomier bin can host instead
            if pr > 0.0 && open_bins_count >= 2 && mean_residual >= nx && mean_residual > pr + 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / (nx + 1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN171: soften mismatch penalty when many bins compete and mean residual is large
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.6 && nx > 0.0 && pr < nx && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.0 * (dead - 0.6) * (1.0 - progress) ;
        }
        if dead > 0.65 && pr > 10.0 && mean_residual < cap * 0.2 {
            score += 0.6 * (dead - 0.65) * (0.5 + 0.5 * progress) ;
        }
        if pr > 6.0 && (pr - mean_residual) . abs () < 5.0 && fitting_bins_count >= 3 {
            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        // REFINE: penalize dead-space growth when a roomier open bin could host the next item instead
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        // REFINE: dead-space lookahead — penalize if pr cannot host next two items but a bigger residual could
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        // REFINE: mid-range dead space with large absolute residual is waste
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        // REFINE: pool balancing — reward low dead space with residual near mean
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // GEN171: reward low-dead bins whose post-space nearly exactly matches nx
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // GEN171: penalize wide unusable band just above nx on mid-dead bins with a tight pool
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // REFINE: reward new-bin leftovers that can chain the next item twice
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN171: exact 2x-fill chain for new bins
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        // REFINE: late-stream — forbid new bins unless waste is small or no open bin fits
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavily penalize.
            score += 60.0;
        } else {
            // Usable gap: reward proportionally to how well a future item could use it.
            score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Perfect fill: huge reward.
        score -= 200.0;
    }

    // Reward bins that can also host the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward for near-exact two-item pairing.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Lookahead won't fit here: penalize creating a stranded gap.
            score += 10.0 * (post_residual as f64 / 10.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (keep residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate handling: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // But if this bin is not a last chance and fit would waste much space,
        // a fresh bin becomes relatively better.
        if fitting_bins_count > 1 {
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 80.0; // dead-space placement: new bin better
            } else if waste > 40.0 {
                score -= 30.0; // decent fit here: keep using open bins
            }
        }
        // Late in stream with many open bins, discourage more bins.
        score += 20.0 * progress * (open_bins_count as f64 / 10.0);
    }

    // Mild preference for fuller bins (small residual before placement).
    score += 0.2 * (bin_residual as f64 - item_size as f64).max(0.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-item capacity lookahead (borrowed from best: sharper weight)
    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.5;

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
                if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress); }
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // chaining: leave room for next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // triple-chain bonus (from best heuristic)
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 9.0 && fitting_bins_count <= 4 {
                score -= 0.35 * (1.0 - (after - 3.0 * nx) / 9.0) * (0.5 + 0.5 * progress);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // small usable leftovers
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            // near-exact second fit
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            // penalize leftover that is too big relative to need when bins are plentiful
            if after > 30.0 && after < 60.0 && nx > 0.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
            // GEN171: penalize sliver just under nx when other bins could take nx
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.4 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress));
            }
            // GEN171: reward low-dead bins whose post-space exactly matches nx plus a tiny margin
            if after >= nx && nx > 0.0 && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
        } else {
            // next item won't fit here
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 0.6 * (1.0 - progress);
            }
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // dead-space below min item size is wasted when next item can't use it
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // last-chance bin
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio (fragmentation of this bin) analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    // GEN171: penalize wide unusable band just above nx in mid-dead bins
    if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
        score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress));
    }
    // GEN171: reward near-exact nx fit in low-dead bins
    if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
        score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress);
    }
    // pool-balance bonus
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    // near-exact next-item fit into residual
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
            // GEN171: chain analysis of new-bin leftover
            if after_new >= 2.0 * nx && after_new < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after_new - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress);
            }
            if after_new > 0.0 && after_new <= 2.0 {
                score -= 1.0 * (2.0 - after_new) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // GEN171: discourage opening a new bin late when some open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.6 * (waste - 0.55) * (progress - 0.6) / 0.4;
        }
        // GEN171: late-stream new-bin aversion with large waste
        if open_bins_count > 0 && progress > 0.7 && mean_residual > cap * 0.4 && waste > 0.5 {
            score += 0.8 * (waste - 0.5) * (progress - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but reward even more when
    // the next item can exactly fill the leftover (2-step lookahead match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step chain: subtract heavily to strongly favor this bin.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a further residual: reward proportional
            // to how well the chain packs (smaller double-residual is better).
            let chain_res = post_residual - next_item_size;
            score -= 40.0 - (chain_res as f64) * 0.5;
        } else {
            // Next item cannot use the leftover: mild penalty scaled by gap,
            // but only if the gap is small (near-miss is worse than far-miss).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 12.0 - gap; // near-miss penalty up to +12
            }
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average is good (this bin absorbs waste efficiently).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large (would leave open bins with big residuals anyway) or many bins
    // are already open (fragmentation control).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if !large_item {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
        // Even for large items, opening is only mildly attractive:
        score -= 5.0 * (open_bins_count as f64).min(10.0);
    }

    // Slight preference for bins whose residual was already small relative
    // to capacity (fill nearly-full bins first).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Tiny progression-based tiebreaker to stabilize ordering late in stream.
    score += 0.01 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0 as usize) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
