    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = pr - nx;
        score -= 45.0;
        // GEN173: perfect refill chain (after == nx) earns extra bonus
        if (after - nx).abs() < 0.5 {
            score -= 8.0 * (0.5 + 0.5 * progress);
        }
        // GEN173: penalize wide leftover bands (after >> nx) late in the stream
