    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
        // GEN173: penalize stranding a residual just below nx when others could host nx
        if pr >= nx * 0.8 && pr < nx && fitting_bins_count >= 2 {
