        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            if after2 >= 2.0 * nx && after2 <= 2.0 * nx + 2.0 && nx >= 3.0 {
                score -= 1.0 * (1.0 - (after2 - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        if progress > 0.4 && progress <= 0.85 && waste > 0.5 && open_bins_count > 0 && mean_residual >= nx {
            score += 1.0 * (waste - 0.5) * (0.6 + 0.4 * progress) ;
        }
        if open_bins_count > 0 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 2.0 {
            score -= 1.2 * (1.0 - (pr - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN175: strongly discourage opening a new bin mid/late stream when an open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN175: discourage new bins near the end when open space still suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // Dead-space ratio (fraction of remaining space stranded after placement).
    let dead = if br > 0.0 { pr / br } else { 1.0 };

    // Exact / near fits.
    if pr == 0.0 {
        score -= 30.0;
    } else if pr <= 2.0 {
        score -= 14.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.0;
    }

    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            // Reward placements that leave room for the next item, tighter is better.
            score -= 14.0 * (1.0 - after / cap).max(0.0);
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0;
            }
            if (after) < 0.5 {
                score -= 5.0; // perfect refill chain
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 1.5 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 6.0 && nx >= 2.0 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 6.0) * (0.5 + 0.5 * progress);
            }
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 5.0 {
                score -= 0.6 * (1.0 - (after - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress);
            }
            // Penalize wide leftover bands far exceeding nx late in the stream.
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.4 * ((after - 25.0) / 30.0) * (progress - 0.5);
            }
        } else {
            // Next item won't fit here: penalize proportionally, harder early.
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 0.6 * (1.0 - progress);
            }
            // When nothing fits nx, mildly favor the largest-residual bin.
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.5 * (1.0 - br / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
            }
            // Favor the bin that wastes the least overall.
            if fitting_bins_count == 0 && br < mean_residual * 0.85 && br > 0.0 {
                score -= 0.3 * (1.0 - br / mean_residual.max(1.0)) * (1.0 - progress);
            }
        }
    }

    // Dead-space penalties scaled by ratio, not fixed thresholds.
    if dead > 0.75 && pr > 12.0 {
        score += 1.5 * (dead - 0.75) * (1.0 + 0.5 * (1.0 - progress));
    }
    if dead > 0.6 && pr > 8.0 && nx > 0.0 && nx > pr {
        score += 0.9 * (dead - 0.6) * (nx - pr) / (nx + 1.0);
    }
    // Reward low dead-space bins that still host nx.
    if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
        score -= 0.5 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
    }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
        score += 1.5 * (dead - 0.9) * (0.5 + progress);
    }

    // Stranded residual just below nx: will be wasted if other bins can host nx.
    if dead > 0.35 && nx > 0.0 && pr > 0.0 && pr < nx && nx - pr <= 4.0 {
        score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress);
    }

    // Fitting-bin pressure: last-chance bin strongly favored.
    if fitting_bins_count == 1 {
        score -= 70.0;
    } else if fitting_bins_count >= 4 && pr > nx && nx > 0.0 {
        score -= 0.5;
    }

    // Open-bin pressure.
    score += (open_bins_count as f64) * 1.2;

    // Tighter bins relative to mean residual.
    score += (mean_residual - pr) * 0.3;

    // Late-stream greediness toward full bins.
    score -= progress * 20.0 * (1.0 - pr / cap);

    // ---- New-bin candidate logic ----
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress); // new bin can host the chain
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0;
        }
        if open_bins_count > 0 && waste > 0.5 && mean_residual > cap * 0.3 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        // Chain planning in the new bin: after hosting nx, residual stays usable.
        if open_bins_count > 0 && nx > 0.0 && waste * cap >= nx {
            let after2 = waste * cap - nx;
            if after2 < 6.0 {
                score -= 1.2 * (1.0 - after2 / 6.0) * (0.4 + 0.6 * progress);
            }
            if after2 >= nx && nx >= 3.0 && after2 < 2.0 * nx {
                score -= 0.5 * (1.0 - (after2 - nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            if after2 >= 2.0 * nx && nx >= 2.0 && after2 < 2.0 * nx + 3.0 {
                score -= 0.7 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress);
            }
        }
        // New bin leaves residual just below nx -> bad.
        if open_bins_count > 0 && nx > 0.0 && waste * cap < nx && waste * cap > 0.0 {
            score += 1.3 * (1.0 - (waste * cap) / nx.max(1.0)) * (0.6 + 0.4 * (1.0 - progress));
        }
        // Strongly discourage new bins mid/late when an open bin can host nx.
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.8 * (progress - 0.35) / 0.65;
        }
        // Discourage new bins early when an open bin fits nx exactly.
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress < 0.3 && waste > 0.5 && mean_residual >= nx {
            score += 0.5 * (0.3 - progress) / 0.3;
        }
        // Near stream end, prefer existing space.
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= item_size as f64 {
            score += 1.2 * (progress - 0.8) / 0.2;
        }
    }

    score
}

