        if progress > 0.4 && progress <= 0.85 && waste > 0.5 && open_bins_count > 0 && mean_residual >= nx {
            score += 1.0 * (waste - 0.5) * (0.6 + 0.4 * progress) ;
        }
        // GEN176: allow new bins whose leftover after nx still hosts nx again (perfect 2-fill)
        if open_bins_count > 0 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 2.0 {
            score -= 1.2 * (1.0 - (pr - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN176: strongly discourage opening a new bin mid/late stream when any open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN176: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // Dead-space avoidance (inherited, softened).
    if pr > 0.0 && pr < 10.0 {
        score += 40.0 * (1.0 - progress * 0.4);
    } else if pr > 0.0 && pr < 20.0 {
        score += 12.0;
    }

    // Exact and near-exact fits.
    if pr == 0.0 {
        score -= 90.0;
    } else if pr <= 2.0 {
        score -= 30.0;
    } else if pr <= 5.0 {
        score -= 15.0;
    } else if pr <= 9.0 {
        score -= 5.0;
    }

    // Lookahead chain rewards: leave a residual the next item can use tightly.
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            score -= 18.0 * (1.0 - after / cap).max(0.0);
            if after == 0.0 {
                score -= 8.0;
            } else if after <= 6.0 {
                score -= 4.0 * (1.0 - after / 6.0) * (0.5 + 0.5 * progress);
            } else if after <= 14.0 {
                score -= 1.5 * (1.0 - (after - 6.0) / 8.0);
            } else if after > 25.0 && progress > 0.5 {
                score += 0.6 * ((after - 25.0) / 30.0) * (progress - 0.5);
            }
            // Multi-chain: residual can host nx two or three more times.
            if nx >= 2.0 && after >= nx && after <= nx + 4.0 {
                score -= 1.2 * (1.0 - (after - nx) / 4.0);
            }
            if nx >= 3.0 && after >= 2.0 * nx && after <= 2.0 * nx + 4.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress);
            }
        } else {
            // Next item won't fit here after placement: penalize stranded gaps,
            // but favor the largest-residual bin as future host.
            score += (nx - pr) * (1.0 + 0.8 * (1.0 - progress));
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.8 * (1.0 - br / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
            }
        }
    }

    // Fitting-bin pressure.
    if fitting_bins_count > 1 {
        score -= 10.0;
    } else if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Open-bin pressure.
    score += (open_bins_count as f64) * 1.5;

    // Tighter-than-mean preference.
    score += (mean_residual - pr) * 0.3;

    // Dead ratio term: penalize bins whose post-residual is mostly unusable.
    let dead = pr / br.max(1.0);
    if dead > 0.6 && pr > 10.0 {
        score += 1.5 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress));
    }
    if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
        score -= 0.8 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
    }

    // New-bin candidate: open only when open bins are genuinely bad.
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score += 35.0;
        // Small waste (item nearly fills a fresh bin): cheap to open.
        if waste < 0.35 {
            score -= 2.5 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        // Late stream: strongly discourage new bins when residual space suffices.
        if open_bins_count > 0 && progress > 0.5 {
            score += 3.0 * (progress - 0.5);
        }
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= item_size as f64 {
            score += 2.0 * (progress - 0.8) / 0.2;
        }
        // If fresh bin can host nx after this item tightly, mild discount.
        if nx > 0.0 && cap - item_size as f64 >= nx {
            let after2 = cap - item_size as f64 - nx;
            if after2 < 6.0 {
                score -= 2.0 * (1.0 - after2 / 6.0) * (0.4 + 0.6 * progress);
            }
        }
    } else if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
        // Half-empty bin becoming mostly dead: discourage.
        score += 1.5 * (pr / br) * (1.0 - progress);
    }

    // Late-stream tightening toward exact fits.
    score -= progress * 20.0 * (1.0 - pr / cap);

    score
}

