        // GEN177: gate new bins harder mid/late when an open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN177: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Fractional waste term: quadratic in residual waste ratio.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste * waste;

    // Reward using bins that are already quite full (tight packing).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fullness;

    // Last-chance bin: strongly prefer filling it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin only when fit is bad.
    score += (open_bins_count as f64) * 0.8;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 35.0;
        } else {
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // New-bin candidate logic: empty bin gets a base cost plus pressure so it only
    // wins when existing fits are poor (high dead space).
    if bin_residual == bin_capacity {
        score += 45.0 + 2.5 * (open_bins_count as f64);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Mild stream-progression calibration: later in the stream, be slightly
    // more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for any plausible item (min size 1 assumed, but typical items larger).
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
        score += 8.0 * dead * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly into this bin's post_residual, strongly favor it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many open bins have slack.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty scaled by open bins and mean residual.
        score += 25.0 + 4.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0; // there are bins with enough slack; avoid new bin
        }
        // Early in stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If next item is large and won't fit anywhere else anyway, new bin is fine.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Slight preference for bins with residual close to mean (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: late in stream, be greedy — prefer tightest fit even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-item capacity lookahead (fine-grained: reward leftover that can host small future items)
    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.0;
    let fits_small = post_residual / 6;
    if fits_small > fits_mid {
        score -= (fits_small - fits_mid) as f64 * 1.2 * (0.4 + 0.6 * progress);
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
                if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress); }
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // GEN178: reward tight after-spaces in the 1..=12 band more aggressively
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0);
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress);
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress);
            }
            if after >= 6.0 && after <= 14.0 && fitting_bins_count >= 3 {
                score -= 0.7 * (1.0 - (after - 6.0) / 8.0);
            }
            // chaining: leave room for next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // chainable after-space: can host next item AND leave a small residual
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            // awkward leftover: barely larger than next item
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress);
            }
            // tiny after-space is excellent
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            // GEN178: reward exact 2-chain and 3-chain refills with tight margins
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 && nx > 0.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
            if nx >= 3.0 && after >= 3.0 * nx && after <= 3.0 * nx + 6.0 {
                score -= 0.8 * (1.0 - (after - 3.0 * nx) / 6.0) * (0.5 + 0.5 * progress);
            }
            // GEN178: penalize wide leftover bands late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5);
            }
            // penalize leftover that is too big relative to need when bins are plentiful
            if after > 30.0 && after < 60.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.4 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        } else {
            // next item won't fit here
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 0.6 * (1.0 - progress);
            }
            // GEN178: late stream, no bin fits nx — favor the largest-residual bin as future host
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br.max(1.0) / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
            }
            if fitting_bins_count == 0 && br < mean_residual * 0.85 && br > 0.0 {
                score -= 0.3 * (1.0 - br / mean_residual.max(1.0)) * (1.0 - progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // dead-space below min item size is wasted when next item can't use it
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // last-chance bin
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio (fragmentation of this bin) analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    // mid-range dead space with large residual: penalize
    if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
        score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress);
    }
    // GEN178: reward low dead-space bins that still leave usable space for nx
    if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
        score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
    }
    // GEN178: penalize high dead-space bins with stranded residuals harder when many bins compete
    if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
        score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25;
    }
    // pool-balance bonus
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    // near-exact next-item fit into residual
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    // GEN178: penalize bins that strand a residual just below nx when other bins could host nx
    if dead > 0.35 && nx > 0.0 && pr >= nx && pr - nx < 1.0 && pr - nx > 0.0 && fitting_bins_count >= 2 {
        score += 0.3 * (1.0 - (pr - nx)) * (1.0 - progress);
    }
    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
            // double-lookahead: reward opening when leftover after next item is tiny
            if after_new > 0.0 && after_new < 6.0 {
                score -= 1.2 * (1.0 - after_new / 6.0) * (0.4 + 0.6 * progress);
            }
            // GEN178: reward multi-chain capacity in the new bin (after hosting nx, room for nx again)
            if after_new >= nx && nx >= 3.0 && after_new < 2.0 * nx {
                score -= 0.5 * (1.0 - (after_new - nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // penalize opening when a fitting open bin's residual is almost exactly the item
        if open_bins_count > 0 && fitting_bins_count >= 1 && mean_residual >= item_size as f64
            && (mean_residual - item_size as f64) < 0.05 * cap {
            score += 1.5 * (1.0 - (mean_residual - item_size as f64) / (0.05 * cap));
        }
        // GEN178: discourage opening a new bin mid/late stream when any open bin can host nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65;
        }
        // GEN178: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= item_size as f64 {
            score += 1.0 * (progress - 0.8) / 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.5 * (1.0 - x) * (1.0 - x))
                  + 30.0 * x * x * (1.0 - x); // penalize mid-range dead space, reward near-perfect fits

    // Stream-progress coupling: as the stream advances, tolerate larger residuals less
    let prog_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += prog_coupling * pr * 0.6;

    // Late stream: strongly prefer tight fits
    score += progress.powi(2) * pr * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward residual that can accommodate the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 10.0 * (nx / cap);
        } else {
            score += 5.0 * (nx / cap) * (1.0 - pr / nx.max(1.0));
        }
    }

    // Mean residual context: penalize bins far from mean residual (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (1.0 + progress);

    // Many open bins: mild pressure to consolidate into existing bins
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - x);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress) - item_size as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue mod 10.
    let pr = post_residual as i64;
    let residue_class = pr % 10;
    // Residues that are "friendly" (likely to be filled by small future items) get rewarded.
    let friendly = matches!(residue_class, 0 | 5 | 10);
    if friendly {
        score -= 6.0;
    } else if residue_class == 1 || residue_class == 9 {
        score += 4.0; // nearly unusable slivers
    } else {
        score += 1.5;
    }

    // Integer-division thresholds: post_residual bucketed by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 {
        score -= 10.0; // bin essentially closed: great
    } else if frac < 0.15 {
        score -= 3.0;
    } else if frac > 0.6 {
        score += 2.0; // leaving a huge empty bin is weak packing
    }

    // Lookahead coupling: harmonic class of next item vs post residual.
    if next_item_size > 0 {
        if (next_item_size as i64) <= pr {
            // next item fits exactly into this residual: strong reward
            let exact = (next_item_size as i64) == pr;
            if exact {
                score -= 20.0;
            } else {
                score -= 5.0;
                // modulo match between next item and residual class
                if (next_item_size as i64) % 10 == residue_class {
                    score -= 3.0;
                }
            }
        } else {
            // next item cannot use this residual: penalize leaving large leftovers
            if pr > (next_item_size as i64) / 2 && pr > 15 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // this bin would be a bad host (large post residual, unfriendly class).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let openness = (open_bins_count as f64).ln_1p();
        // base penalty so existing bins are preferred unless fit is poor
        score += 25.0;
        // early stream: opening bins is cheaper
        score -= 20.0 * (1.0 - progress);
        // many open bins with slack: discourage new bins
        score += 4.0 * openness;
        // if placing in an existing bin would waste a lot, new bin becomes viable
        if post_residual > 40 && !friendly {
            score -= 15.0;
        }
        if next_item_size > 0 && (next_item_size as i64) <= bin_capacity as i64 / 2 {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    // Mild pressure to prefer tighter bins when many bins are open.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Small late-stream tightening: exact fits matter more as stream ends.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    score -= 4.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // item (sizes >= 1, but realistically items < 10 are rare / wasted space)
    // are heavily penalized. Dead zones: post_residual in 1..=9.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tight-fit reward: reward leaving a gap that exactly matches the
    // lookahead item (k=2 lookahead exploitation).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        // gap large enough for next item but wastefully so
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins, penalize opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; later, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If no open bin fits, new bin is the only option: soften penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Reward using bins whose residual is close to the mean (balance),
        // penalize draining already-small bins below usable threshold.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Prefer bins that end with a residual still usable by typical items
    // (>= 10) over bins ending in the dead zone — handled above — and mildly
    // reward large fills.
    score -= 0.3 * item_size as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
