            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress) ;
            }
            // GEN178: triple-chain bonus for new bins when residual economy is tight
            if after2 >= 3.0 * nx && nx >= 3.0 && after2 < 3.0 * nx + 5.0 && mean_residual < cap * 0.3 {
                score -= 0.6 * (1.0 - (after2 - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        // discourage opening a new bin late when an open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.7 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
        // GEN178: strongly discourage opening a new bin mid/late stream when any open bin can host nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN178: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // reward low-dead bins whose post-space exactly matches nx plus tiny margin
        let dead = pr / br . max (1.0) ;
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // penalize mid-dead bins leaving a wide unusable band just above nx
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN178: reward low dead-space bins that still leave usable space for nx
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.4 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
        // GEN178: penalize high dead-space bins with large stranded residuals when many bins compete
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25 ;
        }
        // GEN178: reward harmonic 3x chain matches at mid-dead ratios
        if dead > 0.2 && dead <= 0.45 && nx >= 4.0 && pr >= 3.0 * nx && pr - 3.0 * nx <= 4.0 && fitting_bins_count <= 3 {
            score -= 0.45 * (1.0 - (pr - 3.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let nx = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if pr > 0.0 && pr < 10.0 {
        score += 60.0 - pr * 4.0;
    }
    // Perfect fit reward.
    if pr == 0.0 {
        score -= 40.0;
    }

    // Lookahead: reward leaving space the next item can use; penalize stranded gaps.
    if nx > 0.0 {
        if pr >= nx {
            let after = pr - nx;
            score -= 15.0 * (1.0 - after / cap).max(0.0);
            // Reward tight refills: leftover after hosting nx is small or matches nx chains.
            if after >= 1.0 && after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0);
            }
            if (pr - nx).abs() < 0.5 {
                score -= 5.0;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 && nx >= 2.0 {
                score -= 3.0 * (1.0 - (after - 2.0 * nx) / 8.0);
            }
        } else if pr > 0.0 {
            // Gap too small for lookahead item: dead space, penalize harder when late.
            score += 20.0 + 10.0 * progress;
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 8.0 * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: consolidate when many bins are open.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(1.0) / 20.0);
    score += pressure * 2.0;

    // Dead-space ratio: penalize bins whose remaining space is mostly wasted.
    let dead = pr / br.max(1.0);
    if pr > 0.0 && dead > 0.6 && pr > 10.0 && nx > 0.0 && nx > pr {
        score += 4.0 * (dead - 0.6);
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins fit poorly.
        let waste = (cap - item_size as f64) / cap;
        let bad_open = if fitting_bins_count == 0 { 0.0 } else { (mean_residual - item_size as f64).max(0.0) };
        score += 30.0 + bad_open * 0.5 - (open_bins_count as f64) * 0.5;
        score += progress * 5.0;
        // Large waste in a new bin is bad unless nothing fits.
        if waste > 0.5 {
            score += 4.0 * (waste - 0.5) * (0.5 + 0.5 * progress);
        }
        // If any open bin can host the next item tightly, discourage a new bin.
        if open_bins_count > 0 && fitting_bins_count >= 1 && mean_residual >= nx * 0.8 && progress > 0.3 {
            score += 6.0 * (progress - 0.3) / 0.7;
        }
        // New bin whose leftover can host nx is more acceptable early.
        if nx > 0.0 && (cap - item_size as f64) >= nx && progress < 0.4 {
            score -= 4.0 * (1.0 - progress);
        }
        // Late stream: never open bins with tiny expected leftovers.
        if progress > 0.8 && mean_residual >= item_size as f64 {
            score += 8.0 * (progress - 0.8) / 0.2;
        }
    } else {
        // Favor tight fits: residual closest above the item.
        score += (bin_residual - item_size) as f64 * 0.1;
        // Prefer bins whose post-residual can exactly host the next item again.
        if pr > 0.0 && nx > 0.0 && pr >= nx && (pr - nx) < 0.02 * cap {
            score -= 4.0 * (1.0 - (pr - nx) / (0.02 * cap));
        }
        // When several bins fit, prefer the one with residual near mean (balanced consolidation).
        if fitting_bins_count >= 3 && (pr - mean_residual).abs() < 3.0 {
            score -= 2.0 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let leftover2 = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - leftover2 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted potential
            score += 15.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small post-residual is good dead-space-wise, but only if not too small to matter
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 5.0; // tiny dead space barely usable
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        let base = 40.0
            - if next_item_size > 0 && next_item_size <= bin_capacity {
                10.0
            } else {
                0.0
            };
        score += base + 0.5 * mean_residual;
        // early in stream, new bins are cheaper; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Many open bins: encourage filling existing ones
    score += 0.2 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

