    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows quadratically as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing in the plausible size range can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - chain_fit / (bin_capacity as f64));
        } else if post_residual > 0 {
            // post-residual too small for next item: mild penalty for wasted remainder
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidation into existing bins (penalize new bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 15.0 + 20.0 * (open_bins_count as f64).sqrt() * (1.0 - 0.5 * progress);
    } else {
        // Reward filling bins that are already partly used relative to mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild global pressure: late in the stream, tighten packing further.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 6.0 * progress * tightness;

    score
}

