        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.6 && nx > 0.0 && pr < nx && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.0 * (dead - 0.6) * (1.0 - progress) ;
        }
        if dead > 0.65 && pr > 10.0 && mean_residual < cap * 0.2 {
            score += 0.6 * (dead - 0.65) * (0.5 + 0.5 * progress) ;
        }
        if pr > 6.0 && (pr - mean_residual) . abs () < 5.0 && fitting_bins_count >= 3 {
            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // GEN179: low-dead bins whose residual after nx still chains nx once more
        if dead <= 0.3 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 4.0 && fitting_bins_count >= 2 {
            score -= 0.9 * (1.0 - (pr - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN179: penalize high-dead bins when a roomier open bin could host nx with a tighter fit
        if dead > 0.7 && nx > 0.0 && pr >= nx && open_bins_count >= 2 && mean_residual >= nx && (mean_residual - nx) < (pr - nx) {
            score += 1.0 * (dead - 0.7) * (0.4 + 0.6 * progress) ;
        }
        // GEN179: reward low-dead bins that still leave usable space for nx
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
        // GEN179: penalize high dead-space bins with stranded residuals when many bins compete
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25 ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN179: reward new-bin leftovers that can chain nx twice exactly
            if after2 >= 2.0 * nx && after2 <= 2.0 * nx + 2.0 && nx >= 3.0 {
                score -= 1.2 * (1.0 - (after2 - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN179: reward triple-chain leftovers in new bins when residual economy is tight
            if after2 >= 3.0 * nx && nx >= 3.0 && after2 <= 3.0 * nx + 5.0 && mean_residual < cap * 0.3 {
                score -= 0.7 * (1.0 - (after2 - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // GEN179: gate new bins harder mid-stream when waste is large and mean residual still hosts nx
        if progress > 0.4 && progress <= 0.85 && waste > 0.5 && open_bins_count > 0 && mean_residual >= nx {
            score += 1.0 * (waste - 0.5) * (0.6 + 0.4 * progress) ;
        }
        // GEN179: allow new bins whose leftover after nx still hosts nx again (perfect 2-fill)
        if open_bins_count > 0 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 2.0 {
            score -= 1.4 * (1.0 - (pr - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN179: strongly discourage opening a new bin mid/late when any open bin can host nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN179: discourage new bins near the end when open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: exact or near-exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic class of post_residual: penalize residuals that are
    // "dead" relative to the smallest item class (1..100 interface).
    let small = 10u32.min(bin_capacity);
    let dead_threshold = 25;
    if post_residual > 0 && post_residual < dead_threshold {
        // small dead space: wasted unless truly tiny
        score += (dead_threshold - post_residual) as f64 * 0.6;
    }

    // Modulo arithmetic on capacity fractions: residual in harmonic bands.
    let q = post_residual / (bin_capacity / 4).max(1);
    match q {
        0 => score -= 15.0,          // residual < 25% capacity: bin nearly full, good
        1 => score += 2.0,           // 25-50%: mildly useful
        2 => score += 6.0,           // 50-75%: fine, plenty of room anyway
        _ => score += 10.0,          // mostly empty bin: keep for bigger items
    }

    // Integer-division threshold coupling with lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead fits too: reward chain placements
            let chain = post_residual / next_item_size.max(1);
            score -= 8.0 + (chain.min(4) as f64) * 4.0;
        } else {
            // lookahead won't fit in leftover: penalize leaving awkward gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Harmonic pairing: leftover + next item near capacity multiples
        let combo = post_residual + next_item_size;
        if combo == bin_capacity {
            score -= 30.0;
        } else if combo > bin_capacity * 3 / 4 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    // or lookahead demands fresh space.
    if bin_residual == bin_capacity {
        score += 40.0;
        let poor_fit = post_residual > 40 && (next_item_size == 0 || next_item_size > post_residual);
        if poor_fit {
            score -= 55.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mean residual context: prefer filling below-average-residual bins.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Mild stream-phase modulation: early on, prefer consolidation.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Post residual that cannot fit any plausible future item (>=1) is pure waste;
    // weight waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= (1.0 - tightness.min(1.0)) * 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize leaving a stranded gap.
        score += 6.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening/spreading;
    // handled via penalizing new-bin candidates and bins with large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += pressure * 2.0;
        // But if no open bin fits well, allow it: soften when fitting bins are scarce.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    } else {
        // Favor filling bins with smaller residuals (best-fit bias) scaled by pressure.
        score += (bin_residual as f64 / bin_capacity as f64) * pressure * 0.5;
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= nx && nx > 0.0 && (after - nx) >= 1.0 && (after - nx) <= 6.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after - nx) / 6.0) * (0.4 + 0.6 * progress) ;
            }
            if after == 0.0 && fitting_bins_count <= 3 {
                score -= 1.2 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && nx >= 2.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - progress) ;
            }
            if after > nx && after - nx <= 3.0 && fitting_bins_count <= 2 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) ;
            }
            if after > 0.0 && after <= 0.5 * cap && (after / 2.0 - nx) . abs () <= 1.0 && nx >= 2.0 {
                score -= 0.6 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
            // GEN171: reward after-space that exactly hosts nx twice (perfect 2-chain)
            if after >= 2.0 * nx && after <= 2.0 * nx + 2.0 && nx >= 3.0 && fitting_bins_count <= 4 {
                score -= 0.9 * (1.0 - (after - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN171: reward after-space matching nx thrice when residual pool is thin
            if after >= 3.0 * nx && after <= 3.0 * nx + 3.0 && nx >= 3.0 && mean_residual < cap * 0.3 {
                score -= 0.7 * (1.0 - (after - 3.0 * nx) / 3.0) * (0.4 + 0.6 * progress) ;
            }
            // GEN171: penalize wide unusable band above nx when mean residual is small (few future hosts)
            if after > nx + 8.0 && after < nx + 20.0 && mean_residual < cap * 0.2 && fitting_bins_count <= 3 {
                score += 0.6 * ((after - nx - 8.0) / 12.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN180: lookahead — reward leftovers that can host nx AND the following item's remainder chain
            if after >= 2.0 * nx && after < 2.0 * nx + 2.0 && nx >= 2.0 && progress > 0.3 {
                score -= 1.1 * (1.0 - (after - 2.0 * nx) / 2.0) * (0.4 + 0.6 * progress) ;
            }
            // GEN180: penalize stranded slivers just below nx after this item (unusable dead space)
            if after > 0.0 && after < nx && fitting_bins_count >= 3 && mean_residual >= nx {
                score += 0.7 * (1.0 - after / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN180: exact refill (after == nx) is the ideal lookahead state — strong bonus
            if (after - nx) . abs () < 0.5 && nx >= 2.0 {
                score -= 1.4 * (0.5 + 0.5 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if pr > 0.0 && open_bins_count >= 2 && mean_residual >= nx && mean_residual > pr + 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / (nx + 1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN171: soften mismatch when another bin can host nx exactly
            if fitting_bins_count >= 3 && mean_residual >= nx && (mean_residual - nx) <= 4.0 {
                score -= 0.7 * (1.0 - progress) ;
            }
            // GEN180: when this bin cannot host nx, mildly prefer the bin whose residual is closest to nx (least future waste)
            if pr > 0.0 && mean_residual >= nx {
                let d = (br - nx) . abs () ;
                if d < 6.0 {
                    score -= 0.5 * (1.0 - d / 6.0) * (0.4 + 0.6 * progress) ;
                }
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.6 && nx > 0.0 && pr < nx && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.0 * (dead - 0.6) * (1.0 - progress) ;
        }
        if dead > 0.65 && pr > 10.0 && mean_residual < cap * 0.2 {
            score += 0.6 * (dead - 0.65) * (0.5 + 0.5 * progress) ;
        }
        if pr > 6.0 && (pr - mean_residual) . abs () < 5.0 && fitting_bins_count >= 3 {
            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // GEN171: low-dead bins whose residual after nx still chains nx once more
        if dead <= 0.3 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 4.0 && fitting_bins_count >= 2 {
            score -= 0.7 * (1.0 - (pr - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN171: penalize high-dead bins when a roomier open bin could host nx with a tight fit
        if dead > 0.7 && nx > 0.0 && pr >= nx && open_bins_count >= 2 && mean_residual >= nx && (mean_residual - nx) < (pr - nx) {
            score += 0.8 * (dead - 0.7) * (0.4 + 0.6 * progress) ;
        }
        // GEN180: high-dead bins with big stranded residuals when many bins compete — extra penalty
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * ((fitting_bins_count as f64 - 3.0) * 0.25) ;
        }
        // GEN180: reward low-dead bins that still leave usable space for nx
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN171: reward new-bin leftovers that can chain nx twice exactly
            if after2 >= 2.0 * nx && after2 <= 2.0 * nx + 2.0 && nx >= 3.0 {
                score -= 1.0 * (1.0 - (after2 - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN180: reward new bins whose leftover after nx still hosts nx again (perfect 2-fill)
            if open_bins_count > 0 && nx >= 3.0 && after2 >= 2.0 * nx && after2 <= 2.0 * nx + 2.0 {
                score -= 1.2 * (1.0 - (after2 - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // GEN171: gate new bins harder mid-stream when waste is large and mean residual still hosts nx
        if progress > 0.4 && progress <= 0.85 && waste > 0.5 && open_bins_count > 0 && mean_residual >= nx {
            score += 1.0 * (waste - 0.5) * (0.6 + 0.4 * progress) ;
        }
        // GEN180: strongly discourage new bins mid/late when any open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN180: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
        // GEN180: penalize bins that strand a residual just below nx after this item, when other bins could host nx
        if nx > 0.0 && pr >= nx && pr - nx > 0.0 && pr - nx < 1.0 && fitting_bins_count >= 2 {
            score += 0.3 * (1.0 - (pr - nx)) * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space relative to capacity (quadratic waste).
    if post_residual > 0 {
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste_frac * waste_frac;
    }

    // Reward exact fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly accommodates the next item (perfect 2-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to how much room remains after.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item will not fit here: penalize creating near-but-not-quite
            // dead space that blocks the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Relative-to-mean adjustment: prefer tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        let lookahead_bad = next_item_size > 0 && post_residual < next_item_size;
        let mut new_bin_score = 30.0 + 60.0 * (1.0 - crowded);
        if lookahead_bad { new_bin_score -= 10.0; }
        if open_bins_count == 0 { new_bin_score -= 100.0; }
        score = score.min(new_bin_score) - 5.0;
        score += new_bin_score * 0.0; // keep base comparison
        score = new_bin_score;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= nx && nx > 0.0 && (after - nx) >= 1.0 && (after - nx) <= 6.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after - nx) / 6.0) * (0.4 + 0.6 * progress) ;
            }
            if after == 0.0 && fitting_bins_count <= 3 {
                score -= 1.2 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && nx >= 2.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - progress) ;
            }
            if after > nx && after - nx <= 3.0 && fitting_bins_count <= 2 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) ;
            }
            if after > 0.0 && after <= 0.5 * cap && (after / 2.0 - nx) . abs () <= 1.0 && nx >= 2.0 {
                score -= 0.6 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 2.0 && nx >= 3.0 && fitting_bins_count <= 4 {
                score -= 0.9 * (1.0 - (after - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 3.0 * nx && after <= 3.0 * nx + 3.0 && nx >= 3.0 && mean_residual < cap * 0.3 {
                score -= 0.7 * (1.0 - (after - 3.0 * nx) / 3.0) * (0.4 + 0.6 * progress) ;
            }
            if after > nx + 8.0 && after < nx + 20.0 && mean_residual < cap * 0.2 && fitting_bins_count <= 3 {
                score += 0.6 * ((after - nx - 8.0) / 12.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN181: reward exact refill (after == nx) — perfect lookahead chain
            if nx >= 2.0 && (after - nx) . abs () < 0.5 {
                score -= 2.2 * (0.5 + 0.5 * progress) ;
            }
            // GEN181: penalize stranded leftover just below nx when another bin can host nx
            if after > 0.0 && after < nx && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.7 * (1.0 - after / nx . max (1.0)) * (0.4 + 0.6 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if pr > 0.0 && open_bins_count >= 2 && mean_residual >= nx && mean_residual > pr + 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / (nx + 1.0)) * (0.5 + 0.5 * progress) ;
            }
            if fitting_bins_count >= 3 && mean_residual >= nx && (mean_residual - nx) <= 4.0 {
                score -= 0.7 * (1.0 - progress) ;
            }
            // GEN181: when no bin fits nx later, mildly favor the bin with the largest residual
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br . max (1.0) / (mean_residual . max (1.0) * 2.0)) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.6 && nx > 0.0 && pr < nx && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.0 * (dead - 0.6) * (1.0 - progress) ;
        }
        if dead > 0.65 && pr > 10.0 && mean_residual < cap * 0.2 {
            score += 0.6 * (dead - 0.65) * (0.5 + 0.5 * progress) ;
        }
        if pr > 6.0 && (pr - mean_residual) . abs () < 5.0 && fitting_bins_count >= 3 {
            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.3 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 4.0 && fitting_bins_count >= 2 {
            score -= 0.7 * (1.0 - (pr - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.7 && nx > 0.0 && pr >= nx && open_bins_count >= 2 && mean_residual >= nx && (mean_residual - nx) < (pr - nx) {
            score += 0.8 * (dead - 0.7) * (0.4 + 0.6 * progress) ;
        }
        // GEN181: reward low-dead bins whose residual still hosts nx with a tight margin
        if dead <= 0.25 && nx > 0.0 && pr >= nx && pr - nx <= 2.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 2.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN181: penalize high-dead bins with large stranded residuals when many bins compete
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25 ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            if after2 >= 2.0 * nx && after2 <= 2.0 * nx + 2.0 && nx >= 3.0 {
                score -= 1.0 * (1.0 - (after2 - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        if progress > 0.4 && progress <= 0.85 && waste > 0.5 && open_bins_count > 0 && mean_residual >= nx {
            score += 1.0 * (waste - 0.5) * (0.6 + 0.4 * progress) ;
        }
        if open_bins_count > 0 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 2.0 {
            score -= 1.2 * (1.0 - (pr - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN181: gate new bins harder late in the stream when open space still fits the current item
        if progress > 0.6 && open_bins_count > 0 && fitting_bins_count >= 1 && mean_residual >= it {
            score += 1.4 * (progress - 0.6) / 0.4 ;
        }
        // GEN181: discourage new bins whose leftover strands a sliver just below nx
        if nx > 0.0 && pr > 0.0 && pr < nx && nx - pr <= 6.0 && open_bins_count > 0 && mean_residual >= nx {
            score += 0.9 * (1.0 - (nx - pr) / 6.0) * (0.5 + 0.5 * progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        score -= 15.0 - (lookahead_waste as f64 / bin_capacity as f64) * 15.0;
        if lookahead_waste == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize small unusable leftovers.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many fitting bins means flexibility is high; slight penalty for using a flexible bin.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Time horizon: early in the stream, be conservative (favor filling existing bins well);
    // late in the stream, less concern about future fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Global state coupling: if open bins have large mean residual, prefer reusing bins
    // over opening new ones; if mean residual is small, opening new bins is less costly.
    if bin_residual < bin_capacity {
        // Existing bin: reward when mean residual across bins is high (space is abundant).
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
    } else {
        // New-bin candidate: penalize when existing bins are spacious (mean residual large),
        // reward opening a new bin when open bins are nearly full.
        let crowd = (mean_residual / bin_capacity as f64).min(1.0);
        score += 30.0 * crowd;
        // Extra penalty for opening a bin when many bins are already open and empty-ish.
        score += (open_bins_count as f64).ln().max(0.0) * 5.0 * crowd;
        // Late in the stream, opening a new bin is fine (no need to close out tight).
        score -= 10.0 * progress;
    }

    // Discourage leaving residuals in the awkward 1..10 band (unusable for min item 10,
    // but interface allows items >= 1, so treat < 5 as near-dead).
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // mid-item capacity lookahead (tuned: reward bins that can still host mid-size items)
    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.0;
    if post_residual % 20 >= 10 && fitting_bins_count >= 2 {
        score -= 0.4;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // perfect refill: after == nx earns a stronger chain bonus
            if nx >= 2.0 && (after - nx).abs() < 0.5 && fitting_bins_count >= 2 {
                score -= 1.2 * (0.4 + 0.6 * progress);
            }
            // chaining: leave room for next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // tight 2-chain bonus
            if nx >= 2.0 && after >= 2.0 * nx && after <= 2.0 * nx + 2.0 && progress > 0.4 {
                score -= 0.5 * (1.0 - (after - 2.0 * nx) / 2.0) * progress;
            }
            // penalize wide leftover bands (after >> nx) late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5);
            }
            // penalize leftover that is too big relative to need when bins are plentiful
            if after > 30.0 && after < 60.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
            // penalize stranding a residual just below nx after this item
            if after > 0.0 && after < 1.0 && fitting_bins_count >= 2 {
                score += 0.3 * (1.0 - after) * (1.0 - progress);
            }
            // reward leaving a sub-unit residual when mean pool is tight
            if after >= 0.5 && after < 1.0 && mean_residual < cap * 0.5 {
                score -= 0.9 * (1.0 - after) * (0.5 + 0.5 * progress);
            }
        } else {
            // next item won't fit here
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if fitting_bins_count >= 2 && mean_residual >= nx { score -= 0.6 * (1.0 - progress); }
            // when no bin can take nx, mildly favor the bin with the largest residual
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br.max(1.0) / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // dead-space below min item size is wasted when next item can't use it
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // last-chance bin
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio (fragmentation of this bin) analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    // penalize high dead-space bins with large stranded residuals harder when many bins compete
    if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
        score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25;
    }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    // reward low dead-space bins that still leave usable space for nx
    if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
        score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
    }
    // pool-balance bonus
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    // near-exact next-item fit into residual
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // discourage opening a new bin mid/late stream when any open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65;
        }
        // discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= item_size as f64 {
            score += 1.0 * (progress - 0.8) / 0.2;
        }
        // discourage opening a new bin early when an open bin fits nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress < 0.3 && waste > 0.5 && mean_residual >= nx {
            score += 0.5 * (0.3 - progress) / 0.3;
        }
        // new-bin chain analysis: leftover after nx in the new bin
        if open_bins_count > 0 && nx > 0.0 && waste * cap >= nx {
            let after2 = waste * cap - nx;
            if after2 < 6.0 {
                score -= 1.2 * (1.0 - after2 / 6.0) * (0.4 + 0.6 * progress);
            }
            if after2 >= nx && nx >= 3.0 && after2 < 2.0 * nx {
                score -= 0.5 * (1.0 - (after2 - nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress);
            }
            // triple-chain bonus when residual economy is tight
            if after2 >= 3.0 * nx && nx >= 3.0 && after2 < 3.0 * nx + 5.0 && mean_residual < cap * 0.3 {
                score -= 0.5 * (1.0 - (after2 - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let base = 1.0 + progress;
    score += 12.0 * pr_norm * pr_norm * (1.0 - pr_norm) * base;

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as u32) < next_item_size {
            score += 8.0 * (1.0 - pr / nxt.max(1.0)) * (0.5 + progress);
        } else {
            // reward bins that can also host the next item
            score -= 4.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Prefer bins with residuals close to the mean (balance), smooth coupling
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Mild penalty for spreading across many open bins early on
    score += 0.3 * open_bins_count as f64 * progress * item_norm;

    // New-bin candidate: keep it neutral-ish, slightly penalized unless nothing fits well
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 3.0 * item_norm;
    }

    score
}

