            score -= 0.7 * (1.0 - (pr - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.7 && nx > 0.0 && pr >= nx && open_bins_count >= 2 && mean_residual >= nx && (mean_residual - nx) < (pr - nx) {
            score += 0.8 * (dead - 0.7) * (0.4 + 0.6 * progress) ;
        }
        // GEN181: penalize high-dead bins whose leftover after nx strands a thin unusable sliver
        if dead > 0.6 && nx > 0.0 && pr >= nx && (pr - nx) > 0.0 && (pr - nx) < 2.0 && fitting_bins_count >= 2 {
            score += 0.5 * (2.0 - (pr - nx)) * (0.5 + 0.5 * progress) ;
        }
        // GEN181: reward low-dead bins that leave after-space exactly equal to nx (perfect chain)
        if dead <= 0.4 && nx > 0.0 && pr >= nx && (pr - nx) . abs () < 0.5 {
            score -= 0.8 * (0.5 + 0.5 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            if after2 >= 2.0 * nx && after2 <= 2.0 * nx + 2.0 && nx >= 3.0 {
                score -= 1.0 * (1.0 - (after2 - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        if progress > 0.4 && progress <= 0.85 && waste > 0.5 && open_bins_count > 0 && mean_residual >= nx {
            score += 1.0 * (waste - 0.5) * (0.6 + 0.4 * progress) ;
        }
        if open_bins_count > 0 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 2.0 {
            score -= 1.2 * (1.0 - (pr - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN181: gate new bins harder late when any open bin still fits nx tightly
        if progress > 0.6 && open_bins_count > 0 && fitting_bins_count >= 1 && mean_residual >= nx && (mean_residual - nx) <= 6.0 {
            score += 1.1 * ((progress - 0.6) / 0.4) * (1.0 - (mean_residual - nx) / 6.0) ;
        }
        // GEN181: allow a new bin when its leftover is a perfect 3-chain of nx
        if open_bins_count > 0 && nx >= 3.0 && pr >= 3.0 * nx && pr <= 3.0 * nx + 3.0 && mean_residual < cap * 0.3 {
            score -= 1.0 * (1.0 - (pr - 3.0 * nx) / 3.0) * (0.4 + 0.6 * progress) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
        // GEN181: prefer bins whose residual tracks the pool mean (balanced depletion)
        if pr > 0.0 && norm_gap < 4.0 && fitting_bins_count >= 2 && progress > 0.5 {
            score -= 0.4 * (1.0 - norm_gap / 4.0) * progress ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: which "slots" remain.
    // Classic reusable sizes: 10, 20, 25, 50, and small leftovers <=10.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit
    } else if pr <= 10 {
        -35.0 // dead space but nearly full
    } else if pr == 50 {
        -40.0 // exactly half — highly reusable
    } else if pr % 50 == 0 {
        -30.0
    } else if pr % 25 == 0 {
        -22.0
    } else if pr % 10 == 0 {
        -15.0
    } else if pr % 5 == 0 {
        -8.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize awkward mid-range dead space quadratically.
    if pr > 10 && pr < 50 {
        score += 0.35 * ((pr as f64) - 10.0);
    }

    // Lookahead coupling: if next item fits the post residual, reward heavily.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 30.0 - 0.3 * slack;
    } else if next_item_size > pr {
        // Next item won't fit here; penalize proportionally to wasted opportunity.
        score += 5.0 + 0.1 * ((next_item_size - pr) as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // New bin baseline: penalize so it's chosen only when fits are bad elsewhere.
        score = cap * 0.85 + 0.2 * (open_bins_count as f64);
        // Late in stream, prefer consolidation into open bins.
        score += 15.0 * progress;
        // If a big item arrives and nothing fits well, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild pressure to fill bins when many are open.
    score += 0.05 * (open_bins_count as f64).powi(2).min(400.0) * 0.1;

    // Prefer bins whose residual is close to mean (balance) slightly.
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let nx = next_item_size as f64;
    let mut score = pr;

    score += 0.011 * (mean_residual - br).abs();

    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.0;

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
                else { score -= 0.8 * (1.0 - progress); }
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // chaining bonuses (combined from lineage)
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && fitting_bins_count <= 3 {
                score -= 0.45 * (1.0 - (after - 2.0 * nx) / 4.0) * (0.6 + 0.4 * (1.0 - progress));
            }
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 6.0 {
                score -= 0.8 * (1.0 - (after - 3.0 * nx) / 6.0) * (0.5 + 0.5 * progress);
            }
            if after >= 3.0 * nx && nx >= 3.0 && after <= 3.0 * nx + 9.0 && fitting_bins_count <= 4 {
                score -= 0.35 * (1.0 - (after - 3.0 * nx) / 9.0) * (0.5 + 0.5 * progress);
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            if after > 0.0 && after <= 2.0 && nx <= item_size as f64 {
                score -= 0.9 * (2.0 - after) * (0.3 + 0.7 * progress);
            }
            if after > 10.0 && after <= 18.0 && fitting_bins_count <= 3 && nx >= 4.0 {
                score -= 0.55 * (1.0 - (after - 10.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // near-exact refill
            if after >= 0.5 && after < 1.0 && mean_residual < cap * 0.5 {
                score -= 0.9 * (1.0 - after) * (0.5 + 0.5 * progress);
            }
            // penalize wide leftover bands late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5);
            }
            // reward residual that can host a 2-chain exactly
            if nx >= 2.0 && after >= 2.0 * nx && after <= 2.0 * nx + 2.0 && progress > 0.4 {
                score -= 0.5 * (1.0 - (after - 2.0 * nx) / 2.0) * progress;
            }
            // penalize stranding a residual just below nx when other bins can host nx
            if fitting_bins_count >= 2 && after > 0.0 && after < 1.0 {
                score += 0.3 * (1.0 - after) * (1.0 - progress);
            }
            if after > 30.0 && after < 60.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
        } else {
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 0.6 * (1.0 - progress);
            }
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress);
            }
            // when no bin can take nx, favor the largest-residual bin as future host
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br.max(1.0) / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
            }
            if fitting_bins_count == 0 && br < mean_residual * 0.85 && br > 0.0 {
                score -= 0.3 * (1.0 - br / mean_residual.max(1.0)) * (1.0 - progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
        score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25;
    }
    if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
        score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
    }
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
        }
        if open_bins_count > 0 && nx > 0.0 && waste * cap >= nx {
            let after2 = waste * cap - nx;
            if after2 < 6.0 { score -= 1.2 * (1.0 - after2 / 6.0) * (0.4 + 0.6 * progress); }
            if after2 >= 2.0 && after2 <= 7.0 && open_bins_count >= 2 {
                score -= 0.7 * (1.0 - (after2 - 2.0) / 5.0) * (0.5 + 0.5 * (1.0 - progress));
            }
            if after2 >= nx && nx >= 3.0 && after2 < 2.0 * nx {
                score -= 0.5 * (1.0 - (after2 - nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress);
            }
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress);
            }
            // triple-chain bonus in tight residual economy
            if after2 >= 3.0 * nx && nx >= 3.0 && after2 < 3.0 * nx + 5.0 && mean_residual < cap * 0.3 {
                score -= 0.5 * (1.0 - (after2 - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // discourage new bins when any open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65;
        }
        // discourage new bins near stream end when open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= item_size as f64 {
            score += 1.0 * (progress - 0.8) / 0.2;
        }
        // discourage new bins early when an open bin fits nx exactly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress < 0.3 && waste > 0.5 && mean_residual >= nx {
            score += 0.5 * (0.3 - progress) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (post_residual near zero handled by base term already).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: bonus if the next item fits the post-residual gap exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.5;

    score
}

