pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: small post_residual strongly preferred
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 180.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 - (slack_after_next as f64) * 0.8;
        } else {
            // next item won't fit here; penalize residual that is too small to be useful
            let uselessness = (next_item_size - post_residual) as f64;
            score += uselessness * 0.3;
        }
    }

    // Relative to mean residual: prefer bins whose residual is already tight
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: penalize unless current bins are bad fits
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 120.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = -50.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            new_bin_penalty = 30.0;
        }
        // late in stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty -= progress * 20.0;
        score += new_bin_penalty;
    }

    // Slight preference for denser bin sets (consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

