        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: subtract for small post-residual (good packing).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Exact or near-exact fits are extremely valuable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Penalize dead space that no future item (min size 1) can use well:
    // small residuals in (0, 10] are fine, but residuals just above common
    // sizes are risky. Penalize post_residual that is slightly larger than
    // next_item_size (tempting but wasteful).
    if next_item_size > 0 && post_residual >= next_item_size {
        // If this bin could also take the next item, reward it (chain fit).
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space for the lookahead item.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    score -= 8.0 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // Early in the stream, opening bins is cheaper (build inventory).
        score -= 40.0 * (1.0 - progress);
        // If nothing fits well elsewhere (this call is one of few fitting bins),
        // opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Prefer bins with smaller residual for large items (best-fit bias).
        score += 0.1 * bin_residual as f64 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late in the stream, demand tight packing.
    let tightness_weight = 0.5 + 2.5 * progress * progress;
    score += tightness_weight * norm_pr * norm_pr * cap * 0.1;

    // Dead-space penalty: post_residual too small for the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 3.0 * waste * (1.0 + progress);
    }

    // Reward bins whose residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: this is the only fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below-average residual (tight bins).
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
