pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let band = post_residual / eighth; // 0..8 harmonic class

    // Reward tight fits strongly (post residual in lowest bands)
    match band {
        0 => score -= 40.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 4.0,
        _ => {}
    }

    // Penalize dead space in high bands proportionally (quadratic waste)
    if band >= 5 {
        score += (band as f64 - 4.0) * 9.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // reward proportionally to how well next item fills remainder
            score -= 18.0 * (1.0 - slack as f64 / cap_f);
            // harmonic class match on next item
            if (next_item_size / eighth) == band && post_residual >= next_item_size {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize large leftovers
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Modulo arithmetic on post_residual vs common item sizes: exact divisor fit bonus
    if post_residual > 0 {
        for m in [10u32, 20, 25, 50].iter() {
            if post_residual % *m == 0 {
                score -= 5.0;
                break;
            }
        }
    }

    // Prefer bins with below-mean residual (consolidate small leftovers)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Early in stream: be more conservative, favor new bins less; late: pack aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above good fits
        score = cap_f * (1.0 - 0.3 * progress) + 15.0;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open new bin
        }
    } else if progress > 0.8 {
        // endgame: minimize bin count, tolerate loose fits
        score -= 10.0;
    }

    // Discourage opening new bins when many bins already open and item fits well
    if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual as f64 > 0.35 * cap_f {
        score += 20.0;
    }

    score
}

