pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: post residual, normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with progress
    let p_norm = post / cap;
    score += p_norm * p_norm * (0.5 + 0.5 * progress);
    score -= p_norm.powi(3) * (1.0 - progress) * 0.5;

    // Reward tight fits more as stream progresses
    let tightness = 1.0 - p_norm;
    score -= tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - post) / cap;
        score += waste * waste * 2.0 * (0.4 + 0.6 * progress);
    }

    // Reward leaving exactly enough room for next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 0.4 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin bonus: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 0.6;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 0.35 + 0.25 * progress;
    }

    // Many open bins: prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 0.02 * tightness;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    let dev = (mean_residual - post) / cap;
    score += 0.15 * dev * dev - 0.1 * dev;

    score
}

