pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: penalize dead space in awkward residue classes
    let pr = post_residual;
    if pr > 0 {
        let m10 = (pr % 10) as f64;
        score += 8.0 * (m10 / 10.0) * (m10 / 10.0); // residuals near multiples of 10 are more reusable
        let m25 = (pr % 25) as f64;
        score += 6.0 * (m25 / 25.0).abs();
    } else {
        score -= 40.0; // perfect closure bonus
    }

    // Small post_residual that next item can't use = dead space
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 15.0; // lookahead fits here
            let slack = (pr - next_item_size) as f64;
            score += 0.2 * slack;
        } else {
            score += 12.0 + 0.3 * pr as f64; // next item won't fit after this placement
        }
        // Harmonic divisibility: if post_residual divides/aligns with next item class
        if pr > 0 && next_item_size % pr == 0 {
            score -= 20.0;
        }
    } else {
        score -= 10.0; // last item: just close tightly
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Bias: opening a new bin is only attractive if existing bins fit poorly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 + 30.0 * (1.0 - fit_ratio) - 25.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing potential in fresh bin
        }
    }

    // Prefer bins already below mean residual (consolidate emptier bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight penalty per extra open bin to encourage consolidation
    score += 0.5 * open_bins_count as f64;

    // Integer-division threshold: post_residual in (0,10] is nearly unusable
    if pr > 0 && pr / 10 == 0 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let min_useful = if next_item_size > 0 { next_item_size.min(item_size) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        score += (min_useful - post_residual) as f64 * 4.0;
        // Extremely tiny slivers are pure dead space: heavy penalty.
        if post_residual < 5 {
            score += 25.0;
        }
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 10.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // blocks the next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0).max(0.0) * 0.3 * (1.0 - progress);

    // New-bin candidate: keep it neutral-ish but penalize slightly when open bins fit well.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
        // But if current bin would leave bad dead space, new bin becomes attractive.
        if post_residual > 0 && post_residual < min_useful {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable leftovers (dead space)
    let pr = post_residual as f64;
    let small_leftover_threshold = 15.0;
    if pr > 0.0 && pr < small_leftover_threshold {
        score += (small_leftover_threshold - pr) * 3.0;
    }

    // 2-step lookahead: reward when next item exactly fills the leftover
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        if pr >= ni {
            // next item fits: reward tight coupling
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
            if diff < 5.0 {
                score -= 8.0; // near-perfect chain
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += 6.0 * (ni - pr) / ni;
        }
    }

    // Compare against mean residual: prefer filling bins tighter than average
    score -= (mean_residual - pr) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless leftovers
    // of open bins are all hopeless
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 {
            (next_item_size as f64 / 100.0) * 5.0
        } else {
            0.0
        };
        score += 30.0 + desperation + open_bins_count as f64 * 2.0;
    }

    // Early in the stream, be slightly more willing to keep bins tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

