    // keep pool balanced
    score += 0.011 * (mean_residual - br).abs();

    // small-residual quality tiers
    if pr == 0.0 {
        score -= 26.0;
    } else if pr <= 2.0 {
        score -= 13.0;
    } else if pr <= 5.0 {
        score -= 8.0;
    } else if pr <= 9.0 {
        score -= 3.5;
    }

    // GEN185: fine-grained residual fitting — continuous tightness reward replaces coarse tiers
    if pr > 0.0 {
        score -= 4.5 * (1.0 - pr / 12.0).max(0.0) * (0.5 + 0.5 * progress);
    }

    // mid-item capacity lookahead (fine-grained: reward leftover that can host small future items)
    let fits_mid = post_residual / 20;
    score -= fits_mid as f64 * 4.0;
    let fits_small = post_residual / 6;
    if fits_small > fits_mid {
        score -= (fits_small - fits_mid) as f64 * 1.2 * (0.4 + 0.6 * progress);
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 14.0 * (1.0 - gap).max(0.0);
            let after = pr - nx;
            if after == 0.0 {
                score -= 4.0;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress); }
                if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress); }
            } else if after <= 12.0 {
                score -= 6.0 * (1.0 - after / 12.0) * (0.5 + 0.5 * progress);
            } else if after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0);
            }
            // reward tight after-spaces in the 1..=12 band more aggressively
            if after >= 1.0 && after <= 4.0 {
                score -= 1.2 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0);
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress);
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress);
            }
            if after >= 6.0 && after <= 14.0 && fitting_bins_count >= 3 {
                score -= 0.7 * (1.0 - (after - 6.0) / 8.0);
            }
            // chaining: leave room for next item twice
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // exact-match bonus
            if (pr - nx).abs() < 0.5 { score -= 5.0; }
            // chainable after-space: can host next item AND leave a small residual
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress);
            }
            // awkward leftover: barely larger than next item
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress);
            }
            // tiny after-space is excellent
            if after > 0.0 && after < 3.0 {
                score -= 1.8 * (3.0 - after) / 3.0 * (0.4 + 0.6 * progress);
            }
            // reward exact 2-chain and 3-chain refills with tight margins
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 && nx > 0.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress);
            }
            if nx >= 3.0 && after >= 3.0 * nx && after <= 3.0 * nx + 6.0 {
                score -= 0.8 * (1.0 - (after - 3.0 * nx) / 6.0) * (0.5 + 0.5 * progress);
            }
            // GEN185: reward near-exact refill (after within 1 of nx) as a strong chain signal
            if nx >= 2.0 && after >= nx && after <= nx + 1.0 {
                score -= 0.9 * (1.0 - (after - nx)) * (0.5 + 0.5 * progress);
            }
            // penalize wide leftover bands late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5);
            }
            // penalize leftover that is too big relative to need when bins are plentiful
            if after > 30.0 && after < 60.0 && nx < after - 5.0 {
                score += 0.5 * (after - 30.0) / 30.0 * (1.0 - progress);
            }
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.4 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress));
            }
        } else {
            // next item won't fit here
            score += (nx - pr) * (1.0 + 0.9 * (1.0 - progress));
            if fitting_bins_count >= 2 && mean_residual >= nx {
                score -= 0.6 * (1.0 - progress);
            }
            // late stream, no bin fits nx — favor the largest-residual bin as future host
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br.max(1.0) / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
            }
            if fitting_bins_count == 0 && br < mean_residual * 0.85 && br > 0.0 {
                score -= 0.3 * (1.0 - br / mean_residual.max(1.0)) * (1.0 - progress);
            }
            // GEN185: when nx cannot fit here, penalize proportionally to how stranded the residual is
            if fitting_bins_count >= 2 && pr > 0.0 && pr < nx * 0.5 {
                score += 0.5 * (1.0 - pr / (nx * 0.5)) * (0.5 + 0.5 * progress);
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap);
    }

    // dead-space below min item size is wasted when next item can't use it
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress);
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap));
    }

    // last-chance bin
    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.0 * (1.0 - progress);
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // dead-ratio (fragmentation of this bin) analysis
    let dead = pr / br.max(1.0);
    if dead > 0.75 && pr > 15.0 { score += 1.2 * (dead - 0.75); }
    if dead > 0.6 && pr > 10.0 { score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)); }
    if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 { score += 1.5 * (dead - 0.9) * (0.5 + progress); }
    if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
        score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress));
    }
    if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
        score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0));
    }
    if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
        score += 0.8 * (dead - 0.55) * (1.0 - progress);
    }
    // mid-range dead space with large residual: penalize
    if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
        score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress);
    }
    // reward low dead-space bins that still leave usable space for nx
    if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
        score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
    }
    // penalize high dead-space bins with stranded residuals harder when many bins compete
    if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
        score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25;
    }
    // pool-balance bonus
    if pr > 4.0 && (pr - mean_residual).abs() < 3.0 && fitting_bins_count >= 2 {
        score -= 0.6 * (1.0 - (pr - mean_residual).abs() / 3.0) * (0.5 + 0.5 * progress);
    }
    // near-exact next-item fit into residual
    if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
        score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap));
    }
    // penalize bins that strand a residual just below nx when other bins could host nx
    if dead > 0.35 && nx > 0.0 && pr >= nx && pr - nx < 1.0 && pr - nx > 0.0 && fitting_bins_count >= 2 {
        score += 0.3 * (1.0 - (pr - nx)) * (1.0 - progress);
    }
    // GEN185: lookahead trade-off — bins whose residual matches nx exactly (pr==nx) are prime hosts
    if nx > 0.0 && pr >= nx && pr - nx <= 2.0 && br > 0.2 * cap {
        score -= 1.1 * (1.0 - (pr - nx) / 2.0) * (0.6 + 0.4 * progress);
    }
    // tight-bin preference
    score += bin_residual as f64 * 0.05;

    // NEW-BIN CANDIDATE logic
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        if nx > 0.0 && nx <= cap && (cap - item_size as f64) >= nx {
            score -= 3.0 * (1.0 - progress);
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35);
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 { score += 2.0; }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5);
        }
        if nx > 0.0 && nx <= waste * cap {
            score += 0.8 * (1.0 - (waste * cap - nx) / cap);
        }
        if open_bins_count > 0 && mean_residual > cap * 0.45 && waste > 0.3 {
            score += 1.2 * (waste - 0.3) * (0.5 + progress);
        }
        if waste > 0.6 && open_bins_count >= 3 {
            score += 1.0 * (waste - 0.6) * (1.0 + progress);
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress);
        }
        if open_bins_count > 0 && nx > 0.0 && waste > 0.55 && nx > waste * cap {
            score += 1.4 * (1.0 - progress);
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress);
        }
        if open_bins_count >= 1 && fitting_bins_count >= 1 && waste > 0.6 && (cap - item_size as f64) < nx {
            score += 0.6 * (waste - 0.6) * (1.0 + progress);
        }
        // leftover after placing next item in new bin
        if open_bins_count > 0 && nx > 0.0 && waste > 0.0 && (cap - item_size as f64) >= nx {
            let after_new = cap - item_size as f64 - nx;
            if after_new > 0.0 && after_new < nx && nx - after_new <= 4.0 {
                score += 1.0 * (1.0 - (nx - after_new) / 4.0) * (0.5 + 0.5 * progress);
            }
            // double-lookahead: reward opening when leftover after next item is tiny
            if after_new > 0.0 && after_new < 6.0 {
                score -= 1.2 * (1.0 - after_new / 6.0) * (0.4 + 0.6 * progress);
            }
            // reward multi-chain capacity in the new bin
            if after_new >= nx && nx >= 3.0 && after_new < 2.0 * nx {
                score -= 0.5 * (1.0 - (after_new - nx) / nx.max(1.0)) * (0.5 + 0.5 * progress);
            }
            // GEN185: reward triple-chain capacity in new bins when pool is lean
            if nx >= 3.0 && after_new >= 3.0 * nx && after_new < 3.0 * nx + 5.0 && open_bins_count <= 3 {
                score -= 0.55 * (1.0 - (after_new - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress);
            }
        }
        // penalize new bin whose leftover can't host next item while some open bin can
        if open_bins_count > 0 && nx > 0.0 && (cap - item_size as f64) < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress);
        }
        // reward opening when open bins nearly saturated and waste small
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress);
        }
        // penalize opening when a fitting open bin's residual is almost exactly the item
        if open_bins_count > 0 && fitting_bins_count >= 1 && mean_residual >= item_size as f64
            && (mean_residual - item_size as f64) < 0.05 * cap {
            score += 1.5 * (1.0 - (mean_residual - item_size as f64) / (0.05 * cap));
        }
        // discourage opening a new bin mid/late stream when any open bin can host nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65;
        }
        // discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= item_size as f64 {
            score += 1.0 * (progress - 0.8) / 0.2;
        }
        // GEN185: discourage opening when any open bin's residual exceeds item by a tiny margin
        if open_bins_count > 0 && mean_residual >= item_size as f64
            && (mean_residual - item_size as f64) < 8.0 && waste > 0.4 {
            score += 1.0 * (1.0 - (mean_residual - item_size as f64) / 8.0) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize post_residual that cannot fit the next item (dead space),
    // reward post_residual that exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 25.0; // leaves a perfect slot for next item
            } else {
                score -= 5.0; // still usable
            }
        } else {
            // dead space relative to lookahead
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with decent fits win; scale with stream progress
        // (later in the stream, consolidating matters more).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * progress;
        // If many open bins are nearly full, a new bin is more attractive.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
    }

    // Penalize bins whose residual is far above mean (fragmentation outliers)
    // unless the fit is very tight.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 && post_residual > 0 {
        score += 0.05 * dev;
    }

    // Slight preference for fuller bins early in the stream (keep small-residual
    // bins available for small future items).
    score += 0.02 * (bin_residual as f64) * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx + 6.0 && nx >= 3.0 {
                score -= 0.9 * (1.0 - ((after - 2.0 * nx) / (nx + 6.0)) . min (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && (after - nx) . abs () < 0.5 {
                score -= 2.2 * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.5 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
            // GEN186: reward after==nx exactly (perfect refill chain) with stronger bonus
            if after >= 0.5 && (after - nx) . abs () < 0.5 && mean_residual < cap * 0.5 {
                score -= 0.8 * (0.5 + 0.5 * progress) ;
            }
            // GEN186: penalize wide leftover bands (after >> nx) late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
            // GEN186: when no bin can host nx, mildly favor the largest-residual bin as future host
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br . max (1.0) / (mean_residual . max (1.0) * 2.0)) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.8 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress) ;
            }
            // GEN186: triple-chain bonus for new bins when residual economy is tight
            if after2 >= 3.0 * nx && nx >= 3.0 && after2 < 3.0 * nx + 5.0 && mean_residual < cap * 0.3 {
                score -= 0.5 * (1.0 - (after2 - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.7 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
        // GEN186: discourage opening new bins when any open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN186: near end of stream, prefer open bins when they still suffice
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        let dead = pr / br . max (1.0) ;
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN186: penalize high dead-space bins with large stranded residuals when many bins compete
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25 ;
        }
        // GEN186: reward low dead-space bins that still leave usable space for nx
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
        // GEN186: penalize bins stranding a residual just below nx when other bins could host nx
        if dead > 0.35 && nx > 0.0 && pr >= nx && pr - nx > 0.0 && pr - nx < 1.0 && fitting_bins_count >= 2 {
            score += 0.3 * (1.0 - (pr - nx)) * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, non-linearly coupled with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Polynomial coupling: penalize large residuals more as stream advances
    score += cap * (norm_pr * norm_pr) * (0.5 + 1.5 * progress * progress);

    // Reward tight fits (small post_residual) with smooth discount
    score -= cap * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item * 2.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward residual that fits the next item smoothly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let fits = if pr >= next { 1.0 } else { 0.0 };
        score -= 5.0 * fits * (next / cap) * (1.0 - 0.5 * progress);
    }

    // Mean residual deviation penalty (smooth)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: penalize opening new bins mildly, less as stream progresses
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 0.5 * progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // triple-chain lookahead
            if after >= 2.0 * nx && after <= 3.0 * nx + 6.0 && nx >= 3.0 {
                score -= 0.9 * (1.0 - ((after - 2.0 * nx) / (nx + 6.0)) . min (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // exact-chain reward (after == nx again)
            if after >= 1.0 && (after - nx) . abs () < 0.5 {
                score -= 2.2 * (0.5 + 0.5 * progress) ;
            }
            // GEN186: strengthen perfect refill chain when residual economy is tight
            if (after - nx) . abs () < 0.5 && mean_residual < cap * 0.3 {
                score -= 0.8 * (0.5 + 0.5 * progress) ;
            }
            // GEN186: penalize wide leftover bands late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5) ;
            }
            // GEN186: reward exact 2-chain late in stream
            if nx >= 2.0 && after >= 2.0 * nx && after <= 2.0 * nx + 2.0 && progress > 0.4 {
                score -= 0.5 * (1.0 - (after - 2.0 * nx) / 2.0) * progress ;
            }
            // penalize sliver just under nx when other bins could host nx
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.5 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
            // GEN186: when no bin can host nx, mildly favor the bin with the largest residual
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br . max (1.0) / (mean_residual . max (1.0) * 2.0)) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.3 && waste < 0.45 && nx > 0.0 && nx > pr {
            score += 0.7 * (0.45 - waste) * (1.0 + 0.5 * progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // prefer fresh bins whose leftover after nx can chain nx once more (exact 2x fill)
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.8 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress) ;
            }
            // GEN186: triple-chain bonus for new bins when residual economy is tight
            if after2 >= 3.0 * nx && nx >= 3.0 && after2 < 3.0 * nx + 5.0 && mean_residual < cap * 0.3 {
                score -= 0.5 * (1.0 - (after2 - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        // discourage opening a new bin late when an open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.7 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
        // GEN186: strongly discourage opening a new bin mid/late stream when any open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN186: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // reward low-dead bins whose post-space exactly matches nx plus tiny margin
        let dead = pr / br . max (1.0) ;
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // penalize mid-dead bins leaving a wide unusable band just above nx
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN186: reward low dead-space bins that still leave usable space for nx
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
        // GEN186: penalize high dead-space bins with large stranded residuals when many bins compete
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25 ;
        }
        // GEN186: reward harmonic 3x-chain matches at mid-dead ratios
        if dead > 0.2 && dead <= 0.45 && nx >= 4.0 && pr >= 3.0 * nx && pr - 3.0 * nx <= 4.0 && fitting_bins_count <= 3 {
            score -= 0.45 * (1.0 - (pr - 3.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN186: penalize bins that will strand a residual just below nx when others could host nx
        if dead > 0.35 && nx > 0.0 && pr >= nx && pr - nx > 0.0 && pr - nx < 1.0 && fitting_bins_count >= 2 {
            score += 0.3 * (1.0 - (pr - nx)) * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small denominators) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = post / cap;

    // Harmonic classes: post_residual divisible by 10, 20, 25, 50 are
    // "clean" leftovers that future items likely recombine into.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 20 == 0 { harmony_bonus += 4.0; }
        if pr % 25 == 0 { harmony_bonus += 5.0; }
        if pr % 50 == 0 { harmony_bonus += 8.0; }
        if pr % 100 == 0 { harmony_bonus += 10.0; }
    }
    score -= harmony_bonus;

    // Penalize dead space: leftover too small for the smallest plausible item.
    if post > 0 && post < 10 {
        score += 40.0;
    } else if post > 0 && post < 20 {
        score += 12.0;
    }

    // Integer-division threshold coupling: leftover must comfortably host the
    // lookahead item; reward exact or near-exact pairings.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 30.0; // perfect harmonic pair with lookahead
            } else if slack <= 10 {
                score -= 12.0;
            } else {
                score += slack as f64 * 0.05;
            }
        } else {
            // Lookahead won't fit here: penalize proportionally to wasted class.
            score += 8.0 + (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Perfect fit reward.
    if post == 0 {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current bin fits are tight
    // (few fitting bins) or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        if fitting_bins_count > 0 && pressure < 0.35 {
            score -= 10.0; // open bins are crowded; fresh bin is fine
        } else {
            score += 30.0; // prefer existing bins otherwise
        }
        // Late in the stream, avoid spawning bins for marginal gain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 15.0 * progress;
        }
    }

    // Mild preference for tighter existing bins relative to mean residual.
    score += (post - mean_residual).max(-20.0).min(20.0) * 0.1;

    // Small tie-break toward fuller bins.
    score -= (bin_residual - post_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are heavily penalized since nothing may ever fill them.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize moderate dead space relative to mean residual: a gap that is
    // much smaller than typical residuals is likely wasted.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio < 0.25 && post_residual > 0 {
            score += 25.0 * (1.0 - ratio);
        }
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins, especially early/late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // New-bin candidate: make opening a new bin costly unless the current bin
    // would leave a large unusable gap or the fit is tight.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow new bin when item is large relative to capacity and no bin
        // fits well (handled implicitly by other bins' scores being high).
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 55.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit with the NEXT item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // exact chain: next item fills this bin perfectly
        } else if post_residual >= next_item_size {
            // next item fits here; reward tight chains, penalize loose ones
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize proportionally to waste
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Penalize large dead space relative to the smallest possible item (1..100 range).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 10.0; // tiny unusable slivers are fine — bin is effectively full
    } else if dead >= 10.0 && dead < 20.0 {
        score += 5.0; // awkward medium gap
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Compare against the mean residual: prefer bins already below-average residual
    // (denser bins) to consolidate space, keep loose bins for future large items.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // New-bin candidate handling: opening a bin is only attractive when the item
    // leaves a large residual in every existing bin or no bin fits well.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // Base cost of opening a new bin.
        let mut new_bin_score = 45.0;
        // If item is large relative to capacity, a fresh bin is a good idea.
        new_bin_score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            new_bin_score += 12.0 * (fitting_bins_count as f64).sqrt();
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 15.0 * progress;
        // If next item is huge and nothing fits it well, new bin helps.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score.max(score - 40.0)) + new_bin_score * 0.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Penalize waste relative to what was available.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Lookahead: if the next item fits exactly in the post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit: mild reward, scaled by how well it fills.
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward gaps.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 3.0 * (1.0 - gap / next_item_size as f64);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_score = bin_capacity as f64 * 0.35 + open_bins_count as f64;
        // Early in stream, opening bins is cheaper (build inventory of residual options).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 20.0 * progress;
        // If mean residual of open bins is small (all tight), a new bin is attractive.
        new_bin_score -= 0.5 * mean_residual;
        // If few bins fit the item, opening fresh capacity is reasonable.
        if fitting_bins_count == 0 {
            new_bin_score -= 25.0;
        }
        // Reserve a new bin when it can host item + next item together.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    // Slight preference to spread load across many bins early, consolidate later.
    score += 0.3 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly discounted early (keep bins open)
    let mut score = pr * (1.0 - 0.35 * (1.0 - progress));

    // Non-linear coupling: quadratic penalty on normalized dead space, weighted by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with cubic bonus
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: bonus if next item fits into resulting residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 5.0 * (1.0 - (next_item_size as f64) / cap);
        } else {
            score += 3.0 * ((next_item_size as f64) - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins)
    score += 2.0 * (mean_residual - pr) / cap;

    // Penalize fragmenting when many bins already open
    score += 0.4 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Dead-space class: residuals that can never absorb the smallest item.
        if post_residual < 10 {
            score += 400.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 120.0; // marginal class
        } else if post_residual <= 40 {
            score += 30.0;
        } else if post_residual <= 70 {
            score -= 40.0; // reusable class
        } else {
            score -= 80.0; // half-bin or better remains
        }

        // Modulo-10 harmonic band: residuals near multiples of 10 align with item grid.
        let m = post_residual % 10;
        if m == 0 {
            score -= 25.0;
        } else if m >= 7 {
            score += 10.0; // awkward sliver above a grid point
        }

        // Lookahead coupling: can next item fill the post_residual?
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0; // chain exact fit
            } else if next_item_size <= post_residual {
                let waste = post_residual - next_item_size;
                score -= 60.0 * (1.0 - waste as f64 / cap);
                // integer-division threshold: how many more items could still fit after next
                let depth = post_residual / next_item_size.max(1);
                score -= 15.0 * depth as f64;
            } else {
                // next item can't use this residual: penalize by overshoot class
                score += 20.0 + 0.5 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current fit is poor and many open bins.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / cap;
        score = 90.0 - 40.0 * fit_quality;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
        if open_bins_count > 3 && mean_residual < item_size as f64 {
            score -= 60.0; // all open bins are tight anyway
        }
        // late in stream, avoid bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference to fill fuller bins (smaller residual) first.
    score -= 0.3 * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving a gap that could fit the next item poorly (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += pressure * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins are crowded.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.3 + open_bins_count as f64 * 2.0;
        if post_residual < item_size {
            score += 20.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (fill the emptiest-fitting first is wrong;
    // instead favor bins already below mean residual to consolidate space).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late-stream tightening: as stream progresses, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

