        }
        // GEN171: low-dead bins whose residual after nx still chains nx once more
        if dead <= 0.3 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 4.0 && fitting_bins_count >= 2 {
            score -= 0.7 * (1.0 - (pr - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN171: penalize high-dead bins when a roomier open bin could host nx with a tight fit
        if dead > 0.7 && nx > 0.0 && pr >= nx && open_bins_count >= 2 && mean_residual >= nx && (mean_residual - nx) < (pr - nx) {
            score += 0.8 * (dead - 0.7) * (0.4 + 0.6 * progress) ;
        }
        // GEN188: reward mid-dead bins that leave a residual exactly equal to nx after this item
        if dead > 0.3 && dead <= 0.6 && nx >= 3.0 && pr >= nx && (pr - nx) . abs () < 1.0 && mean_residual < cap * 0.4 {
            score -= 0.6 * (0.5 + 0.5 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN171: reward new-bin leftovers that can chain nx twice exactly
            if after2 >= 2.0 * nx && after2 <= 2.0 * nx + 2.0 && nx >= 3.0 {
                score -= 1.0 * (1.0 - (after2 - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // GEN171: gate new bins harder mid-stream when waste is large and mean residual still hosts nx
        if progress > 0.4 && progress <= 0.85 && waste > 0.5 && open_bins_count > 0 && mean_residual >= nx {
            score += 1.0 * (waste - 0.5) * (0.6 + 0.4 * progress) ;
        }
        // GEN171: allow new bins whose leftover after nx still hosts nx again (perfect 2-fill)
        if open_bins_count > 0 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 2.0 {
            score -= 1.2 * (1.0 - (pr - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN188: gate new bins harder late-stream when an open bin can host nx with a tight fit
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * ((progress - 0.35) / 0.65) ;
        }
        // GEN188: strongly discourage new bins near the end when open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * ((progress - 0.8) / 0.2) ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            // GEN156: strengthen triple-chain lookahead — residual that can host nx twice more
            if after >= 2.0 * nx && after <= 3.0 * nx + 6.0 && nx >= 3.0 {
                score -= 0.9 * (1.0 - ((after - 2.0 * nx) / (nx + 6.0)) . min (1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN156: reward after exactly matching nx again (perfect chain)
            if after >= 1.0 && (after - nx) . abs () < 0.5 {
                score -= 2.2 * (0.5 + 0.5 * progress) ;
            }
            // GEN156: penalize sliver just under nx when other bins could host nx
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.5 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
            // GEN189: penalize wide leftover bands late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5) ;
            }
            // GEN189: reward 2-chain exact refill late
            if nx >= 2.0 && after >= 2.0 * nx && after <= 2.0 * nx + 2.0 && progress > 0.4 {
                score -= 0.5 * (1.0 - (after - 2.0 * nx) / 2.0) * progress ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            // GEN156: soften mismatch penalty when many bins compete and mean residual is large
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
            // GEN189: when no bin can host nx, mildly favor the largest-residual bin as future host
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br . max (1.0) / (mean_residual . max (1.0) * 2.0)) * (0.5 + 0.5 * progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        // GEN189: penalize high dead-space bins with stranded residuals when many bins compete
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25 ;
        }
        // GEN189: reward low dead-space bins that still leave usable space for nx
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
        // GEN189: penalize stranded residual just below nx after this item
        if dead > 0.35 && nx > 0.0 && pr >= nx && pr - nx > 0.0 && pr - nx < 1.0 && fitting_bins_count >= 2 {
            score += 0.3 * (1.0 - (pr - nx)) * (1.0 - progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        // two-step lookahead on fresh bin
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN156: prefer fresh bins whose leftover after nx can chain nx once more (exact 2x fill)
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.8 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress) ;
            }
            // GEN189: triple-chain bonus for new bins when residual economy is tight
            if after2 >= 3.0 * nx && nx >= 3.0 && after2 < 3.0 * nx + 5.0 && mean_residual < cap * 0.3 {
                score -= 0.5 * (1.0 - (after2 - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        // GEN156: discourage opening a new bin late when an open bin already fits nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.7 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
        // GEN189: strongly discourage new bins mid/late stream when an open bin can host nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN189: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        // GEN156: reward low-dead bins whose post-space exactly matches nx plus tiny margin
        let dead = pr / br . max (1.0) ;
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        // GEN156: penalize mid-dead bins leaving a wide unusable band just above nx
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN189: reward harmonic 3x-chain fits at mid-dead ratios
        if dead > 0.2 && dead <= 0.45 && nx >= 4.0 && pr >= 3.0 * nx && pr - 3.0 * nx <= 4.0 && fitting_bins_count <= 3 {
            score -= 0.45 * (1.0 - (pr - 3.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN189: reward tight nx refills when the bin is already mostly full
        if pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with slight nonlinearity.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining: post_residual consumed by next item
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 18.0 - (slack_after_next as f64) * 0.25;
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.30;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= 0.6 * open_bins_count as f64;
    }

    // Early in stream: slight preference to fill bins rather than open new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 4.0;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Only attractive when the item is large and no good existing fit exists,
        // or when the current item would leave a large awkward residue elsewhere.
        score += 20.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    // Penalize very small leftover fragments (dead space) superlinearly.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tightness reward: smooth polynomial in fill fraction (1 - pr/cap)
    let fill = 1.0 - pr / cap;
    score -= 18.0 * fill.powi(3) + 10.0 * fill.powi(2);

    // Penalize small dead space that nothing can use (non-linear coupling with item size)
    let dead = if pr > 0.0 && pr < item_size as f64 { 1.0 } else { 0.0 };
    score += 14.0 * dead * pr / cap;

    // Lookahead: reward residuals that can still host the next item (smooth falloff)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let fit_quality = 1.0 - (gap / cap).powi(2);
            score -= 8.0 * fit_quality;
        } else {
            score += 4.0 * (1.0 - (gap.abs() / cap).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // Stream progress coupling: late in the stream, consolidate into few bins
    score += 6.0 * progress * (pr / cap);
    score -= 3.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to the mean (balanced packing), smooth term
    score += 2.0 * ((pr - mean_residual) / cap).powi(2);

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let waste_if_open = cap - item_size as f64;
        score = cap + waste_if_open - 12.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= cap; // no alternative, allow new bin
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0 as usize) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
                score += 0.9 * (1.0 - (nx - after) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= nx && nx > 0.0 && (after - nx) >= 1.0 && (after - nx) <= 6.0 && fitting_bins_count >= 2 {
                score -= 0.6 * (1.0 - (after - nx) / 6.0) * (0.4 + 0.6 * progress) ;
            }
            if after == 0.0 && fitting_bins_count <= 3 {
                score -= 1.2 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && nx >= 2.0 && fitting_bins_count >= 2 {
                score -= 0.5 * (1.0 - progress) ;
            }
            if after > nx && after - nx <= 3.0 && fitting_bins_count <= 2 {
                score += 0.8 * (1.0 - (after - nx) / 3.0) ;
            }
            if after > 0.0 && after <= 0.5 * cap && (after / 2.0 - nx) . abs () <= 1.0 && nx >= 2.0 {
                score -= 0.6 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 4.0 && progress > 0.6 {
                score -= 0.8 * (1.0 - (after - 2.0 * nx) / 4.0) * progress ;
            }
            if after >= nx + 2.0 && after <= nx + 10.0 && fitting_bins_count >= 2 {
                score -= 0.9 * (1.0 - (after - nx - 2.0) / 8.0) * (0.5 + 0.5 * progress) ;
            }
            if after > nx + 1.0 && after < nx + 4.0 && after > 6.0 {
                score += 0.8 * (1.0 - (after - nx - 1.0) / 3.0) * (0.6 + 0.4 * progress) ;
            }
            // GEN171: reward after-space that exactly hosts nx twice (perfect 2-chain)
            if after >= 2.0 * nx && after <= 2.0 * nx + 2.0 && nx >= 3.0 && fitting_bins_count <= 4 {
                score -= 0.9 * (1.0 - (after - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN171: reward after-space matching nx thrice when residual pool is thin
            if after >= 3.0 * nx && after <= 3.0 * nx + 3.0 && nx >= 3.0 && mean_residual < cap * 0.3 {
                score -= 0.7 * (1.0 - (after - 3.0 * nx) / 3.0) * (0.4 + 0.6 * progress) ;
            }
            // GEN171: penalize wide unusable band above nx when mean residual is small (few future hosts)
            if after > nx + 8.0 && after < nx + 20.0 && mean_residual < cap * 0.2 && fitting_bins_count <= 3 {
                score += 0.6 * ((after - nx - 8.0) / 12.0) * (0.5 + 0.5 * progress) ;
            }
            // GEN189: penalize large stranded leftovers well above nx late in the stream (dead-space growth)
            if after > 30.0 && after < 60.0 && progress > 0.5 && nx < after - 5.0 {
                score += 0.5 * ((after - 30.0) / 30.0) * (progress - 0.5) ;
            }
            // GEN189: reward tight refill chains when mean residual economy is thin
            if after >= nx && after <= nx + 2.0 && fitting_bins_count >= 2 && mean_residual < cap * 0.3 {
                score -= 0.7 * (1.0 - (after - nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if pr > 0.0 && nx - pr <= 4.0 {
                score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if pr > 0.0 && open_bins_count >= 2 && mean_residual >= nx && mean_residual > pr + 3.0 {
                score += 1.0 * (1.0 - (nx - pr) / (nx + 1.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN171: soften mismatch when another bin can host nx exactly
            if fitting_bins_count >= 3 && mean_residual >= nx && (mean_residual - nx) <= 4.0 {
                score -= 0.7 * (1.0 - progress) ;
            }
            // GEN189: when no bin can host nx, mildly favor the roomiest bin as future host
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br / (mean_residual . max (1.0) * 2.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN189: when no bin can host nx, avoid stranding tiny residuals
            if fitting_bins_count == 0 && br < mean_residual * 0.85 && br > 0.0 {
                score -= 0.3 * (1.0 - br / mean_residual . max (1.0)) * (1.0 - progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }
    if pr > 0.0 && pr < 6.0 && nx > 0.0 && nx > pr {
        score += 1.0 * (nx - pr) / (nx + 1.0) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.8 && pr > 15.0 {
            score += 1.2 * (dead - 0.8) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.8 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.45 && dead <= 0.7 && pr > 7.0 && nx > 0.0 && nx <= pr {
            score -= 0.7 * (0.7 - dead) * (1.0 - (pr - nx) / (pr + 1.0)) ;
        }
        if dead > 0.55 && dead < 0.85 && pr > 12.0 && nx > 0.0 && nx > pr {
            score += 0.8 * (dead - 0.55) * (nx - pr) / (nx + 1.0) ;
        }
        if dead > 0.9 && pr > 20.0 && fitting_bins_count >= 3 {
            score += 1.5 * (dead - 0.9) * (0.5 + progress) ;
        }
        if dead > 0.7 && pr > 12.0 && mean_residual < br * 0.6 {
            score += 0.7 * (dead - 0.7) * (1.0 + 0.4 * progress) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if pr > 0.0 && br > 0.5 * cap && pr > 0.6 * br && fitting_bins_count >= 2 {
            score += 1.2 * (pr / br) * (1.0 - progress) ;
        }
        if dead > 0.5 && pr > 8.0 && nx > 0.0 && nx > pr && fitting_bins_count <= 3 {
            score += 0.9 * (dead - 0.5) * (1.0 + 0.6 * (1.0 - progress)) ;
        }
        if dead > 0.4 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.55 && open_bins_count >= 3 && mean_residual > br * 1.3 {
            score += 0.8 * (dead - 0.55) * (1.0 - progress) ;
        }
        if pr > 4.0 && (pr - mean_residual) . abs () < 3.0 && fitting_bins_count >= 2 {
            score -= 0.6 * (1.0 - (pr - mean_residual) . abs () / 3.0) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.6 && nx > 0.0 && pr < nx && open_bins_count >= 2 && mean_residual >= nx {
            score += 1.0 * (dead - 0.6) * (1.0 - progress) ;
        }
        if dead > 0.65 && pr > 10.0 && mean_residual < cap * 0.2 {
            score += 0.6 * (dead - 0.65) * (0.5 + 0.5 * progress) ;
        }
        if pr > 6.0 && (pr - mean_residual) . abs () < 5.0 && fitting_bins_count >= 3 {
            score -= 0.4 * (1.0 - (pr - mean_residual) . abs () / 5.0) * progress ;
        }
        if dead > 0.75 && pr > 10.0 && open_bins_count >= 2 && mean_residual > pr + 5.0 && nx > 0.0 && nx <= mean_residual {
            score += 0.7 * (dead - 0.75) * (0.5 + 0.5 * progress) ;
        }
        if dead > 0.5 && pr > 0.0 && nx > 0.0 && pr >= nx && pr < 2.0 * nx && mean_residual >= 2.0 * nx {
            score += 0.8 * (dead - 0.5) * (0.4 + 0.6 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && pr > 20.0 && br > 0.5 * cap {
            score += 0.7 * (dead - 0.5) * ((pr - 20.0) / 20.0) * (0.5 + 0.5 * progress) ;
        }
        if dead <= 0.35 && pr > 6.0 && mean_residual > br {
            score -= 0.5 * (1.0 - dead / 0.35) * (1.0 - (mean_residual - br) / mean_residual . max (1.0)) * (0.5 + 0.5 * progress) ;
        }
        // GEN171: low-dead bins whose residual after nx still chains nx once more
        if dead <= 0.3 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 4.0 && fitting_bins_count >= 2 {
            score -= 0.7 * (1.0 - (pr - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN171: penalize high-dead bins when a roomier open bin could host nx with a tight fit
        if dead > 0.7 && nx > 0.0 && pr >= nx && open_bins_count >= 2 && mean_residual >= nx && (mean_residual - nx) < (pr - nx) {
            score += 0.8 * (dead - 0.7) * (0.4 + 0.6 * progress) ;
        }
        // GEN189: penalize high dead-space bins with stranded residuals when many bins compete
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25 ;
        }
        // GEN189: reward low dead-space bins that still leave usable space for nx
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > waste * cap {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && waste > 0.4 && waste < 0.6 && nx > 0.0 && nx > waste * cap && fitting_bins_count <= 2 {
            score += 0.9 * (0.6 - waste) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && waste > 0.45 && mean_residual > cap * 0.55 {
            score += 1.0 * (waste - 0.45) * (1.0 + progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if open_bins_count > 0 && nx > 0.0 && pr < nx && mean_residual >= nx {
            score += 1.3 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && mean_residual < cap * 0.15 && waste < 0.25 {
            score -= 1.5 * (1.0 - waste / 0.25) * (0.5 + 0.5 * progress) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && nx >= 2.0 {
                score -= 0.9 * (1.0 - progress) ;
            }
            // GEN171: reward new-bin leftovers that can chain nx twice exactly
            if after2 >= 2.0 * nx && after2 <= 2.0 * nx + 2.0 && nx >= 3.0 {
                score -= 1.0 * (1.0 - (after2 - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.0 && nx > 0.0 && pr < nx {
            score += 1.0 * (1.0 - pr / nx) * (0.6 + 0.4 * (1.0 - progress)) ;
        }
        if nx > 0.0 && pr >= nx && (pr - nx) >= 1.0 && (pr - nx) <= 5.0 {
            score -= 0.8 * (1.0 - (pr - nx) / 5.0) * (0.5 + 0.5 * progress) ;
        }
        if progress > 0.7 && waste > 0.3 && open_bins_count >= 2 && fitting_bins_count >= 1 {
            score += 1.2 * (waste - 0.3) * progress ;
        }
        if progress > 0.8 && waste > 0.2 && open_bins_count >= 3 {
            score += 0.9 * (waste - 0.2) * (1.0 + progress) ;
        }
        if progress > 0.85 && waste > 0.35 && fitting_bins_count >= 1 {
            score += 1.5 * (waste - 0.35) * (1.0 + progress) ;
        }
        // GEN171: gate new bins harder mid-stream when waste is large and mean residual still hosts nx
        if progress > 0.4 && progress <= 0.85 && waste > 0.5 && open_bins_count > 0 && mean_residual >= nx {
            score += 1.0 * (waste - 0.5) * (0.6 + 0.4 * progress) ;
        }
        // GEN171: allow new bins whose leftover after nx still hosts nx again (perfect 2-fill)
        if open_bins_count > 0 && nx >= 3.0 && pr >= 2.0 * nx && pr <= 2.0 * nx + 2.0 {
            score -= 1.2 * (1.0 - (pr - 2.0 * nx) / 2.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN189: strongly discourage new bins mid/late stream when any open bin can host nx
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN189: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr >= nx && nx > 0.0 && (pr - nx) < 0.02 * cap {
            score -= 2.0 * (1.0 - (pr - nx) / (0.02 * cap)) ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if pr > 0.0 && pr <= 1.0 && nx > 0.0 {
            score -= 1.0 * (1.0 - progress) ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;

    // Class 0: residual in [0, quarter) -> dead space; heavy penalty scaled by class depth.
    if post_residual < 10 {
        score -= 12.0; // near-perfect closure
    } else if pr < quarter {
        score += 6.0 * (1.0 - pr / quarter); // unusable sliver penalty
    } else if pr < cap / 2.0 {
        // Class 1: half-bin zone — moderately useful.
        score += 1.5;
    } else if pr < 3.0 * quarter {
        // Class 2: three-quarter zone — good.
        score -= 2.0;
    } else {
        // Class 3: large residual — very good.
        score -= 4.0;
    }

    // Integer-division threshold on residual: multiples of 10 are "harmonious" with
    // the item-size grid, so leftover chunks there are reusable.
    let res10 = post_residual / 10;
    if res10 >= 1 && post_residual % 10 == 0 {
        score -= 3.0;
    }
    // Penalize residuals that are awkward (not representable as a sum of common sizes).
    if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin;
    // reward more when the next item is small (easy to place elsewhere anyway).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tight = (post_residual - next_item_size) as f64;
            score -= 5.0 - 0.05 * tight; // next item chains nicely here
        } else {
            score += 1.0; // next item won't fit here; residual likely stranded
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 15.0 && open_bins_count > 0;
        if crowded {
            score -= 6.0;
        } else {
            score += 10.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - pr / cap);

    // Mild pressure to consolidate across many open bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;

    score += 0.011 * (mean_residual - br) . abs () ;

    // fine-grained tight-fit rewards
    if pr == 0.0 {
        score -= 27.0 ;
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.5 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.0 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
                if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if (pr - nx) . abs () < 0.5 {
                score -= 5.5 ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= nx && after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx + 6.0 && nx >= 3.0 {
                score -= 0.9 * (1.0 - ((after - 2.0 * nx) / (nx + 6.0)) . min (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && (after - nx) . abs () < 0.5 {
                score -= 2.2 * (0.5 + 0.5 * progress) ;
            }
            if after >= 1.0 && after < 3.0 && fitting_bins_count >= 2 && mean_residual >= nx {
                score += 0.5 * (3.0 - after) / 2.0 * (0.5 + 0.5 * (1.0 - progress)) ;
            }
            // GEN190: penalize wide leftover bands (after >> nx) late in the stream
            if after > nx * 2.5 && after > 25.0 && progress > 0.5 {
                score += 0.35 * ((after - 25.0) / 30.0) * (progress - 0.5) ;
            }
            // GEN190: reward exact 2-chain refill near mid/late stream
            if nx >= 2.0 && after >= 2.0 * nx && after <= 2.0 * nx + 2.0 && progress > 0.4 {
                score -= 0.5 * (1.0 - (after - 2.0 * nx) / 2.0) * progress ;
            }
        } else {
            score += (nx - pr) * (0.95 + 0.9 * (1.0 - progress)) ;
            if pr < 3.0 {
                score -= 2.5 ;
            }
            if fitting_bins_count >= 3 && mean_residual > cap * 0.4 {
                score -= 0.5 * (1.0 - progress) ;
            }
            // GEN190: when no bin can host nx, mildly favor the largest-residual bin (future host)
            if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
                score -= 0.45 * (1.0 - br . max (1.0) / (mean_residual . max (1.0) * 2.0)) * (0.5 + 0.5 * progress) ;
            }
            // GEN190: prefer the bin wasting the least overall space when nx can't fit later
            if fitting_bins_count == 0 && br < mean_residual * 0.85 && br > 0.0 {
                score -= 0.3 * (1.0 - br / mean_residual . max (1.0)) * (1.0 - progress) ;
            }
        }
    } else {
        score -= 8.0 * (1.0 - pr / cap) ;
    }

    // dead-space penalties
    if pr > 0.0 && pr < 10.0 && nx > pr {
        score += 2.5 + 1.5 * (1.0 - progress) ;
    }
    if pr > 0.0 && pr < 0.25 * cap && pr > 9.0 {
        score += 1.5 * (1.0 - pr / (0.25 * cap)) ;
    }

    if br > 0.0 && br < cap {
        let dead = pr / br . max (1.0) ;
        if dead > 0.75 && pr > 15.0 {
            score += 1.2 * (dead - 0.75) ;
        }
        if dead > 0.6 && pr > 10.0 {
            score += 0.6 * (dead - 0.6) * (1.0 + 0.5 * (1.0 - progress)) ;
        }
    }

    if fitting_bins_count <= 1 && pr > 0.0 && nx > 0.0 && pr >= nx {
        score -= 4.5 * (1.0 - progress) ;
    } else if fitting_bins_count <= 2 {
        score -= 1.5 ;
    }
    if fitting_bins_count >= 4 && nx > 0.0 && pr > nx {
        score -= 0.5 ;
    }

    let is_new_bin = br == cap && pr == (cap - it) ;
    if is_new_bin {
        let waste = (cap - it) / cap ;
        let poor_fits = fitting_bins_count == 0
            || (nx > 0.0 && pr > nx && pr > 0.45 * cap)
            || (pr > 0.0 && pr < 10.0 && nx > pr) ;
        if poor_fits {
            score -= 12.0 ;
        } else {
            score += 6.0 + 4.5 * (1.0 - progress) ;
        }
        if nx > 0.0 && nx <= cap && pr >= nx {
            score -= 3.0 * (1.0 - progress) ;
        }
        if waste < 0.35 {
            score -= 2.0 * (1.0 - waste / 0.35) ;
        } else {
            score += 1.5 * ((waste - 0.35) / 0.65) ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.5 {
            score += 2.0 ;
        }
        if open_bins_count > 0 && mean_residual > cap * 0.3 && waste > 0.5 {
            score += 2.5 * ((waste - 0.5) / 0.5) ;
        }
        if open_bins_count > 0 && waste > 0.55 && nx > 0.0 && nx > pr {
            score += 1.4 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count <= 2 && waste > 0.5 {
            score += 1.1 * (waste - 0.5) * (1.0 - progress) ;
        }
        if pr > 0.0 && pr < mean_residual * 0.5 {
            score += 1.0 * (1.0 - pr / (mean_residual * 0.5).max(1.0)) ;
        }
        if nx > 0.0 && (pr - nx) . abs () < 0.5 {
            score -= 4.0 ;
        }
        if nx > 0.0 && pr >= nx {
            let after2 = pr - nx ;
            if after2 < 6.0 {
                score -= 1.5 * (1.0 - progress) ;
            }
            if after2 > 0.0 && after2 < nx && nx - after2 <= 4.0 {
                score += 1.0 * (1.0 - (nx - after2) / 4.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 >= 2.0 * nx && after2 < 2.0 * nx + 3.0 && nx >= 2.0 {
                score -= 0.8 * (1.0 - (after2 - 2.0 * nx) / 3.0) * (0.5 + 0.5 * progress) ;
            }
            if after2 > 0.0 && after2 <= 2.0 {
                score -= 1.0 * (2.0 - after2) * (0.5 + 0.5 * progress) ;
            }
            // GEN190: triple-chain bonus for new bins under residual economy pressure
            if after2 >= 3.0 * nx && nx >= 3.0 && after2 < 3.0 * nx + 5.0 && mean_residual < cap * 0.3 {
                score -= 0.5 * (1.0 - (after2 - 3.0 * nx) / 5.0) * (0.5 + 0.5 * progress) ;
            }
        }
        if pr > 0.4 * cap && open_bins_count > 2 {
            score += 3.0 * (pr / cap - 0.4) ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 4.0 && open_bins_count > 3 {
            score -= 2.0 * (1.0 - progress) ;
        }
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.6 && waste > 0.55 {
            score += 0.7 * (waste - 0.55) * (progress - 0.6) / 0.4 ;
        }
        // GEN190: strongly discourage new bins mid/late when any open bin can host nx tightly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress > 0.35 && mean_residual >= nx * 0.8 {
            score += 0.7 * (progress - 0.35) / 0.65 ;
        }
        // GEN190: discourage new bins when the stream is nearly done and open space suffices
        if open_bins_count > 0 && progress > 0.8 && mean_residual >= it {
            score += 1.0 * (progress - 0.8) / 0.2 ;
        }
        // GEN190: discourage opening a new bin early when an open bin fits nx exactly
        if open_bins_count > 0 && fitting_bins_count >= 1 && progress < 0.3 && waste > 0.5 && mean_residual >= nx {
            score += 0.5 * (0.3 - progress) / 0.3 ;
        }
    } else {
        let norm_gap = (pr - mean_residual) . abs () ;
        if pr > 0.0 && norm_gap < 8.0 {
            score -= 0.6 * (1.0 - norm_gap / 8.0) * (1.0 - progress) ;
        }
        if pr > 10.0 && nx > 0.0 && nx > pr * 0.9 && nx <= pr * 1.15 {
            score += 1.0 ;
        }
        if br > 0.5 * cap && pr >= nx && nx > 0.0 && fitting_bins_count >= 3 {
            score -= 1.0 ;
        }
        if fitting_bins_count <= 2 && nx > 0.0 && pr >= nx && pr - nx < 3.0 {
            score -= 1.8 ;
        }
        if nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 0.9 * (1.0 - (pr - nx) / 2.0) * (0.4 + 0.6 * (1.0 - progress)) ;
        }
        if pr > 0.0 && pr <= 6.0 && nx > 0.0 && nx > pr {
            score -= 1.0 * (1.0 - pr / 6.0) ;
        }
        if pr > 12.0 && pr < 0.4 * cap && nx > 0.0 && nx > pr {
            score += 1.2 * (1.0 - pr / (0.4 * cap)) ;
        }
        if pr > 0.0 && pr <= 20.0 && nx > 0.0 && nx >= pr {
            score -= 0.5 * (pr / 20.0) ;
        }
        let dead = pr / br . max (1.0) ;
        if dead <= 0.2 && nx > 0.0 && pr >= nx && pr - nx <= 1.0 {
            score -= 0.8 * (1.0 - (pr - nx)) * (0.6 + 0.4 * progress) ;
        }
        if dead > 0.5 && dead <= 0.75 && nx > 0.0 && pr - nx > 12.0 && pr - nx < 25.0 && mean_residual < cap * 0.25 {
            score += 0.5 * (dead - 0.5) * ((pr - nx - 12.0) / 13.0) * (0.5 + 0.5 * (1.0 - progress)) ;
        }
        if dead > 0.85 && pr > 25.0 && fitting_bins_count >= 5 {
            score += 1.0 * (dead - 0.85) * (1.0 - progress) ;
        }
        if dead > 0.45 && nx > 0.0 && pr > 2.0 && pr < nx && nx - pr <= 4.0 {
            score += 0.7 * (1.0 - (nx - pr) / 4.0) * (0.5 + 0.5 * progress) ;
        }
        // GEN190: reward low dead-space bins that still leave usable space for nx
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 0.35 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress) ;
        }
        // GEN190: penalize bins that strand a residual just below nx after this item
        if dead > 0.35 && nx > 0.0 && pr >= nx && pr - nx > 0.0 && pr - nx < 1.0 && fitting_bins_count >= 2 {
            score += 0.3 * (1.0 - (pr - nx)) * (1.0 - progress) ;
        }
        // GEN190: penalize high dead-space bins harder when many bins compete
        if dead > 0.65 && pr > 12.0 && fitting_bins_count >= 4 {
            score += 0.4 * (dead - 0.65) * (fitting_bins_count as f64 - 3.0) * 0.25 ;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; the smaller the dead gap relative to capacity, the worse.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item cannot use the leftover: leftover is more likely dead space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a new empty bin should only win when fits are terrible.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or residual
        // capacity is already abundant.
        score += 20.0 + 3.0 * open_bins_count as f64 + 0.5 * mean_residual.max(0.0);
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If no open bin can fit, the new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: mild bonus to keep bins consolidated.
        score -= 2.0;
    }

    // Mild preference for bins below mean residual (balancing load).
    score += 0.05 * ((post_residual as f64) - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space relative to next item
            score += 0.25 * (post_residual as f64 - nxt).abs();
        }
    }

    // Compare residual against mean residual of open bins
    let mr = mean_residual.max(0.0);
    if (post_residual as f64) > mr {
        score += 0.15 * (post_residual as f64 - mr);
    } else {
        score -= 0.10 * (mr - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when current fits are bad
    if bin_residual == bin_capacity {
        score -= 6.0;
        // penalize opening new bins early in the stream
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        if open_bins_count > 0 && next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score += 15.0; // an open bin chains perfectly, don't open new
        }
    }

    // Small penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let nx = next_item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Dead-space avoidance (softened from parent to avoid over-penalizing small usable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: next item fits into post-residual — reward tight refills (GEN191: graded).
    if nx > 0.0 && pr >= nx {
        let after = pr - nx;
        score -= 45.0 * (1.0 - after / cap).max(0.0);
        // Exact refill chain bonus
        if after == 0.0 {
            score -= 12.0;
        } else if after <= 4.0 {
            score -= 6.0 * (1.0 - after / 4.0) * (0.5 + 0.5 * progress);
        } else if after <= 12.0 {
            score -= 3.0 * (1.0 - (after - 4.0) / 8.0);
        }
        // Multi-chain harmonics: leave room for 2x or 3x next items
        if nx >= 2.0 && after >= 2.0 * nx && after <= 2.0 * nx + 4.0 {
            score -= 5.0 * (1.0 - (after - 2.0 * nx) / 4.0) * (0.5 + 0.5 * progress);
        }
        if nx >= 3.0 && after >= 3.0 * nx && after <= 3.0 * nx + 6.0 {
            score -= 3.5 * (1.0 - (after - 3.0 * nx) / 6.0) * (0.5 + 0.5 * progress);
        }
        // Penalize stranding a residual just below nx (unusable for lookahead)
        if after > 0.0 && after < 1.0 && fitting_bins_count >= 2 {
            score += 3.0 * (1.0 - after) * (1.0 - progress);
        }
    } else if nx > 0.0 && pr > 0.0 {
        // Next item won't fit here: penalize proportionally, stronger early.
        score += (nx - pr) * (0.6 + 0.8 * (1.0 - progress));
        // But favor the bin with the largest residual as the likely future host.
        if fitting_bins_count == 0 && br >= mean_residual * 1.15 {
            score -= 4.0 * (1.0 - br / (mean_residual.max(1.0) * 2.0)) * (0.5 + 0.5 * progress);
        }
    }

    // Fitting pressure.
    if fitting_bins_count > 1 {
        score -= 10.0;
    } else if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Open bins pressure.
    score += (open_bins_count as f64) * 1.5;

    // Tighter bins relative to mean residual.
    score += (mean_residual - pr) * 0.3;

    // Dead-ratio analysis for open bins (borrowed idea: fraction of remaining space wasted).
    if bin_residual != bin_capacity && br > 0.0 {
        let dead = pr / br.max(1.0);
        if dead > 0.75 && pr > 15.0 {
            score += 2.0 * (dead - 0.75);
        }
        if dead <= 0.3 && pr >= nx && nx > 0.0 && br > 0.3 * cap {
            score -= 3.0 * (1.0 - dead / 0.3) * (0.4 + 0.6 * progress);
        }
        if dead > 0.5 && nx > 0.0 && pr > nx && pr - nx <= 2.0 && pr > 8.0 {
            score += 1.5 * (1.0 - (pr - nx) / 2.0);
        }
    }

    // NEW-BIN CANDIDATE evaluation (GEN191: lookahead-driven, replaces flat penalty).
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let waste = (cap - item_size as f64) / cap;
        // If placing item here leaves room for nx with a tight chain, favor the new bin.
        let after_new = cap - item_size as f64 - nx;
        if nx > 0.0 && after_new >= 0.0 {
            if after_new == 0.0 {
                score -= 6.0;
            } else if after_new < nx {
                score -= 2.0 * (1.0 - after_new / nx.max(1.0)) * (0.5 + 0.5 * progress);
            } else {
                // Wide leftover: penalize, especially mid/late stream.
                score += 1.5 * ((after_new - nx) / cap) * (0.5 + progress);
            }
        } else if nx > 0.0 {
            // New bin can't host nx after this item: penalize when open bins could.
            if open_bins_count > 0 && mean_residual >= nx {
                score += 2.5 * (1.0 - progress);
            }
        }
        // Large waste in a fresh bin: discourage, more so when many bins are open.
        if waste > 0.5 {
            score += 2.0 * (waste - 0.5) * (1.0 + 0.5 * progress);
        }
        // Late stream: strongly discourage new bins when open space suffices.
        if open_bins_count > 0 && progress > 0.7 && mean_residual >= item_size as f64 {
            score += 3.0 * (progress - 0.7) / 0.3;
        }
        // Early stream with tight mean residual: opening is more acceptable.
        if progress < 0.25 && mean_residual < cap * 0.2 {
            score -= 2.0 * (1.0 - progress);
        }
    }

    // Late-stream tightening toward exact fits.
    score -= progress * 20.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to wasted gap
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let open_pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0).sqrt());
    if bin_residual < bin_capacity {
        score -= 2.0 * open_pressure.min(5.0);
    }

    // Mean residual coupling: bins far below mean residual are attractive targets.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 3.0 * dev;

    // Time horizon: late in stream, be conservative — keep residual flexibility.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when current item is large
    // and no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item && (fitting_bins_count == 0 || post_residual == 0) {
            score -= 10.0;
        } else {
            score += 5.0 + 3.0 * open_pressure.min(4.0);
        }
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let br = bin_residual as f64 ;
    let it = item_size as f64 ;
    let progress = (step_index as f64 / total_items . max (1.0 as usize) as f64) . clamp (0.0 , 1.0) ;
    let nx = next_item_size as f64 ;
    let mut score = pr ;
    score += 0.011 * (mean_residual - br) . abs () ;

    if pr == 0.0 {
        score -= 27.0 ;
        if fitting_bins_count <= 2 { score -= 1.5 * (1.0 - progress) ; }
        if fitting_bins_count >= 3 { score -= 0.8 * (1.0 - progress) ; }
    } else if pr <= 2.0 {
        score -= 13.5 ;
    } else if pr <= 5.0 {
        score -= 8.0 ;
    } else if pr <= 9.0 {
        score -= 3.0 ;
    } else if pr <= 16.0 {
        score -= 0.8 ;
    }

    if nx > 0.0 {
        if pr >= nx {
            let gap = (pr - nx) / cap ;
            score -= 14.5 * (1.0 - gap) . max (0.0) ;
            let after = pr - nx ;
            if after == 0.0 {
                score -= 4.0 ;
            } else if after <= 12.0 {
                score -= 6.0 ;
            } else if after <= 20.0 && fitting_bins_count <= 2 {
                score -= 2.0 ;
            }
            if after >= 12.0 && after <= 30.0 {
                score -= 1.5 * (1.0 - (after - 12.0) / 18.0) ;
            }
            if after >= 1.0 && after <= 4.0 {
                score -= 2.5 * (1.0 - progress) ;
            }
            if after >= 1.0 && after <= 6.0 && fitting_bins_count <= 3 {
                score -= 1.0 * (1.0 - after / 6.0) ;
            }
            if after >= 2.0 && after <= 10.0 && fitting_bins_count <= 2 {
                score -= 0.8 * (1.0 - (after - 2.0) / 8.0) * (0.6 + 0.4 * progress) ;
            }
            if after >= 4.0 && after <= 16.0 && fitting_bins_count >= 4 {
                score -= 0.9 * (1.0 - (after - 4.0) / 12.0) * (1.0 - progress) ;
            }
            if after >= 20.0 && mean_residual < cap * 0.35 {
                score -= 1.0 * (1.0 - progress) ;
            }
            if after >= 2.0 * nx && after <= 2.0 * nx + 8.0 {
                score -= 1.0 * (1.0 - (after - 2.0 * nx) / 8.0) * (0.4 + 0.6 * progress) ;
            }
            if after >= 2.0 * nx && after <= 3.0 * nx && nx >= 2.0 {
                score -= 0.7 * (1.0 - (after - 2.0 * nx) / nx . max (1.0)) * (0.5 + 0.5 * progress) ;
            }
            if after > 0.0 && after < nx && nx - after <= 4.0 {
